24: #[must_use]
25: pub fn combat_action_workload(
26:     work: CombatActionWork,
27:     action_duration_seconds: AnimationElapsed,
28:     weapon_mass_kg: f32,
29:     weapon_inertia_kg_m2: f32,
30:     carried_mass_kg: f32,
31:     body_mass_kg: f32,
32:     parameters: CombatFatigueParameters,
33: ) -> CombatActionWorkload {
34:     let duration = action_duration_seconds.seconds().clamp(
35:         parameters.minimum_action_seconds.seconds(),
36:         parameters.maximum_action_seconds.seconds(),
37:     );
38:     let weapon_energy = |travel_metres: f32| {
39:         let linear_speed = travel_metres / duration;
40:         let angular_speed = std::f32::consts::PI / duration;
41:         0.5 * weapon_mass_kg.max(0.0) * linear_speed * linear_speed
42:             + 0.5 * weapon_inertia_kg_m2.max(0.0) * angular_speed * angular_speed
43:     };
44:     let mechanical_joules = match work {
45:         CombatActionWork::Attack => weapon_energy(parameters.attack_travel_metres),
46:         CombatActionWork::WeaponDefense => weapon_energy(parameters.defense_travel_metres),
47:         CombatActionWork::ExplosiveDodge => {
48:             let moved_mass = body_mass_kg.max(0.0) + carried_mass_kg.max(0.0);
49:             0.5 * moved_mass
50:                 * parameters
51:                     .dodge_speed_metres_per_second
52:                     .metres_per_second()
53:                     .powi(2)
54:         }
55:     };
56:     CombatActionWorkload {
57:         metabolic_joules: mechanical_joules / parameters.mechanical_efficiency,
58:     }
59: }
