61: /// Unsustainable movement adds to the same fatigue as weapon work.
62: /// Sustainable unloaded jogging holds fatigue steady; stationary rest recovers.
63: #[must_use]
64: pub fn combat_movement_fatigue_per_second(
65:     effort_speed_metres_per_second: NonnegativeSpeed,
66:     sustainable_speed_metres_per_second: NonnegativeSpeed,
67:     carried_mass_kg: f32,
68:     endurance: f32,
69:     parameters: CombatFatigueParameters,
70: ) -> f32 {
71:     let effort = effort_speed_metres_per_second.metres_per_second().max(0.0);
72:     let ratio = if effort == 0.0 {
73:         0.0
74:     } else {
75:         effort
76:             / sustainable_speed_metres_per_second
77:                 .metres_per_second()
78:                 .max(0.0)
79:     };
80:     let aerobic =
81:         parameters.aerobic_watts_per_endurance * endurance.max(parameters.minimum_endurance);
82:     let carry = if ratio > 0.0 {
83:         carried_mass_kg.max(0.0) * parameters.carry_watts_per_kg
84:     } else {
85:         0.0
86:     };
87:     (aerobic * ratio * ratio + carry - aerobic).max(0.0) / parameters.capacity(endurance)
88: }
