118:         )
119:     });
120:     let moving = movement.is_some_and(|movement| movement.length_squared() > 0.0);
121:     let burden = view.body_weight() + view.inventory_weight();
122:     let speeds = || -> adventuresim_tactical_core::animation::AnimationValueResult<_> {
123:         let sprint_speed = tactical_sprint_speed(
124:             view.raw_limb_attr(LimbAttribute::Strength, BodyPart::LeftLeg),
125:             view.raw_limb_attr(LimbAttribute::Strength, BodyPart::RightLeg),
126:             view.body_part_health(BodyPart::LeftLeg),
127:             view.body_part_health(BodyPart::RightLeg),
128:             burden,
129:         )?;
