131:         let effort_speed = tactical_movement_speed_for_pace(
132:             movement,
133:             pace,
134:             skeleton.map_or(WeaponGuardState::Lowered, SkeletonState::weapon_guard),
135:             jog_speed,
136:             sprint_speed,
137:         )?;
138:         Ok((jog_speed, effort_speed))
139:     };
