107: fn source_coordinates(source: &str, path: &str) -> (usize, usize) {
108:     let item_id = path
109:         .strip_prefix("item ")
110:         .and_then(|path| path.split(['.', ':']).next());
111:     let item_start = item_id
112:         .and_then(|id| source.find(&format!("\"id\": \"{id}\"")))
113:         .unwrap_or(0);
114:     let field = path
115:         .split('.')
116:         .rev()
117:         .find(|component| !component.bytes().all(|byte| byte.is_ascii_digit()))
118:         .and_then(|component| component.split_whitespace().last())
119:         .unwrap_or("items");
120:     let offset = source[item_start..]
121:         .find(&format!("\"{field}\""))
122:         .map(|offset| item_start + offset)
123:         .unwrap_or(item_start);
124:     let before = &source[..offset];
125:     let line = before.bytes().filter(|byte| *byte == b'\n').count() + 1;
126:     let column = before
127:         .rsplit('\n')
128:         .next()
129:         .map_or(1, |line| line.chars().count() + 1);
130:     (line, column)
131: }
