225:     }
226:     for (source_index, source) in sources.iter().enumerate() {
227:         if source.len() > MAX_SOURCE_BYTES {
228:             diagnostics.push(CatalogDiagnostic::new(
229:                 source_index,
230:                 "item catalog",
231:                 format!("source exceeds {MAX_SOURCE_BYTES} bytes"),
232:             ));
233:         }
234:     }
235:     let item_count: usize = documents
236:         .iter()
237:         .filter_map(Value::as_object)
238:         .filter_map(|root| root.get("items"))
239:         .filter_map(Value::as_array)
240:         .map(Vec::len)
241:         .sum();
242:     if item_count > MAX_ITEMS {
243:         diagnostics.push(CatalogDiagnostic::new(
244:             0,
245:             "item catalog",
246:             format!("at most {MAX_ITEMS} items are supported"),
247:         ));
248:     }
249:     for (source_index, document) in documents.iter().enumerate() {
250:         let mut errors = CatalogDiagnostics {
251:             source_index,
252:             diagnostics: &mut diagnostics,
253:         };
254:         let Some(root) = document.as_object() else {
255:             errors.push("catalog", "root must be an object");
256:             continue;
257:         };
258:         reject_unknown(root, &["schema_version", "items"], "catalog", &mut errors);
259:         if root.get("schema_version").and_then(Value::as_u64) != Some(1) {
260:             errors.push("catalog.schema_version", "supported value is 1");
261:         }
262:         let Some(items) = root.get("items").and_then(Value::as_array) else {
263:             errors.push("catalog.items", "required array");
264:             continue;
265:         };
266:         for (index, item) in items.iter().enumerate() {
267:             validate_item(item, index, &mut ids, &mut errors);
268:         }
269:         if let Err(error) = serde_json::from_value::<crate::item_catalog_schema::ItemCatalogDocument>(
270:             document.clone(),
271:         ) {
272:             errors.push("item catalog", format!("typed schema mismatch: {error}"));
273:         }
274:     }

