150: impl<'de> Visitor<'de> for StrictValueVisitor {
151:     type Value = StrictValue;
152: 
153:     fn expecting(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
154:         formatter.write_str("a strict JSON-compatible YAML value")
