161: fn record_final_totals(
162:     causal: &mut AutoresolveCausalSummary,
163:     outcome: &adventuresim_core::autoresolve::BattleOutcome,
164: ) -> MeasurementResult<()> {
165:     for combatant in outcome.allies.iter().chain(&outcome.enemies) {
166:         causal.final_blood_loss_fraction.checked_add(
167:             Measurement::<BloodLossFraction>::from_native(combatant.blood_loss_fraction)?,
168:         )?;
169:         causal.final_wound_count += combatant.wound_count as u64;
170:         causal.final_open_wound_count += combatant.open_wound_count as u64;
171:         causal.final_internal_wound_count += combatant.internal_wound_count as u64;
172:         causal
173:             .final_wound_flow_fraction_per_second
174:             .checked_add(Measurement::<WoundFlowFractionPerSecond>::from_native(
175:                 combatant.wound_flow_fraction_per_second,
176:             )?)?;
177:         causal
178:             .final_fatigue
179:             .checked_add(Measurement::<Fatigue>::from_native(combatant.fatigue)?)?;
180:         causal
181:             .final_acute_trauma
182:             .checked_add(Measurement::<AcuteTrauma>::from_native(
183:                 combatant.acute_trauma,
184:             )?)?;
185:         causal
186:             .final_imbalance
187:             .checked_add(Measurement::<Imbalance>::from_native(combatant.imbalance)?)?;
188:     }
189:     Ok(())
190: }
