13:     src: &mut LiveEvents<'de>,
14:     f: F,
15:     wrap_err: W,
16:     synthesized_null_should_be_eof: P,
17: ) -> Result<R, Error>
18: where
19:     F: FnOnce(&mut LiveEvents<'de>) -> Result<R, Error>,
20:     W: Fn(Error, &LiveEvents<'de>) -> Error,
21:     P: Fn(&Error) -> bool,
22: {
23:     let value_res = crate::anchor_store::with_document_scope(|| {
24:         crate::properties_redaction::with_interp_redaction_scope(|| f(src))
25:     });
26:     match value_res {
27:         Ok(v) => {
28:             src.finalize_document_budget()
29:                 .map_err(|e| wrap_err(e, src))?;
30:             Ok(v)
31:         }
32:         Err(e) => {
33:             if src.synthesized_null_emitted() && synthesized_null_should_be_eof(&e) {
34:                 // If the only thing in the input was an empty document (synthetic null),
35:                 // surface this as an EOF error to preserve expected error semantics
36:                 // for incompatible target types (e.g., bool).
37:                 Err(wrap_err(
38:                     Error::eof().with_location(src.last_location()),
