81: pub(crate) fn enforce_single_document_and_finish<'de, W>(
82:     src: &mut LiveEvents<'de>,
83:     multiple_docs_hint: &'static str,
84:     wrap_err: W,
85: ) -> Result<(), Error>
86: where
87:     W: Fn(Error, &LiveEvents<'de>) -> Error,
88: {
89:     // After finishing first document, peek ahead to detect either another document/content
90:     // or trailing garbage. Preserve the compatibility behavior that ignores malformed YAML
91:     // after "...", but never suppress a reader or reader-limit failure.
92:     match src.peek() {
93:         Ok(Some(_)) => {
94:             return Err(wrap_err(
95:                 Error::multiple_documents(multiple_docs_hint).with_location(src.last_location()),
96:                 src,
97:             ));
98:         }
99:         Ok(None) => {}
100:         Err(e) => {
101:             if src.seen_doc_end() && !matches!(&e, Error::IOError { .. }) {
102:                 // Trailing garbage after a proper document end marker is ignored.
103:             } else {
104:                 return Err(wrap_err(e, src));
105:             }
106:         }
107:     }
108: 
109:     src.finish().map_err(|e| wrap_err(e, src))
110: }
