585: 
586: fn leave_mission_for_server(
587:     ctx: &ReducerContext,
588:     mut character: Character,
589:     server: Identity,
590: ) -> Result<(), String> {
591:     if !character.has_tactical_server_assignment() || character.server != server {
592:         return Err("Only the character's owning tactical server can remove it".into());
593:     }
594:     let character_id = character.id;
595:     if character.temporary {
596:         log::info!("Leaving mission for character #{character_id}: removing temporary character..");
597:         crate::character::delete_temporary_character(ctx, character)?;
598:     } else {
599:         log::info!("Leaving mission for character #{character_id}: resetting server info..");
600:         character.server = Identity::ZERO;
601:         ctx.db.character().id().update(character);
602:     }
603: 
604:     Ok(())

950: pub(crate) fn on_join_request(
951:     join: On<FromClient<JoinRequest>>,
952:     mut commands: Commands,
953:     mut state: ResMut<MissionState>,
954:     loading_players: Query<(), With<LoadingPlayer>>,
955:     players: Query<(), With<Player>>,
956:     mut disconnected_players: Query<(Entity, &mut DisconnectedPlayer, &DisconnectedProjection)>,
957:     inventory_items: Query<(Entity, &ItemOf)>,
958:     mut pending_actions: ResMut<PendingEquipmentActions>,
959:     mut action_sequences: ResMut<LastEquipmentSequence>,
960:     conn: Res<SpacetimeDb>,
961:     ready: Res<SpacetimeDbReady>,
962:     vista: Res<SceneVistaBundleResource>,
963:     combat_config: Res<TacticalCombatConfig>,
964: ) -> Result {
965:     let Some(client) = join.client_id.entity() else {
966:         return Ok(());
967:     };
968:     if loading_players.contains(client) || players.contains(client) {
969:         return Ok(());
970:     }
971:     let reconnect =
972:         disconnected_players
973:             .iter_mut()
974:             .find_map(|(entity, mut session, projection)| {
975:                 try_claim_reconnect(join.character_id, join.reconnect_token, &mut session)
976:                     .then(|| (entity, projection.clone()))
977:             });
978:     if let Some((disconnected, projection)) = reconnect {
979:         let token = fresh_reconnect_token();
980:         let projected = projection.projected();
981:         if projected {
982:             queue_replication_rebind(&mut commands, client);
983:         }
984:         projection.insert(&mut commands, client);
985:         commands.entity(client).insert(ReconnectSession {
986:             character_id: join.character_id,
987:             token,
988:         });
989:         send_reconnect_capability(&mut commands, join.client_id, join.character_id, token);
990:         send_scene_vista(&mut commands, join.client_id, &vista);
991:         send_combat_config(&mut commands, join.client_id, &combat_config);
992:         reconnect_equipment_lifecycle(
993:             disconnected,
994:             client,
995:             &mut pending_actions,
996:             &mut action_sequences,
997:         );
998:         for (item, owner) in &inventory_items {
999:             if owner.0 == disconnected {
1000:                 commands.entity(item).insert(ItemOf(client));
1001:             }
1002:         }
1003:         if projected {
1004:             commands.queue(move |world: &mut World| rebuild_inventory_holding_cache(world, client));
1005:         }
1006:         commands.entity(disconnected).despawn();
1007:         info!(
1008:             character_id = join.character_id.0,
1009:             "Rebound reconnect to transient tactical state"
1010:         );
1011:         return Ok(());
1012:     }
1013:     if join.reconnect_token.is_some() {
1014:         warn!(
1015:             character_id = join.character_id.0,
1016:             "Rejected invalid or consumed reconnect capability"
1017:         );
1018:         return Ok(());
1019:     }
1020:     if !state.allows_party_join(join.character_id) {
1021:         warn!(
1022:             character_id = join.character_id.0,
1023:             "Rejected unseen Party join after enrollment sealed"
1024:         );
1025:         return Ok(());
1026:     }
