11: #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, Serialize, Deserialize)]
12: #[serde(rename_all = "kebab-case")]
13: pub enum MapChannel {
14:     Albedo,
15:     Normal,
16:     Height,
17:     Arm,
18:     Opacity,
19:     FrontAlbedo,
20:     BackAlbedo,
21:     FrontNormal,
22:     BackNormal,
23:     HeightAo,
24:     LitterSurface,
25:     Transmittance,
26:     OpticalNormal,
27:     ThicknessRoughness,
28: }
29: 
30: impl MapChannel {
31:     pub const fn slug(self) -> &'static str {
32:         match self {
33:             Self::Albedo => "albedo",
34:             Self::Normal => "normal",
35:             Self::Height => "height",
36:             Self::Arm => "arm",
37:             Self::Opacity => "opacity",
38:             Self::FrontAlbedo => "front-albedo",
39:             Self::BackAlbedo => "back-albedo",
40:             Self::FrontNormal => "front-normal",
41:             Self::BackNormal => "back-normal",
42:             Self::HeightAo => "height-ao",
43:             Self::LitterSurface => "surface",
44:             Self::Transmittance => "transmittance",
45:             Self::OpticalNormal => "optical-normal",
46:             Self::ThicknessRoughness => "thickness-roughness",
47:         }
48:     }
49: }
50: 
51: #[derive(Clone, Copy, Debug, Serialize, Deserialize)]
52: pub enum PixelEncoding {
53:     R8,
54:     Rg8,
55:     Rgba8,
56:     Srgb8,
57: }
58: 
59: impl PixelEncoding {
60:     pub const fn channels(self) -> usize {
61:         match self {
62:             Self::R8 => 1,
63:             Self::Rg8 => 2,
64:             Self::Rgba8 | Self::Srgb8 => 4,
65:         }
66:     }
67: 
68:     pub const fn texture_format(self) -> TextureFormat {
69:         match self {
70:             Self::R8 => TextureFormat::R8Unorm,
71:             Self::Rg8 => TextureFormat::Rg8Unorm,
72:             Self::Rgba8 => TextureFormat::Rgba8Unorm,
73:             Self::Srgb8 => TextureFormat::Rgba8UnormSrgb,
74:         }
75:     }
