63: fn committed_collection_loads_exact_mips_and_samplers_without_baking() {
64:     let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../assets");
65:     let mut app = App::new();
66:     app.add_plugins((
67:         MinimalPlugins,
68:         AssetPlugin {
69:             file_path: root.to_str().unwrap().to_owned(),
70:             ..Default::default()
71:         },
72:         BakedTexturesPlugin,
73:     ))
74:     .init_asset::<Image>();
75:     app.finish();
76:     app.cleanup();
77:     let server = app.world().resource::<AssetServer>().clone();
78:     let textures =
79:         app.world_mut()
80:             .resource_scope(|world, mut residency: Mut<ProceduralTextureResidency>| {
81:                 let textures = ProceduralTextureAssets::reserve(
82:                     &mut residency,
83:                     &mut world.resource_mut::<Assets<Image>>(),
84:                 );
85:                 residency.request(
86:                     &server,
87:                     PROCEDURAL_TEXTURE_CATALOGUE.iter().map(|recipe| recipe.id),
88:                 );
89:                 residency.request(
90:                     &server,
91:                     PROCEDURAL_TEXTURE_CATALOGUE.iter().map(|recipe| recipe.id),
92:                 );
93:                 assert_eq!(
94:                     residency.requested_container_count(),
95:                     PROCEDURAL_TEXTURE_CATALOGUE.len()
96:                 );
97:                 textures
98:             });
99:     let handles = requested_images(&textures);
100:     let deadline = Instant::now() + Duration::from_secs(30);
101:     loop {
102:         app.update();
103:         if app
104:             .world()
105:             .resource::<ProceduralTextureResidency>()
106:             .is_ready(PROCEDURAL_TEXTURE_CATALOGUE.iter().map(|recipe| recipe.id))
107:         {
108:             break;
109:         }
110:         assert!(
111:             Instant::now() < deadline,
112:             "committed texture loading timed out"
113:         );
114:         std::thread::sleep(Duration::from_millis(10));
115:     }
116:     // Verify the runtime bindings cover every committed recipe channel exactly once,
117:     // and that Image upload preserves all metadata and the complete pixel payload.
118:     let images = app.world().resource::<Assets<Image>>();
119:     let mut checked = 0;
120:     for descriptor in PROCEDURAL_TEXTURE_CATALOGUE {
121:         let bytes = std::fs::read(root.join(descriptor.id.runtime_asset_path())).unwrap();
122:         let bake = BakedRecipe::from_compressed_bytes(&bytes).unwrap();
123:         assert_eq!(bake.recipe, descriptor.id);
124:         for map in bake.maps {
125:             let image = images
126:                 .iter()
127:                 .map(|(_, image)| image)
128:                 .find(|image| image.data.as_ref() == Some(&map.bytes))
129:                 .expect("runtime binding for baked map");
130:             assert_eq!(image.width(), map.size);
131:             assert_eq!(image.height(), map.size);
132:             assert_eq!(image.texture_descriptor.mip_level_count, map.mip_levels);
133:             assert_eq!(map.mip_levels, map.size.ilog2() + 1);
134:             assert_eq!(
135:                 image.texture_descriptor.format,
136:                 map.encoding.texture_format()
137:             );
138:             assert_eq!(image.sampler, map.sampler);
139:             assert_eq!(image.data.as_ref().unwrap(), &map.bytes);
140:             checked += 1;
141:         }
142:     }
143:     assert_eq!(checked, handles.len());
144:     let blood = images.get(&textures.terrain_blood_mask).unwrap();
145:     assert!(blood.data.as_ref().unwrap().iter().all(|pixel| *pixel == 0));
146:     assert!(blood.asset_usage.contains(RenderAssetUsages::MAIN_WORLD));
147: }

