30: pub(super) fn show(world: &mut World, id: ExhibitId) {
31:     if world
32:         .get_resource::<CurrentExhibit>()
33:         .is_some_and(|current| current.id == id)
34:     {
35:         return;
36:     }
37:     world.remove_resource::<PendingScenery>();
38:     if let Some(current) = world.remove_resource::<CurrentExhibit>() {
39:         let view = world.resource::<OrbitView>().clone();
40:         world
41:             .resource_mut::<ExhibitCache>()
42:             .views
43:             .insert(current.id, view);
44:         if !Exhibit::get(current.id).is_studio() {
45:             crate::presentation::clear_demo_scene(world);
46:             world.insert_resource(SceneryRetirement(SCENERY_RELEASE_FRAMES));
47:         }
48:     }
49:     let studio = world
50:         .query_filtered::<Entity, With<StudioEntity>>()
51:         .iter(world)
52:         .collect::<Vec<_>>();
53:     for entity in studio {
54:         world.entity_mut(entity).despawn();
55:     }
56: 
57:     let exhibit = Exhibit::get(id);
58:     if !exhibit.texture_recipes().is_empty() && world.contains_resource::<AssetServer>() {
59:         let server = world.resource::<AssetServer>().clone();
60:         world
61:             .resource_mut::<adventuresim_procedural_textures::ProceduralTextureResidency>()
62:             .request(&server, exhibit.texture_recipes().iter().copied());
63:     }
64:     if world.contains_resource::<AssetServer>() {
65:         if id == ExhibitId::Oak {
66:             let server = world.resource::<AssetServer>().clone();
67:             world
68:                 .resource_mut::<crate::presentation::PreparedTreeImpostorAssets>()
69:                 .request(&server);
70:         } else {
71:             world
72:                 .resource_mut::<crate::presentation::PreparedTreeImpostorAssets>()
73:                 .release();
74:         }
75:     }
76:     *world.resource_mut::<OrbitView>() = exhibit.view();
77:     let result = if exhibit.is_studio() {
78:         exhibits::studio(world);
79:         load_studio(world, &exhibit)
80:     } else if world.contains_resource::<SceneryRetirement>() {
81:         world.insert_resource(PendingScenery(id));
82:         Ok(None)
83:     } else {
84:         match scenery_ready(world, &exhibit) {
85:             Ok(true) => exhibit.spawn(world).map_err(Arc::new),
86:             Ok(false) => {
87:                 world.insert_resource(PendingScenery(id));
88:                 Ok(None)
89:             }
90:             Err(error) => Err(Arc::new(error)),
91:         }
92:     };
93:     world.flush();
94:     for (entity, mut visibility) in world
95:         .query::<(&DemoEntity, &mut Visibility)>()
96:         .iter_mut(world)
97:     {
98:         *visibility = if entity.0 == id {
99:             Visibility::Inherited
100:         } else {
101:             Visibility::Hidden
102:         };
103:     }
104:     if let Some(view) = world.resource::<ExhibitCache>().views.get(&id).cloned() {
105:         *world.resource_mut::<OrbitView>() = view;
106:     }
107:     world.insert_resource(CurrentExhibit { id, scene: result });
108: }
