244: fn report_readiness(
245:     current: Option<Res<CurrentExhibit>>,
246:     assets: Res<AssetServer>,
247:     pending: Option<Res<crate::presentation::PendingCityBuildings>>,
248:     scenery: Option<Res<residency::PendingScenery>>,
249: ) {
250:     let Some(current) = current else {
251:         return;
252:     };
253:     let mut status = DemoStatus::Ready {
254:         exhibit: current.id,
255:     };
256:     if scenery.is_some() {
257:         status = DemoStatus::Loading {
258:             exhibit: current.id,
259:             completed: 0,
260:             total: 0,
261:         };
262:     }
263:     if let Some(pending) = pending {
264:         if !pending.finished() {
265:             status = DemoStatus::Loading {
266:                 exhibit: current.id,
267:                 completed: pending.completed(),
268:                 total: pending.total,
269:             };
270:         } else if let Some(message) = pending.failure() {
271:             status = DemoStatus::Unavailable {
272:                 exhibit: current.id,
273:                 message: message.into(),
274:             };
275:         }
276:     }
277:     match &current.scene {
278:         Err(error) => {
279:             status = DemoStatus::Unavailable {
280:                 exhibit: current.id,
281:                 message: error.to_string(),
282:             }
283:         }
284:         Ok(Some(scene)) => {
285:             let error = match assets.get_load_state(scene.id()) {
286:                 Some(bevy::asset::LoadState::Failed(error)) => Some(error),
287:                 _ => match assets.get_recursive_dependency_load_state(scene.id()) {
288:                     Some(bevy::asset::RecursiveDependencyLoadState::Failed(error)) => Some(error),
289:                     _ => None,
290:                 },
291:             };
292:             if let Some(error) = error {
293:                 status = DemoStatus::Unavailable {
294:                     exhibit: current.id,
295:                     message: error.to_string(),
296:                 };
297:             } else if !assets.is_loaded_with_dependencies(scene.id()) {
298:                 status = DemoStatus::Loading {
299:                     exhibit: current.id,
300:                     completed: 0,
301:                     total: 0,
302:                 };
303:             }
304:         }
305:         Ok(None) => {}
306:     }
307:     *STATUS.lock().expect("demo status lock") = status;
308: }
