1: //! Explicit authoring step. Normal builds and game startup never execute this binary.
2: 
3: use std::{error::Error, path::Path, time::Instant};
4: 
5: use adventuresim_procedural_textures::{
6:     BakedRecipe, PROCEDURAL_TEXTURE_CATALOGUE, TextureParameters,
7: };
8: 
9: fn main() -> Result<(), Box<dyn Error>> {
10:     let arguments: Vec<_> = std::env::args().skip(1).collect();
11:     let [selection] = arguments.as_slice() else {
12:         return Err("usage: bake-procedural-textures <all|recipe-slug>".into());
13:     };
14:     let recipes: Vec<_> = PROCEDURAL_TEXTURE_CATALOGUE
15:         .iter()
16:         .filter(|entry| selection == "all" || selection == entry.id.slug())
17:         .collect();
18:     if recipes.is_empty() {
19:         return Err(format!("unknown texture recipe: {selection}").into());
20:     }
21:     let assets = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../assets");
22:     let params = TextureParameters::default();
23:     for descriptor in recipes {
24:         let started = Instant::now();
25:         println!("Baking {} at full resolution...", descriptor.id.slug());
26:         let bake = BakedRecipe::generate(descriptor.id, &params);
27:         let bytes = bake.to_compressed_bytes()?;
28:         // Verify the exact complete mip payload and metadata before publishing.
29:         if BakedRecipe::from_compressed_bytes(&bytes)?.to_bytes() != bake.to_bytes() {
30:             return Err(format!("{} did not round-trip", descriptor.id.slug()).into());
31:         }
32:         let output = assets.join(descriptor.id.runtime_asset_path());
33:         std::fs::create_dir_all(output.parent().expect("asset has a parent directory"))?;
34:         std::fs::write(&output, &bytes)?;
35:         println!(
36:             "Saved {} ({} bytes, {:.2}s)",
37:             output.display(),
38:             bytes.len(),
39:             started.elapsed().as_secs_f64()
40:         );
41:     }
42:     Ok(())
43: }

