59:         let server = world.resource::<AssetServer>().clone();
60:         world
61:             .resource_mut::<adventuresim_procedural_textures::ProceduralTextureResidency>()
62:             .request(&server, exhibit.texture_recipes().iter().copied());
63:     }
64:     if world.contains_resource::<AssetServer>() {
65:         if id == ExhibitId::Oak {
66:             let server = world.resource::<AssetServer>().clone();
67:             world
