112:         if retirement.0 > 0 {
113:             retirement.0 -= 1;
114:             return;
115:         }
116:         world.remove_resource::<SceneryRetirement>();
117:     }
118:     if let Some(id) = world
119:         .get_resource::<PendingScenery>()
120:         .map(|pending| pending.0)
121:     {
122:         match scenery_ready(world, &Exhibit::get(id)) {
123:             Ok(true) => {}
124:             Ok(false) => return,
125:             Err(error) => {
126:                 world.remove_resource::<PendingScenery>();
127:                 world.resource_mut::<CurrentExhibit>().scene = Err(Arc::new(error));
128:                 return;
129:             }
130:         }
131:     }
132:     if let Some(pending) = world.remove_resource::<PendingScenery>() {
133:         let result = Exhibit::get(pending.0).spawn(world).map_err(Arc::new);
134:         if let Some(view) = world
135:             .resource::<ExhibitCache>()
136:             .views
137:             .get(&pending.0)
138:             .cloned()
139:         {
140:             *world.resource_mut::<OrbitView>() = view;
141:         }
142:         world.resource_mut::<CurrentExhibit>().scene = result;
143:     }
144: }
