147:     world
148:         .get_resource::<adventuresim_procedural_textures::ProceduralTextureResidency>()
149:         .is_none_or(|residency| residency.is_ready(exhibit.texture_recipes().iter().copied()))
150: }
151: 
152: fn scenery_ready(world: &World, exhibit: &Exhibit) -> ArtDemoPreparationResult<bool> {
153:     if !textures_ready(world, exhibit) {
154:         return Ok(false);
155:     }
156:     if exhibit.id() != ExhibitId::Oak {
157:         return Ok(true);
158:     }
159:     let residency = world.resource::<crate::presentation::PreparedTreeImpostorAssets>();
160:     let handle = residency
161:         .handle()
162:         .ok_or(ArtDemoPreparationError::ImpostorNotRequested)?;
163:     let server = world.resource::<AssetServer>();
164:     if let Some(bevy::asset::LoadState::Failed(error)) = server.get_load_state(handle.id()) {
165:         return Err(ArtDemoPreparationError::ImpostorLoad { source: error });
166:     }
167:     Ok(server.is_loaded_with_dependencies(handle.id()))
168: }

