131:     disconnected: On<Disconnected>,
132:     clients: Query<(), With<AdventureSimulatorClient>>,
133:     mut screen: ResMut<LoadingScreen>,
134: ) {
135:     if !clients.contains(disconnected.entity) {
136:         return;
137:     }
138:     let reason = match &disconnected.reason {
139:         DisconnectReason::ByUser(reason) | DisconnectReason::ByPeer(reason) => reason.clone(),
140:         DisconnectReason::ByError(error) => format!("{error:#}"),
141:     };
142:     screen.fail(LoadingFailure::ConnectionLost(reason));
