1: //! Fixed geographic lattice using the existing vista pigment and material.
2: use super::*;
3: use adventuresim_tactical_core::regional_terrain::{REGIONAL_TERRAIN_SIDE, RegionalTerrain};
4: 
5: pub(in crate::presentation) fn regional_mesh(
6:     terrain: &RegionalTerrain,
7:     weather: WeatherSnapshot,
8: ) -> Option<Mesh> {
9:     let spacing = terrain.request().scale.spacing_metres();
10:     let center = (REGIONAL_TERRAIN_SIDE - 1) as f32 * 0.5;
11:     let mut positions = Vec::with_capacity(terrain.vertices().len());
12:     let mut colors = Vec::with_capacity(terrain.vertices().len());
13:     for (index, vertex) in terrain.vertices().iter().enumerate() {
14:         // Native map mesh port: X east, Y absolute source elevation, Z south.
15:         // Missing positions are never referenced by an emitted triangle.
16:         positions.push([
17:             (index % REGIONAL_TERRAIN_SIDE) as f32 * spacing - center * spacing,
18:             vertex.map_or(0.0, |vertex| f32::from(vertex.elevation.get())),
19:             center * spacing - (index / REGIONAL_TERRAIN_SIDE) as f32 * spacing,
20:         ]);
21:         colors.push(vertex.map_or([0.0; 4], |vertex| {
22:             pigment::vista_sample_color(vertex.environment, weather).to_array()
23:         }));
24:     }
25:     let mut indices = Vec::new();
26:     for row in 0..REGIONAL_TERRAIN_SIDE - 1 {
27:         for column in 0..REGIONAL_TERRAIN_SIDE - 1 {
28:             let south_west = row * REGIONAL_TERRAIN_SIDE + column;
29:             let south_east = south_west + 1;
30:             let north_west = south_west + REGIONAL_TERRAIN_SIDE;
31:             let north_east = north_west + 1;
32:             for triangle in [
33:                 [south_west, south_east, north_west],
34:                 [south_east, north_east, north_west],
35:             ] {
36:                 if triangle
37:                     .iter()
38:                     .all(|index| terrain.vertices()[*index].is_some())
39:                 {
40:                     indices.extend(triangle.map(|index| index as u32));
41:                 }
42:             }
43:         }
44:     }
45:     if indices.is_empty() {
46:         return None;
47:     }
48:     let mut mesh = Mesh::new(
49:         PrimitiveTopology::TriangleList,
50:         RenderAssetUsages::RENDER_WORLD,
51:     );
52:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
53:     mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, colors);
54:     mesh.insert_indices(Indices::U32(indices));
55:     Some(mesh.with_computed_area_weighted_normals())
56: }

