1: //! Geographic positions on the exact triangles emitted by the regional mesh.
2: use adventuresim_tactical_core::regional_terrain::{REGIONAL_TERRAIN_SIDE, RegionalTerrain};
3: use adventuresim_world_schema::coordinates::{
4:     Wgs84CoordinateMicrodegrees,
5:     terrain_projection::{NativeTerrainCoordinate, NativeTerrainOffset},
6: };
7: use bevy::{math::DVec2, prelude::*};
8: 
9: pub(super) struct SurfaceSegment {
10:     pub endpoints: [Vec3; 2],
11:     /// Native plane normal, with positive up component; not a scene direction.
12:     pub normal: Vec3,
13: }
14: 
15: /// Native Bevy mesh port: east, absolute interpolated elevation, south metres.
16: /// No triangle containing a missing source vertex supplies a surface position.
17: pub(super) fn position(
18:     terrain: &RegionalTerrain,
19:     origin: Wgs84CoordinateMicrodegrees,
20: ) -> Option<Vec3> {
21:     let offset = NativeTerrainCoordinate::from(terrain.request().origin.to_e7())
22:         .offset_to(origin.to_e7().into());
23:     position_at_offset(terrain, offset)
24: }
25: 
26: pub(super) fn position_at_offset(
27:     terrain: &RegionalTerrain,
28:     offset: NativeTerrainOffset,
29: ) -> Option<Vec3> {
30:     let triangle = triangle(terrain, offset)?;
31:     Some(on_triangle(triangle, offset))
32: }
33: 
34: /// Endpoints on one grid triangle. The caller splits at grid and diagonal edges.
35: /// Selecting by the midpoint admits both boundary endpoints to that same plane.
36: pub(super) fn segment(
37:     terrain: &RegionalTerrain,
38:     endpoints: [NativeTerrainOffset; 2],
39: ) -> Option<SurfaceSegment> {
40:     let [start, end] = endpoints;
41:     let midpoint = NativeTerrainOffset {
42:         east_metres: (start.east_metres + end.east_metres) * 0.5,
43:         north_metres: (start.north_metres + end.north_metres) * 0.5,
44:     };
45:     let triangle = triangle(terrain, midpoint)?;
46:     Some(SurfaceSegment {
47:         endpoints: endpoints.map(|offset| on_triangle(triangle, offset)),
48:         normal: (triangle[1] - triangle[0]).cross(triangle[2] - triangle[0]),
49:     })
50: }
51: 
52: /// Native homogeneous triangle vertices: X east, Y absolute elevation, Z south.
53: fn triangle(terrain: &RegionalTerrain, offset: NativeTerrainOffset) -> Option<[Vec3; 3]> {
54:     let spacing = f64::from(terrain.request().scale.spacing_metres());
55:     let centre = (REGIONAL_TERRAIN_SIDE - 1) as f64 * 0.5;
56:     let column = offset.east_metres / spacing + centre;
57:     let row = offset.north_metres / spacing + centre;
58:     if !(0.0..=(REGIONAL_TERRAIN_SIDE - 1) as f64).contains(&column)
59:         || !(0.0..=(REGIONAL_TERRAIN_SIDE - 1) as f64).contains(&row)
60:     {
61:         return None;
62:     }
63:     let cell_column = column.floor().min((REGIONAL_TERRAIN_SIDE - 2) as f64) as u32;
64:     let cell_row = row.floor().min((REGIONAL_TERRAIN_SIDE - 2) as f64) as u32;
65:     let columns = [
66:         Some(cell_column),
67:         (column.fract() == 0.0)
68:             .then_some(cell_column.checked_sub(1))
69:             .flatten(),
70:     ];
71:     let rows = [
72:         Some(cell_row),
73:         (row.fract() == 0.0)
74:             .then_some(cell_row.checked_sub(1))
75:             .flatten(),
76:     ];
77:     let grid = DVec2::new(column, row);
78:     for row in rows.into_iter().flatten() {
79:         for column in columns.into_iter().flatten() {
80:             if let Some(triangle) = triangle_at_cell(terrain, UVec2::new(column, row), grid) {
81:                 return Some(triangle);
82:             }
83:         }
84:     }
85:     None
86: }
87: 
88: /// Native mesh grid port: cell and continuous position both use east/north axes.
89: /// At shared edges either covered triangle is a valid source elevation plane.
90: fn triangle_at_cell(terrain: &RegionalTerrain, cell: UVec2, grid: DVec2) -> Option<[Vec3; 3]> {
91:     let fraction = grid - cell.as_dvec2();
92:     if !fraction.cmpge(DVec2::ZERO).all() || !fraction.cmple(DVec2::ONE).all() {
93:         return None;
94:     }
95:     let south_west = cell.y as usize * REGIONAL_TERRAIN_SIDE + cell.x as usize;
96:     let south_east = south_west + 1;
97:     let north_west = south_west + REGIONAL_TERRAIN_SIDE;
98:     let north_east = north_west + 1;
99:     let lower = [south_west, south_east, north_west];
100:     let upper = [south_east, north_east, north_west];
101:     let triangles = if fraction.x + fraction.y < 1.0 {
102:         [Some(lower), None]
103:     } else if fraction.x + fraction.y > 1.0 {
104:         [Some(upper), None]
105:     } else {
106:         [Some(lower), Some(upper)]
107:     };
108:     let spacing = f64::from(terrain.request().scale.spacing_metres());
109:     let centre = (REGIONAL_TERRAIN_SIDE - 1) as f64 * 0.5;
110:     let vertex = |index: usize| {
111:         terrain.vertices()[index].map(|vertex| {
112:             Vec3::new(
113:                 ((index % REGIONAL_TERRAIN_SIDE) as f64 - centre) as f32 * spacing as f32,
114:                 f32::from(vertex.elevation.get()),
115:                 (centre - (index / REGIONAL_TERRAIN_SIDE) as f64) as f32 * spacing as f32,
116:             )
117:         })
118:     };
119:     for indices in triangles.into_iter().flatten() {
120:         if let [Some(first), Some(second), Some(third)] = indices.map(vertex) {
121:             return Some([first, second, third]);
122:         }
123:     }
124:     None
125: }
126: 
127: fn on_triangle([first, second, third]: [Vec3; 3], offset: NativeTerrainOffset) -> Vec3 {
128:     let normal = (second - first).cross(third - first);
129:     let east = offset.east_metres as f32;
130:     let south = -offset.north_metres as f32;
131:     let height = first.y - (normal.x * (east - first.x) + normal.z * (south - first.z)) / normal.y;
132:     Vec3::new(east, height, south)
133: }

