54:             NativeTerrainCoordinate::from(window_origin.to_e7()).frame_from(city.origin().into());
55:         let offset = projection.origin;
56:         // Native GPU port: metres relative to the current terrain window,
57:         // including the city's absolute source elevation. Reflection changes
58:         // north-positive local Z into the map's south-positive world Z.
59:         let translation = Vec3::new(
60:             offset.east_metres as f32,
61:             f32::from(city.input().absolute_elevation_metres.get()),
