1: //! The native terrain sampler's shared local east/north projection.
2: //! Checked geographic origins enter this numerical port once. Intermediate
3: //! samples retain continuous degrees, including points outside source coverage.
4: use super::Wgs84CoordinateE7;
5: 
6: pub const METRES_PER_LATITUDE_DEGREE: f64 = 111_320.0;
7: pub const MIN_LONGITUDE_SCALE: f64 = 0.01;
8: 
9: /// Native TerrainPack coordinates, not a checked geographic position. Offsets
10: /// can leave WGS84 or package bounds; the source lookup owns missing coverage.
11: #[derive(Clone, Copy, Debug)]
12: pub struct NativeTerrainCoordinate {
13:     pub latitude_degrees: f64,
14:     pub longitude_degrees: f64,
15: }
16: 
17: /// Numerical-kernel output for a mesh or camera adapter, in local east/north
18: /// metres. Logical scene positions retain their existing checked frame types.
19: #[derive(Clone, Copy, Debug)]
20: pub struct NativeTerrainOffset {
21:     pub east_metres: f64,
22:     pub north_metres: f64,
23: }
24: 
25: /// Affine numerical port between two local terrain sampler frames. North
26: /// metres share one scale; east metres follow each origin's longitude scale.
27: #[derive(Clone, Copy, Debug)]
28: pub struct NativeTerrainFrame {
29:     pub origin: NativeTerrainOffset,
30:     pub east_scale: f64,
31: }
32: 
33: impl From<Wgs84CoordinateE7> for NativeTerrainCoordinate {
34:     fn from(origin: Wgs84CoordinateE7) -> Self {
35:         Self {
36:             latitude_degrees: origin.latitude().degrees(),
37:             longitude_degrees: origin.longitude().degrees(),
38:         }
39:     }
40: }
41: 
42: impl NativeTerrainCoordinate {
43:     /// Transform coordinates authored at `source` into this sampler's frame,
44:     /// without an intermediate geographic rounding or a second projection.
45:     pub fn frame_from(self, source: Self) -> NativeTerrainFrame {
46:         NativeTerrainFrame {
47:             origin: self.offset_to(source),
48:             east_scale: self.longitude_scale() / source.longitude_scale(),
49:         }
50:     }
51: 
52:     /// Terrain sampling kernel: signed east/north metres become continuous
53:     /// degrees. The operation order matches imported tactical terrain capture.
54:     pub fn at_offset(self, east_metres: f64, north_metres: f64) -> Self {
55:         let latitude_delta = north_metres / METRES_PER_LATITUDE_DEGREE;
56:         let longitude_scale = self.longitude_scale();
57:         let longitude_delta = east_metres / (METRES_PER_LATITUDE_DEGREE * longitude_scale);
58:         Self {
59:             latitude_degrees: self.latitude_degrees + latitude_delta,
60:             longitude_degrees: self.longitude_degrees + longitude_delta,
61:         }
62:     }
63: 
64:     /// Inverse local projection at this sampler origin. This does not choose a
65:     /// new origin or round a geographic position during mesh/camera arithmetic.
66:     pub fn offset_to(self, target: Self) -> NativeTerrainOffset {
67:         let longitude_scale = self.longitude_scale();
68:         NativeTerrainOffset {
69:             east_metres: (target.longitude_degrees - self.longitude_degrees)
70:                 * (METRES_PER_LATITUDE_DEGREE * longitude_scale),
71:             north_metres: (target.latitude_degrees - self.latitude_degrees)
72:                 * METRES_PER_LATITUDE_DEGREE,
73:         }
74:     }
75: 
76:     fn longitude_scale(self) -> f64 {
77:         self.latitude_degrees
78:             .to_radians()
79:             .cos()
80:             .abs()
81:             .max(MIN_LONGITUDE_SCALE)
82:     }
83: }

