107: /// CanvasRect is the shared native viewport port. Admit map rectangles here;
108: /// half-visible CSS edges can round outward by at most one physical pixel.
109: fn viewport<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<CanvasRect, D::Error> {
110:     let rect = CanvasRect::deserialize(deserializer)?;
111:     let valid = rect.width > 0
112:         && rect.height > 0
113:         && rect.full_width >= rect.width
114:         && rect.full_height >= rect.height
115:         && rect.offset_x.is_finite()
116:         && rect.offset_y.is_finite()
117:         && rect.offset_x >= 0.0
118:         && rect.offset_y >= 0.0
119:         && f64::from(rect.offset_x) + f64::from(rect.width) <= f64::from(rect.full_width) + 1.0
120:         && f64::from(rect.offset_y) + f64::from(rect.height) <= f64::from(rect.full_height) + 1.0;
121:     if valid {
122:         Ok(rect)
123:     } else {
124:         Err(serde::de::Error::custom(MapProtocolError::Viewport))
125:     }
126: }

