4: const RECENT_WINDOW_LIMIT = 4;
5: const MAX_CONNECTIONS = 8192;
6: const MAX_CONNECTION_POINTS = 65536;
7: const connectionKinds = new Set(["land","river","coast","canal","ferry","winter","inferred_walking_link"]);
8: const scales = new Set(["neighborhood", "district", "region", "country", "continent"]);
