16: function admitRequest({ source, origin, scale }) {
17:   if (typeof source !== "string" || !/^[a-f0-9]{64}$/.test(source)
18:     || !scales.has(scale) || !Number.isInteger(origin?.latitude)
19:     || !Number.isInteger(origin?.longitude) || Math.abs(origin.latitude) > 90_000_000
20:     || Math.abs(origin.longitude) > 180_000_000) {
21:     throw new RegionalEnvironmentLoadError("map/environment-request", "Invalid regional environment request");
22:   }
23:   return Object.freeze({ source, scale, origin: Object.freeze({
24:     latitude: origin.latitude, longitude: origin.longitude,
25:   }) });
26: }
