32: function admitWindow(environment, request) {
33:   const terrain=environment?.terrain;
34:   if (terrain?.source !== request.source || terrain?.request?.scale !== request.scale
35:     || terrain?.request?.origin?.latitude !== request.origin.latitude
36:     || terrain?.request?.origin?.longitude !== request.origin.longitude
37:     || !Array.isArray(terrain?.vertices) || terrain.vertices.length !== WINDOW_VERTICES
38:     || !Array.isArray(environment.connections) || environment.connections.length>MAX_CONNECTIONS) {
39:     throw new RegionalEnvironmentLoadError("map/environment-response", "Environment response does not match its window");
40:   }
41:   let count=0;
42:   for(const line of environment.connections) {
43:     if(!connectionKinds.has(line?.kind) || !Array.isArray(line.points) || line.points.length<2
44:       || (count+=line.points.length)>MAX_CONNECTION_POINTS || line.points.some(point=>
45:         !Number.isInteger(point?.latitude) || Math.abs(point.latitude)>900_000_000
46:         || !Number.isInteger(point?.longitude) || Math.abs(point.longitude)>1_800_000_000)) {
47:       throw new RegionalEnvironmentLoadError("map/environment-response", "Invalid regional connections");
48:     }
49:   }
50:   return environment;
51: }
