53: export function createRegionalEnvironmentRequests({ runtimePromise, install, changed = () => {},
54:   fetchEnvironment = (...args) => (window.strategicFetch || fetch)(...args) }) {
55:   const recent = new Map();
56:   let state = Object.freeze({ phase: "idle" });
57:   let current, resident;
58:   const publish = value => { state = Object.freeze(value); changed(state); };
59: 
60:   async function load(owned) {
61:     const { request, key, controller } = owned;
62:     const { signal } = controller;
63:     try {
64:       signal.throwIfAborted();
65:       let product = recent.get(key);
66:       const reused = product !== undefined;
67:       if (!reused) {
68:         const query = new URLSearchParams({ latitude: request.origin.latitude,
69:           longitude: request.origin.longitude, scale: request.scale });
70:         const response = await fetchEnvironment(`/api/map/environment/${request.source}?${query}`,
71:           { headers: { Accept: "application/json" }, cache: "no-store", signal });
72:         signal.throwIfAborted();
73:         if (!response.ok) throw new RegionalEnvironmentLoadError("map/environment-http",
74:           `Could not load map environment (${response.status})`);
75:         product = admitWindow(await response.json(), request);
76:         signal.throwIfAborted();
77:       }
78:       await runtimePromise;
79:       signal.throwIfAborted();
80:       if (resident?.key !== key) install(product);
81:       resident = { key, request };
82:       recent.delete(key); recent.set(key, product);
83:       while (recent.size > RECENT_WINDOW_LIMIT) recent.delete(recent.keys().next().value);
