95:   const controller = {
96:     get state() { return state; },
97:     request(input, { retry = false } = {}) {
98:       const request = admitRequest(input);
99:       const key = keyFor(request);
100:       if (resident?.key === key) {
101:         current?.controller.abort(); current = undefined;
102:         if (state.phase !== "prepared" || keyFor(state.request) !== key) {
103:           publish({ phase: "prepared", request });
104:         }
105:         return Promise.resolve({ status: "reused", request });
106:       }
107:       if (current?.key === key) return current.promise;
108:       if (!retry && state.phase === "failed" && keyFor(state.request) === key) {
109:         return Promise.resolve({ status: "failed", request, cause: state.cause });
110:       }
111:       current?.controller.abort();
112:       const owned = { request, key, controller: new AbortController() };
113:       current = owned;
114:       owned.promise = Promise.resolve().then(() => load(owned));
115:       publish({ phase: "loading", request });
116:       return owned.promise;
117:     },
118:     retry() {
119:       return state.phase === "failed" ? controller.request(state.request, { retry: true })
120:         : Promise.resolve({ status: "unchanged" });
121:     },
122:     cancel() {
123:       current?.controller.abort(); current = undefined;
124:       publish(resident ? { phase: "prepared", request: resident.request } : { phase: "idle" });
125:     },
126:   };
127:   return controller;
128: }

