1: //! Exact six-vertex support prism admission, independent of contact tolerances.
2: use bevy::math::{Vec3, Vec3Swizzles};
3: use serde::Serialize;
4: 
5: #[derive(Clone, Copy, Debug, PartialEq, Serialize, thiserror::Error)]
6: pub enum SupportGeometryIssue {
7:     #[error("support prism cannot be represented by the physics engine")]
8:     Collider,
9:     #[error(transparent)]
10:     Membership(#[from] super::PropertyMemberIssue),
11:     #[error("support geometry has a non-finite position")]
12:     NonFinite,
13:     #[error("support prism top and base have different plan positions")]
14:     Pair,
15:     #[error("support prism has a reversed or wholly collapsed height interval")]
16:     Height,
17:     #[error("support geometry has incomplete cells or noncanonical triangle indices")]
18:     Topology,
19:     #[error("support geometry has invalid property or member bindings")]
20:     Members,
21:     #[error("support query index has invalid bounds, topology or source references")]
22:     Query,
23: }
24: 
25: /// Quantized clipping can collapse a plan edge or reverse a tiny triangle's
26: /// winding. These represented contact cells remain valid: admission checks
27: /// finite paired vertices and ordered heights, without a proximity epsilon or
28: /// changing the producer's vertices and topology.
29: pub(super) fn prism(points: &[Vec3; 6]) -> Result<(), SupportGeometryIssue> {
30:     if points.iter().any(|point| !point.is_finite())
31:         || !points.iter().copied().sum::<Vec3>().is_finite()
32:     {
33:         return Err(SupportGeometryIssue::NonFinite);
34:     }
35:     if (0..3).any(|i| points[i].xz() != points[i + 3].xz()) {
36:         return Err(SupportGeometryIssue::Pair);
37:     }
38:     if (0..3).any(|i| points[i].y < points[i + 3].y)
39:         || (0..3).all(|i| points[i].y == points[i + 3].y)
40:     {
41:         return Err(SupportGeometryIssue::Height);
42:     }
43:     Ok(())
44: }
45: 
46: /// Physics faces follow exact represented winding. Zero-area contact cells have
47: /// no solid; the existing query-area threshold separately governs bearings.
48: pub(super) fn solid_faces(points: &[Vec3; 6], faces: [[u32; 3]; 8]) -> Option<[[u32; 3]; 8]> {
49:     let [a, b, c] = [points[0], points[1], points[2]].map(|p| p.xz().as_dvec2());
50:     let area = (b - a).perp_dot(c - a);
51:     if area == 0.0 {
52:         None
53:     } else if area < 0.0 {
54:         Some(faces.map(|[a, b, c]| [a, c, b]))
55:     } else {
56:         Some(faces)
57:     }
58: }

