116:     fn append(self, mesh: &mut BoundarySupportMesh) -> Result<(), BoundarySupportError> {
117:         let Self {
118:             property,
119:             triangles,
120:             member,
121:             element,
122:             gate: _,
123:             limits,
124:             embedment: _,
125:         } = self;
126:         let centre = member.pose.plan_metres().as_dvec2();
127:         let (sine, cosine) = f64::from(member.orientation.yaw_radians()).sin_cos();
128:         let tangent = DVec2::new(cosine, -sine);
129:         let inward = DVec2::new(sine, cosine);
130:         let half = member.size_metres.metres().xz().as_dvec2() * 0.5;
131:         let outline = [
132:             DVec2::NEG_ONE,
133:             DVec2::new(1.0, -1.0),
134:             DVec2::ONE,
135:             DVec2::new(-1.0, 1.0),
136:         ]
137:         .map(|p| centre + tangent * p.x * half.x + inward * p.y * half.y);
138:         let mut covered = 0.0;
139:         for triangle in triangles {
140:             let mut polygon = triangle.points().map(|p| p.xz().as_dvec2()).to_vec();
141:             for i in 0..outline.len() {
142:                 let a = outline[i];
143:                 let edge = outline[(i + 1) % outline.len()] - a;
144:                 polygon = planar::clip(polygon, |p| edge.perp_dot(p - a));
145:             }
146:             let area = planar::signed_area(&polygon).abs();
147:             if area <= 0.0 {
148:                 continue;
149:             }
150:             covered += area;
151:             for i in 1..polygon.len().saturating_sub(1) {
152:                 let points = [polygon[0], polygon[i], polygon[i + 1]];
153:                 if planar::signed_area(&points) == 0.0 {
154:                     continue;
155:                 }
156:                 mesh.cells.push(self.cell(triangle, points)?);
157:             }
158:         }
159:         let expected =
160:             f64::from(member.size_metres.metres().x) * f64::from(member.size_metres.metres().z);
161:         let permitted = 2.0
162:             * f64::from(member.size_metres.metres().x + member.size_metres.metres().z)
163:             * f64::from(limits.contact_tolerance_metres.metres());
164:         let discrepancy = (covered - expected).abs();
165:         if discrepancy > permitted {
166:             return Err(BoundarySupportError::new(
167:                 property,
168:                 element,
169:                 BoundarySupportConstraint::Coverage,
170:                 centre.as_vec2(),
171:                 discrepancy,
172:                 permitted,
173:             ));
174:         }
175:         Ok(())
176:     }
