116:     fn append(self, mesh: &mut BoundarySupportMesh) -> Result<(), BoundarySupportError> {
117:         let Self {
118:             property,
119:             triangles,
120:             member,
121:             element,
122:             gate: _,
123:             limits,
124:             embedment: _,
125:         } = self;
126:         let centre = member.pose.plan_metres().as_dvec2();
127:         let (sine, cosine) = f64::from(member.orientation.yaw_radians()).sin_cos();
128:         let tangent = DVec2::new(cosine, -sine);
129:         let inward = DVec2::new(sine, cosine);
130:         let half = member.size_metres.metres().xz().as_dvec2() * 0.5;
131:         let outline = [
132:             DVec2::NEG_ONE,
133:             DVec2::new(1.0, -1.0),
134:             DVec2::ONE,
135:             DVec2::new(-1.0, 1.0),
136:         ]
137:         .map(|p| centre + tangent * p.x * half.x + inward * p.y * half.y);
138:         let mut covered = 0.0;
139:         for triangle in triangles {
140:             let mut polygon = triangle.points().map(|p| p.xz().as_dvec2()).to_vec();
141:             for i in 0..outline.len() {
142:                 let a = outline[i];
143:                 let edge = outline[(i + 1) % outline.len()] - a;
144:                 polygon = planar::clip(polygon, |p| edge.perp_dot(p - a));
145:             }
146:             let area = planar::signed_area(&polygon).abs();
147:             if area <= 0.0 {
148:                 continue;
149:             }
150:             covered += area;
151:             for i in 1..polygon.len().saturating_sub(1) {
152:                 let points = [polygon[0], polygon[i], polygon[i + 1]];
153:                 if planar::signed_area(&points) == 0.0 {
154:                     continue;
155:                 }
156:                 mesh.cells.push(self.cell(triangle, points)?);
157:             }
158:         }
159:         let expected =
160:             f64::from(member.size_metres.metres().x) * f64::from(member.size_metres.metres().z);
161:         let permitted = 2.0
162:             * f64::from(member.size_metres.metres().x + member.size_metres.metres().z)
163:             * f64::from(limits.contact_tolerance_metres.metres());
164:         let discrepancy = (covered - expected).abs();
165:         if discrepancy > permitted {
166:             return Err(BoundarySupportError::new(
167:                 property,
168:                 element,
169:                 BoundarySupportConstraint::Coverage,
170:                 centre.as_vec2(),
171:                 discrepancy,
172:                 permitted,
173:             ));
174:         }
175:         Ok(())
176:     }
177:     fn cell(
178:         &self,
179:         triangle: &GroundTriangle,
180:         points: [DVec2; 3],
181:     ) -> Result<BoundarySupportCell, BoundarySupportError> {
182:         let mut top = [Position::<GateRelative>::ORIGIN; 3];
183:         let mut base = [Position::<GateRelative>::ORIGIN; 3];
184:         for (j, point) in points.into_iter().enumerate() {
185:             let soil = triangle.height_f64(point) as f32;
186:             let construction_error = |cause| {
187:                 BoundarySupportError::construction(
188:                     self.property,
189:                     crate::city_layout::BoundaryGeometryError {
190:                         element: self.element,
191:                         cause,
192:                     },
193:                 )
194:             };
195:             let levels = member_levels(self.member, soil, self.gate, self.embedment)
196:                 .map_err(construction_error)?;
197:             if levels.head.metres() <= levels.base.metres() {
198:                 return Err(BoundarySupportError::new(
199:                     self.property,
200:                     self.element,
201:                     BoundarySupportConstraint::PostHeadroom,
202:                     point.as_vec2(),
203:                     f64::from(levels.base.metres() - levels.head.metres()),
204:                     0.0,
205:                 ));
206:             }
207:             top[j] = adventuresim_building_generator::spatial_geometry::Position::<
208:                 crate::scene_coordinates::GateRelative,
209:             >::from_metres(Vec3::new(
210:                 point.x as f32,
211:                 levels.head.metres() - self.gate.metres(),
212:                 point.y as f32,
213:             ))
214:             .map_err(construction_error)?;
215:             base[j] = adventuresim_building_generator::spatial_geometry::Position::<
216:                 crate::scene_coordinates::GateRelative,
217:             >::from_metres(Vec3::new(
218:                 point.x as f32,
219:                 levels.base.metres() - self.gate.metres(),
220:                 point.y as f32,
221:             ))
222:             .map_err(construction_error)?;
223:         }
224:         BoundarySupportCell::new(
225:             [top[0], top[1], top[2], base[0], base[1], base[2]],
226:             self.member.material,
227:             self.element,
228:         )
229:         .map_err(|cause| BoundarySupportError::cell(self.property, self.element, cause))
230:     }
231: }
