233: struct MemberLevels {
234:     base: SupportElevation,
235:     head: SupportElevation,
236: }
237: 
238: fn member_levels(
239:     member: CityBoundaryMember,
240:     soil: f32,
241:     gate: SupportElevation,
242:     embedment: FoundationEmbedment,
243: ) -> Result<MemberLevels, adventuresim_building_generator::spatial_geometry::GeometryError> {
244:     use crate::city_layout::CityBoundaryPose;
245:     let (centre, gate_relative, cap) = match member.pose {
246:         CityBoundaryPose::GatePost { centre, .. } => (centre.metres().y, true, false),
247:         CityBoundaryPose::Wall { centre, .. } => (centre.metres().y, false, false),
248:         CityBoundaryPose::WallCap { centre, .. } => (centre.metres().y, false, true),
249:     };
250:     let nominal_base = centre - member.size_metres.metres().y * 0.5;
251:     let nominal_head = centre + member.size_metres.metres().y * 0.5;
252:     let elevation = |metres| {
253:         SupportElevation::from_metres(metres).ok_or(
254:             adventuresim_building_generator::spatial_geometry::GeometryError::NonFinite {
255:                 role: adventuresim_building_generator::spatial_geometry::GeometryRole::Elevation,
256:                 axis: adventuresim_building_generator::spatial_geometry::CoordinateAxis::Y,
257:             },
258:         )
259:     };
260:     Ok(MemberLevels {
261:         base: elevation(if cap {
262:             soil + nominal_base
263:         } else {
264:             soil - embedment.metres()
265:         })?,
266:         head: elevation(if gate_relative {
267:             gate.metres() + nominal_head
268:         } else {
269:             soil + nominal_head
270:         })?,
271:     })
272: }

