1: //! Fixed enclosure geometry shares material draws within spatial cells.
2: use super::{BuildingLodMaterial, TacticalBuildingMaterials};
3: use adventuresim_tactical_core::{
4:     city_layout::grounding::{BoundarySupportCell, BoundarySupportElement},
5:     prelude::{CityBoundaryMaterial, SceneBoundary},
6:     scene_coordinates::GateDatum,
7: };
8: use bevy::mesh::{GenerateTangentsError, MeshMergeError};
9: use bevy::prelude::*;
10: use std::collections::HashMap;
11: 
12: // Keep culling spatially useful without retaining an entity for every wall cap.
13: const BOUNDARY_BATCH_METRES: f32 = 128.0;
14: 
15: type BoundaryBatchResult<T> = std::result::Result<T, BoundaryBatchError>;
16: 
17: pub(super) struct BoundaryMesh {
18:     pub mesh: Mesh,
19:     pub material: Handle<StandardMaterial>,
20:     pub origin: Vec3,
21: }
22: 
23: #[derive(Default)]
24: pub(super) struct BoundaryBatches {
25:     meshes: HashMap<(IVec2, AssetId<StandardMaterial>), BoundaryMesh>,
26:     pub members: usize,
27: }
28: 
29: #[derive(Clone, Copy)]
30: pub(super) enum BoundaryPlacement {
31:     GateRelative,
32:     Scene(GateDatum),
33: }
34: 
35: #[derive(Debug, thiserror::Error)]
36: pub(super) enum BoundaryBatchError {
37:     #[error("{element:?} has nonfinite boundary mesh positions or texture coordinates")]
38:     NonFiniteVertex { element: BoundarySupportElement },
39:     #[error(transparent)]
40:     Tangents(#[from] GenerateTangentsError),
41:     #[error(transparent)]
42:     Merge(#[from] MeshMergeError),
43: }
44: 
45: impl BoundaryBatches {
46:     pub fn insert_boundary(
47:         &mut self,
48:         boundary: &SceneBoundary,
49:         placement: BoundaryPlacement,
50:         materials: &TacticalBuildingMaterials,
51:     ) -> BoundaryBatchResult<()> {
52:         for cell in boundary.fixed_support().cells() {
53:             let material = match cell.material() {
54:                 CityBoundaryMaterial::Masonry => BuildingLodMaterial::Wall(
55:                     adventuresim_building_generator::WallMaterialClass::RubbleMasonry,
56:                 ),
57:                 CityBoundaryMaterial::Timber => BuildingLodMaterial::Timber,
58:                 CityBoundaryMaterial::Iron => BuildingLodMaterial::Iron,
59:             };
60:             self.insert(
61:                 cell,
62:                 placement,
63:                 materials
64:                     .for_building(boundary.front_building_id().0)
65:                     .get(material),
66:             )?;
67:         }
68:         Ok(())
69:     }
70: 
71:     pub fn insert(
72:         &mut self,
73:         member: &BoundarySupportCell,
74:         placement: BoundaryPlacement,
75:         material: Handle<StandardMaterial>,
76:     ) -> BoundaryBatchResult<()> {
77:         // The parent supplies the gate transform for relative batches. Distant
78:         // batches encode that same datum in scene-space vertices instead.
79:         let elevation = match placement {
80:             BoundaryPlacement::GateRelative => 0.0,
81:             BoundaryPlacement::Scene(datum) => datum.elevation().metres(),
82:         };
83:         let vertices = member.native_positions();
84:         let centre =
85:             vertices.iter().copied().sum::<Vec3>() / vertices.len() as f32 + Vec3::Y * elevation;
86:         let cell = (centre.xz() / BOUNDARY_BATCH_METRES).floor().as_ivec2();
87:         let origin = Vec3::new(cell.x as f32, 0.0, cell.y as f32) * BOUNDARY_BATCH_METRES;
88:         let mesh = mesh(member, origin - Vec3::Y * elevation)?;
89:         match self.meshes.entry((cell, material.id())) {
90:             std::collections::hash_map::Entry::Occupied(mut entry) => {
91:                 entry.get_mut().mesh.merge(&mesh)?;
92:             }
93:             std::collections::hash_map::Entry::Vacant(entry) => {
94:                 entry.insert(BoundaryMesh {
95:                     mesh,
96:                     material,
97:                     origin,
98:                 });
99:             }
100:         }
101:         self.members += 1;
102:         Ok(())
103:     }
104: 
105:     pub fn finish(self) -> impl ExactSizeIterator<Item = BoundaryMesh> {
106:         self.meshes.into_values()
107:     }
108: }
109: 
110: /// Every rendered face uses the shared cell's exact collision vertices.
111: fn mesh(cell: &BoundarySupportCell, origin: Vec3) -> BoundaryBatchResult<Mesh> {
112:     use bevy::{
113:         asset::RenderAssetUsages, mesh::Indices, render::render_resource::PrimitiveTopology,
114:     };
115:     let mut positions = Vec::new();
116:     let mut normals = Vec::new();
117:     let mut uvs = Vec::new();
118:     for triangle in cell.triangles() {
119:         let normal = (triangle[1] - triangle[0])
120:             .cross(triangle[2] - triangle[0])
121:             .normalize();
122:         // Omit only zero-area faces produced by coincident f32 intersection
123:         // vertices. These have no surface or collider bearing area.
124:         if !normal.is_finite() {
125:             continue;
126:         }
127:         let absolute = normal.abs();
128:         for point in triangle {
129:             let uv = if absolute.x >= absolute.y && absolute.x >= absolute.z {
130:                 Vec2::new(point.z, point.y)
131:             } else if absolute.y >= absolute.z {
132:                 Vec2::new(point.x, point.z)
133:             } else {
134:                 Vec2::new(point.x, point.y)
135:             };
136:             let position = point - origin;
137:             let uv = uv / adventuresim_building_generator::BUILDING_DETAIL_UV_METRES_PER_UNIT;
138:             if !position.is_finite() || !uv.is_finite() {
139:                 return Err(BoundaryBatchError::NonFiniteVertex {
140:                     element: cell.element(),
141:                 });
142:             }
143:             positions.push(position.to_array());
144:             normals.push(normal.to_array());
145:             uvs.push(uv.to_array());
146:         }
147:     }
148:     // Each cell has eight faces, so at most 24 native vertex ordinals fit u32.
149:     let indices: Vec<_> = (0..positions.len() as u32).collect();
150:     let mut mesh = Mesh::new(
151:         PrimitiveTopology::TriangleList,
152:         RenderAssetUsages::RENDER_WORLD | RenderAssetUsages::MAIN_WORLD,
153:     );
154:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
155:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
156:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
157:     mesh.insert_indices(Indices::U32(indices));
158:     mesh.generate_tangents()?;
159:     Ok(mesh)
160: }
