9: pub(crate) type PreparationResult<T> = std::result::Result<T, PreparationError>;
10: 
11: /// Asset roles shared by dependency, residency and installation failures.
12: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
13: pub(crate) enum ProductKind {
14:     RegionalCity,
15:     Scene,
16:     Facade,
17:     Venue,
18:     VenueGeometry,
19: }
20: 
21: #[derive(Debug, Error)]
22: pub(crate) enum PreparationError {
23:     #[error("preparation identity sequence is exhausted")]
24:     SequenceExhausted,
25:     #[error("preparation no longer owns its product slot")]
26:     StalePreparation,
27:     #[error("preparation belongs to another presentation owner")]
28:     PreparationOwner,
29:     #[error("completed preparation belongs to another scene document")]
30:     PreparationInputMismatch,
31:     #[error("generation product residency is poisoned")]
32:     ResidencyPoisoned,
33:     #[error("generation JSON is invalid: {0}")]
34:     Json(#[from] serde_json::Error),
35:     #[error("generation dependencies cannot be decoded: {0}")]
36:     DependenciesDecode(#[source] ciborium::de::Error<std::io::Error>),
37:     #[error("generation product cannot be decoded: {0}")]
38:     ProductDecode(#[source] ciborium::de::Error<std::io::Error>),
39:     #[error("generation dependencies cannot be encoded: {0}")]
40:     DependenciesEncode(#[source] ciborium::ser::Error<std::io::Error>),
41:     #[error("generation product cannot be encoded: {0}")]
42:     ProductEncode(#[source] ciborium::ser::Error<std::io::Error>),
43:     #[error(transparent)]
44:     SceneInput(#[from] Box<SceneInputError>),
45:     #[error(transparent)]
46:     Building(#[from] Box<GenerationError>),
47:     #[error(transparent)]
48:     Geometry(#[from] GeometryError),
49:     #[error(transparent)]
50:     VistaMesh(#[from] VistaMeshError),
51:     #[error(transparent)]
52:     Interior(#[from] Box<InteriorLayoutError>),
53:     // The graphics parser currently exposes prose at its external YAML boundary.
54:     // Keep that boundary classified here without branching on its message.
55:     #[error("generation graphics configuration is invalid: {message}")]
56:     GraphicsConfiguration { message: String },
57:     #[error("{product:?} was not prepared before use")]
58:     NotPrepared { product: ProductKind },
59:     #[error("generation product does not match its requested input")]
60:     ProductMismatch,
61:     #[error("scene transfer changed its exact occupied building bindings")]
62:     SceneBindingsMismatch,
63:     #[error("promoted venue {building} has no distant placement")]
64:     MissingDistantPlacement { building: SceneBuildingId },
65:     #[error("promoted venue {building} changed its physical placement or program")]
66:     PromotedPlacementMismatch { building: SceneBuildingId },
67: }
68: 
69: impl PreparationError {
70:     /// Stable browser failure classification; display prose remains diagnostic.
71:     #[cfg(target_family = "wasm")]
72:     pub(super) fn code(&self) -> &'static str {
73:         match self {
74:             Self::SequenceExhausted => "generation/sequence-exhausted",
75:             Self::StalePreparation => "generation/stale-preparation",
76:             Self::PreparationOwner => "generation/preparation-owner",
77:             Self::PreparationInputMismatch => "generation/preparation-input",
78:             Self::ResidencyPoisoned => "generation/residency-poisoned",
79:             Self::Json(_) => "generation/json",
80:             Self::DependenciesDecode(_) => "generation/dependencies-decode",
81:             Self::ProductDecode(_) => "generation/product-decode",
82:             Self::DependenciesEncode(_) => "generation/dependencies-encode",
83:             Self::ProductEncode(_) => "generation/product-encode",
84:             Self::SceneInput(_) => "generation/scene-input",
85:             Self::Building(_) => "generation/building",
86:             Self::Geometry(_) => "generation/geometry",
87:             Self::VistaMesh(_) => "generation/vista-mesh",
88:             Self::Interior(_) => "generation/interior",
89:             Self::GraphicsConfiguration { .. } => "generation/graphics-configuration",
90:             Self::NotPrepared { .. } => "generation/not-prepared",
91:             Self::ProductMismatch => "generation/product-mismatch",
92:             Self::SceneBindingsMismatch => "generation/scene-bindings-mismatch",
93:             Self::MissingDistantPlacement { .. } => "generation/missing-distant-placement",
94:             Self::PromotedPlacementMismatch { .. } => "generation/promoted-placement-mismatch",
95:         }
96:     }
97: }
