1: //! Canonical settlement exteriors share geometry and GPU packing with actor cities.
2: use super::*;
3: use adventuresim_tactical_core::{
4:     regional_city::RegionalCityInput, scene_input::TacticalBuildingPlacement,
5: };
6: use adventuresim_world_schema::coordinates::Wgs84CoordinateMicrodegrees;
7: use bevy::ecs::system::SystemState;
8: 
9: pub(in crate::presentation) fn queue_focused_city(
10:     world: &mut World,
11:     city: &RegionalCityInput,
12:     root: Entity,
13:     window_origin: Wgs84CoordinateMicrodegrees,
14: ) -> Result {
15:     let mut state = SystemState::<(
16:         ResMut<TacticalBuildingMeshCache>,
17:         ResMut<Assets<Mesh>>,
18:         ResMut<gpu::PendingGpuCities>,
19:     )>::new(world);
20:     let (mut cache, mut meshes, mut cities) = state.get_mut(world)?;
21:     let owner = PresentationOwner::RegionalMap;
22:     let mut queued = gpu::PendingGpuBuildings::default();
23:     queued.set_publication(
24:         root,
25:         gpu::CityFrame::from_geographic_city(city, window_origin),
26:     );
27:     let mut append = |placement: &TacticalBuildingPlacement, appearance| -> Result {
28:         let compiled = cached_building_levels(
29:             owner,
30:             &mut cache,
31:             &placement.program,
32:             BuildingDetail::Facade,
33:             &mut meshes,
34:             None,
35:         )?;
36:         let rotation = Quat::from_rotation_y(placement.orientation.yaw_radians());
37:         let centre = Vec3::new(
38:             placement.centre_metres.metres().x,
39:             placement.base_elevation_metres.metres(),
40:             placement.centre_metres.metres().y,
41:         );
42:         // Facade vertices are rebased around their compiled origin. Restore
43:         // all three components after rotation, preserving asymmetric recipes.
44:         let transform =
45:             Transform::from_translation(centre + rotation * compiled.local_origin.metres())
46:                 .with_rotation(rotation);
47:         queued.push(root, &transform, appearance, &compiled);
48:         Ok(())
49:     };
50:     for placement in &city.input().buildings {
51:         append(placement, gpu::PlacementAppearance::Primary(placement.id))?;
52:     }
53:     for placement in &city.input().distant_buildings {
54:         append(
55:             &(*placement).into(),
56:             gpu::PlacementAppearance::Distant(*placement),
57:         )?;
58:     }
59:     // Publish only the complete queue. A failed facade leaves the current GPU
60:     // city and the actor owner's unpublished placements unchanged.
61:     *cities.owners.get_mut(owner) = queued;
62:     Ok(())
63: }

