1: const CITY_INSTALLATION_DEADLINE_MS = 120_000;
2: 
3: // Only the small ticket is decoded in JavaScript. The canonical document stays
4: // opaque text; parsing its physical seeds here would lose integer precision.
5: export async function installRegionalCity(runtime, {request, document, preparation, signal}) {
6:   signal.throwIfAborted();
7:   const ticket = JSON.parse(preparation);
8:   const deadline = performance.now() + CITY_INSTALLATION_DEADLINE_MS;
9:   // Preparation and terrain publication run independently. Native city
10:   // admission needs an actual presented window for its geographic frame.
11:   while (true) {
12:     signal.throwIfAborted();
13:     const state = JSON.parse(runtime.wasm_regional_map_status());
14:     if (state.source === request.source && state.city_requested === request.place
15:       && state.environment_ready && state.presented && state.requested
16:       && state.presented.scale === state.requested.scale
17:       && state.presented.origin.latitude === state.requested.origin.latitude
18:       && state.presented.origin.longitude === state.requested.origin.longitude) break;
19:     if (performance.now() >= deadline) throw new Error("City detail terrain presentation timed out");
20:     await new Promise(resolve => requestAnimationFrame(resolve));
21:   }
22:   runtime.wasm_command(JSON.stringify({type:"regional-map", command:{
23:     type:"install-city", document_json:document, preparation:ticket,
24:   }}));
25:   while (true) {
26:     signal.throwIfAborted();
27:     const status = JSON.parse(runtime.wasm_regional_map_status()).city_installation;
28:     if (status?.preparation.owner === ticket.owner
29:       && status.preparation.sequence === ticket.sequence) {
30:       if (status.phase === "ready") return;
31:       if (status.phase === "failed") throw new Error(`City detail unavailable (${status.error})`);
32:     }
33:     if (performance.now() >= deadline) throw new Error("City detail installation timed out");
34:     await new Promise(resolve => requestAnimationFrame(resolve));
35:   }
36: }

