3: // One focused settlement per document owner. The admitted Rust document and
4: // ticket stay opaque: JSON rewriting would lose precision in physical seeds.
5: export function createRegionalCityRequests({ runtimePromise, install, changed = () => {},
6:   fetchCity = (...args) => (window.strategicFetch || fetch)(...args),
7:   prepareCity = prepareRegionalCity }) {
8:   let state = Object.freeze({ phase: "idle" });
9:   let current, resident, preparing;
10:   const publish = value => { state = Object.freeze(value); changed(state); };
11:   const keyFor = request => `${request.source}/${request.place}`;
12: 
13:   async function load(owned) {
14:     const { request, key, controller } = owned;
15:     const { signal } = controller;
16:     try {
17:       signal.throwIfAborted();
18:       const query = new URLSearchParams({ place: request.place });
19:       const response = await fetchCity(`/api/map/city/${request.source}?${query}`,
20:         { headers: { Accept: "application/json" }, cache: "no-store", signal });
21:       signal.throwIfAborted();
22:       if (!response.ok) throw new Error(`Could not prepare city (${response.status})`);
23:       const document = await response.text();
24:       signal.throwIfAborted();
25:       const runtime = await runtimePromise;
26:       signal.throwIfAborted();
27:       // Release the previous map owner's preparation before beginning another.
28:       // Actor scene preparation has independent ownership and can run alongside.
29:       while (preparing) {
30:         await preparing.catch(() => {});
31:         signal.throwIfAborted();
32:       }
33:       const ownedPreparation = prepareCity(runtime, document, { signal });
34:       preparing = ownedPreparation;
35:       let preparation;
36:       try { preparation = await ownedPreparation; }
37:       finally { if (preparing === ownedPreparation) preparing = undefined; }
38:       try {
39:         signal.throwIfAborted();
40:         // Native installation may fail after accepting the command. Residency
41:         // requires its acknowledgement, not merely successful command sending.
42:         // Once replacement is queued, the previous city may be displaced even
43:         // if this request is cancelled before that acknowledgement arrives.
44:         resident = undefined;
45:         await install({ request, document, preparation, signal });
46:         signal.throwIfAborted();
47:       } catch (cause) {
48:         runtime.wasm_cancel_generation(preparation);
49:         throw cause;
50:       }
51:       resident = { request, key };
52:       publish({ phase: "prepared", request });
53:       return { status: "prepared", request };
54:     } catch (cause) {
55:       if (signal.aborted || current !== owned) return { status: "superseded" };
56:       publish({ phase: "failed", request, cause });
57:       return { status: "failed", request, cause };
58:     } finally {
59:       if (current === owned) current = undefined;
60:     }
61:   }
62: 
63:   const controller = {
64:     get state() { return state; },
65:     request({ source, place }, { retry = false } = {}) {
66:       if (typeof source !== "string" || !/^[a-f0-9]{64}$/.test(source)
67:         || typeof place !== "string" || !/^place:v1:settlement:(?:[a-f0-9]{2})+$/.test(place)) {
68:         throw new Error("Invalid focused settlement request");
69:       }
70:       const request = Object.freeze({ source, place }), key = keyFor(request);
71:       if (resident?.key === key) {
72:         current?.controller.abort(); current = undefined;
73:         if (state.phase !== "prepared" || keyFor(state.request) !== key) {
74:           publish({ phase: "prepared", request });
75:         }
76:         return Promise.resolve({ status: "reused", request });
77:       }
78:       if (current?.key === key) return current.promise;
79:       if (!retry && state.phase === "failed" && keyFor(state.request) === key) {
80:         return Promise.resolve({ status: "failed", request, cause: state.cause });
81:       }
82:       current?.controller.abort();
83:       const owned = { request, key, controller: new AbortController() };
84:       current = owned;
85:       owned.promise = Promise.resolve().then(() => load(owned));
86:       publish({ phase: "loading", request });
87:       return owned.promise;
88:     },
89:     retry() {
90:       return state.phase === "failed" ? controller.request(state.request, { retry: true })
91:         : Promise.resolve({ status: "unchanged" });
92:     },
93:     cancel() {
94:       current?.controller.abort(); current = undefined;
95:       publish(resident ? { phase: "prepared", request: resident.request } : { phase: "idle" });
96:     },
97:   };
98:   return controller;
99: }

