261:         warn!(error = %error.0, "Could not assemble focused map city");
262:         let root = pending.root;
263:         residency.pending = None;
264:         if let Some(status) = &mut residency.status {
265:             *status = InstallationStatus::failed(status.preparation, InstallationFailure::Assembly);
266:         }
267:         if let Ok(entity) = world.get_entity_mut(root) {
268:             entity.despawn();
269:         }
270:         return;
271:     }
272:     if world.get::<CityAssemblyPublished>(pending.root).is_none()
273:         || !buildings::city_gpu_ready(PresentationOwner::RegionalMap)
274:     {
275:         return;
276:     }
277:     if let Some(pending) = residency.pending.take()
278:         && let Some(old) = residency.installed.replace(pending)
279:         && let Ok(entity) = world.get_entity_mut(old.root)
280:     {
281:         entity.despawn();
282:     }
283:     residency.settled_frames = 0;
284: }

