309: fn prepare(
310:     scenes: Res<CityGpuScenes>,
311:     pipelines: Res<Pipelines>,
312:     cache: Res<PipelineCache>,
313:     buffers: Res<RenderAssets<GpuShaderBuffer>>,
314:     device: Res<RenderDevice>,
315:     queue: Res<RenderQueue>,
316:     views: Query<CityView, Without<Camera2d>>,
317:     mut prepared: ResMut<CityViews>,
318:     mut scratch: ResMut<scratch::Scratch>,
319: ) {
320:     let resources = GpuResources {
321:         pipelines: &pipelines,
322:         cache: &cache,
323:         buffers: &buffers,
324:         device: &device,
325:         queue: &queue,
326:     };
327:     for owner in PresentationOwner::ALL {
328:         resources.prepare_owner(
329:             owner,
330:             scenes.owners.get(owner),
331:             &views,
332:             prepared.owners.get_mut(owner),
333:             scratch.owners.get_mut(owner),
334:         );

