15:             (
16:                 storage_buffer_read_only::<Vec4>(false),
17:                 storage_buffer_read_only::<assembly::Building>(false),
18:                 storage_buffer_read_only::<UVec2>(false),
19:                 storage_buffer_read_only::<assembly::DrawRange>(false),
20:                 storage_buffer_read_only::<u32>(false),
21:                 storage_buffer_read_only::<u32>(false),
22:                 storage_buffer_read_only::<CityFrame>(false),
23:             ),
