39: #[derive(Default)]
40: pub(super) struct CityScratch {
41:     pub batches: Vec<Batch>,
42:     source: Option<AssetId<ShaderBuffer>>,
43:     pub slots: usize,
44: }
45: 
46: impl CityScratch {
47:     pub fn prepare(
48:         &mut self,
49:         scene: &CityGpuScene,
50:         slots: usize,
51:         buffers: &RenderAssets<GpuShaderBuffer>,
52:         device: &RenderDevice,
53:         queue: &RenderQueue,
54:         cache: &PipelineCache,
55:     ) -> bool {
56:         if scene.count == 0 {
57:             *self = Self::default();
58:             return false;
59:         }
60:         let source = Some(scene.buildings.id());
61:         if self.source == source && self.slots >= slots {
62:             return true;
63:         }
64:         let (Some(buildings), Some(frame)) = (
65:             buffers.get(&scene.buildings),
66:             buffers.get(&scene.frame_buffer),
67:         ) else {
68:             return false;
69:         };
70:         let layout = cache.get_bind_group_layout(&geometry_layout());
71:         let mut prepared = Vec::new();
72:         let mut bytes = 0;
73:         for batch in scene.batches.iter() {
74:             let (Some(vertices), Some(indices), Some(ranges), Some(owners)) = (
75:                 buffers.get(&batch.vertices),
76:                 buffers.get(&batch.indices),
77:                 buffers.get(&batch.source),
78:                 buffers.get(&batch.owners),
79:             ) else {
80:                 return false;
81:             };
82:             let size = u64::from(batch.capacity) * slots as u64 * size_of::<UVec2>() as u64;
83:             if size > device.limits().max_storage_buffer_binding_size {
84:                 warn!(
85:                     size,
86:                     "City visibility scratch exceeds device binding capacity"
87:                 );
88:                 return false;
89:             }
90:             let visible = device.create_buffer(&BufferDescriptor {
91:                 label: Some("city camera-group visibility"),
92:                 size,
93:                 usage: BufferUsages::STORAGE,
94:                 mapped_at_creation: false,
95:             });
96:             let indirect = device.create_buffer(&BufferDescriptor {
97:                 label: Some("city camera-group draws"),
98:                 size: slots as u64 * 16,
99:                 usage: BufferUsages::STORAGE
100:                     | BufferUsages::INDIRECT
101:                     | BufferUsages::VERTEX
102:                     | BufferUsages::COPY_DST,
103:                 mapped_at_creation: false,
104:             });
105:             let words: Vec<u8> = (0..slots)
106:                 .flat_map(|slot| {
107:                     [VERTICES_PER_CLUSTER, 0, 0, slot as u32 * batch.capacity]
108:                         .into_iter()
109:                         .flat_map(u32::to_le_bytes)
110:                 })
111:                 .collect();
112:             queue.write_buffer(&indirect, 0, &words);
113:             let geometry = device.create_bind_group(
114:                 "city indexed geometry",
115:                 &layout,
116:                 &BindGroupEntries::sequential((
117:                     vertices.buffer.as_entire_binding(),
118:                     buildings.buffer.as_entire_binding(),
119:                     visible.as_entire_binding(),
120:                     ranges.buffer.as_entire_binding(),
121:                     indices.buffer.as_entire_binding(),
122:                     owners.buffer.as_entire_binding(),
123:                     frame.buffer.as_entire_binding(),
124:                 )),
125:             );
126:             prepared.push(Batch {
127:                 geometry,
128:                 visible,
129:                 indirect,
130:             });
131:             bytes += size + slots as u64 * 16;
132:         }
133:         self.batches = prepared;
134:         self.source = source;
135:         self.slots = slots;
136:         info!(slots, bytes, "GPU city camera-group scratch");
137:         true
138:     }
139: }

