1: //! Affine handoff from city east/up/north to geographic east/up/south.
2: use super::{CityGpuScenes, PresentationOwner};
3: use adventuresim_tactical_core::regional_city::RegionalCityInput;
4: use adventuresim_world_schema::coordinates::{
5:     Wgs84CoordinateMicrodegrees, terrain_projection::NativeTerrainCoordinate,
6: };
7: use bevy::{
8:     prelude::*,
9:     render::{render_resource::ShaderType, storage::ShaderBuffer},
10: };
11: 
12: /// The east scale follows the shared sampler projection. The sign corrects
13: /// winding and tangent handedness; other vector lanes are alignment padding.
14: #[derive(Clone, Copy, Debug, PartialEq, ShaderType)]
15: pub(in crate::presentation) struct CityFrame {
16:     pub(super) world_from_city: Mat4,
17:     normal_from_city: Mat4,
18:     handedness: Vec4,
19: }
20: 
21: #[derive(Debug, thiserror::Error)]
22: pub(in crate::presentation) enum CityFrameError {
23:     #[error("installed city frame buffer is unavailable")]
24:     Buffer,
25: }
26: 
27: impl Default for CityFrame {
28:     fn default() -> Self {
29:         Self {
30:             world_from_city: Mat4::IDENTITY,
31:             normal_from_city: Mat4::IDENTITY,
32:             handedness: Vec4::X,
33:         }
34:     }
35: }
36: 
37: impl CityFrame {
38:     /// Conservative radius scale for projected sphere level selection.
39:     pub(super) fn radius_scale(self) -> f32 {
40:         self.world_from_city.x_axis.x.max(1.0)
41:     }
42: 
43:     /// Native mesh adapter; columns carry east/up/north city metres into the
44:     /// current east/up/south map frame. This includes absolute source elevation.
45:     pub(in crate::presentation) fn world_from_city(self) -> Mat4 {
46:         self.world_from_city
47:     }
48: 
49:     pub(in crate::presentation) fn from_geographic_city(
50:         city: &RegionalCityInput,
51:         window_origin: Wgs84CoordinateMicrodegrees,
52:     ) -> Self {
53:         let projection =
54:             NativeTerrainCoordinate::from(window_origin.to_e7()).frame_from(city.origin().into());
55:         let offset = projection.origin;
56:         // Native GPU port: metres relative to the current terrain window,
57:         // including the city's absolute source elevation. Reflection changes
58:         // north-positive local Z into the map's south-positive world Z.
59:         let translation = Vec3::new(
60:             offset.east_metres as f32,
61:             f32::from(city.input().absolute_elevation_metres.get()),
62:             -offset.north_metres as f32,
63:         );
64:         let world_from_city = Mat4::from_scale_rotation_translation(
65:             Vec3::new(projection.east_scale as f32, 1.0, -1.0),
66:             Quat::IDENTITY,
67:             translation,
68:         );
69:         Self {
70:             world_from_city,
71:             normal_from_city: world_from_city.inverse().transpose(),
72:             handedness: -Vec4::X,
73:         }
74:     }
75: 
76:     /// Moving the terrain window updates this small buffer; building placement
77:     /// and geometry buffers remain resident in their canonical city frame.
78:     pub(in crate::presentation) fn install(
79:         self,
80:         world: &mut World,
81:         owner: PresentationOwner,
82:     ) -> Result<(), CityFrameError> {
83:         world.init_resource::<CityGpuScenes>();
84:         let scene = world.resource::<CityGpuScenes>().owners.get(owner);
85:         if scene.frame == self {
86:             return Ok(());
87:         }
88:         if scene.count != 0 {
89:             let handle = scene.frame_buffer.clone();
90:             let mut buffers = world.resource_mut::<Assets<ShaderBuffer>>();
91:             buffers
92:                 .get_mut(&handle)
93:                 .ok_or(CityFrameError::Buffer)?
94:                 .set_data(self);
95:         }
96:         world
97:             .resource_mut::<CityGpuScenes>()
98:             .owners
99:             .get_mut(owner)
100:             .frame = self;
101:         Ok(())
102:     }
103: }

