1: //! Loading stages and the rules that decide when a load is ready or stuck.
2: use crate::presentation::pipeline_readiness::SETTLED_RENDER_FRAMES;
3: use std::{fmt, time::Duration};
4: 
5: /// How long every stage may stand still before the load counts as stuck. Long
6: /// enough for one slow browser pipeline compile; the connection has no timeout
7: /// of its own, so this also bounds an unanswered connect. Measured in game
8: /// time, because a browser stops running frames in a background tab and the
9: /// wall clock would fail the load the moment the tab returned.
10: const STALL_LIMIT: Duration = Duration::from_secs(90);
11: 
12: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
13: pub(super) enum LoadingStage {
14:     Connection,
15:     Character,
16:     Textures,
17:     Terrain,
18:     Vista,
19:     Trees,
20:     GroundCover,
21:     Sky,
22:     Equipment,
23:     Pose,
24:     Shaders,
25: }
26: 
27: impl LoadingStage {
28:     pub(super) const ALL: [Self; 11] = [
29:         Self::Connection,
30:         Self::Character,
31:         Self::Textures,
32:         Self::Terrain,
33:         Self::Vista,
34:         Self::Trees,
35:         Self::GroundCover,
36:         Self::Sky,
37:         Self::Equipment,
38:         Self::Pose,
39:         Self::Shaders,
40:     ];
41: 
42:     pub(super) fn label(self) -> &'static str {
43:         match self {
44:             Self::Connection => "Connecting to the server",
45:             Self::Character => "Joining the scene",
46:             Self::Textures => "Loading textures",
47:             Self::Terrain => "Shaping the terrain",
48:             Self::Vista => "Raising the distant landscape",
49:             Self::Trees => "Growing trees",
50:             Self::GroundCover => "Laying ground cover",
51:             Self::Sky => "Lighting the sky",
52:             Self::Equipment => "Fitting equipment",
53:             Self::Pose => "Posing your character",
54:             Self::Shaders => "Compiling shaders",
55:         }
56:     }
57: }
58: 
59: #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
60: pub(super) struct StageProgress {
61:     pub(super) completed: usize,
62:     pub(super) total: usize,
63: }
64: 
65: impl StageProgress {
66:     pub(super) const PENDING: Self = Self {
67:         completed: 0,
68:         total: 1,
69:     };
70:     pub(super) const FINISHED: Self = Self {
71:         completed: 1,
72:         total: 1,
73:     };
74: 
75:     pub(super) fn from_flag(finished: bool) -> Self {
76:         if finished {
77:             Self::FINISHED
78:         } else {
79:             Self::PENDING
80:         }
81:     }
82: 
83:     pub(super) fn is_finished(self) -> bool {
84:         self.total > 0 && self.completed >= self.total
85:     }
86: 
87:     pub(super) fn fraction(self) -> f32 {
88:         if self.total == 0 {
89:             return 0.0;
90:         }
91:         self.completed.min(self.total) as f32 / self.total as f32
92:     }
93: }
94: 
95: /// One entry per [`LoadingStage`], in [`LoadingStage::ALL`] order.
96: #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
97: pub(super) struct LoadingProgress {
98:     stages: [StageProgress; LoadingStage::ALL.len()],
99: }
100: 
101: impl LoadingProgress {
102:     pub(super) fn get(&self, stage: LoadingStage) -> StageProgress {
103:         self.stages[stage as usize]
104:     }
105: 
106:     pub(super) fn set(&mut self, stage: LoadingStage, progress: StageProgress) {
107:         self.stages[stage as usize] = progress;
108:     }
109: 
110:     fn first_unfinished(&self) -> Option<LoadingStage> {
111:         LoadingStage::ALL
112:             .into_iter()
113:             .find(|stage| !self.get(*stage).is_finished())
114:     }
115: }
116: 
117: /// Turns a shrinking backlog into progress. The size of a backlog is unknown
118: /// up front, so its largest observed size stands in for the total.
119: #[derive(Clone, Copy, Debug, Default)]
120: pub(super) struct BacklogPeak(usize);
121: 
122: impl BacklogPeak {
123:     pub(super) fn observe(&mut self, pending: usize) -> StageProgress {
124:         self.0 = self.0.max(pending);
125:         if self.0 == 0 {
126:             return StageProgress::FINISHED;
127:         }
128:         StageProgress {
129:             completed: self.0 - pending,
130:             total: self.0,
131:         }
132:     }
133: }
134: 
135: pub(super) enum RunVerdict {
136:     Waiting,
137:     Ready,
138:     Stalled(LoadingStage),
139: }
140: 
141: /// One attempt at loading a scene.
142: pub(super) struct LoadingRun {
143:     pub(super) progress: LoadingProgress,
144:     pub(super) trees: BacklogPeak,
145:     pub(super) pipelines: BacklogPeak,
146:     settled_frames: usize,
147:     last_advance: Duration,
148: }
149: 
150: impl LoadingRun {
151:     pub(super) fn new(now: Duration) -> Self {
152:         Self {
153:             progress: LoadingProgress::default(),
154:             trees: BacklogPeak::default(),
155:             pipelines: BacklogPeak::default(),
156:             settled_frames: 0,
157:             last_advance: now,
158:         }
159:     }
160: 
161:     pub(super) fn observe(&mut self, progress: LoadingProgress, now: Duration) -> RunVerdict {
162:         if progress != self.progress {
163:             self.last_advance = now;
164:         }
165:         self.progress = progress;
166:         let Some(stage) = progress.first_unfinished() else {
167:             self.settled_frames += 1;
168:             return if self.settled_frames >= SETTLED_RENDER_FRAMES {
169:                 RunVerdict::Ready
170:             } else {
171:                 RunVerdict::Waiting
172:             };
173:         };
174:         self.settled_frames = 0;
175:         if now.saturating_sub(self.last_advance) >= STALL_LIMIT {
176:             RunVerdict::Stalled(stage)
177:         } else {
178:             RunVerdict::Waiting
179:         }
180:     }
181: }
182: 
183: /// Why a load stopped. Presentation text comes from [`fmt::Display`].
184: #[derive(Clone, Debug, Eq, PartialEq)]
185: pub(super) enum LoadingFailure {
186:     ConnectionLost(String),
187:     Asset(String),
188:     Stalled(LoadingStage),
189: }
190: 
191: impl fmt::Display for LoadingFailure {
192:     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
193:         match self {
194:             Self::ConnectionLost(reason) => write!(formatter, "Connection lost: {reason}"),
195:             Self::Asset(path) => write!(formatter, "Could not load {path}"),
196:             Self::Stalled(stage) => {
197:                 write!(formatter, "Loading stopped at: {}", stage.label())
198:             }
199:         }
200:     }
201: }

