12: /// Scatter and instanced grass each mark a scene when generated.
13: const GROUND_LAYERS_PER_SCENE: usize = 2;
14: 
15: #[derive(SystemParam)]
16: pub(super) struct LoadingSources<'w, 's> {
17:     client: Res<'w, State<ClientState>>,
18:     players: Query<'w, 's, Option<&'static PoseBufferRig>, With<ClientPlayer>>,
19:     textures: Res<'w, ProceduralTextureResidency>,
20:     scene: SceneReadiness<'w, 's>,
21:     sky: Res<'w, AtmosphereIblCache>,
22:     settings: Res<'w, TacticalGraphicsSettings>,
23: }
24: 
25: impl LoadingSources<'_, '_> {
26:     /// Equipment and pipelines are passed in because their sources are checked
27:     /// fallibly or live in the render world.
28:     pub(super) fn progress(
29:         &self,
30:         run: &mut LoadingRun,
31:         equipment_settled: bool,
32:         waiting_pipelines: usize,
33:     ) -> LoadingProgress {
34:         let scene = self.scene.counts();
35:         let scene_known = scene.scenes > 0;
36:         let local_player = self.players.iter().next();
37:         let trees = run.trees.observe(scene.pending_trees);
38:         let pipelines = run.pipelines.observe(waiting_pipelines);
39:         let mut progress = LoadingProgress::default();
40:         progress.set(
41:             LoadingStage::Connection,
42:             StageProgress::from_flag(*self.client.get() == ClientState::Connected),
43:         );
44:         progress.set(
45:             LoadingStage::Character,
46:             StageProgress::from_flag(local_player.is_some()),
47:         );
48:         progress.set(
49:             LoadingStage::Textures,
50:             StageProgress {
51:                 completed: self
52:                     .textures
53:                     .installed_count(PROCEDURAL_TEXTURE_CATALOGUE.iter().map(|recipe| recipe.id)),
54:                 total: PROCEDURAL_TEXTURE_CATALOGUE.len(),
55:             },
56:         );
57:         progress.set(
58:             LoadingStage::Terrain,
59:             scene_progress(scene_known, scene.terrain_presented, scene.scenes),
60:         );
61:         progress.set(
62:             LoadingStage::Vista,
63:             StageProgress::from_flag(scene.vista_presented),
64:         );
65:         progress.set(
66:             LoadingStage::Trees,
67:             if scene_known {
68:                 trees
69:             } else {
70:                 StageProgress::PENDING
71:             },
72:         );
73:         progress.set(
74:             LoadingStage::GroundCover,
75:             scene_progress(
76:                 scene_known,
77:                 scene.ground_layers_presented,
78:                 scene.scenes * GROUND_LAYERS_PER_SCENE,
79:             ),
80:         );
81:         progress.set(
82:             LoadingStage::Sky,
83:             StageProgress::from_flag(self.sky.is_ready(&self.settings)),
84:         );
85:         progress.set(
86:             LoadingStage::Equipment,
87:             StageProgress::from_flag(local_player.is_some() && equipment_settled),
88:         );
89:         progress.set(
90:             LoadingStage::Pose,
91:             StageProgress::from_flag(
92:                 local_player
93:                     .flatten()
94:                     .is_some_and(PoseBufferRig::has_presented_pose),
95:             ),
96:         );
97:         progress.set(LoadingStage::Shaders, pipelines);
98:         progress
99:     }
100: }
