25: fn wait_for_installation(
26:     view: Option<Res<super::protocol::StrategicView>>,
27:     installed: Res<super::status::SceneInstallationReady>,
28:     scene: Option<Res<super::RetainedScene>>,
29:     mut opened: Local<bool>,
30:     mut previous_scene: Local<Option<Entity>>,
31:     mut cameras: Query<
32:         &mut VisibleEntities,
