53:     // running. Only postpone mesh specialization until the final environment is
54:     // installed. Reopen for each city; weather changes within an installed city
55:     // never close this gate. The first frame of a replacement ignores the old
56:     // city's readiness, which is published at the end of the previous frame.
57:     for mut visible in &mut cameras {
58:         visible.get_mut(TypeId::of::<Mesh3d>()).clear();
59:     }
