25: impl RangeGroups {
26:     pub fn push(&mut self, range: (u32, u32, u32), owners: Arc<[u32]>) {
27:         let index = *self.identities.entry(owners.as_ptr()).or_insert_with(|| {
28:             let index = self.owners.len();
29:             self.owners.push(owners);
30:             index
31:         });
32:         self.ranges.entry(range).or_default().push(index);
33:     }
