35:     pub fn finish(self) -> InstanceRanges {
36:         let mut ranges: Vec<_> = self.ranges.into_iter().collect();
37:         ranges.sort_unstable_by_key(|(key, _)| *key);
38:         let mut lists = HashMap::<Vec<usize>, (u32, u32)>::new();
39:         let mut result = InstanceRanges {
40:             ranges: Vec::new(),
41:             owners: Vec::new(),
42:             capacity: 0,
43:         };
44:         for ((start, count, flags), mut groups) in ranges {
45:             groups.sort_unstable();
46:             let (owner_start, length) = *lists.entry(groups.clone()).or_insert_with(|| {
47:                 let mut owners: Vec<_> = groups
48:                     .iter()
49:                     .flat_map(|&group| self.owners[group].iter().copied())
50:                     .collect();
51:                 owners.sort_unstable();
52:                 let start = result.owners.len() as u32;
53:                 let length = owners.len() as u32;
54:                 result.owners.extend(owners);
55:                 (start, length)
56:             });
57:             let clusters = count.div_ceil(VERTICES_PER_CLUSTER);
