1: //! Pack each prototype once, then reference its shared placement list.
2: use super::*;
3: 
4: pub(super) fn pack(world: &World, groups: Vec<input::Group>) -> AssemblyResult<PackedCity> {
5:     let mut geometry = geometry::Geometry::default();
6:     let mut meshes = HashMap::new();
7:     let mut components = HashMap::new();
8:     let mut buildings = Vec::new();
9:     let mut batches: HashMap<_, (Handle<StandardMaterial>, ranges::RangeGroups)> = HashMap::new();
10:     for group in groups {
11:         let mut radius: f32 = 0.0;
12:         let mut levels = 0;
13:         for part in &group.parts {
14:             let slices = match meshes.entry(part.mesh.id()) {
15:                 std::collections::hash_map::Entry::Occupied(entry) => entry.into_mut(),
16:                 std::collections::hash_map::Entry::Vacant(entry) => entry.insert(
17:                     geometry.insert(
18:                         world
19:                             .resource::<Assets<Mesh>>()
20:                             .get(&part.mesh)
21:                             .ok_or(AssemblyError::MissingMesh)?,
22:                     ),
23:                 ),
24:             };
25:             radius = radius.max(
26:                 slices.iter().map(|slice| slice.radius).fold(0.0, f32::max)
27:                     + part.local_transform.w_axis.truncate().length(),
28:             );
29:             levels |= 1 << (part.level & LOD_LEVEL_MASK);
30:         }
31:         let Some(first) = group.parts.first() else {
32:             continue;
33:         };
34:         let owners: Arc<[u32]> = group
35:             .placements
36:             .iter()
37:             .map(|&transform| {
38:                 let index = buildings.len() as u32;
39:                 buildings.push(Building {
40:                     transform,
41:                     bounds: transform.w_axis.truncate().extend(radius),
42:                     uv_offset: Vec4::ZERO,
43:                     levels: first
44:                         .fade
45:                         .as_ref()
46:                         .map_or(UVec4::new(levels, 0, 0, 0), |fade| {
47:                             UVec4::new(levels, 1, fade.start.to_bits(), fade.end.to_bits())
48:                         }),
49:                 });
50:                 index
51:             })
52:             .collect();
53:         for part in &group.parts {
54:             let component = component_index(part, &mut buildings, &mut components)?;
55:             for slice in &meshes[&part.mesh.id()] {
56:                 batches
57:                     .entry((slice.page, part.material.id()))
58:                     .or_insert_with(|| (part.material.clone(), ranges::RangeGroups::default()))
59:                     .1
60:                     .push(
61:                         (slice.start, slice.count, part.level | component),
62:                         owners.clone(),
63:                     );
64:             }
65:         }
66:     }
67:     Ok(PackedCity {
68:         geometry,
69:         buildings,
70:         batches: batches
71:             .into_iter()
72:             .map(|(key, (handle, groups))| (key, (handle, groups.finish())))
73:             .collect(),
74:     })
75: }

