1: //! Static vista furniture shares canonical geometry and GPU visibility records.
2: use super::*;
3: use crate::presentation::{
4:     furniture::{VistaFurniturePresentation, outdoor_range},
5:     interior_lighting::InteriorMaterialSource,
6: };
7: use adventuresim_tactical_core::prelude::{FurnitureLocation, SceneFurniture};
8: 
9: pub(super) fn parts(world: &mut World) -> Vec<Part> {
10:     let owners: HashMap<_, _> = world
11:         .query_filtered::<(Entity, &SceneFurniture), With<VistaFurniturePresentation>>()
12:         .iter(world)
13:         .filter(|(_, furniture)| matches!(furniture.location, FurnitureLocation::Outdoor { .. }))
14:         .map(|(entity, furniture)| (entity, outdoor_range(furniture.key.kind())))
15:         .collect();
16:     let parts: Vec<_> = world
17:         .query::<(
18:             Entity,
19:             &ChildOf,
20:             &GlobalTransform,
21:             &Mesh3d,
22:             Option<&MeshMaterial3d<StandardMaterial>>,
23:             Option<&InteriorMaterialSource>,
24:         )>()
25:         .iter(world)
26:         .filter_map(|(entity, parent, transform, mesh, standard, interior)| {
27:             let fade = owners.get(&parent.parent())?.clone();
28:             let material = standard
29:                 .map(|material| material.0.clone())
30:                 .or_else(|| interior.map(|material| material.0.clone()))?;
31:             Some(Part {
32:                 entity: Some(entity),
33:                 root: parent.parent(),
34:                 transform: transform.to_matrix(),
35:                 local_transform: Mat4::IDENTITY,
36:                 uv_offset: Vec2::ZERO,
37:                 mesh: mesh.0.clone(),
38:                 material,
39:                 level: 2,
40:                 fade: Some(fade),
41:             })
42:         })
43:         .collect();
44:     info!(
45:         instances = owners.len(),
46:         parts = parts.len(),
47:         "GPU city outdoor furniture"
48:     );
49:     parts
50: }

