17: pub(super) fn outdoor_range(kind: FurnitureKind) -> std::ops::Range<f32> {
18:     match kind {
19:         FurnitureKind::CanvasStall => STALL_FADE_METRES,
20:         _ => SMALL_FURNITURE_FADE_METRES,
21:     }
