31: impl Plugin for FurniturePresentationPlugin {
32:     fn build(&self, app: &mut App) {
33:         app.init_resource::<FurnitureMeshCache>()
34:             .add_observer(on_furniture_added)
35:             .add_observer(on_vista_furniture)
36:             .add_systems(
37:                 PostUpdate,
38:                 visibility::update_interior_visibility
39:                     .after(bevy::transform::TransformSystems::Propagate)
40:                     .before(bevy::camera::visibility::VisibilitySystems::VisibilityPropagate),
41:             );
42:     }
43: }
