45: #[derive(Default, Resource)]
46: struct FurnitureMeshCache(BTreeMap<FurnitureKey, Vec<FurnitureBatch>>);
47: 
48: struct FurnitureBatch {
49:     mesh: Handle<Mesh>,
50:     material: BuildingLodMaterial,
51: }
52: 
53: fn on_furniture_added(
54:     event: On<Add, SceneFurniture>,
55:     furniture: Query<&SceneFurniture>,
56:     mut commands: Commands,
57:     mut cache: ResMut<FurnitureMeshCache>,
58:     mut meshes: ResMut<Assets<Mesh>>,
59:     materials: Res<TacticalBuildingMaterials>,
60: ) -> Result {
61:     let instance = furniture.get(event.entity)?;
62:     let batches = match cache.0.entry(instance.key) {
63:         std::collections::btree_map::Entry::Occupied(entry) => entry.into_mut(),
64:         std::collections::btree_map::Entry::Vacant(entry) => {
65:             let recipe = instance.key.recipe()?;
66:             entry.insert(
67:                 recipe
68:                     .meshes
69:                     .iter()
70:                     .map(|batch| FurnitureBatch {
71:                         mesh: meshes.add(recipe_mesh(batch, Vec3::ZERO)),
72:                         material: batch.material,
73:                     })
74:                     .collect(),
75:             )
76:         }
77:     };
78:     let range = match instance.location {
79:         FurnitureLocation::Interior { .. } => None,
80:         FurnitureLocation::Outdoor { .. } => Some(VisibilityRange {
81:             start_margin: 0.0..0.0,
82:             end_margin: outdoor_range(instance.key.kind()),
83:             use_aabb: false,
84:         }),
85:     };
86:     let palette = materials.for_building(instance.id.0);
87:     commands
88:         .entity(event.entity)
89:         .insert(Visibility::default())
90:         .with_children(|parent| {
91:             for batch in batches.iter() {
92:                 let mut mesh = parent.spawn((
93:                     Name::new(format!("{:?} furniture", instance.key.kind())),
94:                     PresentedFurnitureMesh {
95:                         material: batch.material,
96:                     },
97:                     Mesh3d(batch.mesh.clone()),
98:                     MeshMaterial3d(palette.get(batch.material)),
99:                     Transform::IDENTITY,
100:                 ));
101:                 if let Some(range) = &range {
102:                     mesh.insert(range.clone());
103:                 }
104:             }
105:         });
106:     Ok(())
107: }
108: 
109: #[derive(Component)]
110: pub(super) struct VistaFurniturePresentation;
111: fn on_vista_furniture(
112:     bundle: On<SceneVistaBundle>,
113:     mut commands: Commands,
114:     existing: Query<Entity, With<VistaFurniturePresentation>>,
115: ) {
116:     for entity in &existing {
117:         commands.entity(entity).despawn();
118:     }
119:     for instance in &bundle.distant_furniture {
120:         commands.spawn((
121:             VistaFurniturePresentation,
122:             instance.scene,
123:             Transform::from_translation(instance.position_metres.metres())
124:                 .with_rotation(Quat::from_rotation_y(instance.orientation.yaw_radians())),
125:         ));
126:     }
127: }

