1: use super::*;
2: use crate::scene_coordinates::ScenePlanPoint;
3: use bevy::math::Vec3Swizzles;
4: use candidates::Candidate;
5: use fabelgeist_determinism::StreamId;
6: use ground::PlacementGround;
7: 
8: const MAX_SUPPORT_ERROR_METRES: f32 = 0.045;
9: const MAX_GROUP_GRADE: f32 = 0.08;
10: const INSTANCE_DOMAIN: StreamId = StreamId::new("furniture.outdoor-identity");
11: 
12: pub(super) fn generate(
13:     input: &TacticalSceneInput,
14:     buildings: &[sites::FurnitureSite],
15:     terrain: &SceneTerrain,
16:     ground: &SceneGround,
17:     obstacles: &[GeneratedObstacle],
18: ) -> Result<FurnitureLayout, super::super::SceneInputError> {
19:     let mut layout = FurnitureLayout {
20:         reserved_routes: reservations::routes(input, buildings)?,
21:         ..Default::default()
22:     };
23:     let mut occupied = occupancy::Occupancy::default();
24:     let support = PlacementGround::new(input, terrain, ground);
25:     let market = candidates::market(input)?;
26:     layout.reserved_routes.extend(market.aisles);
27:     for footprint in reservations::obstacles(input, terrain, buildings, obstacles)?
28:         .into_iter()
29:         .chain(layout.reserved_routes.iter().copied())
30:     {
31:         occupied.insert(footprint);
32:     }
33:     for candidate in market.groups {
34:         accept(input, &support, candidate, &mut occupied, &mut layout);
35:     }
36:     let mut ordered = buildings.iter().collect::<Vec<_>>();
37:     ordered.sort_by_key(|building| building.placement.id);
38:     for building in ordered {
39:         let mut accepted = 0;
40:         for candidate in candidates::building(input, building)? {
41:             if accept(input, &support, candidate, &mut occupied, &mut layout) {
42:                 accepted += 1;
43:                 if accepted >= candidates::group_limit(building) {
44:                     break;
45:                 }
46:             }
47:         }
48:     }
49:     Ok(layout)
50: }
51: 
52: fn accept(
53:     input: &TacticalSceneInput,
54:     support: &PlacementGround,
55:     candidate: Candidate,
56:     occupied: &mut occupancy::Occupancy,
57:     layout: &mut FurnitureLayout,
58: ) -> bool {
59:     let footprint = candidate.footprint;
60:     let Some(playable) = support.scope(footprint) else {
61:         return false;
62:     };
63:     if occupied.intersects(footprint) {
64:         return false;
65:     }
66:     let corners = footprint.corners();
67:     if candidate
68:         .market
69:         .is_some_and(|market| !corners.into_iter().all(|corner| market.contains(corner)))
70:     {
71:         return false;
72:     }
73:     let samples = corners
74:         .into_iter()
75:         .map(ScenePlanPoint::from_metres)
76:         .chain([Some(footprint.centre())])
77:         .map(|point| {
78:             let point = point?;
79:             if input
80:                 .landform
81:                 .is_some_and(|landform| landform.transition_collar().contains(point))
82:                 || !support.allows_activity(point)
83:             {
84:                 return None;
85:             }
86:             support.height_at(point)
87:         })
88:         .collect::<Option<Vec<_>>>();
89:     let Some(samples) = samples else {
90:         return false;
91:     };
92:     let min = samples
93:         .iter()
94:         .map(|height| height.metres())
95:         .fold(f32::INFINITY, f32::min);
96:     let max = samples
97:         .into_iter()
98:         .map(|height| height.metres())
99:         .fold(f32::NEG_INFINITY, f32::max);
100:     if max - min > footprint.half_extents().metres().length() * 2.0 * MAX_GROUP_GRADE {
101:         return false;
102:     }
103:     let Some(instances) = supported_instances(&candidate, support) else {
104:         return false;
105:     };
106:     occupied.insert(footprint);
107:     layout.groups.push(FurnitureGroup {
108:         id: candidate.id,
109:         kind: candidate.kind,
110:         anchor: candidate.anchor,
111:         footprint,
112:     });
113:     if matches!(playable, ground::PlacementScope::Playable) {
114:         layout.instances.extend(instances);
115:     } else {
116:         layout.distant_instances.extend(instances);
117:     }
118:     true
119: }
120: 
121: fn supported_instances(
122:     candidate: &Candidate,
123:     support: &PlacementGround,
124: ) -> Option<Vec<GeneratedFurniture>> {
125:     candidate
126:         .items
127:         .iter()
128:         .enumerate()
129:         .map(|(index, item)| {
130:             let centre = ScenePlanPoint::from_metres(
131:                 candidate.footprint.centre().metres()
132:                     + candidate
133:                         .footprint
134:                         .orientation()
135:                         .local_to_world(item.offset.metres().xz()),
136:             )?;
137:             let supports = &item.recipe.support_points_metres;
138:             if supports.is_empty() {
139:                 return None;
140:             }
141:             let heights = supports
142:                 .iter()
143:                 .map(|point| {
144:                     let position = centre.metres()
145:                         + candidate
146:                             .footprint
147:                             .orientation()
148:                             .local_to_world(Vec2::new(point.metres().x, point.metres().z));
149:                     support
150:                         .height_at(ScenePlanPoint::from_metres(position)?)
151:                         .map(|height| height.metres() - point.metres().y)
152:                 })
153:                 .collect::<Option<Vec<_>>>()?;
154:             let min = heights.iter().copied().fold(f32::INFINITY, f32::min);
155:             let max = heights.into_iter().fold(f32::NEG_INFINITY, f32::max);
156:             if max - min > MAX_SUPPORT_ERROR_METRES {
157:                 return None;
158:             }
159:             Some(GeneratedFurniture {
160:                 scene: SceneFurniture {
161:                     id: FurnitureInstanceId(
162:                         INSTANCE_DOMAIN
163:                             .seed(candidate.id.0.into(), &[index as u64])
164:                             .to_u64(),
165:                     ),
166:                     key: item.key,
167:                     location: FurnitureLocation::Outdoor {
168:                         group_id: candidate.id,
169:                     },
170:                 },
171:                 position_metres:
172:                     adventuresim_building_generator::spatial_geometry::Position::from_metres(
173:                         Vec3::new(centre.metres().x, max, centre.metres().y),
174:                     )
175:                     .ok()?,
176:                 orientation: candidate.footprint.orientation(),
177:             })
178:         })
179:         .collect()
180: }

crates/adventuresim-tactical-core/src/scene_input/furniture/candidates/frontage.rs
1: //! Bounded local frontage searches retain door, street and neighbouring-lot access.
2: use super::*;
3: use adventuresim_world_schema::settlement_buildings::BuildingUse;
4: 
5: const FRONTAGE_GAP_METRES: f32 = 0.35;
6: const FRONTAGE_SAMPLES: u64 = 5;
7: const FRONTAGE_END_FRACTION: f32 = 0.8;
8: 
9: fn kind(building: &sites::FurnitureSite) -> Option<FurnitureGroupKind> {
10:     use BuildingUse::*;
11:     match building.placement.program.usage? {
12:         Inn | Stable => Some(FurnitureGroupKind::HorseStop),
13:         Warehouse | Granary | Brewery | Malthouse | Bakehouse | TimberYard | WoadStore | Barn
14:         | WeighHouse | CustomsHouse => Some(FurnitureGroupKind::Receiving),
15:         Dwelling | Rectory | Manor => Some(FurnitureGroupKind::Domestic),
16:         GeneralShop | Smithy | Weaponsmith | Armorer | Tailor | Herbalist | Bookshop | Butcher
17:         | Cooper | Carpenter | Wheelwright | Cobbler | Weaver | Tannery | Dyer | Ropemaker
18:         | Chandler | Potter | Stonecutter | Fishmonger | Apothecary | PrintingHouse | WaterMill
19:         | FullingMill | PaperMill | Sawmill | HorseMill | Windmill | Mint | SaltWorks | Smelter
20:         | AssayHouse | Brickworks | Glassworks => Some(FurnitureGroupKind::Workshop),
21:         _ => None,
22:     }
23: }
24: 
25: pub(in crate::scene_input::furniture) fn group_limit(building: &sites::FurnitureSite) -> usize {
26:     match kind(building) {
27:         Some(FurnitureGroupKind::HorseStop) => 1,
28:         Some(_) => 2,
29:         None => 0,
30:     }
31: }
32: 
33: pub(in crate::scene_input::furniture) fn building(
34:     input: &TacticalSceneInput,
35:     building: &sites::FurnitureSite,
36: ) -> Result<Vec<Candidate>, crate::scene_input::SceneInputError> {
37:     let Some(kind) = kind(building) else {
38:         return Ok(Vec::new());
39:     };
40:     let half = building.half_extents.metres();
41:     let mut candidates = Vec::new();
42:     for slot in 0..FRONTAGE_SAMPLES * 4 {
43:         let candidate = LocalCandidate::new(
44:             input.seed,
45:             slot,
46:             kind,
47:             FurnitureAnchor::Building {
48:                 id: building.placement.id,
49:             },
50:         )?;
51:         let size = candidate.half_extents.metres();
52:         let fraction = ((slot % FRONTAGE_SAMPLES) as f32 / (FRONTAGE_SAMPLES - 1) as f32 * 2.0
53:             - 1.0)
54:             * FRONTAGE_END_FRACTION;
55:         let local = match slot / FRONTAGE_SAMPLES {
56:             0 => Vec2::new(half.x * fraction, -half.y - size.y - FRONTAGE_GAP_METRES),
57:             1 => Vec2::new(half.x + size.x + FRONTAGE_GAP_METRES, half.y * fraction),
58:             2 => Vec2::new(-half.x - size.x - FRONTAGE_GAP_METRES, half.y * fraction),
59:             _ => Vec2::new(half.x * fraction, half.y + size.y + FRONTAGE_GAP_METRES),
60:         };
61:         let candidate = candidate.place(
62:             crate::scene_coordinates::ScenePlanPoint::try_from(
63:                 building.placement.centre_metres.metres()
64:                     + building.placement.orientation.local_to_world(local),
65:             )?,
66:             building.placement.orientation,
67:         )?;
68:         candidates.push(candidate);
69:     }
70:     Ok(candidates)
71: }

