6: const CUSTOMER_AISLE_METRES: f32 = 2.0;
7: const ROW_SEPARATION_METRES: f32 = 0.25;
8: const STALL_SEPARATION_METRES: f32 = 0.25;
9: const BOUNDARY_MARGIN_METRES: f32 = 0.15;
10: const MAX_MARKET_ROWS_PER_HALF: usize = 128;
11: const MAX_ROW_CANDIDATES: usize = 512;
12: const ROW_ID_SHIFT: u32 = 32;
13: 
14: pub(in crate::scene_input::furniture) struct MarketCandidates {
15:     pub groups: Vec<Candidate>,
