19: struct MarketFrame {
20:     centre: Vec2,
21:     orientation: BuildingOrientation,
22:     minimum: Vec2,
23:     maximum: Vec2,
24: }
25: 
26: impl MarketFrame {
27:     fn new(input: &TacticalSceneInput, corners: [Vec2; 4]) -> Option<Self> {
28:         let centre = corners.into_iter().sum::<Vec2>() * 0.25;
29:         let orientation = BuildingOrientation::from_frontage_tangent(corners[1] - corners[0])?;
30:         let mut minimum = Vec2::splat(f32::INFINITY);
31:         let mut maximum = Vec2::splat(f32::NEG_INFINITY);
32:         for corner in corners {
33:             let point = orientation.world_to_local(corner - centre);
34:             minimum = minimum.min(point);
35:             maximum = maximum.max(point);
36:         }
37:         let mut lower_inset = Vec2::ZERO;
38:         let mut upper_inset = Vec2::ZERO;
39:         for edge in 0..4 {
40:             let start = corners[edge];
41:             let end = corners[(edge + 1) % 4];
42:             let tangent = (end - start).normalize_or_zero();
43:             let mut inward = Vec2::new(-tangent.y, tangent.x);
44:             if inward.dot(centre - (start + end) * 0.5) < 0.0 {
45:                 inward = -inward;
46:             }
47:             let clearance = reservations::market_edge_clearance(input, start, end, inward).ok()?
48:                 + BOUNDARY_MARGIN_METRES;
49:             let local_inward = orientation.world_to_local(inward);
50:             let axis = if local_inward.x.abs() > local_inward.y.abs() {
51:                 0
52:             } else {
53:                 1
54:             };
55:             if local_inward[axis] > 0.0 {
56:                 lower_inset[axis] = lower_inset[axis].max(clearance);
57:             } else {
58:                 upper_inset[axis] = upper_inset[axis].max(clearance);
59:             }
60:         }
61:         Some(Self {
62:             centre,
63:             orientation,
64:             minimum: minimum + lower_inset,
65:             maximum: maximum - upper_inset,
66:         })
67:     }
68: 
69:     fn point(&self, local: Vec2) -> Vec2 {
70:         self.centre + self.orientation.local_to_world(local)
71:     }
72: }
