74: pub(in crate::scene_input::furniture) fn market(
75:     input: &TacticalSceneInput,
76: ) -> Result<MarketCandidates, crate::scene_input::SceneInputError> {
77:     let mut result = MarketCandidates {
78:         groups: Vec::new(),
79:         aisles: Vec::new(),
80:     };
81:     let mut row_depth = 0.0_f32;
82:     for variant in FurnitureVariant::ALL {
83:         let LocalReservationBounds {
84:             minimum: min,
85:             maximum: max,
86:         } = reservation_bounds(
87:             FurnitureKey::natural(FurnitureKind::CanvasStall, variant).recipe()?,
88:         );
89:         row_depth = row_depth.max(max.y - min.y);
90:     }
91:     for (index, patch) in input.streets.iter().enumerate() {
92:         let CityStreetPatch::Market { corners_metres, .. } = *patch else {
93:             continue;
94:         };
95:         let Some(frame) = MarketFrame::new(input, corners_metres) else {
96:             continue;
97:         };
98:         for (half, direction) in [-1.0, 1.0].into_iter().enumerate() {
99:             let limit = if direction < 0.0 {
100:                 -frame.minimum.y
101:             } else {
102:                 frame.maximum.y
103:             };
104:             let mut cursor = reservations::MARKET_AISLE_HALF_WIDTH_METRES + BOUNDARY_MARGIN_METRES;
105:             for row in 0..MAX_MARKET_ROWS_PER_HALF {
106:                 if cursor + row_depth > limit {
107:                     break;
108:                 }
109:                 let y = direction * (cursor + row_depth * 0.5);
110:                 MarketRow {
111:                     patch_index: index,
112:                     patch: *patch,
113:                     y,
114:                     row: half * MAX_MARKET_ROWS_PER_HALF + row,
115:                     direction,
116:                 }
117:                 .append(input, &frame, &mut result.groups)?;
118:                 cursor += row_depth;
119:                 if row.is_multiple_of(2) {
120:                     cursor += ROW_SEPARATION_METRES;
121:                 } else {
122:                     cursor += BOUNDARY_MARGIN_METRES;
123:                     let aisle_y = direction * (cursor + CUSTOMER_AISLE_METRES * 0.5);
124:                     result.aisles.push(reservations::route(
125:                         frame.point(Vec2::new(frame.minimum.x, aisle_y)),
126:                         frame.point(Vec2::new(frame.maximum.x, aisle_y)),
127:                         CUSTOMER_AISLE_METRES * 0.5,
128:                     )?);
129:                     cursor += CUSTOMER_AISLE_METRES + BOUNDARY_MARGIN_METRES;
130:                 }
131:             }
132:         }
133:     }
134:     Ok(result)
135: }
