137: struct MarketRow {
138:     patch_index: usize,
139:     patch: CityStreetPatch,
140:     y: f32,
141:     row: usize,
142:     direction: f32,
143: }
144: impl MarketRow {
145:     fn append(
146:         &self,
147:         input: &TacticalSceneInput,
148:         frame: &MarketFrame,
149:         candidates: &mut Vec<Candidate>,
150:     ) -> Result<(), crate::scene_input::SceneInputError> {

144: impl MarketRow {
145:     fn append(
146:         &self,
147:         input: &TacticalSceneInput,
148:         frame: &MarketFrame,
149:         candidates: &mut Vec<Candidate>,
150:     ) -> Result<(), crate::scene_input::SceneInputError> {
151:         let Self {
152:             patch_index,
153:             patch,
154:             y,
155:             row,
156:             direction,
157:         } = *self;
158:         let facing_centre = row.is_multiple_of(2);
159:         let reversed = (direction < 0.0) == facing_centre;
160:         let orientation =
161:             if reversed {
162:                 BuildingOrientation::from_radians(
163:                 frame.orientation.yaw_radians() + std::f32::consts::PI,
164:             )
165: .ok_or(adventuresim_building_generator::spatial_geometry::GeometryError::InvalidProjection)?
166:             } else {
167:                 frame.orientation
168:             };
169:         let mut x = frame.minimum.x;
170:         for column in 0..MAX_ROW_CANDIDATES {
171:             let slot = ((row as u64) << ROW_ID_SHIFT) | column as u64;
172:             let candidate = LocalCandidate::new(
173:                 StreamId::new("furniture.market-anchor").seed(
174:                     input.seed,
175:                     &[
176:                         u64::from(frame.centre.x.to_bits()),
177:                         u64::from(frame.centre.y.to_bits()),
178:                         u64::from(frame.orientation.yaw_radians().to_bits()),
179:                     ],
180:                 ),
181:                 slot,
182:                 FurnitureGroupKind::Vendor,
183:                 FurnitureAnchor::Market {
184:                     patch_index: patch_index as u32,
185:                 },
186:             )?;
187:             let half_width = candidate.half_extents.metres().x;
188:             // Restart beyond the central through-route instead of wasting a crossing slot.
189:             let crossing = reservations::MARKET_AISLE_HALF_WIDTH_METRES + BOUNDARY_MARGIN_METRES;
190:             if x < crossing && x + half_width * 2.0 > -crossing {
191:                 x = crossing;
192:             }
193:             if x + half_width * 2.0 > frame.maximum.x {
194:                 break;
195:             }
196:             let mut candidate = candidate.place(
197:                 crate::scene_coordinates::ScenePlanPoint::try_from(
198:                     frame.point(Vec2::new(x + half_width, y)),
199:                 )?,
200:                 orientation,
201:             )?;
202:             candidate.market = Some(patch);
203:             x += half_width * 2.0 + STALL_SEPARATION_METRES;
204:             candidates.push(candidate);
205:         }
206:         Ok(())
207:     }
208: }

