112: /// Furniture-local X/Z metre bounds assembled by the native clearance kernel.
113: /// These extrema are scratch data; admitted extents cross into LocalCandidate.
114: pub(super) struct LocalReservationBounds {
115:     pub minimum: Vec2,
116:     pub maximum: Vec2,
117: }
118: pub(super) fn reservation_bounds(
119:     recipe: &adventuresim_building_generator::furniture::FurnitureRecipe,
120: ) -> LocalReservationBounds {
121:     let mut min = Vec2::new(
122:         recipe.bounds.min().metres().x,
123:         recipe.bounds.min().metres().z,
124:     );
125:     let mut max = Vec2::new(
126:         recipe.bounds.max().metres().x,
127:         recipe.bounds.max().metres().z,
128:     );
129:     for clearance in &recipe.clearances {
130:         min = min.min(Vec2::new(
131:             clearance.bounds.min().metres().x,
132:             clearance.bounds.min().metres().z,
133:         ));
134:         max = max.max(Vec2::new(
135:             clearance.bounds.max().metres().x,
136:             clearance.bounds.max().metres().z,
137:         ));
138:     }
139:     LocalReservationBounds {
140:         minimum: min,
141:         maximum: max,
142:     }
143: }

