22: impl FurnitureSiteRecipe {
23:     pub fn new(
24:         plan: &BuildingPlan,
25:         bounds: adventuresim_building_generator::spatial_geometry::SpatialBounds<
26:             adventuresim_building_generator::spatial_geometry::Architectural,
27:         >,
28:     ) -> Result<Self, SceneInputError> {
29:         let centre = bounds.centre()?.metres();
30:         let origin = Vec2::new(centre.x, centre.z);
31:         let mut routes = Vec::new();
32:         for opening in plan
33:             .opening_assemblies
34:             .iter()
35:             .filter(|o| o.use_kind == OpeningUse::Door && o.frame.outside_room.is_none())
36:         {
37:             let start = opening.frame.origin - origin;
38:             routes.push(LocalReservation::route(
39:                 start,
40:                 start + opening.frame.outward * reservations::DOOR_APPROACH_METRES,
41:                 opening.profile.exterior_width_metres() * 0.5 + reservations::DOOR_SHOULDER_METRES,
42:             )?);
43:         }
44:         if let Some(workplace) = &plan.workplace {
45:             for passage in &workplace.passages {
46:                 let min = Vec2::new(
47:                     passage.bounds.min().metres().x,
48:                     passage.bounds.min().metres().z,
49:                 );
50:                 let max = Vec2::new(
51:                     passage.bounds.max().metres().x,
52:                     passage.bounds.max().metres().z,
53:                 );
54:                 routes.push(LocalReservation::from_metres(
55:                     (min + max) * 0.5 - origin,
56:                     (max - min) * 0.5,
57:                     BuildingOrientation::IDENTITY,
58:                 )?);
59:             }
60:         }
61:         Ok(Self {
62:             half_extents: bounds.plan_half_extents()?,
63:             routes,
64:         })
65:     }
66:     fn place(
67:         &self,
68:         placement: TacticalBuildingPlacement,
69:     ) -> Result<FurnitureSite, SceneInputError> {
70:         let routes = self
71:             .routes
72:             .iter()
73:             .map(|route| route.place(&placement))
74:             .collect::<Result<Vec<_>, _>>()?;
75:         Ok(FurnitureSite {
76:             placement,
77:             half_extents: self.half_extents,
78:             routes,
79:         })
80:     }
81: }
