1: //! Spatial broad phase for the same exact rotated reservation tests.
2: use super::*;
3: use std::collections::BTreeMap;
4: const RESERVATION_CELL_METRES: f32 = 16.0;
5: #[derive(Default)]
6: pub(super) struct Occupancy(BTreeMap<(i32, i32), Vec<FurnitureFootprint>>);
7: fn cells(footprint: FurnitureFootprint) -> impl Iterator<Item = (i32, i32)> {
8:     let corners = footprint.corners();
9:     let min = (corners
10:         .into_iter()
11:         .fold(Vec2::splat(f32::INFINITY), Vec2::min)
12:         / RESERVATION_CELL_METRES)
13:         .floor()
14:         .as_ivec2();
15:     let max = (corners
16:         .into_iter()
17:         .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max)
18:         / RESERVATION_CELL_METRES)
19:         .floor()
20:         .as_ivec2();
21:     (min.x..=max.x).flat_map(move |x| (min.y..=max.y).map(move |y| (x, y)))
22: }
23: impl Occupancy {
24:     pub(super) fn insert(&mut self, footprint: FurnitureFootprint) {
25:         for cell in cells(footprint) {
26:             self.0.entry(cell).or_default().push(footprint);
27:         }
28:     }
29:     pub(super) fn intersects(&self, footprint: FurnitureFootprint) -> bool {
30:         cells(footprint).any(|cell| {
31:             self.0
32:                 .get(&cell)
33:                 .is_some_and(|items| items.iter().any(|other| footprint.intersects(*other)))
34:         })
35:     }
36: }
37: #[cfg(test)]
38: mod tests {
39:     use super::*;
40:     #[test]
41:     fn broad_phase_matches_exact_intersection_for_rotated_multicell_footprints() {
42:         let mut index = Occupancy::default();
43:         let footprints = (0..20)
44:             .map(|i| {
45:                 FurnitureFootprint::from_metres(
46:                     Vec2::new(i as f32 * 7.0 - 60.0, i as f32 - 10.0),
47:                     Vec2::new(20.0, 2.0),
48:                     BuildingOrientation::from_radians(i as f32 * 0.3).unwrap(),
49:                 )
50:                 .unwrap()
51:             })
52:             .collect::<Vec<_>>();
53:         for f in &footprints {
54:             index.insert(*f);
55:         }
56:         for x in -30..30 {
57:             for z in -30..30 {
58:                 let q = FurnitureFootprint::from_metres(
59:                     Vec2::new(x as f32 * 3.0, z as f32 * 3.0),
60:                     Vec2::new(2.0, 4.0),
61:                     BuildingOrientation::from_radians(0.6).unwrap(),
62:                 )
63:                 .unwrap();
64:                 assert_eq!(
65:                     index.intersects(q),
66:                     footprints.iter().any(|f| f.intersects(q))
67:                 );
68:             }
69:         }
