1: //! Actual playable/vista support, with an explicit authority boundary.
2: use super::*;
3: use crate::{
4:     city_layout::grounding::SupportElevation, scene::GroundSubstrate,
5:     scene_coordinates::ScenePlanPoint, vista_surface::vista_triangle_height,
6: };
7: const WET_GROUND_LIMIT_BPS: u16 = 2500;
8: pub(super) struct PlacementGround<'a> {
9:     input: &'a TacticalSceneInput,
10:     terrain: &'a SceneTerrain,
11:     ground: &'a SceneGround,
12: }
13: pub(super) enum PlacementScope {
14:     Playable,
15:     Vista,
16: }
17: impl<'a> PlacementGround<'a> {
18:     pub(super) fn new(
19:         input: &'a TacticalSceneInput,
20:         terrain: &'a SceneTerrain,
21:         ground: &'a SceneGround,
22:     ) -> Self {
23:         Self {
24:             input,
25:             terrain,
26:             ground,
27:         }
28:     }
29:     pub(super) fn height_at(&self, point: ScenePlanPoint) -> Option<SupportElevation> {
30:         self.terrain.height_at(point).or_else(|| {
31:             vista_triangle_height(
32:                 self.input.vista.lods.first()?,
33:                 self.input.vista.lods.get(1),
34:                 self.terrain,
35:                 point,
36:             )
37:         })
38:     }
39:     pub(super) fn scope(&self, footprint: FurnitureFootprint) -> Option<PlacementScope> {
40:         let playable = FurnitureFootprint::from_metres(
41:             Vec2::ZERO,
42:             Vec2::new(self.terrain.width(), self.terrain.depth()) * 0.5,
43:             BuildingOrientation::IDENTITY,
44:         )
45:         .ok()?;
46:         if footprint.corners().into_iter().all(|p| {
47:             crate::scene_coordinates::ScenePlanPoint::try_from(p)
48:                 .is_ok_and(|point| playable.contains(point))
49:         }) {
50:             Some(PlacementScope::Playable)
51:         } else if footprint.intersects(playable) {
52:             None
53:         } else {
54:             Some(PlacementScope::Vista)
55:         }
56:     }
57:     pub(super) fn allows_activity(&self, point: ScenePlanPoint) -> bool {
58:         if self
59:             .input
60:             .landform
61:             .is_some_and(|landform| landform.transition_collar().contains(point))
62:         {
63:             return false;
64:         }
65:         if let Some(surface) = self.ground.ground_at(point) {
66:             return !matches!(
67:                 surface.substrate,
68:                 GroundSubstrate::Water | GroundSubstrate::Mud
69:             );
70:         }
71:         let Some(lod) = self.input.vista.lods.first() else {
72:             return false;
73:         };
74:         let local = point.metres()
75:             - Vec2::new(
76:                 lod.origin_east_metres as f32,
77:                 lod.origin_north_metres as f32,
78:             );
79:         let grid = local / lod.spacing_metres
80:             + Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1)) * 0.5;
81:         let cell = grid.floor().as_ivec2();
82:         if cell.x < 0
83:             || cell.y < 0
84:             || cell.x >= i32::from(lod.width) - 1
85:             || cell.y >= i32::from(lod.depth) - 1
86:         {
87:             return false;
88:         }
89:         [0, 1].into_iter().all(|z| {
90:             [0, 1].into_iter().all(|x| {
91:                 let e = lod.environment
92:                     [(cell.y as usize + z) * usize::from(lod.width) + cell.x as usize + x];
93:                 e.water_bps < WET_GROUND_LIMIT_BPS && e.wetland_bps < WET_GROUND_LIMIT_BPS
94:             })
95:         })
96:     }
97: }

