1: //! Checked scene reservations keep dimensional extents distinct from positions.
2: use super::*;
3: use crate::scene_coordinates::ScenePlanPoint;
4: use adventuresim_building_generator::spatial_geometry::{GeometryError, PlanExtents};
5: 
6: /// Physical kit bounds plus the access/workspace that must remain unobstructed.
7: #[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize, Reflect)]
8: #[reflect(opaque)]
9: #[serde(try_from = "FootprintWire")]
10: pub struct FurnitureFootprint {
11:     #[serde(rename = "centre_metres")]
12:     centre: ScenePlanPoint,
13:     #[serde(rename = "half_extents_metres")]
14:     half_extents: PlanExtents,
15:     orientation: BuildingOrientation,
16: }
17: #[derive(Deserialize)]
18: struct FootprintWire {
19:     centre_metres: ScenePlanPoint,
20:     half_extents_metres: PlanExtents,
21:     orientation: BuildingOrientation,
22: }
23: impl TryFrom<FootprintWire> for FurnitureFootprint {
24:     type Error = GeometryError;
25:     fn try_from(wire: FootprintWire) -> Result<Self, Self::Error> {
26:         Self::new(
27:             wire.centre_metres,
28:             wire.half_extents_metres,
29:             wire.orientation,
30:         )
31:     }
32: }
33: impl FurnitureFootprint {
34:     pub fn new(
35:         centre: ScenePlanPoint,
36:         half_extents: PlanExtents,
37:         orientation: BuildingOrientation,
38:     ) -> Result<Self, GeometryError> {
39:         let footprint = Self {
40:             centre,
41:             half_extents,
42:             orientation,
43:         };
44:         if !orientation.is_valid() || footprint.corners().iter().any(|p| !p.is_finite()) {
45:             return Err(GeometryError::InvalidProjection);
46:         }
47:         Ok(footprint)
48:     }
49:     /// Admission from native metre buffers at the reservation numerical kernel.
50:     pub(super) fn from_metres(
51:         centre: Vec2,
52:         half_extents: Vec2,
53:         orientation: BuildingOrientation,
54:     ) -> Result<Self, GeometryError> {
55:         Self::new(
56:             ScenePlanPoint::try_from(centre)?,
57:             PlanExtents::from_metres(half_extents)?,
58:             orientation,
59:         )
60:     }
61:     pub fn centre(self) -> ScenePlanPoint {
62:         self.centre
63:     }
64:     pub fn half_extents(self) -> PlanExtents {
65:         self.half_extents
66:     }
67:     pub fn orientation(self) -> BuildingOrientation {
68:         self.orientation
69:     }
70:     /// Scene east/north metre corners for footprint clearance, occupancy bounds
71:     /// and terrain sampling.
72:     pub fn corners(self) -> [Vec2; 4] {
73:         [
74:             Vec2::new(-1.0, -1.0),
75:             Vec2::new(1.0, -1.0),
76:             Vec2::ONE,
77:             Vec2::new(-1.0, 1.0),
78:         ]
79:         .map(|corner| {
80:             self.centre.metres()
81:                 + self
82:                     .orientation
83:                     .local_to_world(corner * self.half_extents.metres())
84:         })
85:     }
86:     pub fn contains(self, point: crate::scene_coordinates::ScenePlanPoint) -> bool {
87:         let point = point.metres();
88:         self.orientation
89:             .world_to_local(point - self.centre.metres())
90:             .abs()
91:             .cmple(self.half_extents.metres())
92:             .all()
93:     }
94:     pub fn intersects(self, other: Self) -> bool {
95:         let axes = [
96:             self.orientation.local_to_world(Vec2::X),
97:             self.orientation.local_to_world(Vec2::Y),
98:             other.orientation.local_to_world(Vec2::X),
99:             other.orientation.local_to_world(Vec2::Y),
100:         ];
101:         axes.into_iter().all(|axis| {
102:             let radius = |footprint: Self| {
103:                 footprint
104:                     .orientation
105:                     .local_to_world(Vec2::X)
106:                     .dot(axis)
107:                     .abs()
108:                     * footprint.half_extents.metres().x
109:                     + footprint
110:                         .orientation
111:                         .local_to_world(Vec2::Y)
112:                         .dot(axis)
113:                         .abs()
114:                         * footprint.half_extents.metres().y
115:             };
116:             (self.centre.metres() - other.centre.metres())
117:                 .dot(axis)
118:                 .abs()
119:                 < radius(self) + radius(other)
120:         })
121:     }
122: }

