12: pub(super) fn generate(
13:     input: &TacticalSceneInput,
14:     buildings: &[sites::FurnitureSite],
15:     terrain: &SceneTerrain,
16:     ground: &SceneGround,
17:     obstacles: &[GeneratedObstacle],
18: ) -> Result<FurnitureLayout, super::super::SceneInputError> {
19:     let mut layout = FurnitureLayout {
20:         reserved_routes: reservations::routes(input, buildings)?,
21:         ..Default::default()
22:     };
23:     let mut occupied = occupancy::Occupancy::default();
24:     let support = PlacementGround::new(input, terrain, ground);
25:     let market = candidates::market(input)?;
26:     layout.reserved_routes.extend(market.aisles);
27:     for footprint in reservations::obstacles(input, terrain, buildings, obstacles)?
28:         .into_iter()
29:         .chain(layout.reserved_routes.iter().copied())
30:     {
31:         occupied.insert(footprint);
32:     }
33:     for candidate in market.groups {
34:         accept(input, &support, candidate, &mut occupied, &mut layout);
35:     }
36:     let mut ordered = buildings.iter().collect::<Vec<_>>();
37:     ordered.sort_by_key(|building| building.placement.id);
38:     for building in ordered {
39:         let mut accepted = 0;
40:         for candidate in candidates::building(input, building)? {
41:             if accept(input, &support, candidate, &mut occupied, &mut layout) {
42:                 accepted += 1;
43:                 if accepted >= candidates::group_limit(building) {
44:                     break;
45:                 }
46:             }
47:         }
48:     }
49:     Ok(layout)
50: }
51: 
52: fn accept(
53:     input: &TacticalSceneInput,
54:     support: &PlacementGround,
55:     candidate: Candidate,
56:     occupied: &mut occupancy::Occupancy,
57:     layout: &mut FurnitureLayout,
58: ) -> bool {
59:     let footprint = candidate.footprint;
60:     let Some(playable) = support.scope(footprint) else {
61:         return false;
62:     };
63:     if occupied.intersects(footprint) {
64:         return false;
65:     }
66:     let corners = footprint.corners();
67:     if candidate
68:         .market
69:         .is_some_and(|market| !corners.into_iter().all(|corner| market.contains(corner)))
70:     {
71:         return false;
72:     }
73:     let samples = corners
74:         .into_iter()
75:         .map(ScenePlanPoint::from_metres)
76:         .chain([Some(footprint.centre())])
77:         .map(|point| {
78:             let point = point?;
79:             if input
80:                 .landform
81:                 .is_some_and(|landform| landform.transition_collar().contains(point))
82:                 || !support.allows_activity(point)
83:             {
84:                 return None;
85:             }
86:             support.height_at(point)
87:         })
88:         .collect::<Option<Vec<_>>>();
89:     let Some(samples) = samples else {
90:         return false;
91:     };
92:     let min = samples
93:         .iter()
94:         .map(|height| height.metres())
95:         .fold(f32::INFINITY, f32::min);
96:     let max = samples
97:         .into_iter()
98:         .map(|height| height.metres())
99:         .fold(f32::NEG_INFINITY, f32::max);
100:     if max - min > footprint.half_extents().metres().length() * 2.0 * MAX_GROUP_GRADE {
101:         return false;
102:     }
103:     let Some(instances) = supported_instances(&candidate, support) else {
104:         return false;
105:     };
106:     occupied.insert(footprint);
107:     layout.groups.push(FurnitureGroup {
108:         id: candidate.id,
109:         kind: candidate.kind,
110:         anchor: candidate.anchor,
111:         footprint,
112:     });
113:     if matches!(playable, ground::PlacementScope::Playable) {
114:         layout.instances.extend(instances);
115:     } else {
116:         layout.distant_instances.extend(instances);
117:     }
118:     true

