40: impl LocalCandidate {
41:     pub(super) fn place(
42:         self,
43:         centre: crate::scene_coordinates::ScenePlanPoint,
44:         orientation: BuildingOrientation,
45:     ) -> Result<Candidate, crate::scene_input::SceneInputError> {
46:         Ok(Candidate {
47:             id: self.id,
48:             kind: self.kind,
49:             anchor: self.anchor,
50:             items: self.items,
51:             footprint: FurnitureFootprint::new(centre, self.half_extents, orientation)?,
52:             market: None,
53:         })
54:     }
55: 
56:     pub(super) fn new(
57:         seed: fabelgeist_determinism::Seed,
58:         slot: u64,
59:         kind: FurnitureGroupKind,
60:         anchor: FurnitureAnchor,
61:     ) -> Result<Self, crate::scene_input::SceneInputError> {
62:         let (anchor_kind, anchor_id) = match anchor {
63:             FurnitureAnchor::Market { patch_index } => (0, u64::from(patch_index)),
64:             FurnitureAnchor::Building { id } => (1, id.0),
65:         };
66:         let id = GROUP_DOMAIN
67:             .seed(seed, &[anchor_kind, anchor_id, kind as u64, slot])
68:             .to_u64();
69:         let variant = if RNG_FURNITURE_GROUP_SIZE.rng(id.into(), &[]).boolean() {
70:             FurnitureVariant::Compact
71:         } else {
72:             FurnitureVariant::Broad
73:         };
74:         let mut items = Vec::new();
75:         let mut minimum = Vec2::splat(f32::INFINITY);
76:         let mut maximum = Vec2::splat(f32::NEG_INFINITY);
77:         for kind in composition::kinds(kind, id) {
78:             let key = FurnitureKey::natural(kind, variant);
79:             let recipe = key.recipe()?;
80:             let LocalReservationBounds {
81:                 minimum: min,
82:                 maximum: max,
83:             } = reservation_bounds(recipe);
84:             let offset = if items.is_empty() {
85:                 Vec2::ZERO
86:             } else {
87:                 Vec2::X * (maximum.x + KIT_GAP_METRES - min.x)
88:             };
89:             minimum = minimum.min(min + offset);
90:             maximum = maximum.max(max + offset);
91:             items.push(LocalItem {
92:                 key,
93:                 offset: Displacement::from_metres(bevy::math::Vec3::new(offset.x, 0.0, offset.y))?,
94:                 recipe,
95:             });
96:         }
97:         let centre = (minimum + maximum) * 0.5;
98:         for item in &mut items {
99:             let moved = item.offset.metres().xz() - centre;
100:             item.offset = Displacement::from_metres(bevy::math::Vec3::new(moved.x, 0.0, moved.y))?;
101:         }
102:         Ok(Self {
103:             id: FurnitureGroupId(id),
104:             kind,
105:             anchor,
106:             items,
107:             half_extents: PlanExtents::from_metres((maximum - minimum) * 0.5)?,
108:         })
109:     }

