4: 
5: /// The server and production review use the same physical recipe, including
6: /// open space between table legs and trough sides. Canvas and water are absent.
7: pub fn furniture_collider(
8:     key: FurnitureKey,
9: ) -> Result<Collider, adventuresim_building_generator::furniture::FurnitureRecipeError> {
10:     Ok(Collider::compound(
11:         key.recipe()?
12:             .colliders
13:             .iter()
14:             .map(|cuboid| {
15:                 (
16:                     cuboid.centre.metres(),
17:                     Quat::from_rotation_y(cuboid.yaw_radians.radians())
18:                         * Quat::from_rotation_x(cuboid.crossfall_radians.radians())
19:                         * Quat::from_rotation_z(cuboid.longfall_radians.radians()),
20:                     Collider::cuboid(
21:                         cuboid.size.metres().x,
22:                         cuboid.size.metres().y,
23:                         cuboid.size.metres().z,
24:                     ),
25:                 )
26:             })
27:             .collect(),
28:     ))
29: }

