51: fn instance(
52:     building: &GeneratedBuilding,
53:     placement: &InteriorPlacement,
54: ) -> Result<GeneratedFurniture> {
55:     let origin = building.collision.bounds.centre()?.metres();
56:     let position = building.placement.centre_metres.metres()
57:         + building
58:             .placement
59:             .orientation
60:             .local_to_world(placement.centre_metres.metres() - Vec2::new(origin.x, origin.z));
61:     let height = building.placement.base_elevation_metres.metres()
62:         + placement
63:             .floor_height(&building.plan)
64:             .map_err(|cause| super::super::SceneInputError::Interior {
65:                 building_id: building.placement.id,
66:                 cause,
67:             })?
68:             .metres();
69:     Ok(GeneratedFurniture {
70:         scene: SceneFurniture {
71:             id: FurnitureInstanceId(
72:                 INTERIOR_INSTANCE_DOMAIN
73:                     .seed(
74:                         building.placement.id.0.into(),
75:                         &[
76:                             u64::from(placement.room_id.serialized_ordinal()),
77:                             placement.storey.index() as u64,
78:                             u64::from(placement.centre_metres.metres().x.to_bits()),
79:                             u64::from(placement.centre_metres.metres().y.to_bits()),
80:                             placement.facing as u64,
