12:         input: &TacticalSceneInput,
13:     ) -> Result<GeneratedTacticalScene, SceneInputError> {
14:         let mut generated = input.generate()?;
15:         let Some(document) = &self.0 else {
16:             return Ok(generated);
17:         };
18:         let requested: BTreeSet<_> = document.playable_building_ids.iter().copied().collect();
19:         assert_eq!(requested.len(), document.playable_building_ids.len());
20:         let mut promoted = Vec::new();
21:         for id in requested {
22:             if generated
23:                 .buildings
24:                 .iter()
25:                 .any(|building| building.placement.id == id)
26:             {
27:                 continue;
28:             }
29:             let placement: adventuresim_tactical_core::scene_input::TacticalBuildingPlacement =
30:                 input
31:                     .distant_buildings
32:                     .iter()
33:                     .find(|building| building.id == id)
34:                     .copied()
35:                     .expect("explicit capture member must exist")
36:                     .into();
37:             let recipe = generated
38:                 .building_recipes
39:                 .take(&placement.program)
40:                 .map(Ok)
41:                 .unwrap_or_else(|| GeneratedBuildingRecipe::generate(placement.program.clone()))
