43:                     SceneInputError::Validation(SceneValidationError::BuildingProgram {
44:                         building: id,
45:                         source: error,
46:                     })
47:                 })?;
48:             promoted.push(GeneratedBuilding {
49:                 placement,
50:                 plan: recipe.plan,
51:                 collision: recipe.collision,
52:             });
53:         }
54:         let owners: BTreeSet<_> = promoted.iter().map(|b| b.placement.id).collect();
55:         generated.boundaries.extend(
56:             input
