18: pub fn furnish(plan: &BuildingPlan, program: &BuildingProgram) -> Result<InteriorLayout> {
19:     let nav = Navigation::new(plan)?;
20:     let mut occupancy = Occupancy::new(&nav)?;
21:     let mut layout = InteriorLayout::default();
22:     for storey in &plan.storeys {
23:         for room in &storey.rooms {
24:             for budget in furniture_budgets(program, room) {
25:                 let mut placed = 0;
26:                 let candidates = candidates(
27:                     plan,
28:                     program,
29:                     room,
30:                     StoreyIndex::from_serialized(storey.level),
31:                     budget,
32:                 )?;
33:                 for group in candidates {
34:                     if placed == budget.count {
35:                         break;
36:                     }
37:                     let previous = layout.placements.len();
38:                     layout.placements.extend(group);
39:                     if super::footprints::validate(plan, &nav, &layout.placements, previous)
40:                         .is_err()
41:                     {
42:                         layout.placements.truncate(previous);
43:                         continue;
44:                     }
45:                     let change = occupancy.add(&layout.placements[previous..])?;
46:                     let flood = occupancy.flood();
47:                     if nav.verify_rooms(&flood).is_err()
48:                         || nav.access_paths(&layout.placements, &flood).is_err()
49:                     {
50:                         occupancy.remove(change);
51:                         layout.placements.truncate(previous);
52:                         continue;
53:                     }
54:                     placed += 1;
55:                 }
56:                 if placed < budget.count {
57:                     layout.unmet_budgets.push(UnmetFurnitureBudget {
58:                         storey: crate::StoreyIndex::from_serialized(storey.level),
59:                         room_id: crate::RoomIndex::from_serialized(room.id),
60:                         kind: budget.kind,
61:                         requested: budget.count,
62:                         placed,
63:                     });
64:                 }
65:             }
66:         }
67:     }
68:     if layout.placements.is_empty() {
69:         return Err(InteriorLayoutError::EmptyLayout);
70:     }
71:     layout.paths = nav.access_paths(&layout.placements, &occupancy.flood())?;
72:     super::finishes::assign(plan, program, &mut layout.placements)?;
73:     Ok(layout)
74: }
