8:     let product = match job {
9:         GenerationJob::RegionalCity { input, graphics } => GenerationProduct::RegionalCity(
10:             Box::new(city::PreparedCityProduct::generate(*input, graphics)?),
11:         ),
12:         GenerationJob::Building(program) => {
13:             GenerationProduct::Building(Box::new(PreparedFacade::generate(*program)?))
14:         }
15:         GenerationJob::Venue(program) => GenerationProduct::Venue(Box::new(
16:             venue::PreparedVenue::generate(*program, dependencies.recipe)?,
17:         )),
18:     };
19:     let mut bytes = Vec::new();
20:     ciborium::into_writer(&product, &mut bytes).map_err(PreparationError::ProductEncode)?;
21:     Ok(bytes)
22: }
23: 
24: pub(super) fn receive(
25:     ticket: PreparationTicket,
26:     job_json: &str,
27:     bytes: &[u8],
28: ) -> PreparationResult<()> {
29:     let mut products = staged_products(ticket)?;
30:     let job: GenerationJob = serde_json::from_str(job_json)?;
31:     job.require_owner(ticket)?;
32:     let product: GenerationProduct =
33:         ciborium::from_reader(bytes).map_err(PreparationError::ProductDecode)?;
34:     match (job, product) {
35:         (
36:             GenerationJob::RegionalCity { input, graphics },
37:             GenerationProduct::RegionalCity(city),
38:         ) if city.matches(&input, &graphics) => {
39:             ticket.require_owner(PresentationOwner::RegionalMap)?;
40:             products.regional_city = Some(Arc::new(*city));
41:         }
42:         (GenerationJob::Building(program), GenerationProduct::Building(facade))
43:             if *program == facade.program =>
44:         {
45:             if !products
46:                 .sites
47:                 .iter()
48:                 .any(|site| site.program == facade.program)
49:             {
50:                 products.sites.push(
51:                     adventuresim_tactical_core::scene_input::ProgramFurnitureSite {
52:                         program: facade.program.clone(),
53:                         recipe: facade.site.clone(),
54:                     },
55:                 );
56:             }
57:             products.facades.push(Arc::new(*facade));
58:         }
59:         (GenerationJob::Venue(program), GenerationProduct::Venue(venue))
60:             if *program == venue.recipe.program =>
61:         {
