//! Decode and native-grid admission precede terrain queries and framework use.
use super::*;

#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum TerrainAdmissionError {
    #[error(
        "terrain needs at least two finite grid vertices on each axis within u32 mesh capacity"
    )]
    Dimensions,
    #[error("terrain grid scale and represented extents must be finite and positive")]
    Scale,
    #[error("terrain coarse stride must divide both cell dimensions")]
    Stride,
    #[error("terrain height samples must be finite")]
    Heights,
}

#[derive(Deserialize)]
pub(super) struct TerrainWire {
    heightmap: Vec<f32>,
    width: usize,
    scale: f32,
    coarse_stride: usize,
    geometry: TerrainGeometry,
}
impl TryFrom<TerrainWire> for SceneTerrain {
    type Error = TerrainAdmissionError;
    fn try_from(wire: TerrainWire) -> Result<Self, Self::Error> {
        let terrain = Self {
            heightmap: wire.heightmap,
            width: wire.width,
            scale: wire.scale,
            coarse_stride: wire.coarse_stride,
            geometry: wire.geometry,
        };
        terrain.validate()?;
        Ok(terrain)
    }
}

pub(super) fn validate_dimensions(
    width: usize,
    depth: usize,
    scale: f32,
    stride: usize,
) -> Result<(), TerrainAdmissionError> {
    if width < 2
        || depth < 2
        || width
            .checked_mul(depth)
            .is_none_or(|n| n > u32::MAX as usize)
        || (width - 1)
            .checked_mul(depth - 1)
            .and_then(|n| n.checked_mul(6))
            .is_none_or(|n| n > u32::MAX as usize)
    {
        return Err(TerrainAdmissionError::Dimensions);
    }
    if !scale.is_finite()
        || scale <= 0.0
        || !((width - 1) as f32 * scale).is_finite()
        || !((depth - 1) as f32 * scale).is_finite()
    {
        return Err(TerrainAdmissionError::Scale);
    }
    if stride == 0 || !(width - 1).is_multiple_of(stride) || !(depth - 1).is_multiple_of(stride) {
        return Err(TerrainAdmissionError::Stride);
    }
    Ok(())
}
impl SceneTerrain {
    pub(super) fn grid_depth_checked(&self) -> Option<usize> {
        (self.width != 0 && self.heightmap.len().is_multiple_of(self.width))
            .then(|| self.heightmap.len() / self.width)
    }
    pub(super) fn validate(&self) -> Result<(), TerrainAdmissionError> {
        let depth = self
            .grid_depth_checked()
            .ok_or(TerrainAdmissionError::Dimensions)?;
        validate_dimensions(self.width, depth, self.scale, self.coarse_stride)?;
        if self.heightmap.iter().any(|h| !h.is_finite()) {
            return Err(TerrainAdmissionError::Heights);
        }
        Ok(())
    }
}
impl Default for SceneTerrain {
    /// A finite flat metre-square grid is the framework default.
    fn default() -> Self {
        Self {
            heightmap: vec![0.0; 4],
            width: 2,
            scale: 1.0,
            coarse_stride: 1,
            geometry: TerrainGeometry::Sampled,
        }
    }
}
//! Validate geographic descriptors independently of producer support selection.
use super::*;

impl TacticalSceneInput {
    pub(super) fn validate_source(&self) -> Result<(), SceneInputError> {
        if self.schema_version != TACTICAL_SCENE_SCHEMA_VERSION {
            return invalid(SceneValidationError::SchemaVersion);
        }
        if self.generation_version != TACTICAL_SCENE_GENERATION_VERSION {
            return invalid(SceneValidationError::GenerationVersion);
        }
        if self.scene_key.is_empty() || self.scene_key.len() > MAX_TEMPLATE_BYTES {
            return invalid(SceneValidationError::SceneKey);
        }
        let source_id = match &self.source {
            SceneSource::ImportedPackage(value) => value.as_str(),
            SceneSource::SyntheticFixture(value) => value.as_str(),
        };
        if source_id.is_empty() || source_id.len() > MAX_SOURCE_ID_BYTES {
            return invalid(SceneValidationError::SourceIdentity);
        }

        validate_grid(&self.playable, MAX_PLAYABLE_SIDE, SampleGridKind::Playable)?;
        crate::scene_fault::validate(self.landform, &self.playable)?;
        urban::validate(self)?;
        establishments::validate(self)?;
        properties::validate(self)?;
        if self.vista.lods.len() > MAX_VISTA_LEVELS {
            return invalid(SceneValidationError::VistaLevelCount);
        }
        let mut previous_level = None;
        let mut previous_spacing = self.playable.spacing_metres;
        let mut vista_samples = 0usize;
        for lod in &self.vista.lods {
            if previous_level.is_some_and(|level| lod.level <= level) {
                return invalid(SceneValidationError::VistaLevelOrder);
            }
            if !lod.origin_east_metres.is_finite() || !lod.origin_north_metres.is_finite() {
                return invalid(SceneValidationError::VistaOrigin);
            }
            let grid = TerrainSampleGrid {
                width: lod.width,
                depth: lod.depth,
                spacing_metres: lod.spacing_metres,
                heights_metres: lod.heights_metres.clone(),
                environment: lod.environment.clone(),
            };
            validate_grid(&grid, u16::MAX as usize, SampleGridKind::Vista)?;
            if lod.spacing_metres <= previous_spacing {
                return invalid(SceneValidationError::VistaSpacingOrder);
            }
            vista_samples = vista_samples.checked_add(lod.heights_metres.len()).ok_or({
                SceneInputError::Validation(SceneValidationError::VistaSampleOverflow)
            })?;
            if vista_samples > MAX_VISTA_SAMPLES {
                return invalid(SceneValidationError::VistaSampleCount);
            }
            previous_level = Some(lod.level);
            previous_spacing = lod.spacing_metres;
        }
        validate_weather(self.weather)?;
        Ok(())
    }
}

