1: //! Accepted support is bound once by the producer and reconstructed by consumers.
2: use super::*;
3: use crate::city_layout::grounding::GeographicSurface;
4: use crate::city_layout::{CitySceneLayout, CompoundGradingPolicy, SelectedCityGrounding};
5: 
6: impl TacticalSceneInput {
7:     /// Seat a complete generated layout against this scene's unchanged source.
8:     /// Selection must succeed for every owner before any placement is published.
9:     /// This is the producer boundary; loading never guesses a missing plan.
10:     pub fn ground_generated_city(
11:         mut self,
12:         layout: &CitySceneLayout,
13:         policy: CompoundGradingPolicy,
14:     ) -> Result<Self, SceneInputError> {
15:         self.validate_source()?;
16:         if self.grounding.is_some()
17:             || self.buildings != layout.playable
18:             || self.distant_buildings != layout.distant
19:             || self.compounds != layout.compounds
20:             || self.gardens != layout.gardens
21:             || self.streets != layout.streets
22:             || self.yards != layout.yards
23:             || self.parishes != layout.parishes
24:         {
25:             return invalid(SceneValidationError::ProducerLayout);
26:         }
27:         if self.buildings.is_empty() && self.distant_buildings.is_empty() {
28:             self.validate()?;
29:             return Ok(self);
30:         }
31:         let prepared = self.prepare_geographic_terrain(&mut GeneratedBuildingRecipes::default())?;
32:         let source = GeographicSurface::from_presented_scene(&prepared.terrain, &self.vista)
33:             .ok_or(SceneInputError::Validation(
34:                 SceneValidationError::GeographicSupport,
35:             ))?;
36:         let grounded = SelectedCityGrounding::select(layout, &source, policy)?.compile()?;
37:         self.grounding = Some(grounded.support_projection()?);
38:         let (layout, _, _) = grounded.into_parts();
39:         self.buildings = layout.playable;
40:         self.distant_buildings = layout.distant;
41:         // Floors must not change geographic preparation or its asset context.
42:         // The consumer verifies the source digest before installing support.
43:         self.validate()?;
44:         Ok(self)
45:     }
46: 
47:     /// Complete canonical placements, including compact distant buildings.
48:     /// Exterior consumers use the same physical records as support binding.
49:     pub fn physical_placements(&self) -> Vec<TacticalBuildingPlacement> {
50:         self.buildings
51:             .iter()
52:             .cloned()
53:             .chain(
54:                 self.distant_buildings
55:                     .iter()
56:                     .copied()
57:                     .map(TacticalBuildingPlacement::from),
58:             )
59:             .collect()
60:     }
61: 
62:     pub(in crate::scene_input) fn validate_grounding(&self) -> Result<(), SceneInputError> {
63:         let placements = self.physical_placements();
64:         match (&self.grounding, placements.is_empty()) {
65:             (None, true) => Ok(()),
66:             (Some(projection), false) => {
67:                 projection.validate_bindings(&placements)?;
68:                 projection.validate_compound_bindings(&self.compounds)?;
69:                 Ok(())
70:             }
71:             (None, false) => invalid(SceneValidationError::MissingSupport),
72:             (Some(_), true) => invalid(SceneValidationError::UnexpectedSupport),
73:         }
74:     }
75: }
