23:     // of the regional substrate color and low-amplitude spatial variation.
24:     // This avoids both subpixel geometry and a flat, hard-selected field.
25:     let sward = sward_coverage * (1.0 - slope * 0.82);
26:     let sward_color = vista.grass_color.rgb;
27:     let sward_cell = floor(in.world_position.xz * 0.5);
28:     let sward_dither = fract(sin(dot(sward_cell, vec2<f32>(12.9898, 78.233))) * 43758.5453);
29:     let sward_target = mix(color, sward_color * mix(0.92, 1.08, sward_dither), 0.88);
30:     color = mix(color, sward_target, sward);
31: 
32:     // Exposed regional slopes use the same kind of solid molded-material
33:     // palette region as playable terrain, without triplanar albedo sampling.
34:     let molded_rock = vec3<f32>(0.31, 0.30, 0.275);
35:     let rock_amount = slope * (1.0 - sward_coverage * 0.48);
36:     color = select(color, molded_rock * 0.90, rock_amount >= 0.5);
37: 
38:     // The same authoritative weather snapshot drives near and vista terrain.
39:     // Snow remains slope-aware at regional scale and mutes the residual sward
40:     // instead of ending at the playable-mesh boundary.
41:     let snow_mask = vista.weather.y * smoothstep(0.28, 0.86, terrain_normal.y);
42:     color = select(color, vec3<f32>(0.79, 0.84, 0.86), snow_mask >= 0.5);
43: 
44:     pbr_input.material.base_color = vec4<f32>(color, 1.0);
45:     pbr_input.material.perceptual_roughness = mix(0.94, 0.82, rock_amount);
46: 
47:     var out: FragmentOutput;
48:     out.color = apply_pbr_lighting(pbr_input);
49:     out.color = main_pass_post_lighting_processing(pbr_input, out.color);
50:     return out;
51: }

