35: impl TryFrom<SupportMeshWire> for PropertySupportMesh {
36:     type Error = SupportSurfaceAdmissionError;
37:     fn try_from(wire: SupportMeshWire) -> Result<Self, Self::Error> {
38:         let mesh = Self {
39:             property_id: wire.property_id,
40:             member_building_ids: wire.member_building_ids,
41:             positions: wire.positions,
42:             support_triangles: wire.support_triangles,
43:             retaining_triangles: wire.retaining_triangles,
44:             contact_tolerance_metres: wire.contact_tolerance_metres,
45:         };
