128:         self.positions.extend(points);
129:         let triangles = [[start, start + 2, start + 1], [start, start + 3, start + 2]];
130:         if matches!(role, SupportFaceRole::Retaining) {
131:             self.retaining_triangles.extend(triangles);
132:         } else {
133:             self.support_triangles.extend(triangles);
134:         }
135:         Ok(())
136:     }
137: 
138:     pub(super) fn convex_floor(
139:         &mut self,
140:         outline: &crate::scene_coordinates::ScenePlanPolygon,
141:         elevation: SupportElevation,
142:     ) -> Result<(), SupportDiagnostic> {
143:         let outline = outline.vertices();
144:         let start = self.vertex_start(outline.len(), outline[0].metres())?;
145:         self.positions.extend(outline.iter().map(|p| {
146:             let point = p.metres();
147:             Vec3::new(point.x, elevation.metres(), point.y)
148:         }));
149:         self.support_triangles.extend(
150:             (1..outline.len() - 1).map(|i| [start, start + i as u32 + 1, start + i as u32]),
151:         );
152:         Ok(())
153:     }
154: 
155:     pub(super) fn append(&mut self, other: &Self) -> Result<(), SupportDiagnostic> {
156:         let point = other.positions.first().map_or(Vec2::ZERO, |p| p.xz());
157:         let offset = self.vertex_start(other.positions.len(), point)?;
158:         self.positions.extend_from_slice(&other.positions);
159:         self.support_triangles.extend(
160:             other
161:                 .support_triangles
162:                 .iter()
163:                 .map(|t| t.map(|i| i + offset)),
164:         );
165:         self.retaining_triangles.extend(
166:             other
167:                 .retaining_triangles
168:                 .iter()
169:                 .map(|t| t.map(|i| i + offset)),
170:         );
171:         Ok(())
172:     }
173: 
174:     pub fn elevations_at(
175:         &self,
176:         scene_point: crate::scene_coordinates::ScenePlanPoint,
177:     ) -> SurfaceElevations {
178:         let point = scene_point.metres();
179:         let mut heights = self
180:             .support_triangles
181:             .iter()
182:             .filter_map(|indices| {
183:                 let [a, b, c] = indices.map(|i| self.positions[i as usize]);
184:                 let ab = b.xz() - a.xz();
185:                 let ac = c.xz() - a.xz();
186:                 let ap = point - a.xz();
187:                 let determinant = ab.perp_dot(ac);
188:                 if determinant == 0.0 {
189:                     return None;
190:                 }
191:                 let u = ap.perp_dot(ac) / determinant;
192:                 let v = ab.perp_dot(ap) / determinant;
193:                 let tolerance = self.contact_tolerance_metres * ab.length().max(ac.length())
194:                     / determinant.abs();
195:                 if !(u >= -tolerance && v >= -tolerance && u + v <= 1.0 + tolerance) {
196:                     return None;
197:                 }
198:                 let height = a.y + (b.y - a.y) * u + (c.y - a.y) * v;
199:                 SupportElevation::from_metres(height).or_else(|| {
200:                     let height = f64::from(a.y)
201:                         + (f64::from(b.y) - f64::from(a.y)) * f64::from(u)
202:                         + (f64::from(c.y) - f64::from(a.y)) * f64::from(v);
203:                     SupportElevation::from_metres(height as f32)
204:                 })
205:             })
206:             .collect::<Vec<_>>();
207:         heights.sort_by(|a, b| a.metres().total_cmp(&b.metres()));
208:         heights.dedup_by(|a, b| (a.metres() - b.metres()).abs() <= self.contact_tolerance_metres);
209:         SurfaceElevations(heights)
210:     }
211: 
212:     /// Maximum physical grade of any support triangle, excluding vertical
213:     /// retaining faces that are not an actor's walkable surface.
214:     pub fn maximum_grade(&self) -> f32 {
215:         self.support_triangles
216:             .iter()
217:             .map(|indices| {
218:                 let [a, b, c] = indices.map(|i| self.positions[i as usize]);
219:                 let normal = (b - a).cross(c - a);
220:                 normal.xz().length() / normal.y.abs()
221:             })
222:             .fold(0.0, f32::max)
223:     }
224: }
225: 
226: impl PropertySupportMesh {
227:     pub(super) fn empty_for_compound(plan: &CompoundSupportPlan) -> Self {
228:         PropertySupportMesh {
229:             property_id: plan.property.id,
230:             member_building_ids: vec![
231:                 plan.property.front_building_id,
232:                 plan.property.rear_building_id,
233:             ],
234:             positions: Vec::new(),
235:             support_triangles: Vec::new(),
236:             retaining_triangles: Vec::new(),
237:             contact_tolerance_metres: plan.limits.contact_tolerance_metres.metres(),
238:         }
239:     }
240: }
