1: //! A street approach preserves source ground and a complete doorway landing.
2: use super::*;
3: 
4: #[derive(Clone, Debug)]
5: pub(super) struct StreetEntryApron {
6:     pub reservation: CityPlotBounds,
7:     pub support_region: CityPlotBounds,
8:     pub mesh: PropertySupportMesh,
9: }
10: 
11: impl CompoundSupportPlan {
12:     /// Bind the exact street door to a supplied external apron. Support extends
13:     /// through the owned setback, stopping at the bearing edge. The doorway
14:     /// landing is level before the actor reaches the wall. Compare a ramp with
15:     /// a flight meeting the supplied riser/going bounds; never extend the
16:     /// external reservation or alter actor movement limits.
17:     pub fn bind_street_entry(
18:         mut self,
19:         threshold: crate::scene_coordinates::ScenePlanPoint,
20:         reservation: CityPlotBounds,
21:         source: &GeographicSurface,
22:         stairs: CourtStairLimits,
23:     ) -> Result<Self, SupportDiagnostic> {
24:         let threshold = threshold.metres();
25:         let region = self.street_entry_region(threshold, reservation)?;
26:         let corners = region.corners();
27:         let points = self.street_source_edge(corners, source)?;
28:         let threshold_local = region
29:             .orientation()
30:             .world_to_local(threshold - region.centre_metres());
31:         let landing_begin = threshold_local.y - stairs.minimum_floor_landing_run_metres.metres();
32:         let run = landing_begin + region.dimensions_metres().y * 0.5;
33:         if run <= 0.0 {
34:             let mut error = self.street_rejection(
35:                 SupportConstraint::StairClearance,
36:                 threshold,
37:                 threshold_local.y + region.dimensions_metres().y * 0.5,
38:                 stairs.minimum_floor_landing_run_metres.metres(),
39:             );
40:             error.violation = error.violation.with_bound(SupportBound::Minimum);
41:             return Err(error);
42:         }
43:         let landing_fraction = run / region.dimensions_metres().y;
44:         let floor = self.levels.front.elevation.metres();
45:         let edge = |t: f32, heights: [f32; 2]| {
46:             let a = points[0].lerp(points[3], t).with_y(heights[0]);
47:             let b = points[1].lerp(points[2], t).with_y(heights[1]);
48:             [a, b]
49:         };
50:         let end = edge(landing_fraction, [floor; 2]);
51:         let mut mesh = PropertySupportMesh::empty_for_compound(&self);
52:         mesh.quad(
53:             [points[0], points[1], end[1], end[0]],
54:             SupportFaceRole::Bearing,
55:         )?;
56:         if mesh.maximum_grade() > self.limits.maximum_grade.ratio() {
57:             mesh = PropertySupportMesh::empty_for_compound(&self);
58:             let rise = [points[0].y, points[1].y]
59:                 .map(|h| (h - floor).abs())
60:                 .into_iter()
61:                 .fold(0.0, f32::max);
62:             let count = (rise / stairs.maximum_riser_metres.metres()).ceil();
63:             let required = count * stairs.minimum_going_metres.metres();
64:             if count > f32::from(u16::MAX)
65:                 || required > run + self.limits.contact_tolerance_metres.metres()
66:             {
67:                 return Err(self.street_rejection(
68:                     SupportConstraint::StairGoing,
69:                     reservation.centre_metres(),
70:                     required,
71:                     run,
72:                 ));
73:             }
74:             let heights = |t: f32| [points[0].y, points[1].y].map(|h| h + (floor - h) * t);
75:             for i in 0..count as u16 {
76:                 let t = f32::from(i) / count;
77:                 let next = f32::from(i + 1) / count;
78:                 let a = edge(landing_fraction * t, heights(t));
79:                 let b = edge(landing_fraction * next, heights(t));
80:                 let c = edge(landing_fraction * next, heights(next));
81:                 mesh.quad([a[0], a[1], b[1], b[0]], SupportFaceRole::Bearing)?;
82:                 mesh.quad([b[0], b[1], c[1], c[0]], SupportFaceRole::Retaining)?;
83:             }
84:         }
85:         mesh.quad(
86:             [end[0], end[1], points[2], points[3]],
87:             SupportFaceRole::Bearing,
88:         )?;
89:         if mesh.maximum_grade() > self.limits.maximum_grade.ratio() {
90:             return Err(self.street_rejection(
91:                 SupportConstraint::AccessGrade,
92:                 reservation.centre_metres(),
93:                 mesh.maximum_grade() * run,
94:                 self.limits.maximum_grade.ratio() * run,
95:             ));
96:         }
97:         self.street_entry = Some(StreetEntryApron {
98:             reservation,
99:             support_region: region,
100:             mesh,
101:         });
102:         Ok(self)
103:     }
104: 
105:     fn street_source_edge(
106:         &self,
107:         corners: [Vec2; 4],
108:         source: &GeographicSurface,
109:     ) -> Result<[Vec3; 4], SupportDiagnostic> {
110:         let mut points = corners.map(|p| Vec3::new(p.x, self.levels.front.elevation.metres(), p.y));
111:         for i in 0..2 {
112:             points[i].y = source
113:                 .elevation_at(
114:                     crate::scene_coordinates::ScenePlanPoint::try_from(corners[i]).map_err(
115:                         |cause| {
116:                             SupportDiagnostic::framed_geometry(&self.property, corners[i], cause)
117:                         },
118:                     )?,
119:                 )
120:                 .ok_or_else(|| {
121:                     self.street_rejection(SupportConstraint::SourceSample, corners[i], 1.0, 0.0)
122:                 })?
123:                 .metres();
124:         }
125:         Ok(points)
126:     }
127: 
128:     fn street_entry_region(
129:         &self,
130:         threshold: Vec2,
131:         reservation: CityPlotBounds,
132:     ) -> Result<CityPlotBounds, SupportDiagnostic> {
133:         let local = |point| {
134:             self.property
135:                 .plot
136:                 .orientation()
137:                 .world_to_local(point - self.property.plot.centre_metres())
138:         };
139:         let centre = local(reservation.centre_metres());
140:         let half = reservation.dimensions_metres() * 0.5;
141:         let plot_half = self.property.plot.dimensions_metres() * 0.5;
142:         let threshold_local = local(threshold);
143:         if self.street_entry.is_some()
144:             || !reservation.is_valid()
145:             || reservation.orientation() != self.property.plot.orientation()
146:             || !self.property.plot.contains(threshold)
147:             || centre.x.abs() + half.x > plot_half.x
148:             || (threshold_local.x - centre.x).abs() > self.limits.contact_tolerance_metres.metres()
149:             || (centre.y + half.y + plot_half.y).abs()
150:                 > self.limits.contact_tolerance_metres.metres()
151:         {
152:             return Err(self.street_rejection(
153:                 SupportConstraint::ThresholdBinding,
154:                 threshold,
155:                 1.0,
156:                 0.0,
157:             ));
158:         }
159:         let bearing_begin = self
160:             .levels
161:             .front
162:             .contact
163:             .corners()
164:             .into_iter()
165:             .map(|point| local(point).y)
166:             .fold(f32::INFINITY, f32::min);
167:         let setback = bearing_begin + plot_half.y;
168:         if setback < -self.limits.contact_tolerance_metres.metres()
169:             || threshold_local.y < bearing_begin
170:         {
171:             return Err(self.street_rejection(SupportConstraint::Bearing, threshold, 1.0, 0.0));
172:         }
173:         (|| -> adventuresim_building_generator::spatial_geometry::GeometryResult<CityPlotBounds> {
174:             CityPlotBounds::new(
175:                 crate::scene_coordinates::ScenePlanPoint::try_from(
176:                     reservation.centre_metres()
177:                         + reservation.orientation().local_to_world(Vec2::Y)
178:                             * setback.max(0.0)
179:                             * 0.5,
180:                 )?,
181:                 adventuresim_building_generator::spatial_geometry::PlanDimensions::from_metres(
182:                     reservation.dimensions_metres() + Vec2::Y * setback.max(0.0),
183:                 )?,
184:                 reservation.orientation(),
185:             )
186:         })()
187:         .map_err(|cause| SupportDiagnostic::framed_geometry(&self.property, threshold, cause))
188:     }
189: 
190:     fn street_rejection(
191:         &self,
192:         constraint: SupportConstraint,
193:         point: Vec2,
194:         measured: f32,
195:         permitted: f32,
196:     ) -> SupportDiagnostic {
197:         let mut error = SupportDiagnostic::new(
198:             &self.property,
199:             constraint,
200:             SupportBoundary::StreetLanding,
201:             point,
202:             measured,
203:             permitted,
204:         );
205:         error.attempted_treatment = Box::new(SupportGradingAttempt::Compound(self.treatment));
206:         error
207:     }
208: }

