1: //! Compact accepted plans reconstruct exact support against a bound source.
2: use super::*;
3: use serde::{Deserialize, Serialize};
4: use sha2::{Digest, Sha256};
5: 
6: #[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)]
7: #[serde(transparent)]
8: pub(super) struct GeographicGeometryDigest([u8; 32]);
9: 
10: impl GeographicGeometryDigest {
11:     pub(super) fn from_geographic(source: &GeographicSurface) -> Self {
12:         let mut digest = Sha256::new();
13:         for triangle in source.triangles() {
14:             for point in triangle {
15:                 for value in point.to_array() {
16:                     digest.update(value.to_bits().to_le_bytes());
17:                 }
18:             }
19:         }
20:         Self(digest.finalize().into())
21:     }
22: }
23: 
24: #[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)]
25: #[serde(transparent)]
26: struct PlacementBindingDigest([u8; 32]);
27: impl PlacementBindingDigest {
28:     fn from_placements(
29:         placements: &[TacticalBuildingPlacement],
30:     ) -> Result<Self, serde_json::Error> {
31:         let mut ordered: Vec<_> = placements.iter().collect();
32:         ordered.sort_by_key(|p| p.id);
33:         let encoded = serde_json::to_vec(&ordered)?;
34:         Ok(Self(Sha256::digest(encoded).into()))
35:     }
36: }
37: 
38: /// The expanded closed terrain is a derived product, never a scene-input blob.
39: /// Source and placement digests bind plans to their exact geographic triangles
40: /// and occupied programmes/floors. Reconstruction publishes no partial surface.
41: #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
42: #[serde(try_from = "ProjectionWire")]
43: pub struct CityGroundingProjection {
44:     source_digest: GeographicGeometryDigest,
45:     placement_digest: PlacementBindingDigest,
46:     embedment: FoundationEmbedment,
47:     surfaces: Vec<PropertySupportSurface>,
48:     property_bindings: Vec<ProjectionPropertyBinding>,
49: }
50: 
51: #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
52: #[serde(deny_unknown_fields)]
53: struct ProjectionPropertyBinding {
54:     property: CityPropertyId,
55:     members: PropertyMembers,
56: }
57: #[derive(Deserialize)]
58: #[serde(deny_unknown_fields)]
59: struct ProjectionWire {
60:     source_digest: GeographicGeometryDigest,
61:     placement_digest: PlacementBindingDigest,
62:     embedment: FoundationEmbedment,
63:     surfaces: Vec<PropertySupportSurface>,
64:     property_bindings: Vec<ProjectionPropertyBinding>,
65: }
66: impl TryFrom<ProjectionWire> for CityGroundingProjection {
67:     type Error = CityGroundingProjectionError;
68:     fn try_from(wire: ProjectionWire) -> Result<Self, Self::Error> {
69:         let projection = Self {
70:             source_digest: wire.source_digest,
71:             placement_digest: wire.placement_digest,
72:             embedment: wire.embedment,
73:             surfaces: wire.surfaces,
74:             property_bindings: wire.property_bindings,
75:         };
76:         projection.validate_owned_surfaces()?;
77:         Ok(projection)
78:     }
79: }
