81: #[derive(Debug, thiserror::Error)]
82: pub enum CityGroundingProjectionError {
83:     #[error("compact support differs from its accepted ordered property membership")]
84:     PropertyMismatch { owners: Vec<ProjectionOwnerContext> },
85:     #[error(
86:         "property {property:?}, member {building}, floor at {location:?}: bound {expected:?}, placement {actual:?}"
87:     )]
88:     FloorMismatch {
89:         property: CityPropertyId,
90:         building: crate::scene_input::SceneBuildingId,
91:         location: crate::scene_coordinates::ScenePlanPoint,
92:         expected: SupportElevation,
93:         actual: SupportElevation,
94:     },
95:     #[error("compact support source differs from the accepted geographic triangles")]
96:     SourceMismatch { owners: Vec<ProjectionOwnerContext> },
97:     #[error("compact support programmes or placements differ from the accepted bindings")]
98:     PlacementMismatch { owners: Vec<ProjectionOwnerContext> },
99:     #[error("compact support embedment is invalid")]
100:     Embedment,
101:     #[error("occupied binding encoding failed: {0}")]
102:     Encoding(#[from] serde_json::Error),
