104:     Surface {
105:         property: CityPropertyId,
106:         issue: SupportSurfaceIssue,
107:     },
108:     #[error(transparent)]
109:     Binding(#[from] CityGroundingError),
110:     #[error(transparent)]
111:     Terrain(#[from] SettlementSupportError),
