113: 
114: impl GroundedCitySceneLayout {
115:     /// Carries the accepted complete plans instead of expanded foundation cells.
116:     pub fn support_projection(
117:         &self,
118:     ) -> Result<CityGroundingProjection, CityGroundingProjectionError> {
119:         let placements = physical_placements(&self.layout);
120:         Ok(CityGroundingProjection {
121:             source_digest: self.source_digest,
122:             placement_digest: PlacementBindingDigest::from_placements(&placements)?,
123:             embedment: self.embedment,
124:             surfaces: self.surfaces.clone(),
125:             property_bindings: self
126:                 .surfaces
127:                 .iter()
128:                 .map(|surface| {
129:                     Ok(ProjectionPropertyBinding {
130:                         property: surface.property_id(),
131:                         members: PropertyMembers::new(surface.member_building_ids().to_vec())
132:                             .map_err(|_| CityGroundingProjectionError::Surface {
133:                                 property: surface.property_id(),
134:                                 issue: SupportSurfaceIssue::Members,
135:                             })?,
136:                     })
137:                 })
138:                 .collect::<Result<Vec<_>, CityGroundingProjectionError>>()?,
139:         })
140:     }
141: }
142: 
143: /// A digest mismatch invalidates every owner bound by that digest. Retain the
144: /// complete affected set rather than naming one arbitrarily as its cause.
145: #[derive(Clone, Debug)]
146: pub struct ProjectionOwnerContext {
147:     pub property: CityPropertyId,
148:     pub members: Vec<crate::scene_input::SceneBuildingId>,
149:     pub locations: Vec<crate::scene_coordinates::ScenePlanPoint>,
150:     pub boundary: ProjectionBoundary,
151: }
152: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
153: pub enum ProjectionBoundary {
154:     GeographicTriangles,
155:     OccupiedBindings,
156: }
157: 
158: impl CityGroundingProjection {
159:     fn owner_contexts(&self, boundary: ProjectionBoundary) -> Vec<ProjectionOwnerContext> {
160:         self.surfaces
161:             .iter()
162:             .map(|surface| ProjectionOwnerContext {
163:                 property: surface.property_id(),
164:                 members: surface.member_building_ids().to_vec(),
165:                 locations: surface
166:                     .support_regions()
167:                     .iter()
168:                     .map(|region| region.centre())
169:                     .collect(),
170:                 boundary,
171:             })
172:             .collect()
173:     }
174:     fn validate_owned_surfaces(&self) -> Result<(), CityGroundingProjectionError> {
175:         let mut properties = BTreeSet::new();
176:         if self.property_bindings.len() != self.surfaces.len()
177:             || self
178:                 .property_bindings
179:                 .iter()
180:                 .zip(&self.surfaces)
181:                 .any(|(binding, surface)| {
182:                     !properties.insert(binding.property)
183:                         || binding.property != surface.property_id()
184:                         || binding.members.ids() != surface.member_building_ids()
185:                 })
186:         {
187:             return Err(CityGroundingProjectionError::PropertyMismatch {
188:                 owners: self.owner_contexts(ProjectionBoundary::OccupiedBindings),
189:             });
190:         }
191:         Ok(())
192:     }
193:     /// Scene descriptors independently bind compound property and front/rear roles.
194:     pub fn validate_compound_bindings(
195:         &self,
196:         compounds: &[CityCompound],
197:     ) -> Result<(), CityGroundingProjectionError> {
198:         for compound in compounds {
199:             let expected = [compound.front_building_id, compound.rear_building_id];
200:             if !self
201:                 .property_bindings
202:                 .iter()
203:                 .any(|binding| binding.property == compound.id && binding.members.ids() == expected)
204:             {
205:                 return Err(CityGroundingProjectionError::PropertyMismatch {
206:                     owners: self.owner_contexts(ProjectionBoundary::OccupiedBindings),
207:                 });
208:             }
209:         }
210:         if self
211:             .property_bindings
212:             .iter()
213:             .filter(|b| b.members.ids().len() == 2)
214:             .count()
215:             != compounds.len()
216:         {
217:             return Err(CityGroundingProjectionError::PropertyMismatch {
218:                 owners: self.owner_contexts(ProjectionBoundary::OccupiedBindings),
219:             });
220:         }
221:         Ok(())
222:     }
223:     /// Exact accepted owners and access regions, available for bounded diagnostics.
224:     pub fn surfaces(&self) -> &[PropertySupportSurface] {
225:         &self.surfaces
226:     }
227: 
228:     /// Validate a clean encoded projection before reconstructing closed solids.
229:     /// The exact source and complete occupied bindings are supplied explicitly.
230:     pub fn reconstruct(
231:         &self,
232:         source: &GeographicSurface,
233:         placements: &[TacticalBuildingPlacement],
234:     ) -> Result<BoundedSettlementTerrain, CityGroundingProjectionError> {
235:         if self.source_digest != GeographicGeometryDigest::from_geographic(source) {
236:             return Err(CityGroundingProjectionError::SourceMismatch {
237:                 owners: self.owner_contexts(ProjectionBoundary::GeographicTriangles),
238:             });
239:         }
240:         self.validate_bindings(placements)?;
241:         Ok(BoundedSettlementTerrain::compile(
242:             &self.surfaces,
243:             source,
244:             self.embedment,
245:         )?)
246:     }
247: 
248:     /// Check complete immutable physical bindings without expanding terrain.
249:     /// Surfaces are admitted at construction or decoding; this checks only
250:     /// cross-owner bindings. Source triangles are checked during reconstruction.
251:     pub fn validate_bindings(
252:         &self,
253:         placements: &[TacticalBuildingPlacement],
254:     ) -> Result<(), CityGroundingProjectionError> {
255:         if self.placement_digest != PlacementBindingDigest::from_placements(placements)? {
256:             return Err(CityGroundingProjectionError::PlacementMismatch {
257:                 owners: self.owner_contexts(ProjectionBoundary::OccupiedBindings),
258:             });
259:         }
260:         if !self.embedment.is_valid() {
261:             return Err(CityGroundingProjectionError::Embedment);
262:         }
263:         self.validate_owned_surfaces()?;
264:         let mut members = BTreeSet::new();
265:         let mut owners = BTreeMap::new();
266:         for surface in &self.surfaces {
267:             for building in surface.member_building_ids() {
268:                 if let Some(first) = owners.insert(*building, surface.property_id()) {
269:                     return Err(SettlementSupportError::DuplicateMember {
270:                         building: *building,
271:                         first,
272:                         second: surface.property_id(),
273:                     }
274:                     .into());
275:                 }
276:                 members.insert(*building);
277:             }
278:         }
279:         let bound_floors: BTreeMap<_, _> = self
280:             .surfaces
281:             .iter()
282:             .flat_map(|surface| {
283:                 surface
284:                     .floor_bearings()
285:                     .iter()
286:                     .map(move |floor| (floor.building(), (surface.property_id(), floor)))
287:             })
288:             .collect();
289:         for placement in placements {
290:             if let Some((property, floor)) = bound_floors.get(&placement.id)
291:                 && floor.elevation() != placement.base_elevation_metres
292:             {
293:                 return Err(CityGroundingProjectionError::FloorMismatch {
294:                     property: *property,
295:                     building: placement.id,
296:                     location: floor.regions()[0].outline().vertices()[0],
297:                     expected: floor.elevation(),
298:                     actual: placement.base_elevation_metres,
299:                 });
300:             }
301:             if !members.remove(&placement.id) {
302:                 return Err(CityGroundingError::UnboundBuilding {
303:                     building: placement.id,
304:                 }
305:                 .into());
306:             }
307:         }
308:         if let Some(building) = members.first() {
309:             return Err(CityGroundingError::UnboundBuilding {
310:                 building: *building,
311:             }
312:             .into());
313:         }
314:         Ok(())
315:     }
316: }
