1: //! Generate an accepted ramp or discrete stair approach with a full landing.
2: use super::*;
3: 
4: pub(super) struct ApronSurfaceBounds {
5:     pub stairs: CourtStairLimits,
6:     pub limits: SupportLimits,
7: }
8: 
9: pub(super) struct ApronSurfaceGeometry {
10:     pub outer: Vec2,
11:     pub direction: Vec2,
12:     pub offset: Vec2,
13:     pub run: f32,
14:     pub landing: f32,
15:     pub source: [f32; 2],
16:     pub floor: SupportElevation,
17: }
18: 
19: impl ApronSurfaceGeometry {
20:     pub fn compile(
21:         self,
22:         owner: &PropertySupportSurface,
23:         bounds: ApronSurfaceBounds,
24:     ) -> Result<PropertySupportMesh, SupportDiagnostic> {
25:         let Self {
26:             outer,
27:             direction,
28:             offset,
29:             run,
30:             landing,
31:             source,
32:             floor,
33:         } = self;
34:         let width = offset.length() * 2.0;
35:         let reject = |constraint, point, measured, permitted| {
36:             owner.rejection(
37:                 constraint,
38:                 SupportBoundary::StreetLanding,
39:                 point,
40:                 measured,
41:                 permitted,
42:             )
43:         };
44:         let stairs = bounds.stairs;
45:         let flight_run = run - landing;
46:         let across_grade = (source[0] - source[1]).abs() / width;
47:         let along_grade = source
48:             .iter()
49:             .map(|h| (floor.metres() - h).abs() / flight_run)
50:             .fold(0.0, f32::max);
51:         let mut mesh = PropertySupportMesh {
52:             positions: Vec::new(),
53:             support_triangles: Vec::new(),
54:             retaining_triangles: Vec::new(),
55:             ..owner.mesh.clone()
56:         };
57:         let edge_at = |distance: f32, heights: [f32; 2]| {
58:             let centre = outer - direction * distance;
59:             let points = [centre - offset, centre + offset];
60:             [0, 1].map(|i| Vec3::new(points[i].x, heights[i], points[i].y))
61:         };
62:         let start = edge_at(0.0, source);
63:         let end = edge_at(flight_run, [floor.metres(); 2]);
64:         if along_grade.hypot(across_grade) <= bounds.limits.maximum_grade.ratio() {
65:             mesh.quad(
66:                 [start[1], start[0], end[0], end[1]],
67:                 SupportFaceRole::Bearing,
68:             )?;
69:         } else {
70:             let rise = source
71:                 .iter()
72:                 .map(|h| (floor.metres() - h).abs())
73:                 .fold(0.0, f32::max);
74:             let count = (rise / stairs.maximum_riser_metres.metres()).ceil();
75:             let required = count * stairs.minimum_going_metres.metres();
76:             if count > f32::from(u16::MAX)
77:                 || required > flight_run + bounds.limits.contact_tolerance_metres.metres()
78:             {
79:                 return Err(reject(
80:                     SupportConstraint::StairGoing,
81:                     outer,
82:                     required,
83:                     flight_run,
84:                 ));
85:             }
86:             if across_grade > bounds.limits.maximum_grade.ratio() {
87:                 return Err(reject(
88:                     SupportConstraint::AccessGrade,
89:                     outer,
90:                     across_grade * width,
91:                     bounds.limits.maximum_grade.ratio() * width,
92:                 ));
93:             }
94:             for i in 0..count as u16 {
95:                 let t = f32::from(i) / count;
96:                 let next = f32::from(i + 1) / count;
97:                 let heights = |t| source.map(|h| h + (floor.metres() - h) * t);
98:                 let a = edge_at(flight_run * t, heights(t));
99:                 let b = edge_at(flight_run * next, heights(t));
100:                 let c = edge_at(flight_run * next, heights(next));
101:                 mesh.quad([a[1], a[0], b[0], b[1]], SupportFaceRole::Bearing)?;
102:                 mesh.quad([b[1], b[0], c[0], c[1]], SupportFaceRole::Retaining)?;
103:             }
104:         }
105:         let inside = edge_at(run, [floor.metres(); 2]);
106:         mesh.quad(
107:             [end[1], end[0], inside[0], inside[1]],
108:             SupportFaceRole::Bearing,
109:         )?;
110:         if mesh.maximum_grade() > bounds.limits.maximum_grade.ratio() {
111:             return Err(reject(
112:                 SupportConstraint::AccessGrade,
113:                 outer,
114:                 mesh.maximum_grade() * run,
115:                 bounds.limits.maximum_grade.ratio() * run,
116:             ));
117:         }
118:         Ok(mesh)
119:     }
120: }

