89:         members: PropertyMembers,
90:         cells: Vec<
91:             [adventuresim_building_generator::spatial_geometry::Position<
92:                 crate::scene_coordinates::Scene,
93:             >; 6],
94:         >,
95:         cut_faces: Vec<
96:             [adventuresim_building_generator::spatial_geometry::Position<
97:                 crate::scene_coordinates::Scene,
98:             >; 3],
