113:             return Err(SupportGeometryIssue::Topology);
114:         }
115:         for cell in cells {
116:             let points = cell.map(|p| p.metres());
117:             super::admission::prism(&points)?;
118:             mesh.append_cell(
119:                 [points[0], points[1], points[2]],
120:                 [points[3], points[4], points[5]],
