146:     pub(crate) fn validate(&self) -> Result<(), SupportGeometryIssue> {
147:         PropertyMembers::validate(&self.member_building_ids)?;
148:         if self.property_id.0 == 0 {
149:             return Err(SupportGeometryIssue::Members);
150:         }
151:         if !self.positions.len().is_multiple_of(6) || u32::try_from(self.positions.len()).is_err() {
152:             return Err(SupportGeometryIssue::Topology);
153:         }
154:         let cells = self.positions.len() / 6;
155:         if self.support_triangles.len() != cells
156:             || self.solid_triangles.len() != cells * FOUNDATION_PRISM_TRIANGLES.len()
157:         {
158:             return Err(SupportGeometryIssue::Topology);
159:         }
160:         for (cell, points) in self.positions.as_chunks::<6>().0.iter().enumerate() {
161:             super::admission::prism(points)?;
162:             let start = (cell * 6) as u32;
163:             if self.support_triangles[cell] != [start, start + 2, start + 1]
164:                 || self.solid_triangles[cell * 8..(cell + 1) * 8]
165:                     != FOUNDATION_PRISM_TRIANGLES.map(|t| t.map(|i| i + start))
166:             {
167:                 return Err(SupportGeometryIssue::Topology);
168:             }
169:         }
170:         if self.cut_faces.iter().flatten().any(|p| !p.is_finite()) {
