176:     pub fn collider(&self) -> Result<SupportCollision, SupportColliderError> {
177:         let mut parts = Vec::new();
178:         for (cell, points) in self.positions.as_chunks::<6>().0.iter().enumerate() {
179:             let points: &[Vec3; 6] = points;
180:             let Some(faces) = super::admission::solid_faces(points, FOUNDATION_PRISM_TRIANGLES)
181:             else {
182:                 continue;
183:             };
184:             let centre = points.iter().copied().sum::<Vec3>() / 6.0;
185:             let vertices = points.iter().map(|p| *p - centre).collect();
186:             // Explicit prism faces preserve finite thin cells without rebuilding
