193:                     cell,
194:                     issue: SupportGeometryIssue::Collider,
195:                 });
196:             };
197:             parts.push((
198:                 centre,
199:                 bevy::math::Quat::IDENTITY,
200:                 avian3d::prelude::Collider::from(shape),
201:             ));
