87:     fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
88:         if deserializer.is_human_readable() {
89:             let mesh = FoundationDocument::deserialize(deserializer)?;
90:             mesh.validate().map_err(D::Error::custom)?;
91:             return Ok(mesh);
92:         }
93:         let cells = FoundationCells::deserialize(deserializer)?;
94:         let count = cell_count(&cells.positions).map_err(D::Error::custom)?;
95:         let mut mesh = Self {
96:             property_id: cells.property_id,
97:             member_building_ids: cells.member_building_ids,
98:             positions: cells.positions,
99:             cut_faces: cells.cut_faces,
100:             solid_triangles: Vec::with_capacity(count * FOUNDATION_PRISM_TRIANGLES.len()),
101:             support_triangles: Vec::with_capacity(count),
102:         };
103:         for cell in 0..count {
