105:             mesh.support_triangles.push([start, start + 2, start + 1]);
106:             mesh.solid_triangles
107:                 .extend(FOUNDATION_PRISM_TRIANGLES.map(|t| t.map(|i| i + start)));
108:         }
109:         mesh.validate().map_err(D::Error::custom)?;
