64: pub(crate) fn constrain(
65:     heights: &mut [f32],
66:     width: usize,
67:     depth: usize,
68:     spacing: f32,
69:     maximum_grade: f32,
70: ) -> Result<(), TerrainGradeError> {
71:     if width < 2
72:         || depth < 2
73:         || width.checked_mul(depth) != Some(heights.len())
74:         || !spacing.is_finite()
75:         || spacing <= 0.0
76:         || !maximum_grade.is_finite()
77:         || maximum_grade < 0.0
78:         || heights.iter().any(|h| !h.is_finite())
79:     {
80:         return Err(TerrainGradeError::InvalidInput);
81:     }
82:     let bound = f64::from(spacing) * f64::from(maximum_grade);
83:     let mut values: Vec<_> = heights.iter().map(|h| f64::from(*h)).collect();
84:     let magnitude = values
85:         .iter()
86:         .fold(f64::from(spacing), |m, h| m.max(h.abs()));
87:     let roundoff = magnitude * f64::from(f32::EPSILON) * HEIGHTMAP_ROUNDOFF_ULPS;
88:     let WorstCell {
89:         rise_metres: initial,
90:         ..
91:     } = worst(&values, width, depth, None);
92:     if initial <= bound + roundoff {
93:         // Geographic relief already satisfying the physical limit retains every
94:         // original bit, including axis-aligned slopes near the permitted bound.
95:         return Ok(());
96:     }
97: 
98:     precondition(&mut values, width, depth, bound);
99:     let target = (bound - roundoff).max(0.0);
100:     let mut dirty = vec![true; (width - 1) * (depth - 1)];
101:     for sweep in 0..MAXIMUM_REPAIR_SWEEPS {
102:         repair_sweep(
103:             &mut values,
104:             &mut dirty,
105:             [width, depth],
106:             target,
107:             SweepDirection::for_pass(sweep),
108:         );
109:         // Clean cells were proved valid at their last visit and have no
110:         // subsequently changed vertex. Only dirty cells can prevent convergence.
111:         let WorstCell {
112:             rise_metres: residual,
113:             ..
114:         } = worst(&values, width, depth, Some(&dirty));
115:         if residual <= target + roundoff * 0.5 {
116:             let replacement: Vec<_> = values.into_iter().map(|value| value as f32).collect();
117:             if replacement.iter().any(|height| !height.is_finite()) {
118:                 return Err(TerrainGradeError::InvalidInput);
119:             }
120:             heights.copy_from_slice(&replacement);
121:             return Ok(());
122:         }
123:     }
124:     let WorstCell {
125:         sample,
126:         rise_metres: measured,
127:     } = worst(&values, width, depth, None);
128:     Err(TerrainGradeError::Convergence {
129:         sample: sample.unwrap_or(HeightmapCell { column: 0, row: 0 }),
130:         measured: GeographicGrade::from_ratio(measured / f64::from(spacing))
131:             .ok_or(TerrainGradeError::InvalidInput)?,
132:         permitted: TerrainGradeLimit::from_ratio(maximum_grade)
133:             .ok_or(TerrainGradeError::InvalidInput)?,
134:         sweeps: DiagnosticCount::new(MAXIMUM_REPAIR_SWEEPS as u64),
135:     })
136: }
