159: // A triangle can change only when one of its shared vertices changes. Dirty
160: // cells retain the original raster order, including changes earlier in this
161: // same pass; skipping a clean cell therefore skips only a proven no-op.
162: fn repair_sweep(
163:     values: &mut [f64],
164:     dirty: &mut [bool],
165:     [width, depth]: [usize; 2],
166:     target: f64,
167:     direction: SweepDirection,
168: ) {
169:     for row in 0..depth - 1 {
170:         let z = direction.index(row, depth);
171:         for column in 0..width - 1 {
172:             let x = direction.index(column, width);
173:             let cell = z * (width - 1) + x;
174:             if !dirty[cell] {
175:                 continue;
176:             }
177:             dirty[cell] = false;
178:             let i = z * width + x;
179:             let first = project(values, [i, i + 1, i + width], target);
180:             let second = project(values, [i + width + 1, i + width, i + 1], target);
181:             if first || second {
182:                 for adjacent_z in z.saturating_sub(1)..=(z + 1).min(depth - 2) {
183:                     for adjacent_x in x.saturating_sub(1)..=(x + 1).min(width - 2) {
184:                         dirty[adjacent_z * (width - 1) + adjacent_x] = true;
185:                     }
186:                 }
187:             }
188:         }
189:     }
190: }
