192: /// Retain the established cardinal repair as a deterministic preconditioner.
193: /// It bounds isolated source-cell jumps before the physical face projection;
194: /// it is insufficient by itself because two permitted axes can form a steep face.
195: fn precondition(values: &mut [f64], width: usize, depth: usize, bound: f64) {
196:     let clamp = |values: &mut [f64], source: usize, target: usize| {
197:         values[target] = values[target].clamp(values[source] - bound, values[source] + bound);
198:     };
199:     for _ in 0..CARDINAL_PRECONDITION_SWEEPS {
200:         for z in 0..depth {
201:             for x in 1..width {
202:                 clamp(values, z * width + x - 1, z * width + x);
203:             }
204:             for x in (0..width - 1).rev() {
205:                 clamp(values, z * width + x + 1, z * width + x);
206:             }
207:         }
208:         for x in 0..width {
209:             for z in 1..depth {
210:                 clamp(values, (z - 1) * width + x, z * width + x);
211:             }
212:             for z in (0..depth - 1).rev() {
213:                 clamp(values, (z + 1) * width + x, z * width + x);
214:             }
215:         }
216:     }
217: }
