249: #[inline]
250: fn project(values: &mut [f64], [a, b, c]: [usize; 3], bound: f64) -> bool {
251:     let u = values[b] - values[a];
252:     let v = values[c] - values[a];
253:     let norm_squared = u * u + v * v;
254:     if norm_squared < bound * bound {
255:         return false;
256:     }
257:     let norm = libm::sqrt(norm_squared);
258:     if norm <= bound {
259:         return false;
260:     }
261:     let mean = (values[a] + values[b] + values[c]) / 3.0;
262:     // In the triangle's height metric the sum/difference gradient axes have
263:     // inverse eigenvalues 3 and 1. Solving their multiplier gives the nearest
264:     // three-height projection; radial scaling is not an orthogonal projection
265:     // and can cycle when adjacent triangles share vertices.
266:     let plus = (u + v) * 0.5;
267:     let minus = (u - v) * 0.5;
268:     let mut lower = 0.0;
269:     let mut upper = if bound > 0.0 {
270:         norm / bound
271:     } else {
272:         f64::INFINITY
273:     };
274:     let (p, m) = if bound > 0.0 {
275:         for _ in 0..f32::MANTISSA_DIGITS {
276:             let multiplier = (lower + upper) * 0.5;
277:             let p = plus / (1.0 + 3.0 * multiplier);
278:             let m = minus / (1.0 + multiplier);
279:             if 2.0 * (p * p + m * m) > bound * bound {
280:                 lower = multiplier;
281:             } else {
282:                 upper = multiplier;
283:             }
284:         }
285:         (plus / (1.0 + 3.0 * upper), minus / (1.0 + upper))
286:     } else {
287:         (0.0, 0.0)
288:     };
289:     values[a] = mean - 2.0 * p / 3.0;
290:     values[b] = values[a] + p + m;
291:     values[c] = values[a] + p - m;
292:     true
293: }
