76:         match self {
77:             Self::Corridor {
78:                 start_metres,
79:                 end_metres,
80:                 half_width_metres,
81:                 ..
82:             } => {
83:                 start_metres.is_finite()
84:                     && end_metres.is_finite()
85:                     && start_metres.distance_squared(end_metres).is_finite()
86:                     && start_metres.distance_squared(end_metres) > 0.0
87:                     && half_width_metres.is_finite()
88:                     && (1.0..=20.0).contains(&half_width_metres)
89:             }
90:             Self::Market { corners_metres, .. } => corners_metres.into_iter().all(Vec2::is_finite),
