22:             Self::Lane => ORDINARY_STREET_HALF_WIDTH_METRES,
23:             Self::Secondary => SECONDARY_STREET_HALF_WIDTH_METRES,
24:             Self::TradeRoute => PRIMARY_STREET_HALF_WIDTH_METRES,
25:         }
26:     }
27:     fn surface(self) -> CityStreetSurface {
28:         match self {
29:             Self::Lane => CityStreetSurface::CompactedEarth,
30:             Self::Secondary => CityStreetSurface::Gravel,
