61: #[derive(Default)]
62: pub(super) struct StreetGraph {
63:     pub(super) blocks: Vec<CityBlock>,
64:     nodes: Vec<Vec2>,
65:     edges: Vec<StreetEdge>,
66:     node_lookup: BTreeMap<(u32, u32), StreetNodeId>,
67:     edge_lookup: BTreeMap<[StreetNodeId; 2], StreetEdgeId>,
68:     boundaries: BTreeMap<BlockId, Vec<StreetEdgeId>>,
69: }
70: 
71: impl StreetGraph {
72:     /// Complete nearby blocks before opening scattered residential frontages.
73:     pub(super) fn development_order(&self) -> BTreeMap<BlockId, usize> {
74:         let mut blocks = self.blocks.iter().collect::<Vec<_>>();
75:         blocks.sort_by(|a, b| {
76:             a.centre()
77:                 .length_squared()
78:                 .total_cmp(&b.centre().length_squared())
79:                 .then(a.id.cmp(&b.id))
80:         });
81:         blocks
82:             .into_iter()
83:             .enumerate()
84:             .map(|(rank, block)| (block.id, rank))
85:             .collect()
86:     }
87: 
88:     pub(super) fn segment(
89:         &mut self,
90:         points: [Vec2; 2],
91:         class: StreetClass,
92:         block: Option<BlockId>,
93:     ) {
94:         let mut nodes = points.map(|point| {
95:             let key = (point.x.to_bits(), point.y.to_bits());
96:             *self.node_lookup.entry(key).or_insert_with(|| {
97:                 let id = StreetNodeId(self.nodes.len());
98:                 self.nodes.push(point);
99:                 id
100:             })
101:         });
102:         nodes.sort_unstable();
103:         let id = *self.edge_lookup.entry(nodes).or_insert_with(|| {
104:             let id = StreetEdgeId(self.edges.len());
105:             self.edges.push(StreetEdge { nodes, class });
106:             id
107:         });
108:         self.edges[id.0].class = self.edges[id.0].class.max(class);
109:         if let Some(block) = block {
110:             self.boundaries.entry(block).or_default().push(id);
111:         }
112:     }
113: 
114:     pub(super) fn developed_streets(&self, developed: &BTreeSet<BlockId>) -> Vec<CityStreetPatch> {
115:         if developed.is_empty() {
116:             return Vec::new();
117:         }
118:         let mut selected = self
119:             .edges
120:             .iter()
121:             .enumerate()
122:             .filter_map(|(index, edge)| {
123:                 (edge.class == StreetClass::TradeRoute).then_some(StreetEdgeId(index))
124:             })
125:             .collect::<BTreeSet<_>>();
126:         for block in developed {
127:             selected.extend(&self.boundaries[block]);
128:         }
129:         let market = self.blocks.iter().find(|block| block.market).unwrap();
130:         selected.extend(&self.boundaries[&market.id]);
131:         let mut adjacency = vec![Vec::new(); self.nodes.len()];
132:         for (index, edge) in self.edges.iter().enumerate() {
133:             let [a, b] = edge.nodes;
134:             adjacency[a.0].push((b, StreetEdgeId(index)));
135:             adjacency[b.0].push((a, StreetEdgeId(index)));
136:         }
137:         let mut parents = vec![None; self.nodes.len()];
138:         let mut reached = vec![false; self.nodes.len()];
139:         let mut queue = VecDeque::new();
140:         for node in self
141:             .edges
142:             .iter()
143:             .filter(|edge| edge.class == StreetClass::TradeRoute)
144:             .flat_map(|edge| edge.nodes)
145:         {
146:             if !reached[node.0] {
147:                 reached[node.0] = true;
148:                 queue.push_back(node);
149:             }
150:         }
151:         while let Some(node) = queue.pop_front() {
152:             for &(next, edge) in &adjacency[node.0] {
153:                 if !reached[next.0] {
154:                     reached[next.0] = true;
155:                     parents[next.0] = Some((node, edge));
156:                     queue.push_back(next);
157:                 }
158:             }
159:         }
160:         for edge in selected.clone() {
161:             for mut node in self.edges[edge.0].nodes {
162:                 assert!(
163:                     reached[node.0],
164:                     "developed frontage is disconnected from the trade route"
165:                 );
166:                 while let Some((parent, connecting)) = parents[node.0] {
167:                     selected.insert(connecting);
168:                     node = parent;
169:                 }
170:             }
171:         }
172:         let mut patches = selected
173:             .into_iter()
174:             .map(|id| {
175:                 let edge = &self.edges[id.0];
176:                 CityStreetPatch::Corridor {
177:                     start_metres: self.nodes[edge.nodes[0].0],
178:                     end_metres: self.nodes[edge.nodes[1].0],
179:                     half_width_metres: edge.class.half_width(),
180:                     surface: edge.class.surface(),
181:                 }
182:             })
183:             .collect::<Vec<_>>();
184:         patches.push(CityStreetPatch::Market {
185:             corners_metres: self
186:                 .blocks
187:                 .iter()
188:                 .find(|block| block.market)
189:                 .unwrap()
190:                 .corners,
191:             surface: CityStreetSurface::Fieldstone,
192:         });
193:         assert!(patches.len() <= MAX_CITY_STREET_PATCHES);
194:         patches
195:     }
196: }
