36: impl SpatialBuckets {
37:     fn new(bounds: impl IntoIterator<Item = (Vec2, Vec2)>) -> Self {
38:         let mut buckets = BTreeMap::<(i32, i32), Vec<usize>>::new();
39:         for (index, (minimum, maximum)) in bounds.into_iter().enumerate() {
40:             let minimum = (minimum / SPATIAL_BUCKET_METRES).floor().as_ivec2();
41:             let maximum = (maximum / SPATIAL_BUCKET_METRES).floor().as_ivec2();
42:             for x in minimum.x..=maximum.x {
43:                 for y in minimum.y..=maximum.y {
44:                     buckets.entry((x, y)).or_default().push(index);
45:                 }
46:             }
47:         }
48:         Self(buckets)
49:     }
50: 
51:     fn at(&self, point: Vec2) -> &[usize] {
52:         let cell = (point / SPATIAL_BUCKET_METRES).floor().as_ivec2();
53:         self.0.get(&(cell.x, cell.y)).map_or(&[], Vec::as_slice)
54:     }
55: 
56:     fn overlapping(&self, minimum: Vec2, maximum: Vec2) -> impl Iterator<Item = usize> + '_ {
57:         let minimum = (minimum / SPATIAL_BUCKET_METRES).floor().as_ivec2();
58:         let maximum = (maximum / SPATIAL_BUCKET_METRES).floor().as_ivec2();
59:         (minimum.x..=maximum.x)
60:             .flat_map(move |x| (minimum.y..=maximum.y).map(move |y| (x, y)))
61:             .filter_map(|cell| self.0.get(&cell))
62:             .flatten()
63:             .copied()
64:     }
65: }
