5:     front: &TacticalBuildingPlacement,
6:     front_recipe: &Recipe,
7:     rear: &TacticalBuildingPlacement,
8:     rear_recipe: &Recipe,
9:     streets: &[CityStreetPatch],
10: ) -> Result<(), CityCompileError> {
11:     let error = |issue| CityCompileError::Compound {
12:         property: compound.id,
13:         issue,
14:     };
15:     let front_door = front_recipe
16:         .door_point(front, adventuresim_building_generator::Direction::North)?
17:         .ok_or(error(CompoundIssue::MissingCourtDoor))?
18:         .metres();
19:     let rear_door = rear_recipe
20:         .door_point(rear, adventuresim_building_generator::Direction::South)?
21:         .ok_or(error(CompoundIssue::MissingRangeDoor))?
22:         .metres();
23:     let endpoints = |route: &CityAccessSegment| [route.start_metres(), route.end_metres()];
24:     let near = |a: Vec2, b: Vec2| a.distance(b) <= CityAccessSegment::JOIN_TOLERANCE_METRES;
25:     let mut connected = BTreeSet::new();
26:     for (i, route) in compound.access.iter().enumerate() {
27:         if endpoints(route)
28:             .iter()
29:             .any(|p| streets.iter().any(|street| street.contains(*p)))
30:         {
31:             connected.insert(i);
32:         }
33:     }
34:     loop {
35:         let before = connected.len();
36:         for (i, route) in compound.access.iter().enumerate() {
37:             if connected.iter().any(|&j| {
38:                 endpoints(&compound.access[j])
39:                     .iter()
40:                     .any(|a| endpoints(route).iter().any(|b| near(*a, *b)))
41:             }) {
42:                 connected.insert(i);
43:             }
44:         }
45:         if before == connected.len() {
46:             break;
47:         }
48:     }
49:     if connected.len() != compound.access.len() || connected.is_empty() {
50:         return Err(error(CompoundIssue::StreetDisconnected));
51:     }
52:     for (door, issue) in [
53:         (front_door, CompoundIssue::MissingCourtDoor),
54:         (rear_door, CompoundIssue::MissingRangeDoor),
55:     ] {
56:         if !compound
57:             .access
58:             .iter()
59:             .any(|route| endpoints(route).iter().any(|p| near(door, *p)))
