5: const MAX_DEVELOPMENT_POPULATION: u32 = 100_000;
6: const BASE_STRIP_COUNT: usize = 32;
7: 
8: /// Keep the surveyed east/west route fixed while larger towns develop along it.
9: /// The allocation bound remains finite even for an unsupported population.
10: #[derive(Clone, Copy)]
11: pub(super) struct DevelopmentExtent {
