16: impl DevelopmentExtent {
17:     pub fn for_population(population: u32) -> Self {
18:         let population = population.clamp(BASE_DEVELOPMENT_POPULATION, MAX_DEVELOPMENT_POPULATION);
19:         let scale = population as f32 / BASE_DEVELOPMENT_POPULATION as f32;
20:         Self {
21:             strip_count: ((BASE_STRIP_COUNT as f32 * scale * 0.5).ceil() as usize) * 2,
22:             radius_y_metres: CITY_RADIUS_Y_METRES * scale,
23:         }
24:     }
