31: /// A Central German market-town design site, rather than a named reconstruction.
32: #[derive(Clone, Debug, PartialEq)]
33: pub struct CitySite {
34:     pub(super) alignment: [Vec2; 5],
35:     pub parish_policy: adventuresim_world_schema::settlement_buildings::AuthoredParishPolicy,
36: }
37: 
38: impl CitySite {
39:     pub fn central_german_market_town() -> Self {
40:         Self {
41:             parish_policy: adventuresim_world_schema::settlement_buildings::AuthoredParishPolicy::CENTRAL_GERMAN_MARKET_TOWN,
42:             alignment: [
43:                 Vec2::new(-1_800.0, -180.0),
44:                 Vec2::new(-450.0, -90.0),
45:                 Vec2::ZERO,
46:                 Vec2::new(450.0, 40.0),
47:                 Vec2::new(1_800.0, 180.0),
48:             ],
49:         }
50:     }
51: 
52:     /// Ascending eastings make the surveyed trade route an unambiguous spine.
53:     pub fn from_trade_route(alignment: [Vec2; 5]) -> Option<Self> {
54:         (alignment.iter().all(|p| p.is_finite())
55:             && alignment.windows(2).all(|pair| pair[1].x > pair[0].x)
56:             && alignment[0].x < -CITY_RADIUS_X_METRES
57:             && alignment[4].x > CITY_RADIUS_X_METRES)
58:             .then_some(Self { alignment, parish_policy: adventuresim_world_schema::settlement_buildings::AuthoredParishPolicy::CENTRAL_GERMAN_MARKET_TOWN })
59:     }
