61:     pub(super) fn route_height(&self, x: f32) -> f32 {
62:         let pair = self
63:             .alignment
64:             .windows(2)
65:             .find(|pair| x <= pair[1].x)
66:             .unwrap_or(&self.alignment[3..]);
67:         pair[0].y
68:             + (pair[1].y - pair[0].y) * ((x - pair[0].x) / (pair[1].x - pair[0].x)).clamp(0.0, 1.0)
69:     }
