1: //! Scene vertices are rounded projections, not newly authored exact polygons.
2: use super::*;
3: use crate::scene_input::BuildingOrientation;
4: use adventuresim_building_generator::plan_geometry::{ArchitecturalPlanPoint, PlanGeometryError};
5: 
6: /// The rigid transform from the authored floor datum to one scene placement.
7: #[derive(Clone, Copy, Debug)]
8: pub struct ArchitecturalPlanProjection {
9:     pub centre: ScenePlanPoint,
10:     pub origin: ArchitecturalPlanPoint,
11:     pub orientation: BuildingOrientation,
12: }
13: 
14: /// A convex physical footprint projected to finite f32 scene coordinates.
15: /// Architectural convexity and CCW topology are established before projection.
16: /// Rotation/translation preserve that topology mathematically; f32 rounding can
17: /// give nearly collinear edges tiny signed bends. These are the actual existing
18: /// render/collision coordinates, retained in order without re-hulling or epsilon
19: /// merging. An arbitrary scene polygon must pass the shared exact constructor.
20: #[derive(Clone, Debug, PartialEq, Serialize)]
21: #[serde(transparent)]
22: pub struct ScenePlanPolygon(Vec<ScenePlanPoint>);
23: impl ArchitecturalPlanProjection {
24:     pub fn from_placement(
25:         placement: &crate::scene_input::TacticalBuildingPlacement,
26:         bounds: adventuresim_building_generator::spatial_geometry::SpatialBounds<
27:             adventuresim_building_generator::spatial_geometry::Architectural,
28:         >,
29:     ) -> Result<Self, adventuresim_building_generator::spatial_geometry::GeometryError> {
30:         use bevy::math::Vec3Swizzles;
31:         if !placement.orientation.is_valid() {
32:             return Err(
33:                 adventuresim_building_generator::spatial_geometry::GeometryError::InvalidProjection,
34:             );
35:         }
36:         Ok(Self {
37:             centre: ScenePlanPoint::try_from(placement.centre_metres.metres())?,
38:             origin: ArchitecturalPlanPoint::try_from(bounds.centre()?.metres().xz())?,
39:             orientation: placement.orientation,
40:         })
41:     }
42: 
43:     /// Project one admitted architectural point with the established f32 order.
44:     pub fn point(
45:         self,
46:         point: ArchitecturalPlanPoint,
47:     ) -> Result<ScenePlanPoint, adventuresim_building_generator::spatial_geometry::GeometryError>
48:     {
49:         if !self.orientation.is_valid() {
50:             return Err(
51:                 adventuresim_building_generator::spatial_geometry::GeometryError::InvalidProjection,
52:             );
53:         }
54:         ScenePlanPoint::try_from(
55:             self.centre.metres()
56:                 + self
57:                     .orientation
58:                     .local_to_world(point.metres() - self.origin.metres()),
59:         )
60:     }
61: }
62: 
63: impl ScenePlanPolygon {
64:     pub fn from_ordered_vertices(vertices: Vec<ScenePlanPoint>) -> Result<Self, PlanGeometryError> {
65:         let polygon = PlanPolygon::from_ordered_vertices(vertices)?;
66:         Ok(Self(polygon.vertices().to_vec()))
67:     }
68: 
69:     pub fn from_architectural(
70:         source: &PlanPolygon<ArchitecturalPlanPoint>,
71:         projection: ArchitecturalPlanProjection,
72:     ) -> Result<Self, PlanGeometryError> {
73:         if !projection.orientation.is_valid() {
74:             return Err(PlanGeometryError::InvalidProjection);
75:         }
76:         let vertices = source
77:             .vertices()
78:             .iter()
79:             .map(|point| {
80:                 ScenePlanPoint::from_metres(
81:                     projection.centre.metres()
82:                         + projection
83:                             .orientation
84:                             .local_to_world(point.metres() - projection.origin.metres()),
85:                 )
86:             })
87:             .collect::<Option<Vec<_>>>()
88:             .ok_or(PlanGeometryError::NonFinite)?;
89:         Self::from_rigid_projection(vertices)
90:     }
91: 
92:     pub fn vertices(&self) -> &[ScenePlanPoint] {
93:         &self.0
94:     }
95: 
96:     pub fn translated(&self, delta: PlanDisplacement) -> Result<Self, PlanGeometryError> {
97:         let vertices = self
98:             .0
99:             .iter()
100:             .map(|point| ScenePlanPoint::from_metres(point.metres() + delta.metres()))
101:             .collect::<Option<Vec<_>>>()
102:             .ok_or(PlanGeometryError::NonFinite)?;
103:         Self::from_rigid_projection(vertices)
104:     }
105: 
106:     /// Only validated rigid transforms may enter here. Distinct vertices and
107:     /// positive represented area reject coordinate collapse/overflow; no general
108:     /// closure or deserialization can bypass the authored convexity boundary.
109:     fn from_rigid_projection(vertices: Vec<ScenePlanPoint>) -> Result<Self, PlanGeometryError> {
110:         let Some(first) = vertices.first() else {
111:             return Err(PlanGeometryError::DegeneratePolygon);
112:         };
113:         let origin = first.metres().as_dvec2();
114:         let area = vertices
115:             .iter()
116:             .zip(vertices.iter().cycle().skip(1))
117:             .map(|(a, b)| (a.metres().as_dvec2() - origin).perp_dot(b.metres().as_dvec2() - origin))
118:             .sum::<f64>();
119:         if vertices.len() < 3 || area <= 0.0 {
120:             return Err(PlanGeometryError::DegeneratePolygon);
121:         }
122:         for (vertex, point) in vertices.iter().enumerate() {
123:             if vertices[..vertex].contains(point) {
124:                 return Err(PlanGeometryError::DuplicateVertex { vertex });
125:             }
126:         }
127:         Ok(Self(vertices))
128:     }
129: }
130: 
131: #[cfg(test)]
132: mod tests {
133:     use super::*;
134:     #[test]
135:     fn rigid_projection_retains_vertices_and_rejects_coordinate_collapse() {
136:         let p = |x, y| ArchitecturalPlanPoint::from_metres(Vec2::new(x, y)).unwrap();
137:         let source = PlanPolygon::from_ordered_vertices(vec![
138:             p(0.0, 0.0),
139:             p(2.0, 0.0),
140:             p(2.0, 2.0),
141:             p(0.0, 2.0),
142:         ])
143:         .unwrap();
144:         let projection = ArchitecturalPlanProjection {
145:             centre: ScenePlanPoint::from_metres(Vec2::new(90.0, -350.0)).unwrap(),
146:             origin: p(1.0, 1.0),
147:             orientation: BuildingOrientation::from_radians(0.37).unwrap(),
148:         };
149:         let projected = ScenePlanPolygon::from_architectural(&source, projection).unwrap();
150:         assert_eq!(
151:             projected
152:                 .vertices()
153:                 .iter()
154:                 .map(|p| p.metres())
155:                 .collect::<Vec<_>>(),
156:             source
157:                 .vertices()
158:                 .iter()
159:                 .map(|p| projection.centre.metres()
160:                     + projection
161:                         .orientation
162:                         .local_to_world(p.metres() - projection.origin.metres()))
163:                 .collect::<Vec<_>>()
164:         );
165:         let delta = PlanDisplacement::from_metres(Vec2::new(-1.0, 2.0)).unwrap();
166:         let translated = projected.translated(delta).unwrap();
167:         assert_eq!(
168:             translated
169:                 .vertices()
170:                 .iter()
171:                 .map(|p| p.metres())
172:                 .collect::<Vec<_>>(),
173:             projected
174:                 .vertices()
175:                 .iter()
176:                 .map(|p| p.metres() + delta.metres())
177:                 .collect::<Vec<_>>()
178:         );
179:         let collapsed = ArchitecturalPlanProjection {
180:             centre: ScenePlanPoint::from_metres(Vec2::splat(1e20)).unwrap(),
181:             ..projection
182:         };
183:         assert!(ScenePlanPolygon::from_architectural(&source, collapsed).is_err());
184:         assert!(
185:             ScenePlanPolygon::from_ordered_vertices(
186:                 projected.vertices().iter().rev().copied().collect()
187:             )
188:             .is_err()
189:         );
190:     }
191: }

