1: //! Shared convex topology retains the coordinate-space owner at every vertex.
2: use bevy::math::Vec2;
3: 
4: /// Numeric access is limited to geometry algorithms and explicit adapters.
5: pub trait PlanVertex: Copy + PartialEq {
6:     fn plan_metres(self) -> Vec2;
7: }
8: 
9: #[derive(Clone, Copy, Debug, PartialEq, serde::Serialize, bevy::reflect::Reflect)]
10: #[serde(transparent)]
11: #[reflect(opaque)]
12: #[repr(transparent)]
13: pub struct ArchitecturalPlanPoint(Vec2);
14: impl ArchitecturalPlanPoint {
15:     pub fn from_metres(metres: Vec2) -> Result<Self, crate::spatial_geometry::GeometryError> {
16:         use crate::spatial_geometry::{CoordinateAxis, GeometryError, GeometryRole};
17:         if !metres.is_finite() {
18:             return Err(GeometryError::NonFinite {
19:                 role: GeometryRole::Position,
20:                 axis: if !metres.x.is_finite() {
21:                     CoordinateAxis::X
22:                 } else {
23:                     CoordinateAxis::Z
24:                 },
25:             });
26:         }
27:         Ok(Self(metres))
28:     }
29:     pub fn metres(self) -> Vec2 {
30:         self.0
31:     }
32: }
33: impl TryFrom<Vec2> for ArchitecturalPlanPoint {
34:     type Error = crate::spatial_geometry::GeometryError;
35:     fn try_from(metres: Vec2) -> Result<Self, Self::Error> {
36:         Self::from_metres(metres)
37:     }
38: }
39: impl<'de> serde::Deserialize<'de> for ArchitecturalPlanPoint {
40:     fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
41:         Self::from_metres(<Vec2 as serde::Deserialize>::deserialize(d)?)
42:             .map_err(serde::de::Error::custom)
43:     }
44: }
45: impl PlanVertex for ArchitecturalPlanPoint {
46:     fn plan_metres(self) -> Vec2 {
47:         self.metres()
48:     }
49: }
50: 
51: #[derive(Clone, Debug, PartialEq, serde::Serialize)]
52: #[serde(rename_all = "snake_case")]
53: pub enum PlanGeometryError {
54:     Geometry(crate::spatial_geometry::GeometryError),
55:     SolidConstruction {
56:         solid: crate::ResolvedItemId,
57:         cause: crate::spatial_geometry::GeometryError,
58:     },
59:     NonFinite,
60:     InvalidProjection,
61:     NegativeSolidDimension,
62:     DegeneratePolygon,
63:     DuplicateVertex {
64:         vertex: usize,
65:     },
66:     NonConvexOrClockwise {
67:         vertex: usize,
68:     },
69: }
70: impl std::fmt::Display for PlanGeometryError {
71:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
72:         match self {
73:             Self::Geometry(cause) => cause.fmt(f),
74:             Self::SolidConstruction { solid, cause } => write!(f, "solid {solid:?}: {cause}"),
75:             Self::InvalidProjection => f.write_str("invalid rigid plan projection"),
76:             Self::NonFinite => f.write_str("nonfinite plan geometry"),
77:             Self::NegativeSolidDimension => f.write_str("negative solid dimension"),
78:             Self::DuplicateVertex { vertex } => write!(f, "duplicate polygon vertex {vertex}"),
79:             Self::DegeneratePolygon => f.write_str("plan polygon has no area"),
80:             Self::NonConvexOrClockwise { vertex } => write!(
81:                 f,
82:                 "plan polygon is not counterclockwise convex at vertex {vertex}"
83:             ),
84:         }
85:     }
86: }
87: impl std::error::Error for PlanGeometryError {
88:     fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
89:         match self {
90:             Self::Geometry(cause) => Some(cause),
91:             Self::SolidConstruction { cause, .. } => Some(cause),
92:             _ => None,
93:         }
94:     }
95: }
96: impl From<crate::spatial_geometry::GeometryError> for PlanGeometryError {
97:     fn from(cause: crate::spatial_geometry::GeometryError) -> Self {
98:         Self::Geometry(cause)
99:     }
100: }
