102: #[derive(Clone, Debug, PartialEq)]
103: pub struct PlanSegment<P: PlanVertex> {
104:     start: P,
105:     end: P,
106: }
107: impl<P: PlanVertex> PlanSegment<P> {
108:     pub fn start(&self) -> P {
109:         self.start
110:     }
111:     pub fn end(&self) -> P {
112:         self.end
113:     }
114: }
115: 
116: /// Finite nondegenerate counterclockwise convex vertices. Collinear boundary
117: /// vertices are allowed; construction never reorders an authored polygon.
118: #[derive(Clone, Debug, PartialEq, serde::Serialize)]
119: pub struct PlanPolygon<P: PlanVertex> {
120:     vertices: Vec<P>,
121: }
122: impl<P: PlanVertex> PlanPolygon<P> {
123:     pub fn from_ordered_vertices(vertices: Vec<P>) -> Result<Self, PlanGeometryError> {
124:         if vertices.iter().any(|p| !p.plan_metres().is_finite()) {
125:             return Err(PlanGeometryError::NonFinite);
126:         }
127:         if vertices.len() < 3 || signed_area(&vertices) == 0.0 {
128:             return Err(PlanGeometryError::DegeneratePolygon);
129:         }
130:         if signed_area(&vertices) < 0.0 {
131:             return Err(PlanGeometryError::NonConvexOrClockwise { vertex: 0 });
132:         }
133:         for (vertex, &a) in vertices.iter().enumerate() {
134:             if vertices[..vertex]
135:                 .iter()
136:                 .any(|&previous| previous.plan_metres() == a.plan_metres())
137:             {
138:                 return Err(PlanGeometryError::DuplicateVertex { vertex });
139:             }
140:             let b = vertices[(vertex + 1) % vertices.len()];
141:             if vertices.iter().any(|&point| cross(a, b, point) < 0.0) {
142:                 return Err(PlanGeometryError::NonConvexOrClockwise { vertex });
143:             }
144:         }
145:         Ok(Self { vertices })
146:     }
147:     pub fn vertices(&self) -> &[P] {
148:         &self.vertices
149:     }
150:     pub fn try_map<Q: PlanVertex>(
151:         &self,
152:         mut map: impl FnMut(P) -> Result<Q, PlanGeometryError>,
153:     ) -> Result<PlanPolygon<Q>, PlanGeometryError> {
154:         let vertices = self
155:             .vertices
156:             .iter()
157:             .copied()
158:             .map(&mut map)
159:             .collect::<Result<Vec<_>, _>>()?;
160:         PlanPolygon::from_ordered_vertices(vertices)
161:     }
162: }
163: 
164: pub(crate) enum PlanHull<P: PlanVertex> {
165:     Empty,
166:     Point(P),
167:     Segment(PlanSegment<P>),
168:     Area(PlanPolygon<P>),
169: }
170: impl<P: PlanVertex> PlanHull<P> {
171:     /// Classify the exact computed finite coordinates: no proximity epsilon.
172:     /// Orientation uses f64 differences of f32 coordinates. Signed zeros compare
173:     /// geometrically equal, including during sorting and duplicate removal.
174:     pub(crate) fn from_points(mut points: Vec<P>) -> Result<Self, PlanGeometryError> {
175:         if points.iter().any(|p| !p.plan_metres().is_finite()) {
176:             return Err(PlanGeometryError::NonFinite);
177:         }
178:         points.sort_by(|a, b| {
179:             let a = a.plan_metres();
180:             let b = b.plan_metres();
181:             let order = |a: f32, b: f32| {
182:                 if a == b {
183:                     std::cmp::Ordering::Equal
184:                 } else {
185:                     a.total_cmp(&b)
186:                 }
187:             };
188:             order(a.x, b.x).then(order(a.y, b.y))
189:         });
190:         points.dedup_by(|a, b| a.plan_metres() == b.plan_metres());
