1: //! Staggered old-quarter lanes meet shared seams at real T-junctions.
2: use super::*;
3: 
4: const SITE_HALF_WIDTH_METRES: f32 = CITY_RADIUS_X_METRES;
5: const EXTENSION_START_METRES: f32 = 300.0;
6: const EXTENSION_BLOCK_METRES: f32 = 96.0;
7: const OLD_BLOCK_MIN_METRES: f32 = 96.0;
8: const OLD_BLOCK_VARIATION_METRES: f32 = 48.0;
9: const MARKET_LENGTH_METRES: f32 = 112.0;
10: const JUNCTION_SPACING_METRES: f32 = 2.0;
11: const STRIP_DEPTH_METRES: f32 = 56.0;
12: const OLD_SEAM_OFFSET_METRES: f32 = 18.0;
13: const OLD_SEAM_PHASE: f32 = 0.45;
14: 
15: pub(super) fn build(
16:     site: &CitySite,
17:     seed: fabelgeist_determinism::Seed,
18:     extent: DevelopmentExtent,
19: ) -> StreetGraph {
20:     let strip_count = extent.strip_count;
21:     let market_strip = extent.market_strip();
22:     let cuts = (0..strip_count)
23:         .map(|strip| strip_cuts(site, seed, strip, market_strip))
24:         .collect::<Vec<_>>();
25:     let seams = (0..=strip_count)
26:         .map(|seam| {
27:             let mut points = Vec::new();
28:             for strip in &cuts[seam.saturating_sub(1)..=seam.min(strip_count - 1)] {
29:                 points.extend_from_slice(strip);
30:             }
31:             points.sort_by(f32::total_cmp);
32:             points.dedup();
33:             points
34:         })
35:         .collect::<Vec<_>>();
36:     let mut graph = StreetGraph::default();
37:     for (strip, splits) in cuts.iter().enumerate() {
38:         for (index, interval) in splits.windows(2).enumerate() {
39:             let [left, right] = [interval[0], interval[1]];
40:             let block = CityBlock {
41:                 id: BlockId(((strip as u64) << 32) | index as u64),
42:                 corners: [
43:                     point(site, strip, left, market_strip),
44:                     point(site, strip, right, market_strip),
45:                     point(site, strip + 1, right, market_strip),
46:                     point(site, strip + 1, left, market_strip),
47:                 ],
48:                 streets: [
49:                     seam_class(strip, market_strip),
50:                     StreetClass::Lane,
51:                     seam_class(strip + 1, market_strip),
52:                     StreetClass::Lane,
53:                 ],
54:                 market: false,
55:             };
56:             for seam in [strip, strip + 1] {
57:                 let boundary = seams[seam]
58:                     .iter()
59:                     .copied()
60:                     .filter(|x| *x >= left && *x <= right)
61:                     .collect::<Vec<_>>();
62:                 for ends in boundary.windows(2) {
63:                     graph.segment(
64:                         [
65:                             point(site, seam, ends[0], market_strip),
66:                             point(site, seam, ends[1], market_strip),
67:                         ],
68:                         seam_class(seam, market_strip),
69:                         Some(block.id),
70:                     );
71:                 }
72:             }
73:             for x in [left, right] {
74:                 graph.segment(
75:                     [
76:                         point(site, strip, x, market_strip),
77:                         point(site, strip + 1, x, market_strip),
78:                     ],
79:                     StreetClass::Lane,
80:                     Some(block.id),
81:                 );
82:             }
83:             graph.blocks.push(block);
84:         }
85:     }
86:     connect_market_and_approaches(&mut graph, site, market_strip);
87:     graph
88: }
89: 
90: fn connect_market_and_approaches(graph: &mut StreetGraph, site: &CitySite, market_strip: usize) {
91:     let market = graph
92:         .blocks
93:         .iter_mut()
94:         .filter(|block| block.streets[0] == StreetClass::TradeRoute)
95:         .filter(|block| block.corners[0].distance(block.corners[1]) >= OLD_BLOCK_MIN_METRES)
96:         .min_by(|a, b| {
97:             a.centre()
98:                 .length_squared()
99:                 .total_cmp(&b.centre().length_squared())
100:         })
101:         .expect("the surveyed spine has a full-width market site");
102:     market.market = true;
103:     for side in [-1.0, 1.0] {
104:         let mut approach = site
105:             .alignment
106:             .iter()
107:             .copied()
108:             .filter(|anchor| anchor.x * side > SITE_HALF_WIDTH_METRES)
109:             .collect::<Vec<_>>();
110:         approach.sort_by(|a, b| (a.x * side).total_cmp(&(b.x * side)));
111:         approach.insert(
112:             0,
113:             point(
114:                 site,
115:                 market_strip,
116:                 side * SITE_HALF_WIDTH_METRES,
117:                 market_strip,
118:             ),
119:         );
120:         for segment in approach.windows(2) {
121:             graph.segment([segment[0], segment[1]], StreetClass::TradeRoute, None);
122:         }
123:     }
124: }
