134: fn point(site: &CitySite, seam: usize, x: f32, market_strip: usize) -> Vec2 {
135:     let offset = seam as i32 - market_strip as i32;
136:     let regular = offset as f32 * STRIP_DEPTH_METRES;
137:     // Unequal old strips retain deep working plots; the eastern extension has
138:     // shared, regular seams. Transition occurs only between authored breakpoints.
139:     let old = regular + (offset as f32 * OLD_SEAM_PHASE).sin() * OLD_SEAM_OFFSET_METRES;
140:     let extension = (x / EXTENSION_START_METRES).clamp(0.0, 1.0);
141:     Vec2::new(x, old + (regular - old) * extension + site.route_height(x))
142: }
143: 
144: fn strip_cuts(
145:     site: &CitySite,
146:     seed: fabelgeist_determinism::Seed,
147:     strip: usize,
148:     market_strip: usize,
149: ) -> Vec<f32> {
150:     let mut anchors = vec![
151:         -SITE_HALF_WIDTH_METRES,
152:         0.0,
153:         MARKET_LENGTH_METRES,
154:         EXTENSION_START_METRES,
155:         SITE_HALF_WIDTH_METRES,
156:     ];
157:     anchors.extend(
158:         site.alignment
159:             .iter()
160:             .map(|p| p.x)
161:             .filter(|x| x.abs() < SITE_HALF_WIDTH_METRES),
162:     );
163:     anchors.sort_by(f32::total_cmp);
164:     anchors.dedup();
165:     let mut cuts = Vec::new();
166:     for span in anchors.windows(2) {
167:         let [left, right] = [span[0], span[1]];
168:         cuts.push(left);
169:         if strip == market_strip && left == 0.0 && right == MARKET_LENGTH_METRES {
170:             continue;
171:         }
172:         let sample = StreamId::new("city.street-span")
173:             .seed(seed, &[strip as u64, u64::from(left.to_bits())]);
174:         let length = if left >= EXTENSION_START_METRES {
175:             EXTENSION_BLOCK_METRES
176:         } else {
177:             OLD_BLOCK_MIN_METRES
178:                 + StreamId::new("city.block-length")
179:                     .rng(sample, &[])
180:                     .inclusive_unit_f32()
181:                     * OLD_BLOCK_VARIATION_METRES
182:         };
183:         let count = ((right - left) / length).round().max(1.0) as usize;
184:         for index in 1..count {
185:             let fraction = index as f32 / count as f32;
186:             let irregular = if left >= EXTENSION_START_METRES {
187:                 0.0
188:             } else {
189:                 StreamId::new("city.street-jitter")
190:                     .rng(sample, &[index as u64])
191:                     .range_f32(-1.0, 1.0)
192:                     * 0.18
193:                     / count as f32
194:             };
195:             let distance = (right - left) * (fraction + irregular);
196:             let distance = if left >= EXTENSION_START_METRES {
197:                 distance
198:             } else {
199:                 (distance / JUNCTION_SPACING_METRES).round() * JUNCTION_SPACING_METRES
200:             };
201:             cuts.push(left + distance);
202:         }
203:     }
204:     cuts.push(SITE_HALF_WIDTH_METRES);
205:     cuts
206: }

