20:     normals: Vec<[f32; 3]>,
21:     #[serde(with = "adventuresim_tactical_core::geometry_transport::binary")]
22:     uvs: Vec<[f32; 2]>,
23:     #[serde(with = "adventuresim_tactical_core::geometry_transport::binary")]
