36: #[repr(u8)]
37: enum PatchKind {
38:     Corridor,
39:     Market,
40:     Yard,
41: }
42: 
43: impl CitySurfaceMeshBuilder {
44:     pub(super) fn append_street(
45:         &mut self,
46:         street: CityStreetPatch,
47:         support: &GroundSupport,
48:         groups: &partition::SpatialIndex<'_, FurnitureGroup>,
49:     ) {
50:         let lift_metres = SURFACE_LIFT_METRES
51:             + f32::from(street.surface().priority()) * SURFACE_PRIORITY_LIFT_METRES;
52:         let patch = match street {
53:             CityStreetPatch::Corridor {
54:                 start_metres,
55:                 end_metres,
56:                 half_width_metres,
57:                 ..
58:             } => {
59:                 let tangent = (end_metres - start_metres).normalize();
60:                 let normal = Vec2::new(-tangent.y, tangent.x) * half_width_metres;
61:                 SurfacePatch {
62:                     corners: [
63:                         start_metres - normal,
64:                         start_metres + normal,
65:                         end_metres + normal,
66:                         end_metres - normal,
67:                     ],
68:                     lift_metres,
69:                     kind: PatchKind::Corridor,
70:                 }
71:             }
72:             CityStreetPatch::Market { corners_metres, .. } => SurfacePatch {
73:                 corners: corners_metres,
74:                 // The plaza owns crossing wear above the streets beneath it.
75:                 lift_metres: lift_metres + MARKET_PRIORITY_LIFT_METRES,
76:                 kind: PatchKind::Market,
77:             },
78:         };
79:         self.append(patch, &[], support, groups);
80:     }
81: 
82:     pub(super) fn append_yard(
83:         &mut self,
84:         yard: CityYardPatch,
85:         beds: &partition::SpatialIndex<'_, [Vec2; 4]>,
86:         support: &GroundSupport,
87:         groups: &partition::SpatialIndex<'_, FurnitureGroup>,
88:     ) {
89:         let exclusions = beds
90:             .candidates(yard.corners_metres)
91:             .into_iter()
92:             .copied()
93:             .filter(|bed| {
94:                 yard.surface == CityYardSurface::PackedEarth
95:                     && partition::overlaps(yard.corners_metres, *bed)
96:             })
97:             .collect::<Vec<_>>();
98:         self.append(
99:             SurfacePatch {
100:                 corners: yard.corners_metres,
101:                 lift_metres: YARD_SURFACE_LIFT_METRES,
102:                 kind: PatchKind::Yard,
103:             },
104:             &exclusions,
105:             support,
106:             groups,
107:         );
108:     }
109: 
110:     fn append(
111:         &mut self,
112:         patch: SurfacePatch,
113:         exclusions: &[[Vec2; 4]],
114:         support: &GroundSupport,
115:         groups: &partition::SpatialIndex<'_, FurnitureGroup>,
116:     ) {
117:         let [a, b, c, d] = patch.corners;
118:         let width = a.distance(b).max(d.distance(c));
119:         let depth = a.distance(d).max(b.distance(c));
120:         let activity = activity::ActivityWear::for_patch(patch.corners, groups);
121:         support.clip(patch.corners, |triangle| {
122:             let plane_normal = (triangle[1] - triangle[0]).cross(triangle[2] - triangle[0]);
123:             let normal = plane_normal.normalize().as_vec3();
124:             let minimum = triangle
125:                 .map(|p| p.xz().as_vec2())
126:                 .into_iter()
127:                 .fold(Vec2::splat(f32::INFINITY), Vec2::min);
128:             let maximum = triangle
129:                 .map(|p| p.xz().as_vec2())
130:                 .into_iter()
131:                 .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max);
132:             for polygon in partition::subtract(triangle.to_vec(), exclusions) {
133:                 for tile in traffic::TrafficTile::covering(minimum, maximum) {
134:                     let polygon = support::clip_polygon(polygon.clone(), tile.corners());
135:                     for index in 1..polygon.len().saturating_sub(1) {
136:                         let clipped = [polygon[0], polygon[index], polygon[index + 1]];
137:                         if (clipped[1] - clipped[0])
138:                             .cross(clipped[2] - clipped[0])
139:                             .length_squared()
140:                             == 0.0
141:                         {
142:                             continue;
143:                         }
144:                         let vertices = self.chunks.entry(tile).or_default();
145:                         for point in clipped {
146:                             // Represent the completed intersection once. Its Y
147:                             // follows the same physical plane at the final X/Z,
148:                             // rather than at a pre-rounded intermediate point.
149:                             let mut point = point.as_vec3();
150:                             let anchor = triangle[0];
151:                             point.y = (anchor.y
152:                                 - (plane_normal.x * (f64::from(point.x) - anchor.x)
153:                                     + plane_normal.z * (f64::from(point.z) - anchor.z))
154:                                     / plane_normal.y) as f32;
155:                             let uv = support::footprint_uv(patch.corners, point.xz());
156:                             vertices.uvs.push(uv.to_array());
157:                             vertices.activities.push(activity.at(point.xz()).to_array());
158:                             vertices.footprints.push([
159:                                 width,
160:                                 depth,
161:                                 f32::from(patch.kind as u8),
162:                                 1.0,
163:                             ]);
164:                             point.y += patch.lift_metres;
165:                             vertices.positions.push(point.to_array());
166:                             vertices.normals.push(normal.to_array());
167:                         }
168:                     }
169:                 }
170:             }
171:         });
172:     }
