16: impl GroundSupport {
17:     /// Admitted patch buffers use the same canonical east/up/north metres as
18:     /// ordinary terrain. Retain their walkable faces without renderer meshes.
19:     pub(in crate::presentation::vista) fn add_patch(&mut self, patch: &SceneTerrainPatch) {
20:         self.add_triangles(
21:             patch.indices().as_chunks::<3>().0.iter().map(|indices| {
22:                 indices.map(|index| Vec3::from_array(patch.positions()[index as usize]))
23:             }),
24:             Vec3::ZERO,
