28:     /// Highest point on the presented city ground, in canonical east/up/north
29:     /// metres. Missing coverage never substitutes a heightfield or nearest face.
30:     pub(in crate::presentation) fn position(&self, point: ScenePlanPoint) -> Option<Vec3> {
31:         let point = point.metres();
32:         let index = self
33:             .index
34:             .get_or_init(|| index::TriangleIndex::new(&self.triangles));
35:         let mut highest: Option<Vec3> = None;
36:         index.query(point, point, |index| {
37:             let triangle = self.triangles[index].map(Vec3::as_dvec3);
38:             let query = point.as_dvec2();
39:             let [a, b, c] = triangle;
40:             // Upward-facing source triangles are clockwise in the east/north
41:             // plan. Classify edges in double precision, as paving clipping does.
42:             if [(a, b), (b, c), (c, a)].into_iter().any(|(start, end)| {
43:                 (end.xz() - start.xz()).perp_dot(query - start.xz()) > f64::from(CLIP_EPSILON)
44:             }) {
45:                 return;
46:             }
47:             let normal = (b - a).cross(c - a);
48:             let height = a.y - (normal.x * (query.x - a.x) + normal.z * (query.y - a.z)) / normal.y;
49:             let position = Vec3::new(point.x, height as f32, point.y);
50:             if highest.is_none_or(|current| position.y > current.y) {
51:                 highest = Some(position);
52:             }
53:         });
54:         highest
55:     }
