57:     pub(in crate::presentation::vista) fn add_mesh(&mut self, mesh: &Mesh, origin: Vec3) {
58:         let Some(positions) = mesh
59:             .attribute(Mesh::ATTRIBUTE_POSITION)
60:             .and_then(VertexAttributeValues::as_float3)
61:         else {
62:             return;
63:         };
64:         let Some(indices) = mesh.indices() else {
65:             return;
66:         };
67:         let indices = indices.iter().collect::<Vec<_>>();
68:         let triangles = indices.as_chunks::<3>().0.iter().map(|indices| {
69:             [indices[0], indices[1], indices[2]].map(|index| Vec3::from_array(positions[index]))
70:         });
