74:     /// Owned terrain already carries the exact triangles. Avoid materializing
75:     /// renderer vertices, normals, UVs and indices just to discard buried and
76:     /// vertical faces for street clipping. The eligibility rule is shared.
77:     pub(in crate::presentation::vista) fn add_triangles(
78:         &mut self,
79:         triangles: impl IntoIterator<Item = [Vec3; 3]>,
80:         origin: Vec3,
81:     ) {
82:         for triangle in triangles {
83:             let triangle = triangle.map(|point| point + origin);
84:             // Vista skirts and cliff walls are not walkable ground support.
85:             if (triangle[1] - triangle[0])
86:                 .cross(triangle[2] - triangle[0])
87:                 .y
88:                 <= CLIP_EPSILON
89:             {
90:                 continue;
91:             }
92:             self.triangles.push(triangle);
93:         }
94:         self.index.take();
95:     }
