97:     pub(in crate::presentation) fn clip(
98:         &self,
99:         corners: [Vec2; 4],
100:         mut emit: impl FnMut([bevy::math::DVec3; 3]),
101:     ) {
102:         let minimum = corners
103:             .into_iter()
104:             .fold(Vec2::splat(f32::INFINITY), Vec2::min);
105:         let maximum = corners
106:             .into_iter()
107:             .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max);
108:         let index = self
109:             .index
110:             .get_or_init(|| index::TriangleIndex::new(&self.triangles));
111:         index.query(minimum, maximum, |index| {
112:             let triangle = self.triangles[index];
113:             let tri_minimum = triangle
114:                 .map(|point| point.xz())
115:                 .into_iter()
116:                 .fold(Vec2::splat(f32::INFINITY), Vec2::min);
117:             let tri_maximum = triangle
118:                 .map(|point| point.xz())
119:                 .into_iter()
120:                 .fold(Vec2::splat(f32::NEG_INFINITY), Vec2::max);
121:             if !tri_maximum.cmpge(minimum).all() || !tri_minimum.cmple(maximum).all() {
122:                 return;
123:             }
124:             let polygon = clip_polygon(triangle.map(Vec3::as_dvec3).to_vec(), corners);
125:             for index in 1..polygon.len().saturating_sub(1) {
126:                 let clipped = [polygon[0], polygon[index], polygon[index + 1]];
127:                 if (clipped[1] - clipped[0])
128:                     .cross(clipped[2] - clipped[0])
129:                     .length_squared()
130:                     > f64::from(CLIP_EPSILON * CLIP_EPSILON)
131:                 {
132:                     emit(clipped);
133:                 }
134:             }
135:         });
136:     }
137: }
138: 
139: pub(super) fn clip_polygon(
140:     mut polygon: Vec<bevy::math::DVec3>,
141:     corners: [Vec2; 4],
142: ) -> Vec<bevy::math::DVec3> {
143:     // Keep intersections in double precision until the represented polygon is
144:     // complete. Repeated f32 lerps can move a constant source edge by one ULP
145:     // across a retaining boundary and place paving on the wrong ground level.
146:     let corners = corners.map(Vec2::as_dvec2);
147:     let winding = (corners[1] - corners[0])
148:         .perp_dot(corners[3] - corners[0])
149:         .signum();
150:     for side in 0..4 {
151:         let start = corners[side];
152:         let edge = corners[(side + 1) % 4] - start;
153:         let distance = |point: bevy::math::DVec3| edge.perp_dot(point.xz() - start) * winding;
154:         let mut clipped = Vec::new();
155:         for index in 0..polygon.len() {
156:             let a = polygon[index];
157:             let b = polygon[(index + 1) % polygon.len()];
158:             let da = distance(a);
159:             let db = distance(b);
160:             if da >= -f64::from(CLIP_EPSILON) {
161:                 clipped.push(a);
162:             }
163:             if (da >= 0.0) != (db >= 0.0) {
164:                 clipped.push(a.lerp(b, da / (da - db)));
165:             }
166:         }
167:         polygon = clipped;
168:         if polygon.is_empty() {
169:             break;
170:         }
171:     }
172:     polygon
173: }
