175: /// Inverse bilinear coordinates preserve the semantic market/yard footprint
176: /// when terrain clipping inserts vertices on an irregular block boundary.
177: pub(super) fn footprint_uv(corners: [Vec2; 4], point: Vec2) -> Vec2 {
178:     let [a, b, c, d] = corners;
179:     let mut uv = Vec2::splat(0.5);
180:     for _ in 0..6 {
181:         let residual = a.lerp(b, uv.x).lerp(d.lerp(c, uv.x), uv.y) - point;
182:         let du = (b - a).lerp(c - d, uv.y);
183:         let dv = (d - a).lerp(c - b, uv.x);
184:         let determinant = du.perp_dot(dv);
185:         if determinant.abs() < CLIP_EPSILON {
186:             break;
187:         }
188:         uv -= Vec2::new(residual.perp_dot(dv), du.perp_dot(residual)) / determinant;
189:     }
190:     uv.clamp(Vec2::ZERO, Vec2::ONE)
191: }
