70:     }
71:     let half_depth = property.plot.dimensions_metres().y * 0.5;
72:     // Vertical terrace boundaries are retaining faces, not walkable ramps.
73:     // Only the explicitly reserved stair flights cross these boundaries.
74:     let points = [
75:         ProfilePoint::at_metres(-half_depth, floor),
76:         ProfilePoint::at_metres(minimum, floor),
77:         ProfilePoint::at_metres(minimum, levels.court),
78:         ProfilePoint::at_metres(maximum, levels.court),
79:         ProfilePoint::at_metres(maximum, levels.rear.elevation),
80:         ProfilePoint::at_metres(half_depth, levels.rear.elevation),
81:     ];
82:     Ok(CourtSupportConstruction {
83:         profile: court_sequence(property, points.into_iter().collect())?,
84:         stairs,
85:     })
86: }
87: 
88: fn court_sequence(
89:     property: &CityCompound,
90:     points: Vec<Option<ProfilePoint>>,
91: ) -> Result<SupportProfile, SupportDiagnostic> {
92:     SupportProfile::stepped(
93:         points
94:             .into_iter()
95:             .collect::<Option<Vec<_>>>()
96:             .ok_or_else(|| {
97:                 SupportDiagnostic::new(
98:                     property,
99:                     SupportConstraint::Reservation,
100:                     SupportBoundary::CourtLanding,
101:                     property.court.centre_metres(),
102:                     1.0,
103:                     0.0,
104:                 )
105:             })?,
106:     )
107:     .map_err(|error| {
108:         SupportDiagnostic::new(
109:             property,
110:             SupportConstraint::Reservation,
111:             SupportBoundary::CourtLanding,
112:             property.plot.centre_metres()
113:                 + property
114:                     .plot
115:                     .orientation()
116:                     .local_to_world(Vec2::Y * error.coordinate().metres()),
117:             1.0,
118:             0.0,
119:         )
120:     })
121: }
122: 
123: pub(super) fn passage(
124:     property: &CityCompound,
125:     levels: CompoundSupportLevels,
126:     route: CityAccessSegment,
127:     limits: SupportLimits,
128: ) -> Result<SupportProfile, SupportDiagnostic> {
129:     let delta = route.end_metres() - route.start_metres();
130:     let length = delta.length();
131:     let direction = delta / length;
132:     let gate = (property.boundary.gate.centre_metres - route.start_metres()).dot(direction);
133:     let door = property
134:         .boundary
135:         .gate
136:         .door(property.id)
137:         .map_err(|cause| SupportDiagnostic::gate_construction(property, cause))?;
138:     let hinge = (door.hinge_centre.metres().xz() - route.start_metres()).dot(direction);
139:     let platform_end = hinge
140:         + door
141:             .horizontal_sweep_radius_metres()
142:             .map_err(|cause| SupportDiagnostic::gate_construction(property, cause))?
143:         + route.half_width_metres();
144:     let points = [
145:         ProfilePoint::at_metres(0.0, levels.street),
146:         ProfilePoint::at_metres(route.half_width_metres(), levels.street),
147:         ProfilePoint::at_metres(gate - route.half_width_metres(), levels.gate),
148:         ProfilePoint::at_metres(platform_end, levels.gate),
149:         ProfilePoint::at_metres(length - route.half_width_metres(), levels.court),
150:         ProfilePoint::at_metres(length, levels.court),
151:     ];
152:     SupportProfile::checked(
153:         property,
154:         points
155:             .into_iter()
156:             .collect::<Option<Vec<_>>>()
157:             .ok_or_else(|| {
158:                 SupportDiagnostic::new(
159:                     property,
160:                     SupportConstraint::Reservation,
161:                     SupportBoundary::GateLanding,
162:                     route.start_metres(),
163:                     1.0,
164:                     0.0,
165:                 )
166:             })?,
167:         limits,
168:         SupportBoundary::GateLanding,
169:         |distance| route.start_metres() + direction * distance.metres(),
170:     )
171: }
