1: //! Complete source intersections bound an affine change to occupied floor levels.
2: use super::*;
3: use adventuresim_building_generator::spatial_geometry::SignedLength;
4: 
5: #[derive(Clone, Copy, Debug)]
6: struct Control {
7:     point: Vec2,
8:     support: f64,
9:     source: f64,
10:     coefficient: f64,
11: }
12: 
13: pub(super) fn floor_shift(
14:     plan: &CompoundSupportPlan,
15:     geographic: &GeographicSurface,
16: ) -> Result<SignedLength, SupportDiagnostic> {
17:     let surface = plan.support_surface()?;
18:     let original = surface.mesh();
19:     let basis = plan.floor_translation_basis()?.mesh()?;
20:     let invalid_triangle = |point| {
21:         SupportDiagnostic::new(
22:             &plan.property,
23:             SupportConstraint::Reservation,
24:             SupportBoundary::PropertyReservation,
25:             point,
26:             1.0,
27:             0.0,
28:         )
29:     };
30:     let mut interval = FloorInterval {
31:         minimum: f64::NEG_INFINITY,
32:         maximum: f64::INFINITY,
33:         upper_control: None,
34:     };
35:     for (indices, shifted) in original
36:         .support_triangles
37:         .iter()
38:         .zip(&basis.support_triangles)
39:     {
40:         let support = GroundTriangle::new(indices.map(|i| original.positions[i as usize]))
41:             .ok_or_else(|| invalid_triangle(original.positions[indices[0] as usize].xz()))?;
42:         let shifted = GroundTriangle::new(shifted.map(|i| basis.positions[i as usize]))
43:             .ok_or_else(|| invalid_triangle(basis.positions[shifted[0] as usize].xz()))?;
44:         let mut covered = 0.0;
45:         for source in geographic.intersecting(&support) {
46:             let polygon = support.intersection(source);
47:             if polygon.len() < 3 || geometry::area(&polygon) <= 0.0 {
48:                 continue;
49:             }
50:             covered += geometry::area(&polygon);
51:             for point in polygon {
52:                 let height = support.height_f64(point.as_dvec2());
53:                 interval.constrain(
54:                     plan,
55:                     Control {
56:                         point,
57:                         support: height,
58:                         source: source.height_f64(point.as_dvec2()),
59:                         coefficient: shifted.height_f64(point.as_dvec2()) - height,
60:                     },
61:                 )?;
62:             }
63:         }
64:         validate_coverage(&surface, &support, covered)?;
65:     }
66:     interval.choose(plan)
67: }
68: 
69: struct FloorInterval {
70:     minimum: f64,
71:     maximum: f64,
72:     upper_control: Option<Control>,
73: }
74: 
75: impl FloorInterval {
76:     fn constrain(
77:         &mut self,
78:         plan: &CompoundSupportPlan,
79:         control: Control,
80:     ) -> Result<(), SupportDiagnostic> {
81:         let displacement = control.support - control.source;
82:         let permitted = f64::from(plan.limits.maximum_displacement_metres.metres());
83:         if control.coefficient == 0.0 {
84:             if displacement.abs() > permitted {
85:                 return Err(rejection(plan, control, 0.0));
86:             }
87:             return Ok(());
88:         }
89:         let a = (-permitted - displacement) / control.coefficient;
90:         let b = (permitted - displacement) / control.coefficient;
91:         self.minimum = self.minimum.max(a.min(b));
92:         if a.max(b) < self.maximum {
93:             self.maximum = a.max(b);
94:             self.upper_control = Some(control);
95:         }
96:         Ok(())
97:     }
98: 
99:     fn choose(self, plan: &CompoundSupportPlan) -> Result<SignedLength, SupportDiagnostic> {
100:         if self.minimum > self.maximum {
101:             let control = self.upper_control.ok_or_else(|| {
102:                 SupportDiagnostic::new(
103:                     &plan.property,
104:                     SupportConstraint::Reservation,
105:                     SupportBoundary::GeographicSurface,
106:                     plan.property.plot.centre_metres(),
107:                     1.0,
108:                     0.0,
109:                 )
110:             })?;
111:             return Err(rejection(plan, control, self.minimum));
112:         }
113:         let margin = f64::from(plan.limits.contact_tolerance_metres.metres());
114:         let shift = if self.minimum + margin <= self.maximum - margin {
115:             0.0_f64.clamp(self.minimum + margin, self.maximum - margin)
116:         } else {
117:             (self.minimum + self.maximum) * 0.5
118:         };
119:         SignedLength::from_metres(shift as f32).map_err(|cause| {
120:             SupportDiagnostic::framed_geometry(
121:                 &plan.property,
122:                 plan.property.plot.centre_metres(),
123:                 cause,
124:             )
125:         })
126:     }
127: }
128: 
129: fn rejection(plan: &CompoundSupportPlan, control: Control, shift: f64) -> SupportDiagnostic {
130:     let measured = (control.support + control.coefficient * shift - control.source).abs() as f32;
131:     let mut error = SupportDiagnostic::new(
132:         &plan.property,
133:         SupportConstraint::CutFill,
134:         SupportBoundary::GeographicSurface,
135:         control.point,
136:         measured,
137:         plan.limits.maximum_displacement_metres.metres(),
138:     );
139:     error.attempted_treatment = Box::new(SupportGradingAttempt::Compound(plan.treatment));
140:     error
141: }

