1: //! Compare a common level courtyard with a bounded stepped courtyard.
2: use super::*;
3: 
4: /// Exact bindings, geographic observations and declared engineering bounds.
5: /// Selection starts at the street observation and seats floors within complete
6: /// source constraints, retaining every horizontal region and declared bound.
7: /// It neither moves a property nor increases its supplied grading reservation.
8: pub struct CompoundSupportRequest<'a> {
9:     pub property: &'a CityCompound,
10:     pub observations: CompoundSupportLevels,
11:     pub street_threshold_metres: crate::scene_coordinates::ScenePlanPoint,
12:     pub street_apron: CityPlotBounds,
13:     pub geographic: &'a GeographicSurface,
14:     pub limits: SupportLimits,
15:     pub stairs: CourtStairLimits,
16:     pub embedment: FoundationEmbedment,
17: }
18: 
19: impl CompoundSupportRequest<'_> {
20:     pub fn select(self) -> Result<CompoundSupportPlan, SupportDiagnostic> {
21:         let mut observations = self.observations;
22:         observations.gate = compound::street_gate_level(self.property, observations, self.limits)?;
23:         match self.candidate(observations, CourtTreatment::Level) {
24:             Ok(level) => return Ok(level),
25:             Err(error)
26:                 if matches!(
27:                     error.constraint,
28:                     SupportConstraint::CutFill
29:                         | SupportConstraint::AccessGrade
30:                         | SupportConstraint::StairGoing
31:                 ) => {}
32:             Err(error) => return Err(error),
33:         }
34:         // The level plan has validated unique member/threshold bindings. Use
35:         // those exact routes to reserve both landings before selecting levels.
36:         let route = |member: MemberSupport| {
37:             self.property
38:                 .access
39:                 .iter()
40:                 .find(|route| route.ends_at(member.court_threshold_metres))
41:                 .ok_or_else(|| {
42:                     SupportDiagnostic::new(
43:                         self.property,
44:                         SupportConstraint::ThresholdBinding,
45:                         SupportBoundary::CourtLanding,
46:                         member.court_threshold_metres.metres(),
47:                         0.0,
48:                         1.0,
49:                     )
50:                 })
51:         };
52:         let front_reach = self
53:             .stairs
54:             .maximum_rise_metres(route(self.observations.front)?, self.limits);
55:         let rear_reach = self
56:             .stairs
57:             .maximum_rise_metres(route(self.observations.rear)?, self.limits);
58:         if front_reach <= 0.0 || rear_reach <= 0.0 {
59:             let mut error = SupportDiagnostic::new(
60:                 self.property,
61:                 SupportConstraint::AccessGrade,
62:                 SupportBoundary::CourtLanding,
63:                 self.property.court.centre_metres(),
64:                 (self.observations.front.elevation.metres() - self.observations.court.metres())
65:                     .abs(),
66:                 front_reach.min(rear_reach).max(0.0),
67:             );
68:             error.attempted_treatment = Box::new(SupportGradingAttempt::Compound(
69:                 CourtTreatment::Terraced(self.stairs),
70:             ));
71:             return Err(error);
72:         }
73:         let mut levels = observations;
74:         let front = levels.front.elevation.metres();
75:         let court = levels
76:             .court
77:             .metres()
78:             .clamp(front - front_reach, front + front_reach);
79:         levels.court = SupportElevation(court);
80:         levels.rear.elevation = SupportElevation(
81:             levels
82:                 .rear
83:                 .elevation
84:                 .metres()
85:                 .clamp(court - rear_reach, court + rear_reach),
86:         );
87:         self.candidate(levels, CourtTreatment::Terraced(self.stairs))
88:     }
89: 
90:     fn candidate(
91:         &self,
92:         levels: CompoundSupportLevels,
93:         treatment: CourtTreatment,
94:     ) -> Result<CompoundSupportPlan, SupportDiagnostic> {
95:         let unbound = CompoundSupportPlan::compile(self.property, levels, self.limits, treatment)?;
96:         let shift = unbound.bounded_floor_shift(self.geographic)?;
97:         let mut selected = unbound.levels;
98:         let geometry_error = |cause| {
99:             SupportDiagnostic::framed_geometry(
100:                 self.property,
101:                 self.property.plot.centre_metres(),
102:                 cause,
103:             )
104:         };
105:         selected.front.elevation = selected
106:             .front
107:             .elevation
108:             .translated(shift)
109:             .map_err(geometry_error)?;
110:         selected.rear.elevation = selected
111:             .rear
112:             .elevation
113:             .translated(shift)
114:             .map_err(geometry_error)?;
115:         selected.court = selected.court.translated(shift).map_err(geometry_error)?;
116:         let plan = CompoundSupportPlan::compile(self.property, selected, self.limits, treatment)?
117:             .bind_street_entry(
118:             self.street_threshold_metres,
119:             self.street_apron,
120:             self.geographic,
121:             self.stairs,
122:         )?;
123:         plan.support_surface()?
124:             .validate_source_controls(self.geographic)?;
125:         Ok(plan)
126:     }
127: }
