1: //! Rough construction quantities; complete triangle intersections bound cut/fill.
2: use super::*;
3: use crate::footprint::{clip, height_in_triangle};
4: use adventuresim_tactical_core::city_layout::grounding::{
5:     DiagnosticMetres, SurfaceDifferenceControl,
6: };
7: use bevy::math::Vec2;
8: 
9: const PERIMETER_QUANTITY_PROBE_METRES: f32 = 1.0;
10: 
11: #[derive(Debug, serde::Serialize)]
12: #[serde(rename_all = "snake_case")]
13: pub(super) enum QuantityError {
14:     Support {
15:         diagnostic: adventuresim_tactical_core::city_layout::grounding::SupportDiagnostic,
16:     },
17:     NonFiniteLocation {
18:         point: Vec2,
19:     },
20:     NonFiniteElevation {
21:         point: Vec2,
22:     },
23:     NonFiniteDisplacement {
24:         point: ScenePlanPoint,
25:     },
26: }
27: 
28: pub(super) fn measure(
29:     plan: &CompoundSupportPlan,
30:     geographic: &[[Vec3; 3]],
31:     terrain_height: &impl Fn(ScenePlanPoint) -> Option<SupportElevation>,
32:     assumed_wall_thickness_metres: f32,
33: ) -> Result<Value, QuantityError> {
34:     let mesh = plan
35:         .mesh()
36:         .map_err(|diagnostic| QuantityError::Support { diagnostic })?;
37:     let mut covered = 0.0;
38:     let mut fill = 0.0;
39:     let mut cut = 0.0;
40:     let mut maximum: Option<SurfaceDifferenceControl> = None;
41:     let mut rejection = None;
42:     for indices in mesh.support_triangles() {
43:         let support = indices.map(|i| mesh.positions()[i as usize]);
44:         let clipper = [support[0].xz(), support[2].xz(), support[1].xz()];
45:         for source in geographic {
46:             let polygon = clip(source.map(|v| v.xz()).to_vec(), &clipper);
47:             let polygon = clip(polygon, &plan.reservation().corners());
48:             if polygon.len() < 3 {
49:                 continue;
50:             }
51:             let differences: Vec<_> = polygon
52:                 .iter()
53:                 .map(|p| height_in_triangle(support, *p) - height_in_triangle(*source, *p))
54:                 .collect();
55:             for (point, difference) in polygon.iter().zip(&differences) {
56:                 let control = displacement_control_at(support, *source, *point)?;
57:                 if maximum.is_none_or(|best| {
58:                     f64::from(difference.abs()) > best.difference_metres.metres().abs()
59:                 }) {
60:                     maximum = Some(control);
61:                 }
62:                 if let Err(error) =
63:                     plan.validate_displacement_at(control.position_metres, control.second_elevation)
64:                 {
65:                     rejection.get_or_insert(error);
66:                 }
67:             }
68:             covered += area(&polygon);
69:             fill += signed_volume(&polygon, &differences, 1.0);
70:             cut += signed_volume(&polygon, &differences, -1.0);
71:         }
72:     }
73:     let internal_faces = mesh
74:         .retaining_triangles()
75:         .iter()
76:         .map(|indices| {
77:             let [a, b, c] = indices.map(|i| mesh.positions()[i as usize]);
78:             f64::from((b - a).cross(c - a).length()) * 0.5
79:         })
80:         .sum::<f64>();
81:     let perimeter_faces = perimeter_faces(plan, terrain_height)?;
82:     Ok(json!({
83:         "covered_reservation_area_m2":covered,
84:         "required_reservation_area_m2":area(&plan.reservation().corners()),
85:         "fill_volume_m3":fill,"cut_volume_m3":cut,
86:         "maximum_absolute_displacement_m":maximum.map(|control|control.difference_metres.metres().abs()),
87:         "maximum_displacement_location_m":maximum.map(|control|control.position_metres),
88:         "grading_rejection":rejection,
89:         "internal_retaining_and_riser_face_area_m2":internal_faces,
90:         "perimeter_face_area_estimate_m2":perimeter_faces,
91:         "perimeter_quantity_probe_spacing_m":PERIMETER_QUANTITY_PROBE_METRES,
92:         "assumed_retaining_thickness_m":assumed_wall_thickness_metres,
93:         "masonry_volume_estimate_m3":perimeter_faces.map(|p|(internal_faces+p)*f64::from(assumed_wall_thickness_metres)),
94:         "quantity_scope":"Rough comparative quantities, not structural wall sizing or historical costs. Cut/fill integrates source/support triangle intersections; perimeter face area uses one-metre probes. Footings, cellar excavation, neighbouring levels and drainage are not represented. An absent perimeter estimate is not zero work.",
95:     }))
96: }
97: 
