165: const QUICKSTEP_FORCE_CURVE_RAMP_FRACTION: f32 = 0.31;
166: /// Smooth rise, maximal mid-push force, and smooth release. Its normalized
167: /// area is 0.69, matching the force-time profile used to calibrate the
