229: /// Samples a monotone cubic through the authored 0/3/6/9/12 root positions.
230: /// End tangents are zero so the physical body can enter and leave combat idle
231: /// without an instantaneous velocity change.
232: pub fn quickstep_motion_target(
233:     normalized_time: f32,
234:     target_displacement_metres: f32,
235:     duration: AnimationElapsed,
236:     profile: [f32; 5],
237: ) -> AnimationValueResult<QuickstepMotionTarget> {
238:     let phase = normalized_time.clamp(0.0, 1.0);
239:     if phase >= 1.0 || duration.is_zero() {
240:         return Ok(QuickstepMotionTarget {
241:             displacement_metres: target_displacement_metres,
242:             velocity_metres_per_second: SignedSpeed::ZERO,
243:             acceleration_metres_per_second_squared: 0.0,
244:         });
245:     }
246:     let segment = ((phase * 4.0).floor() as usize).min(3);
247:     let u = phase * 4.0 - segment as f32;
248:     let secants =
249:         std::array::from_fn::<_, 4, _>(|index| (profile[index + 1] - profile[index]) * 4.0);
250:     let mut tangents = [0.0; 5];
251:     for index in 1..4 {
252:         let before = secants[index - 1];
253:         let after = secants[index];
254:         if before > 0.0 && after > 0.0 {
255:             tangents[index] = 2.0 * before * after / (before + after);
256:         }
257:     }
258:     let p0 = profile[segment];
259:     let p1 = profile[segment + 1];
260:     let m0 = tangents[segment] * 0.25;
261:     let m1 = tangents[segment + 1] * 0.25;
262:     let u2 = u * u;
263:     let u3 = u2 * u;
264:     let position = (2.0 * u3 - 3.0 * u2 + 1.0) * p0
265:         + (u3 - 2.0 * u2 + u) * m0
266:         + (-2.0 * u3 + 3.0 * u2) * p1
267:         + (u3 - u2) * m1;
268:     let derivative_u = (6.0 * u2 - 6.0 * u) * p0
269:         + (3.0 * u2 - 4.0 * u + 1.0) * m0
270:         + (-6.0 * u2 + 6.0 * u) * p1
271:         + (3.0 * u2 - 2.0 * u) * m1;
272:     let second_derivative_u = (12.0 * u - 6.0) * p0
273:         + (6.0 * u - 4.0) * m0
274:         + (-12.0 * u + 6.0) * p1
275:         + (6.0 * u - 2.0) * m1;
276:     let duration = duration.seconds();
277:     Ok(QuickstepMotionTarget {
278:         displacement_metres: position * target_displacement_metres,
279:         velocity_metres_per_second: SignedSpeed::from_metres_per_second(
280:             derivative_u * 4.0 * target_displacement_metres / duration,
281:         )?,
282:         acceleration_metres_per_second_squared: second_derivative_u
283:             * 16.0
284:             * target_displacement_metres
285:             / (duration * duration),
286:     })
287: }
