17: pub(super) enum OffensiveCombatPhase {
18:     Assessing(Timer),
19:     GuardingCommittedThreat,
20:     Pursuing,
21:     MeleeWindup {
22:         timer: Timer,
23:         strike_family: StrikeFamily,
24:         #[reflect(remote = adventuresim_tactical_core::animation::ReflectedAnimationElapsed)]
25:         recovery_seconds: AnimationElapsed,
26:     },
27:     RangedWindup(Timer),
28:     Cooldown(Timer),
29:     WithdrawingUnableToContinue(Timer),
30: }
31: 
32: impl MeleePursuit {
33:     fn start(
34:         self,
35:         cmd: &mut Commands,
36:         input: &mut AuthoritativeMovementIntent,
37:         controller: &mut OffensiveCombatAi,
38:         skeleton: &SkeletonState,
39:         facts: &OffensiveFacts,
40:         config: &AiOffenseConfig,
41:     ) -> ElapsedResult<()> {
42:         let Self {
43:             entity,
44:             target,
45:             distance,
46:         } = self;
47:         let arrival = match facts.melee_lunge_delay {
48:             Some(MeleeLungeArrival::ArrivesIn(arrival)) => arrival,
49:             Some(MeleeLungeArrival::NotNeeded) => AnimationElapsed::ZERO,
50:             Some(MeleeLungeArrival::CannotArrive) | None => return Ok(()),
51:         };
52:         let Some(RecoveryTime::After(recovery)) = facts.melee_recovery_seconds else {
53:             return Ok(());
54:         };
55:         let windup = CombatDuration::from_elapsed(config.windup_seconds)?;
56:         let timer = Timer::new(
57:             config.windup_seconds.max(arrival).native_duration()?,
58:             TimerMode::Once,
59:         );
60:         input.0 = long_weapon_windup_movement(
61:             facts.weapon_reach,
62:             facts.preferred_melee_measure,
63:             distance,
64:             config.long_weapon_measure_threshold_metres,
65:         );
66:         let Some(strike_family) = skeleton.available_strike_family(facts.strike_family) else {
67:             return Ok(());
68:         };
69:         cmd.trigger(MeleeAttackStartedIntent {
70:             attacker: entity,
71:             target: Some(target),
72:             windup,
73:             reported_precision: ReportedPrecision::new(config.hit_precision)
74:                 .expect("AI precision is finite"),
75:             strike_family,
76:             hand: AttackHand::Main,
77:         });
78:         controller.phase = OffensiveCombatPhase::MeleeWindup {
79:             timer,
80:             strike_family,
81:             recovery_seconds: recovery,
82:         };
83:         Ok(())
84:     }
85: }
