91: pub(super) fn drive_offensive_phase(
92:     cmd: &mut Commands,
93:     time: &Time<()>,
94:     entity: Entity,
95:     target: Entity,
96:     distance: f32,
97:     input: &mut AuthoritativeMovementIntent,
98:     controller: &mut OffensiveCombatAi,
99:     skeleton: &SkeletonState,
100:     target_skeleton: &SkeletonState,
101:     facts: &OffensiveFacts,
102:     config: &AiOffenseConfig,
103:     random: &mut CombatRandom,
104: ) -> ElapsedResult<()> {
105:     if matches!(controller.phase, OffensiveCombatPhase::Pursuing) {
106:         drive_pursuit_phase(
107:             cmd,
108:             entity,
109:             target,
110:             distance,
111:             input,
112:             controller,
113:             skeleton,
114:             target_skeleton,
115:             facts,
116:             config,
117:             random,
118:         )?;
119:         return Ok(());
120:     }
121:     match &mut controller.phase {
122:         OffensiveCombatPhase::Pursuing => unreachable!("pursuit was handled above"),
123:         OffensiveCombatPhase::GuardingCommittedThreat => {
124:             maintain_committed_threat_guard(
125:                 input,
126:                 controller,
127:                 target_skeleton,
128:                 random,
129:                 facts,
130:                 config,
131:             )?;
132:         }
133:         OffensiveCombatPhase::Assessing(timer) => {
134:             hold_and_tick(input, timer, time);
135:             if timer.is_finished() {
136:                 controller.phase = OffensiveCombatPhase::Pursuing;
137:             }
138:         }
139:         OffensiveCombatPhase::MeleeWindup { .. } | OffensiveCombatPhase::RangedWindup(_) => {
140:             complete_windup(
141:                 MeleePursuit {
142:                     entity,
143:                     target,
144:                     distance,
145:                 },
146:                 cmd,
147:                 time,
148:                 OffensiveControls { input, controller },
149:                 facts,
150:                 config,
151:                 random,
152:             )?;
153:         }
154:         OffensiveCombatPhase::Cooldown(timer) => {
155:             input.0 = None;
156:             timer.tick(time.delta());
157:             if timer.is_finished() {
158:                 controller.phase = OffensiveCombatPhase::Pursuing;
159:             }
160:         }
161:         OffensiveCombatPhase::WithdrawingUnableToContinue(timer) => {
162:             continue_withdrawal(cmd, time, entity, input, timer);
