27: pub(crate) fn load_combat_config(path: &Path) -> Result<TacticalCombatConfig, String> {
28:     const MAX_COMBAT_CONFIG_BYTES: u64 = 64 * 1024;
29:     let length = std::fs::metadata(path)
30:         .map_err(|error| format!("could not inspect {}: {error}", path.display()))?
31:         .len();
32:     if length == 0 || length > MAX_COMBAT_CONFIG_BYTES {
33:         return Err("combat config must contain between 1 byte and 64 KiB".into());
34:     }
35:     let text = std::fs::read_to_string(path)
36:         .map_err(|error| format!("could not read {}: {error}", path.display()))?;
37:     let config: TacticalCombatConfig = serde_saphyr::from_str(&text)
38:         .map_err(|error| format!("{} is not valid YAML: {error}", path.display()))?;
39:     config
40:         .validate()
41:         .map_err(|error| format!("{}: {error}", path.display()))?;
42:     Ok(config)
43: }
