58: impl SceneTerrainPatch {
59:     pub fn collider(&self) -> avian3d::prelude::Collider {
60:         avian3d::prelude::Collider::trimesh(
61:             self.positions
62:                 .iter()
63:                 .copied()
64:                 .map(Vec3::from_array)
65:                 .collect(),
66:             self.indices
67:                 .as_chunks::<3>()
68:                 .0
69:                 .iter()
70:                 .map(|triangle| [triangle[0], triangle[1], triangle[2]])
71:                 .collect(),
72:         )
73:     }
74: 
75:     pub fn colliders_with_terrain(
76:         &self,
77:         terrain: &SceneTerrain,
78:     ) -> Result<Vec<avian3d::prelude::Collider>, crate::city_layout::grounding::SupportColliderError>
79:     {
80:         let (mut positions, mut triangles) =
81:             terrain.natural_collision_mesh_with_transition(self.transition_collar);
82:         let total = positions
83:             .len()
84:             .checked_add(self.positions.len())
85:             .ok_or(crate::city_layout::grounding::SupportGeometryIssue::Topology)?;
86:         u32::try_from(total)
87:             .map_err(|_| crate::city_layout::grounding::SupportGeometryIssue::Topology)?;
88:         let patch_offset = positions.len() as u32;
89:         positions.extend(self.positions.iter().copied().map(Vec3::from_array));
90:         triangles.extend(self.indices.as_chunks::<3>().0.iter().map(|triangle| {
91:             [
92:                 triangle[0] + patch_offset,
93:                 triangle[1] + patch_offset,
94:                 triangle[2] + patch_offset,
95:             ]
96:         }));
97:         let mut colliders = terrain.foundation_colliders()?;
98:         colliders.push(avian3d::prelude::Collider::trimesh(positions, triangles));
99:         Ok(colliders)
100:     }
101: 
102:     pub fn triangle_count(&self) -> usize {
103:         self.indices.len() / 3
104:     }
105: }
