107: impl SimulatedScarpSurface {
108:     fn offset_at(&self, point: ScenePlanPoint) -> f32 {
109:         let grid = (point.metres() - self.minimum.metres()) / self.spacing;
110:         let x0 = (grid.x.floor() as usize).min(self.side - 2);
111:         let z0 = (grid.y.floor() as usize).min(self.side - 2);
112:         let fraction = (grid - Vec2::new(x0 as f32, z0 as f32)).clamp(Vec2::ZERO, Vec2::ONE);
113:         let a = self.offsets[z0 * self.side + x0];
114:         let b = self.offsets[z0 * self.side + x0 + 1];
115:         let c = self.offsets[(z0 + 1) * self.side + x0];
116:         let d = self.offsets[(z0 + 1) * self.side + x0 + 1];
117:         a.lerp(b, fraction.x)
118:             .lerp(c.lerp(d, fraction.x), fraction.y)
119:     }

