41: pub(super) fn validate_dimensions(
42:     width: usize,
43:     depth: usize,
44:     scale: f32,
45:     stride: usize,
46: ) -> Result<(), TerrainAdmissionError> {
47:     if width < 2
48:         || depth < 2
49:         || width
50:             .checked_mul(depth)
51:             .is_none_or(|n| n > u32::MAX as usize)
52:         || (width - 1)
53:             .checked_mul(depth - 1)
54:             .and_then(|n| n.checked_mul(6))
55:             .is_none_or(|n| n > u32::MAX as usize)
56:     {
57:         return Err(TerrainAdmissionError::Dimensions);
58:     }
59:     if !scale.is_finite()
60:         || scale <= 0.0
61:         || !((width - 1) as f32 * scale).is_finite()
62:         || !((depth - 1) as f32 * scale).is_finite()
63:     {
64:         return Err(TerrainAdmissionError::Scale);
65:     }
66:     if stride == 0 || !(width - 1).is_multiple_of(stride) || !(depth - 1).is_multiple_of(stride) {
67:         return Err(TerrainAdmissionError::Stride);
68:     }
69:     Ok(())
70: }
71: impl SceneTerrain {
72:     pub(super) fn grid_depth_checked(&self) -> Option<usize> {
73:         (self.width != 0 && self.heightmap.len().is_multiple_of(self.width))
74:             .then(|| self.heightmap.len() / self.width)
75:     }
76:     pub(super) fn validate(&self) -> Result<(), TerrainAdmissionError> {
77:         let depth = self
78:             .grid_depth_checked()
79:             .ok_or(TerrainAdmissionError::Dimensions)?;
