73:         grid_depth: usize,
74:         scale: f32,
75:         samples: Vec<GroundSurface>,
76:     ) -> Option<Self> {
77:         if grid_width < 2
78:             || grid_depth < 2
79:             || !scale.is_finite()
80:             || scale <= 0.0
81:             || samples.len() != grid_width.checked_mul(grid_depth)?
82:             || samples.iter().any(|sample| {
