187: fn chamfer_distance_to(
188:     width: usize,
189:     height: usize,
190:     sources: impl Fn(usize) -> bool,
191:     maximum: usize,
192: ) -> Vec<usize> {
193:     let mut distance = (0..width * height)
194:         .map(|index| if sources(index) { 0 } else { maximum + 1 })
195:         .collect::<Vec<_>>();
196:     for z in 0..height {
197:         for x in 0..width {
198:             let index = z * width + x;
199:             for (dx, dz) in [(-1_isize, 0_isize), (0, -1), (-1, -1), (1, -1)] {
200:                 let nx = x as isize + dx;
201:                 let nz = z as isize + dz;
202:                 if nx >= 0 && nz >= 0 && nx < width as isize && nz < height as isize {
203:                     distance[index] = distance[index]
204:                         .min(distance[nz as usize * width + nx as usize].saturating_add(1));
205:                 }
206:             }
207:         }
208:     }
209:     for z in (0..height).rev() {
210:         for x in (0..width).rev() {
211:             let index = z * width + x;
212:             for (dx, dz) in [(1_isize, 0_isize), (0, 1), (1, 1), (-1, 1)] {
213:                 let nx = x as isize + dx;
214:                 let nz = z as isize + dz;
215:                 if nx >= 0 && nz >= 0 && nx < width as isize && nz < height as isize {
216:                     distance[index] = distance[index]
217:                         .min(distance[nz as usize * width + nx as usize].saturating_add(1));
218:                 }
219:             }
220:         }
221:     }
222:     distance
223: }
