141: fn convex_quad_contains(corners: [Vec2; 4], point: Vec2) -> bool {
142:     let mut sign = 0.0_f32;
143:     for index in 0..4 {
144:         let start = corners[index];
145:         let end = corners[(index + 1) % 4];
146:         let cross = (end - start).perp_dot(point - start);
147:         if cross == 0.0 {
148:             continue;
149:         }
150:         if sign == 0.0 {
151:             sign = cross.signum();
152:         } else if cross.signum() != sign {
153:             return false;
154:         }
155:     }
156:     true
157: }
158: 
159: fn polygon_area(corners: [Vec2; 4]) -> f32 {
160:     (0..4)
161:         .map(|index| corners[index].perp_dot(corners[(index + 1) % 4]))
162:         .sum::<f32>()
163:         * 0.5
164: }

