1: //! Bounded fractions and their conversion to game quantities.
2: use serde::{Deserialize, Serialize};
3: 
4: /// The basis-point representation of one whole (100%).
5: pub const BASIS_POINTS_PER_WHOLE: u16 = 10_000;
6: 
7: /// A validated fraction of one whole, represented in basis points.
8: #[derive(
9:     Clone, Copy, Debug, Default, Eq, Hash, Ord, PartialEq, PartialOrd, Serialize, Deserialize,
10: )]
11: #[cfg_attr(feature = "spacetimedb", derive(spacetimedb_lib::SpacetimeType))]
12: #[cfg_attr(feature = "spacetimedb", sats(crate = spacetimedb_lib))]
13: #[serde(transparent)]
14: pub struct UnitBasisPoints {
15:     basis_points: u16,
16: }
17: 
18: impl UnitBasisPoints {
19:     pub const ZERO: Self = Self { basis_points: 0 };
20:     pub const WHOLE: Self = Self {
21:         basis_points: BASIS_POINTS_PER_WHOLE,
22:     };
23: 
24:     pub const fn new(value: u16) -> Option<Self> {
25:         if value <= BASIS_POINTS_PER_WHOLE {
26:             Some(Self {
27:                 basis_points: value,
28:             })
29:         } else {
30:             None
31:         }
32:     }
33: 
34:     pub const fn saturating(value: u16) -> Self {
35:         Self {
36:             basis_points: if value > BASIS_POINTS_PER_WHOLE {
37:                 BASIS_POINTS_PER_WHOLE
38:             } else {
39:                 value
40:             },
41:         }
42:     }
43: 
44:     pub fn from_unit_f32(value: f32) -> Option<Self> {
45:         if !value.is_finite() || !(0.0..=1.0).contains(&value) {
46:             return None;
47:         }
48:         Self::new((value * f32::from(BASIS_POINTS_PER_WHOLE)).round() as u16)
49:     }
50: 
51:     pub fn from_unit_f64(value: f64) -> Option<Self> {
52:         if !value.is_finite() || !(0.0..=1.0).contains(&value) {
53:             return None;
54:         }
55:         Self::new((value * f64::from(BASIS_POINTS_PER_WHOLE)).round() as u16)
56:     }
57: 
58:     pub fn from_ratio_floor(numerator: u64, denominator: u64) -> Option<Self> {
59:         if denominator == 0 {
60:             return None;
61:         }
62:         let value = u128::from(numerator).saturating_mul(u128::from(BASIS_POINTS_PER_WHOLE))
63:             / u128::from(denominator);
64:         Some(Self::saturating(value.min(u128::from(u16::MAX)) as u16))
65:     }
66: 
67:     pub const fn get(self) -> u16 {
68:         self.basis_points
69:     }
70: 
71:     pub const fn complement(self) -> Self {
72:         Self {
73:             basis_points: BASIS_POINTS_PER_WHOLE - self.basis_points,
74:         }
75:     }
76: 
77:     pub fn as_unit_f32(self) -> f32 {
78:         f32::from(self.basis_points) / f32::from(BASIS_POINTS_PER_WHOLE)
79:     }
80: 
81:     pub fn as_unit_f64(self) -> f64 {
82:         f64::from(self.basis_points) / f64::from(BASIS_POINTS_PER_WHOLE)
83:     }
84: 
85:     pub const fn scale_u32_floor(self, whole: u32) -> u32 {
86:         ((whole as u64 * self.basis_points as u64) / BASIS_POINTS_PER_WHOLE as u64) as u32
87:     }
88: 
89:     pub const fn scale_u64_floor(self, whole: u64) -> u64 {
90:         ((whole as u128 * self.basis_points as u128) / BASIS_POINTS_PER_WHOLE as u128) as u64
91:     }
92: }
93: 
94: /// A validated signed fraction of one whole, represented in basis points.
95: #[derive(
96:     Clone, Copy, Debug, Default, Eq, Hash, Ord, PartialEq, PartialOrd, Serialize, Deserialize,
97: )]
98: #[cfg_attr(feature = "spacetimedb", derive(spacetimedb_lib::SpacetimeType))]
99: #[cfg_attr(feature = "spacetimedb", sats(crate = spacetimedb_lib))]
100: #[serde(transparent)]
101: pub struct SignedUnitBasisPoints {
102:     basis_points: i16,
103: }
104: 
105: impl SignedUnitBasisPoints {
106:     pub const MIN: Self = Self {
107:         basis_points: -(BASIS_POINTS_PER_WHOLE as i16),
108:     };
109:     pub const MAX: Self = Self {
110:         basis_points: BASIS_POINTS_PER_WHOLE as i16,
111:     };
112:     pub const ZERO: Self = Self { basis_points: 0 };
113: 
114:     pub const fn new(value: i16) -> Option<Self> {
115:         if value >= Self::MIN.basis_points && value <= Self::MAX.basis_points {
116:             Some(Self {
117:                 basis_points: value,
118:             })
119:         } else {
120:             None
121:         }
122:     }
123: 
124:     pub const fn get(self) -> i16 {
125:         self.basis_points
126:     }
127: 
128:     pub fn as_unit_f32(self) -> f32 {
129:         f32::from(self.basis_points) / f32::from(BASIS_POINTS_PER_WHOLE)
130:     }
131: }
