287: pub fn lod_transition_weight(lod: &VistaLod, coarser: &VistaLod, world: ScenePlanPoint) -> f32 {
288:     let world = world.metres();
289:     let center = Vec2::new(
290:         lod.origin_east_metres as f32,
291:         lod.origin_north_metres as f32,
292:     );
293:     let half_extent = f32::from(lod.width.saturating_sub(1)) * lod.spacing_metres * 0.5;
294:     // Begin morphing one coarse sample before the boundary. A one-fine-cell
295:     // band still exposes the square footprint whenever adjacent LOD spacing
296:     // grows rapidly (50 m -> 250 m -> 1 km).
297:     let transition_width = coarser
298:         .spacing_metres
299:         .min(half_extent)
300:         .max(lod.spacing_metres);
301:     let radius = (world - center).abs().max_element();
302:     ((radius - (half_extent - transition_width)) / transition_width).clamp(0.0, 1.0)
303: }
