309: /// Height of the actual clipped vista triangle, including the playable seam.
310: /// Uses the same rectangle splits and vertex policy as the production mesh.
311: pub fn vista_triangle_height(
312:     lod: &VistaLod,
313:     coarser: Option<&VistaLod>,
314:     terrain: &SceneTerrain,
315:     point: ScenePlanPoint,
316: ) -> Option<SupportElevation> {
317:     sampled_vista_triangle_height(
318:         lod,
319:         coarser,
320:         Some(terrain),
321:         Vec2::new(terrain.width(), terrain.depth()) * 0.5,
322:         point,
323:     )
324: }
325: 
326: /// Sample the rendered ring in canonical east/north metres. The inner rectangle
327: /// and optional playable seam are the same inputs used by sampled ring meshing.
328: pub fn sampled_vista_triangle_height(
329:     lod: &VistaLod,
330:     coarser: Option<&VistaLod>,
331:     terrain: Option<&SceneTerrain>,
332:     inner_half_extent: Vec2,
333:     point: ScenePlanPoint,
334: ) -> Option<SupportElevation> {
335:     if !lod.has_height_grid() {
336:         return None;
337:     }
338:     let local = point.metres()
339:         - Vec2::new(
340:             lod.origin_east_metres as f32,
341:             lod.origin_north_metres as f32,
342:         );
343:     let half = inner_half_extent;
344:     let size = Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1));
345:     let cell = (local / lod.spacing_metres + size * 0.5).floor();
346:     if cell.cmplt(Vec2::ZERO).any() || cell.cmpge(size).any() {
347:         return None;
348:     }
349:     let minimum = (cell - size * 0.5) * lod.spacing_metres;
350:     let maximum = minimum + Vec2::splat(lod.spacing_metres);
351:     for rectangle in cell_rectangles_outside_inner_rectangle(minimum, maximum, half) {
352:         for [x0, x1, z0, z1] in subdivide_playable_boundary_rectangle(rectangle, half, terrain) {
353:             if local.x < x0 || local.x > x1 || local.y < z0 || local.y > z1 {
354:                 continue;
355:             }
356:             let vertex = |x, z| {
357:                 native_presented_vista_vertex_height(
358:                     lod,
359:                     coarser,
360:                     terrain,
361:                     PlanDisplacement::from_metres(Vec2::new(x, z))?,
362:                     half,
363:                 )
364:             };
365:             let a = vertex(x0, z0)?;
366:             let b = vertex(x1, z0)?;
367:             let c = vertex(x1, z1)?;
368:             let d = vertex(x0, z1)?;
369:             let u = (local.x - x0) / (x1 - x0);
370:             let v = (local.y - z0) / (z1 - z0);
371:             return SupportElevation::from_metres(if u >= v {
372:                 a * (1.0 - u) + b * (u - v) + c * v
373:             } else {
374:                 a * (1.0 - v) + d * (v - u) + c * u
375:             });
376:         }
377:     }
378:     None
379: }
380: 
381: // Bilinear, LOD, seam and triangle interpolation are one native calculation.
382: // Intermediate f32 samples stay unadmitted so a nonfinite coarse sample cannot
383: // become "absent" and select the valid-own fallback before the completed result.
384: fn native_presented_vista_vertex_height(
385:     lod: &VistaLod,
386:     coarser_lod: Option<&VistaLod>,
387:     playable_terrain: Option<&SceneTerrain>,
388:     local: PlanDisplacement,
389:     playable_half_extent: Vec2,
390: ) -> Option<f32> {
391:     let world = lod.scene_point(local).ok()?;
392:     let vista_height = native_presented_height_at(lod, world, coarser_lod)?;
393:     Some(playable_terrain.map_or(vista_height, |terrain| {
394:         native_stitch_vista_height_to_playable_edge(
395:             terrain,
396:             local,
397:             playable_half_extent,
398:             lod.spacing_metres,
399:             vista_height,
400:         )
401:     }))
402: }
403: 
404: fn native_stitch_vista_height_to_playable_edge(
405:     terrain: &SceneTerrain,
406:     local: PlanDisplacement,
407:     playable_half_extent: Vec2,
408:     transition_width: f32,
409:     vista_height: f32,
410: ) -> f32 {
411:     let local = local.metres();
412:     let boundary = local.clamp(-playable_half_extent, playable_half_extent);
413:     let Some(playable_height) =
414:         ScenePlanPoint::from_metres(boundary).and_then(|point| terrain.height_at(point))
415:     else {
416:         return vista_height;
417:     };
418:     let outside_distance = (local.abs() - playable_half_extent)
419:         .max(Vec2::ZERO)
420:         .max_element();
421:     let vista_weight = if transition_width > 0.0 {
422:         (outside_distance / transition_width).clamp(0.0, 1.0)
423:     } else {
424:         f32::from(outside_distance > 0.0)
425:     };

