4: impl TacticalSceneInput {
5:     pub(super) fn validate_source(&self) -> Result<(), SceneInputError> {
6:         if self.schema_version != TACTICAL_SCENE_SCHEMA_VERSION {
7:             return invalid(SceneValidationError::SchemaVersion);
8:         }
9:         if self.generation_version != TACTICAL_SCENE_GENERATION_VERSION {
10:             return invalid(SceneValidationError::GenerationVersion);
11:         }
12:         if self.scene_key.is_empty() || self.scene_key.len() > MAX_TEMPLATE_BYTES {
13:             return invalid(SceneValidationError::SceneKey);
14:         }
15:         let source_id = match &self.source {
16:             SceneSource::ImportedPackage(value) => value.as_str(),
17:             SceneSource::SyntheticFixture(value) => value.as_str(),
18:         };
19:         if source_id.is_empty() || source_id.len() > MAX_SOURCE_ID_BYTES {
20:             return invalid(SceneValidationError::SourceIdentity);
21:         }
22: 
23:         validate_grid(&self.playable, MAX_PLAYABLE_SIDE, SampleGridKind::Playable)?;
24:         crate::scene_fault::validate(self.landform, &self.playable)?;
25:         urban::validate(self)?;
26:         establishments::validate(self)?;
27:         properties::validate(self)?;
28:         if self.vista.lods.len() > MAX_VISTA_LEVELS {
29:             return invalid(SceneValidationError::VistaLevelCount);
30:         }
31:         let mut previous_level = None;
32:         let mut previous_spacing = self.playable.spacing_metres;
33:         let mut vista_samples = 0usize;
34:         for lod in &self.vista.lods {
35:             if previous_level.is_some_and(|level| lod.level <= level) {
36:                 return invalid(SceneValidationError::VistaLevelOrder);
37:             }
38:             if !lod.origin_east_metres.is_finite() || !lod.origin_north_metres.is_finite() {
39:                 return invalid(SceneValidationError::VistaOrigin);
40:             }
41:             let grid = TerrainSampleGrid {
42:                 width: lod.width,
43:                 depth: lod.depth,
44:                 spacing_metres: lod.spacing_metres,
45:                 heights_metres: lod.heights_metres.clone(),
46:                 environment: lod.environment.clone(),
47:             };
48:             validate_grid(&grid, u16::MAX as usize, SampleGridKind::Vista)?;
49:             if lod.spacing_metres <= previous_spacing {
50:                 return invalid(SceneValidationError::VistaSpacingOrder);
51:             }
52:             vista_samples = vista_samples.checked_add(lod.heights_metres.len()).ok_or({
53:                 SceneInputError::Validation(SceneValidationError::VistaSampleOverflow)
54:             })?;
55:             if vista_samples > MAX_VISTA_SAMPLES {
56:                 return invalid(SceneValidationError::VistaSampleCount);
57:             }
58:             previous_level = Some(lod.level);
59:             previous_spacing = lod.spacing_metres;
60:         }
61:         validate_weather(self.weather)?;
62:         Ok(())
63:     }
64: }

