32:                 let cell_min = Vec2::new(
33:                     (x as f32 - center_x) * self.lod.spacing_metres,
34:                     (z as f32 - center_z) * self.lod.spacing_metres,
35:                 );
36:                 let cell_max = cell_min + Vec2::splat(self.lod.spacing_metres);
37:                 for rectangle in cell_rectangles_outside_inner_rectangle(
