43:                         subdivide_playable_boundary_rectangle(
44:                             rectangle,
45:                             self.inner_half_extent,
46:                             self.playable_terrain,
47:                         )
48:                     {
49:                         let base = positions.len() as u32;
50:                         let vertices = [
51:                             self.vertex(PlanDisplacement::try_from(Vec2::new(
52:                                 minimum_x, minimum_z,
53:                             ))?)?,
54:                             self.vertex(PlanDisplacement::try_from(Vec2::new(
55:                                 maximum_x, minimum_z,
56:                             ))?)?,
57:                             self.vertex(PlanDisplacement::try_from(Vec2::new(
58:                                 maximum_x, maximum_z,
59:                             ))?)?,
60:                             self.vertex(PlanDisplacement::try_from(Vec2::new(
61:                                 minimum_x, maximum_z,
62:                             ))?)?,
63:                         ];
64:                         positions.extend(vertices.map(|vertex| vertex.0));
65:                         normals.extend(vertices.map(|vertex| vertex.1));
66:                         colors.extend(vertices.map(|vertex| vertex.2));
67:                         indices.extend_from_slice(&[
68:                             base,
69:                             base + 2,
70:                             base + 1,
71:                             base,
72:                             base + 3,
73:                             base + 2,
74:                         ]);
75:                     }
76:                 }
77:             }
78:         }
79:         if positions.is_empty() {
80:             return Ok(None);
81:         }
82:         let mut mesh = Mesh::new(
83:             PrimitiveTopology::TriangleList,
84:             RenderAssetUsages::RENDER_WORLD,
85:         );
86:         mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
87:         mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
88:         mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, colors);
