312: pub fn materialize_scene_input(
313:     directory: &Path,
314:     mission_id: &str,
315:     input: &TacticalSceneInput,
316: ) -> Result<PathBuf, String> {
317:     fs::create_dir_all(directory).map_err(|error| error.to_string())?;
318:     let key = Sha256::digest(mission_id.as_bytes())
319:         .iter()
320:         .take(12)
321:         .map(|byte| format!("{byte:02x}"))
322:         .collect::<String>();
323:     let path = directory.join(format!("scene-{key}.json"));
324:     let bytes = serde_json::to_vec(input).map_err(|error| error.to_string())?;
325:     if let Ok(existing) = fs::read(&path) {
326:         if existing == bytes {
327:             return Ok(path);
328:         }
329:         return Err("existing scene input does not match the deterministic request".into());
330:     }
331:     let temporary = directory.join(format!("scene-{key}.tmp"));
332:     fs::write(&temporary, bytes).map_err(|error| error.to_string())?;
333:     fs::rename(&temporary, &path).map_err(|error| error.to_string())?;
334:     Ok(path)
335: }
