19:         {
20:             return Err("business operator identity is duplicated".into());
21:         }
22:     }
23:     let mut establishments = Vec::with_capacity(layout.businesses.len());
24:     for site in &layout.businesses {
25:         let operator = operators
26:             .remove(&site.key)
27:             .ok_or("placed business is missing its resident operator")?;
28:         let operator_name = operator.operator_name.clone();
29:         establishments.push(SceneEstablishment {
30:             building_id: site.building_id,
31:             business_id: operator.business_id.clone(),
32:             operator_character_id: operator.operator_character_id,
33:             operator_name: operator_name.clone(),
