49:     let longitude_e7 = LongitudeE7::from_degrees(args.longitude)
50:         .ok_or("longitude must be finite and within -180..=180")?
51:         .get();
52:     let terrain = TerrainPack::load(&args.terrain_manifest, &args.terrain_pack)
53:         .map_err(|error| format!("failed to load final terrain pack: {error}"))?;
54:     if terrain.purpose() != TerrainPurpose::Final {
