135: pub(in crate::autoresolve) fn advance_melee_pair_movement(
136:     first: &mut Combatant,
137:     second: &mut Combatant,
138:     interval_start: BattleTime,
139:     elapsed: AnimationElapsed,
140:     recorder: &mut BattleRecorder,
141:     parameters: crate::combat::AutoresolveParameters,
142: ) -> BattleResolutionResult<()> {
143:     if elapsed.is_zero() || first.is_defeated() || second.is_defeated() {
144:         return Ok(());
145:     }
146:     let time = interval_start.checked_add(elapsed)?;
147:     if first.melee_engagement_target != Some(second.id)
148:         || second.melee_engagement_target != Some(first.id)
149:     {
150:         let initial_separation = maximum_melee_pair_surface_separation(first, second, parameters);
151:         first.melee_engagement_target = Some(second.id);
152:         second.melee_engagement_target = Some(first.id);
153:         first.melee_engagement_distance_metres = initial_separation;
154:         second.melee_engagement_distance_metres = initial_separation;
155:         first.melee_separation_velocity_metres_per_second = SignedSpeed::ZERO;
156:         second.melee_separation_velocity_metres_per_second = SignedSpeed::ZERO;
157:     }
158:     let (movement, first_intent, second_intent) =
159:         preview_melee_pair_movement(first, second, elapsed, parameters)?;
160:     first.melee_engagement_distance_metres = movement.distance_after_metres;
161:     second.melee_engagement_distance_metres = movement.distance_after_metres;
162:     first.melee_separation_velocity_metres_per_second =
163:         movement.first.velocity_after_metres_per_second;
164:     second.melee_separation_velocity_metres_per_second =
165:         movement.second.velocity_after_metres_per_second;
166:     let (a, a_axis, a_intent, b, b_axis, b_intent) = if first.id <= second.id {
167:         (
168:             &*first,
169:             movement.first,
170:             first_intent,
171:             &*second,
172:             movement.second,
173:             second_intent,
174:         )
175:     } else {
176:         (
177:             &*second,
178:             movement.second,
179:             second_intent,
180:             &*first,
181:             movement.first,
182:             first_intent,
183:         )
184:     };
185:     record_movement(recorder, a, b.id, movement, a_axis, a_intent, time);
186:     record_movement(recorder, b, a.id, movement, b_axis, b_intent, time);
187:     Ok(())
188: }
189: 
190: fn movement_phase(combatant: &Combatant, time: BattleTime) -> MeleeTimelinePhase {
191:     if combatant.melee_attack_started_at_seconds.is_some() {
192:         MeleeTimelinePhase::Windup
193:     } else if combatant.melee_recovery_until_seconds > time {
194:         MeleeTimelinePhase::Recovery
195:     } else {
196:         MeleeTimelinePhase::NeutralGuard
197:     }
198: }
199: 
200: fn record_movement(
201:     recorder: &mut BattleRecorder,
202:     combatant: &Combatant,
203:     target_id: u64,
204:     movement: OpposedMovement,
205:     axis: AxisMotion,
206:     intent: MeleeMovementAction,
207:     time: BattleTime,
208: ) {
209:     let phase = movement_phase(combatant, time);
210:     let mut event = MeleeTimelineEvent::at(MeleeTimelineKind::Movement, time);
211:     event.combatant_id = Some(combatant.id);
212:     event.target_id = Some(target_id);
213:     event.engagement_distance_before_metres = Some(movement.distance_before_metres);
214:     event.engagement_distance_after_metres = Some(movement.distance_after_metres);
215:     event.movement_action = Some(intent);
216:     event.movement_elapsed_seconds = Some(movement.elapsed_seconds);
217:     event.movement_displacement_metres = Some(axis.displacement_metres);
218:     event.movement_velocity_before_metres_per_second = Some(axis.velocity_before_metres_per_second);
219:     event.movement_velocity_after_metres_per_second = Some(axis.velocity_after_metres_per_second);
220:     event.movement_speed_limit_metres_per_second = Some(axis.speed_limit_metres_per_second);
221:     event.readiness_before_seconds = Some(combatant.melee_recovery_until_seconds);
222:     event.readiness_after_seconds = event.readiness_before_seconds;
223:     event.phase_before = Some(phase);
224:     event.phase_after = Some(phase);
225:     recorder.record_timeline(event);
226: }

