53: pub(in crate::melee_combat_iteration) fn record_timeline_event(
54:     combatant: &mut AutoresolveCombatantCausal,
55:     event: &adventuresim_core::autoresolve::MeleeTimelineEvent,
56: ) -> IterationResult<()> {
57:     match event.kind {
58:         MeleeTimelineKind::Movement => record_movement_event(combatant, event)?,
59:         MeleeTimelineKind::AttackStarted => combatant.attack_starts += 1,
60:         MeleeTimelineKind::Response => record_response_event(combatant, event)?,
61:         MeleeTimelineKind::AttackCanceled => combatant.committed_attacks_canceled += 1,
62:         MeleeTimelineKind::AttackTransformed => combatant.committed_attacks_transformed += 1,
63:         MeleeTimelineKind::Contact if event.simultaneous_members.len() > 1 => {
64:             combatant.simultaneous_contacts += 1;
65:         }
66:         MeleeTimelineKind::Contact | MeleeTimelineKind::Terminal => {}
67:     }
68:     Ok(())
69: }
