71: fn record_movement_event(
72:     combatant: &mut AutoresolveCombatantCausal,
73:     event: &adventuresim_core::autoresolve::MeleeTimelineEvent,
74: ) -> IterationResult<()> {
75:     let missing = |observation| ReportContractError::MissingMovementObservation {
76:         sequence: event.sequence,
77:         observation,
78:     };
79:     let before = event
80:         .movement_velocity_before_metres_per_second
81:         .ok_or_else(|| missing(MovementObservation::VelocityBefore))?;
82:     let after = event
83:         .movement_velocity_after_metres_per_second
84:         .ok_or_else(|| missing(MovementObservation::VelocityAfter))?;
85:     let speed_limit = event
86:         .movement_speed_limit_metres_per_second
87:         .ok_or_else(|| missing(MovementObservation::SpeedLimit))?;
88:     let elapsed = event
89:         .movement_elapsed_seconds
90:         .ok_or_else(|| missing(MovementObservation::Elapsed))?;
91:     if let Some(action) = event.movement_action {
92:         *combatant
93:             .movement_actions
94:             .entry(format!("{action:?}"))
95:             .or_default() += 1;
96:     }
97:     let displacement = event.movement_displacement_metres.unwrap_or_default().abs();
98:     let velocity = before.magnitude().max(after.magnitude());
99:     let elapsed_measurement = Measurement::<AutoresolveSeconds>::from_elapsed(elapsed)?;
100:     combatant
101:         .movement_elapsed_seconds
102:         .checked_add(elapsed_measurement)?;
103:     combatant.movement_segments += 1;
104:     combatant
105:         .movement_absolute_displacement_metres
106:         .checked_add(Measurement::<MovementMetres>::from_native(displacement)?)?;
107:     combatant.maximum_movement_speed_metres_per_second = combatant
108:         .maximum_movement_speed_metres_per_second
109:         .max(Measurement::<MovementSpeed>::from_speed(velocity)?);
110:     combatant.maximum_movement_segment_seconds = combatant
111:         .maximum_movement_segment_seconds
112:         .max(elapsed_measurement);
113:     // This f32 inequality is the original movement-contract kernel: metres
114:     // versus metres/second times seconds, with the existing metre tolerance.
115:     combatant.movement_displacement_limit_failures +=
116:         u64::from(displacement > speed_limit.metres_per_second() * elapsed.seconds() + 1.0e-5);
117:     let distance_delta = event
118:         .engagement_distance_before_metres
119:         .zip(event.engagement_distance_after_metres)
120:         .map_or(0.0, |(before, after)| (after - before).abs());
121:     combatant.movement_nonzero_delta_zero_elapsed +=
122:         u64::from(distance_delta > 0.0 && elapsed.is_zero());
123:     Ok(())
124: }
