126: fn record_response_event(
127:     combatant: &mut AutoresolveCombatantCausal,
128:     event: &adventuresim_core::autoresolve::MeleeTimelineEvent,
129: ) -> MeasurementResult<()> {
130:     if let Some(availability) = event.response_availability {
131:         *combatant
132:             .response_availability
133:             .entry(format!("{availability:?}"))
134:             .or_default() += 1;
135:     }
136:     if let Some(choice) = event.response_choice {
137:         *combatant
138:             .response_choices
139:             .entry(format!("{choice:?}"))
140:             .or_default() += 1;
141:     }
142:     if let Some(delay) = event.phase_adaptation_delay_seconds
143:         && !delay.is_zero()
144:     {
145:         combatant.phase_adaptation_events += 1;
146:         combatant
147:             .phase_adaptation_delay_seconds
148:             .checked_add(Measurement::<AutoresolveSeconds>::from_elapsed(delay)?)?;
149:     }
150:     Ok(())
