153: fn record_contact_measures(
154:     attacker: &mut AutoresolveCombatantCausal,
155:     telemetry: &adventuresim_core::autoresolve::MeleeContactTelemetry,
156: ) -> MeasurementResult<()> {
157:     attacker.contact_measure_samples += 1;
158:     attacker.mean_scheduled_contact_measure_metres.checked_add(
159:         Measurement::<ContactMetres>::from_native(telemetry.scheduled_contact_measure_metres)?,
160:     )?;
161:     let actual =
162:         Measurement::<ContactMetres>::from_native(telemetry.actual_contact_measure_metres)?;
163:     attacker
164:         .mean_actual_contact_measure_metres
165:         .checked_add(actual)?;
166:     let separation = Measurement::<CenterSeparationMetres>::from_native(
167:         telemetry.actual_center_separation_metres,
168:     )?;
169:     attacker.minimum_actual_contact_measure_metres = Some(
170:         attacker
171:             .minimum_actual_contact_measure_metres
172:             .map_or(actual, |minimum| minimum.min(actual)),
173:     );
174:     attacker.maximum_actual_contact_measure_metres = Some(
175:         attacker
176:             .maximum_actual_contact_measure_metres
177:             .map_or(actual, |maximum| maximum.max(actual)),
178:     );
179:     attacker.minimum_actual_center_separation_metres = Some(
180:         attacker
181:             .minimum_actual_center_separation_metres
182:             .map_or(separation, |minimum| minimum.min(separation)),
183:     );
184:     Ok(())
185: }

