285: fn record_autoresolve_timeline(
286:     causal: &mut AutoresolveCausalSummary,
287:     outcome: &adventuresim_core::autoresolve::BattleOutcome,
288:     john_id: u64,
289: ) -> IterationResult<()> {
290:     let scheduled_contact_ticks = outcome
291:         .timeline
292:         .iter()
293:         .filter(|event| event.kind == MeleeTimelineKind::AttackStarted)
294:         .filter_map(|event| Some((event.attack_id?, event.attack_contact_tick?)))
295:         .collect::<BTreeMap<_, _>>();
296:     for event in &outcome.timeline {
297:         let Some(id) = event.combatant_id else {
298:             continue;
299:         };
300:         let combatant = if id == john_id {
301:             &mut causal.john
302:         } else {
303:             &mut causal.opponent
304:         };
305:         if event.kind == MeleeTimelineKind::Contact
306:             && event.attack_id.and_then(|attack_id| {
307:                 scheduled_contact_ticks
308:                     .get(&attack_id)
309:                     .map(|scheduled| event.tick < *scheduled)
310:             }) == Some(true)
311:         {
312:             combatant.premature_contact_events += 1;
313:         }
314:         causal::record_timeline_event(combatant, event)?;
315:     }
316:     if let Some(first) = outcome
317:         .timeline
318:         .iter()
319:         .find(|event| event.kind == MeleeTimelineKind::Contact)
320:     {
321:         causal.john_first_contacts += u64::from(first.combatant_id == Some(john_id));
322:         causal.opponent_first_contacts += u64::from(first.combatant_id != Some(john_id));
323:     }
324:     Ok(())
325: }

1: //! Native report quantities retain f64 precision through sums and reductions.
2: //!
3: //! Roles distinguish clocks and units even when they share numeric storage.
4: //! Native f32 observations are promoted once; sums and means never narrow back
5: //! into gameplay quantities. Scalar projection belongs to the report serializer
6: //! or to the named arithmetic operations below.
7: 
8: use std::{marker::PhantomData, time::Duration};
9: 
10: use adventuresim_core::{
11:     elapsed::AnimationElapsed, linear_speed::NonnegativeSpeed, unit_interval::UnitInterval,
12: };
13: use adventuresim_tactical_server::iteration::TacticalElapsed;
14: use serde::Serialize;
15: 
16: pub(super) type MeasurementResult<T> = Result<T, MeasurementError>;
17: 
18: #[derive(Clone, Copy, Debug, Default, PartialEq, PartialOrd, Serialize)]
19: #[serde(transparent)]
20: pub(super) struct Measurement<Role> {
21:     value: f64,
22:     #[serde(skip)]
23:     role: PhantomData<Role>,
24: }
25: 
26: #[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
27: pub(crate) enum MeasurementError {
28:     #[error("native report {quantity:?} must be finite")]
29:     NonFinite { quantity: ReportQuantity },
30:     #[error("native report {quantity:?} arithmetic overflowed")]
31:     Overflow { quantity: ReportQuantity },
32: }
33: 
34: pub(super) trait ReportUnit: Copy + Default + PartialOrd {
35:     const QUANTITY: ReportQuantity;
36: }
37: 
38: macro_rules! report_quantities {
39:     ($($role:ident),+ $(,)?) => {
40:         #[derive(Clone, Copy, Debug, PartialEq, Eq)]
41:         pub(crate) enum ReportQuantity {
42:             $($role),+
43:         }
44: 
45:         $(
46:             #[derive(Clone, Copy, Debug, Default, PartialEq, PartialOrd)]
47:             pub(super) struct $role;
48: 
49:             impl ReportUnit for $role {
50:                 const QUANTITY: ReportQuantity = ReportQuantity::$role;
51:             }
52:         )+
53:     };
54: }
55: 
56: report_quantities! {
57:     TacticalSeconds,
58:     AutoresolveSeconds,
59:     ContactMetres,
60:     CenterSeparationMetres,
61:     WeaponReachMetres,
62:     MovementMetres,
63:     MovementSpeed,
64:     ContactJoules,
65:     HealthDamage,
66:     BloodLossFraction,
67:     WoundFlowFractionPerSecond,
68:     Fatigue,
69:     AcuteTrauma,
70:     Imbalance,
71:     PainIncapacitation,
72:     IncapacitationPerformance,
73:     AttackPowerMultiplier,
74:     WinRate,
75:     WinRateDifference,
76:     WallSeconds,
77:     WallMilliseconds,
78:     DuelsPerWallSecond,
79:     TacticalSecondsPerWallSecond,
80: }
81: 
82: impl<Role: ReportUnit> Measurement<Role> {
83:     pub(super) const ZERO: Self = Self {
84:         value: 0.0,
85:         role: PhantomData,
86:     };
87: 
88:     /// Admission at a native observation or authored report-limit boundary.
89:     pub(super) fn from_native(value: f32) -> MeasurementResult<Self> {
90:         Self::from_f64(f64::from(value))
91:     }
92: 
93:     pub(super) fn checked_add(&mut self, sample: Self) -> MeasurementResult<()> {
94:         *self = Self::from_arithmetic(self.value + sample.value)?;
95:         Ok(())
96:     }
97: 
98:     /// Divide after the original ordered sum. An unobserved mean keeps its
99:     /// existing zero representation; contact extrema use Option separately.
100:     pub(super) fn mean(self, samples: u64) -> MeasurementResult<Self> {
101:         if samples == 0 {
102:             return Ok(self);
103:         }
104:         Self::from_arithmetic(self.value / samples as f64)
105:     }
106: 
107:     pub(super) fn min(self, other: Self) -> Self {
108:         Self {
109:             value: self.value.min(other.value),
110:             role: PhantomData,
111:         }
112:     }
113: 
114:     pub(super) fn max(self, other: Self) -> Self {
115:         Self {
116:             value: self.value.max(other.value),
117:             role: PhantomData,
118:         }
119:     }
120: 
121:     fn from_f64(value: f64) -> MeasurementResult<Self> {
122:         if !value.is_finite() {
123:             return Err(MeasurementError::NonFinite {
124:                 quantity: Role::QUANTITY,
125:             });
126:         }
127:         Ok(Self {
128:             value,
129:             role: PhantomData,
130:         })

