34: impl<'v> PreparedRangedDefense<'v> {
35:     fn prepare(
36:         shot: &authority::ValidatedRangedShot,
37:         viewer: &'v TacticalPlayerViewer<'_, '_>,
38:         states: &Query<&TacticalCombatState>,
39:         skeletons: &Query<&SkeletonState>,
40:         pending: &Query<&PendingDefenderResponse>,
41:         time: &Time<()>,
42:         config: &DefenseAuthorityConfig,
43:     ) -> Option<Self> {
44:         let ValidatedRangedImpact::Hit {
45:             target, target_yaw, ..
46:         } = shot.impact()
47:         else {
48:             return None;
49:         };
50:         let defender_view = viewer.get(target).ok()?;
51:         let defender_skeleton = skeletons.get(target).ok()?;
52:         let flanking = ranged_flanking(shot.attacker_yaw(), target_yaw);
53:         let response = match resolve_passive_block(
54:             pending.get(target).ok(),
55:             time,
56:             &defender_view,
57:             defender_skeleton,
58:             config,
59:         ) {
60:             Ok(response) => response,
61:             Err(error) => {
62:                 warn!(%error, "cannot resolve defense timing");
63:                 return None;
64:             }
65:         };
66:         let (Ok(attacker), Ok(defender)) = (states.get(shot.attacker()), states.get(target)) else {
67:             return None;
68:         };
69:         let performance = match RangedPerformances::admit(attacker, defender) {
70:             Ok(performance) => performance,
71:             Err(error) => {
72:                 warn!(%error, "invalid ranged combat performance");
73:                 return None;
74:             }
75:         };
76:         Some(Self {
77:             defender_view,
78:             response,
79:             performance,
80:             flanking,
81:         })
82:     }
83: }
