126: pub(super) fn resolve_ranged_attack(
127:     event: On<RangedAttackIntent>,
128:     mut cmd: Commands,
129:     viewer: TacticalPlayerViewer,
130:     spatial: SpatialQuery,
131:     q_character: Query<(&CharacterLook, &Transform)>,
132:     q_sides: Query<&TacticalCombatSide>,
133:     q_states: Query<&TacticalCombatState>,
134:     q_skeletons: Query<&SkeletonState>,
135:     mut q_authorities: Query<&mut RangedAttackAuthority>,
136:     q_pending: Query<&PendingDefenderResponse>,
137:     q_scene_items: Query<Entity, With<TacticalSceneItem>>,
138:     q_ammo: Query<(Entity, &ItemOf, &ItemProperties, &TacticalItemQuantity)>,
139:     q_ids: Query<&CharacterId>,
140:     mut consequences: ResMut<TacticalConsequenceAccumulator>,
141:     time: Res<Time<()>>,
142:     config: Res<TacticalCombatConfig>,
143: ) {
144:     let attacker = event.attacker;
145:     let Ok(attacker_view) = viewer.get(attacker) else {
146:         return;
147:     };
148:     let Ok((attacker_look, attacker_transform)) = q_character.get(attacker) else {
149:         return;
150:     };
151:     let target_character = event.target.and_then(|target| q_character.get(target).ok());
152:     let now = CombatInstant::from_elapsed(&time);
153:     let Ok(mut authority) = q_authorities.get_mut(attacker) else {
154:         return;
155:     };
156:     let facts = RangedIntentFacts {
157:         attacker,
158:         target: event.target,
159:         attacker_side: q_sides.get(attacker).ok().copied(),
160:         target_side: event
161:             .target
162:             .and_then(|target| q_sides.get(target).ok().copied()),
163:         attacker_incapacitated: q_states
164:             .get(attacker)
165:             .ok()

166:             .map(TacticalCombatState::is_incapacitated),
167:         target_incapacitated: event.target.and_then(|target| {
168:             q_states
169:                 .get(target)
170:                 .ok()
171:                 .map(TacticalCombatState::is_incapacitated)
172:         }),
173:         reported_precision: event.reported_precision,
174:         weapon_is_ranged: attacker_view.weapon_is_ranged(),
175:         weapon_range: attacker_view.weapon_reach(),
176:         range_latency_tolerance: config
177:             .realtime_authority
178:             .ranged
179:             .range_latency_tolerance_metres,
180:         separation: target_character.map(|(_, transform)| {
181:             attacker_transform
182:                 .translation
183:                 .distance(transform.translation)
184:         }),
185:         target_in_aim_cone: target_character.map(|(_, transform)| {
186:             ranged_target_in_aim_cone(
187:                 attacker_look.yaw,
188:                 attacker_transform.translation,
189:                 transform.translation,
190:                 config.realtime_authority.ranged.aim_half_angle_degrees,
191:             )
192:         }),
193:         authority_permits: authority.permits(now),
194:         body_part: event.body_part,
195:         attacker_position: attacker_transform.translation,
196:         target_position: target_character.map(|(_, transform)| transform.translation),
197:         attacker_yaw: attacker_look.yaw,
198:         target_yaw: target_character.map(|(look, _)| look.yaw),
199:     };
200:     let validated = match validate_ranged_intent(facts) {
201:         Ok(validated) => validated,
202:         Err(reason) => {
203:             if !matches!(reason, RangedIntentRejection::Windup) {
204:                 debug!("Rejected ranged intent from {attacker:?}: {reason:?}");
205:             }
206:             return;
207:         }
208:     };
209:     if let ValidatedRangedImpact::Hit {
210:         target,
211:         target_position,
212:         ..
213:     } = validated.impact()
214:     {
215:         let line_of_sight = authoritative_line_of_sight(
216:             &spatial,
217:             &q_scene_items,
218:             validated.attacker(),
219:             target,
220:             validated.attacker_position(),
221:             target_position,
222:         );
223:         if !line_of_sight {
224:             debug!(
225:                 "Rejected ranged intent from {attacker:?}: {:?}",
226:                 RangedIntentRejection::BlockedLineOfSight
227:             );
228:             return;
229:         }
230:     }
231:     let cooldown =
232:         match CombatDuration::from_elapsed(config.realtime_authority.ranged.cooldown_seconds) {
233:             Ok(cooldown) => cooldown,
234:             Err(error) => {
235:                 warn!(%error, "attack cooldown exceeds native clock");
236:                 return;
237:             }
238:         };
239:     let ammunition = RangedAmmunition::find(validated.attacker(), &q_ammo);
240:     let defense = if ammunition.is_some()
241:         && matches!(validated.impact(), ValidatedRangedImpact::Hit { .. })
242:     {
243:         let Some(defense) = PreparedRangedDefense::prepare(
244:             &validated,
245:             &viewer,
246:             &q_states,
247:             &q_skeletons,
248:             &q_pending,
249:             &time,
250:             &config.realtime_authority.defense,
251:         ) else {
252:             return;
253:         };
254:         Some(defense)
255:     } else {
256:         None
257:     };
258:     let Some(shot) = authority.authorize_shot(validated, now, cooldown) else {
259:         return;
260:     };
261:     // Dry fire consumes only cooldown; misses consume ammunition without defense.
262:     let Some(ammunition) = ammunition else {
263:         return;
264:     };
265:     ammunition.consume(&mut cmd, &q_ids, &mut consequences, &shot);
266:     let Some(PreparedRangedDefense {
267:         defender_view,
268:         response: defender_response,
269:         performance,
270:         flanking,
271:     }) = defense
272:     else {
