7: pub(crate) fn reconnect_equipment_lifecycle(
8:     old: Entity,
9:     new: Entity,
10:     pending: &mut PendingEquipmentActions,
11:     sequences: &mut LastEquipmentSequence,
12: ) {
13:     pending
14:         .0
15:         .retain(|(actor, _)| *actor != old && *actor != new);
16:     sequences.0.remove(&new);
17:     if let Some(sequence) = sequences.0.remove(&old) {
18:         sequences.0.insert(new, sequence);
19:     }
20: }
21: 
22: pub(crate) fn purge_equipment_lifecycle(
23:     actor: Entity,
24:     pending: &mut PendingEquipmentActions,
25:     sequences: &mut LastEquipmentSequence,
26: ) {
27:     pending.0.retain(|(queued, _)| *queued != actor);
28:     sequences.0.remove(&actor);
29: }

