568: fn pickup(
569:     commands: &mut Commands,
570:     actor: Entity,
571:     hand: EquipmentHand,
572:     requested: Entity,
573:     players: &Query<(&Transform, &CharacterLook), With<Player>>,
574:     items: &Query<ItemView<'_>>,
575:     spatial: &SpatialQuery,
576: ) -> bool {
577:     if hand_item(actor, hand, items).is_some() {
578:         return false;
579:     }
580:     let Ok((actor_transform, _)) = players.get(actor) else {
581:         return false;
582:     };
583:     let Ok((_, _, _, _, _, physical, scene, item_transform)) = items.get(requested) else {
584:         return false;
585:     };
586:     let Some((physical, item_transform)) = physical
587:         .filter(|physical| physical.is_valid())
588:         .zip(item_transform)
589:         .filter(|_| scene)
590:     else {
591:         return false;
592:     };
593:     let item_position = item_box_center(item_transform.translation, physical);
594:     if item_position.distance_squared(actor_transform.translation) > PICKUP_RANGE_M * PICKUP_RANGE_M
595:     {
596:         return false;
597:     }
598:     let origin = actor_transform.translation + Vec3::Y * 0.6;
599:     let sight = item_position - origin;
600:     let distance = sight.length();
601:     let Ok(direction) = Dir3::new(sight) else {
602:         return false;
603:     };
604:     // Terrain/support LOS is evaluated separately from item pointing; item
605:     // boxes therefore do not become combat/visibility blockers.
606:     let blocker_filter = SpatialQueryFilter::from_mask(TACTICAL_TERRAIN_LAYER);
607:     if spatial
608:         .cast_ray(origin, direction, distance, true, &blocker_filter)
609:         .is_some()
610:     {
611:         return false;
612:     }
613:     commands
614:         .entity(requested)
615:         .remove::<TacticalSceneItem>()
616:         .remove::<RigidBody>()
617:         .remove::<Collider>()
618:         .remove::<CollisionLayers>()
619:         .insert((
620:             ItemOf(actor),
621:             hand_topology(hand),
622:             hand.slot(),
623:             Transform::default(),
624:         ));
625:     true
626: }
