538: fn read_forest(directory: &Path, south: i16, west: i16) -> crate::Result<Option<Vec<u8>>> {
539:     let latitude = if south >= 0 {
540:         format!("N{south:02}")
541:     } else {
542:         format!("S{:02}", -south)
543:     };
544:     let longitude = if west >= 0 {
545:         format!("E{west:03}")
546:     } else {
547:         format!("W{:03}", -west)
548:     };
549:     let path = directory.join(format!("TCD_{latitude}_{longitude}.tif"));
550:     if !path.is_file() {
551:         return Ok(None);
552:     }
553:     let mut decoder = Decoder::new(BufReader::new(File::open(&path)?))
554:         .map_err(|error| crate::Error::Validation(error.to_string()))?;
555:     if decoder
556:         .dimensions()
557:         .map_err(|error| crate::Error::Validation(error.to_string()))?
558:         != (1_000, 1_000)
559:     {
560:         return Err(crate::Error::Validation(format!(
561:             "{} has invalid forest grid",
562:             path.display()
563:         )));
564:     }
565:     let DecodingResult::U8(pixels) = decoder
566:         .read_image()
567:         .map_err(|error| crate::Error::Validation(error.to_string()))?
568:     else {
569:         return Err(crate::Error::Validation(format!(
570:             "{} is not UInt8",
571:             path.display()
572:         )));
573:     };
574:     Ok(Some(pixels))
575: }
