11: fn tube_centers(points: &[[f64; 3]], radius: f64, segments: usize) -> Result<Solid, GenerateError> {
12:     let mut path: Vec<_> = points.iter().map(|p| p.map(f64::from)).collect();
13:     path.push(path[0]);
14:     Solid::sweep(
15:         &path,
16:         &Sweep {
17:             width: radius * 2.0,
18:             depth: radius * 2.0,
19:             radial_segments: segments,
20:             ..Sweep::default()
21:         },
22:         Detail::High,
23:     )
24:     .map_err(GenerateError::Construction)
25: }
26: fn sheath_parts(
27:     blade: &FittedPart,
28:     design: &WeaponHolderDesign,
29: ) -> Result<Vec<PartSource>, GenerateError> {
30:     let envelope =
31:         ClearanceEnvelope::new(&blade.positions, 32).map_err(GenerateError::Construction)?;
32:     let [base, tip] = envelope.extent();
33:     let clearance = metres(design.clearance);
34:     let wall = metres(design.wall_thickness);
35:     let cavity_tip = tip + clearance;
36:     let body = holder_part(
37:         "scabbard-body",
38:         design.body_material,
39:         envelope
40:             .shell(base, cavity_tip, clearance, wall, LoftEnd::Closed)
41:             .map_err(GenerateError::Construction)?,
42:         0.82,
43:     );
44:     let fitting = |name, lower, upper| {
45:         envelope
46:             .shell(lower, upper, clearance + wall, 0.002, LoftEnd::Open)
47:             .map(|solid| holder_part(name, design.fitting_material, solid, 0.82))
48:             .map_err(GenerateError::Construction)
49:     };
50:     let throat = fitting(
51:         "scabbard-throat",
52:         base,
53:         (base + metres(design.throat_length)).min(cavity_tip),
54:     )?;
55:     let chape = fitting(
56:         "scabbard-chape",
57:         (cavity_tip + wall - metres(design.chape_length)).max(base),
58:         cavity_tip + wall,
59:     )?;
60:     let hanger_half_width = metres(design.hanger_width) * 0.5;
61:     let hanger_half_height = metres(design.hanger_height) * 0.5;
62:     let mouth = bounds(&envelope.ring(base, clearance + wall));
63:     let hanger_center = [
64:         mouth.min[0] - hanger_half_width,
65:         base + hanger_half_height,
66:         (mouth.min[2] + mouth.max[2]) * 0.5,
67:     ];
68:     let hanger_centers = (0..28)
69:         .map(|index| {
70:             let angle = index as f64 / 28.0 * std::f64::consts::TAU;
71:             [
72:                 hanger_center[0] + angle.cos() * hanger_half_width,
73:                 hanger_center[1] + angle.sin() * hanger_half_height,
74:                 hanger_center[2],
75:             ]
76:         })
77:         .collect::<Vec<_>>();
78:     let suspension = holder_part(
79:         "scabbard-suspension",
80:         design.body_material,
81:         tube_centers(&hanger_centers, metres(design.loop_bar_radius), 10)?,
82:         0.65,
83:     );
84:     Ok(vec![body, throat, chape, suspension])
85: }
