87: fn haft_loop_parts(
88:     grip: &FittedPart,
89:     design: &WeaponHolderDesign,
90: ) -> Result<Vec<PartSource>, GenerateError> {
91:     let center_x = (grip.bounds.min[0] + grip.bounds.max[0]) * 0.5;
92:     let center_z = (grip.bounds.min[2] + grip.bounds.max[2]) * 0.5;
93:     let grip_length = grip.bounds.max[1] - grip.bounds.min[1];
94:     let y = grip.bounds.min[1] + grip_length * (f64::from(design.loop_position.0) / 1000.0);
95:     let radius_x = (grip.bounds.max[0] - grip.bounds.min[0]) * 0.5
96:         + metres(design.clearance)
97:         + metres(design.loop_bar_radius);
98:     let radius_z = (grip.bounds.max[2] - grip.bounds.min[2]) * 0.5
99:         + metres(design.clearance)
100:         + metres(design.loop_bar_radius);
101:     let ring_centers = (0..24)
102:         .map(|index| {
103:             let angle = index as f64 / 24.0 * std::f64::consts::TAU;
104:             [
105:                 center_x + angle.cos() * radius_x,
106:                 y,
107:                 center_z + angle.sin() * radius_z,
108:             ]
109:         })
110:         .collect::<Vec<_>>();
111:     let hanger_half_width = metres(design.hanger_width) * 0.5;
112:     let hanger_half_height = metres(design.hanger_height) * 0.5;
113:     let hanger_center = [center_x - radius_x - hanger_half_width, y, center_z];
114:     let hanger_centers = (0..28)
115:         .map(|index| {
116:             let angle = index as f64 / 28.0 * std::f64::consts::TAU;
117:             [
118:                 hanger_center[0] + angle.cos() * hanger_half_width,
119:                 hanger_center[1] + angle.sin() * hanger_half_height,
120:                 hanger_center[2],
121:             ]
122:         })
123:         .collect::<Vec<_>>();
124:     Ok(vec![
125:         holder_part(
126:             "haft-frog",
127:             design.body_material,
128:             tube_centers(&ring_centers, metres(design.loop_bar_radius), 10)?,
129:             0.65,
130:         ),
131:         holder_part(
132:             "belt-loop",
133:             design.body_material,
134:             tube_centers(&hanger_centers, metres(design.loop_bar_radius), 10)?,
135:             0.65,
136:         ),
137:     ])
138: }
