51:         || !(4..=40).contains(&design.throat_length.0)
52:         || !(6..=60).contains(&design.chape_length.0)
53:         || design.loop_position.0 > 1000
54:         || !(2..=12).contains(&design.loop_bar_radius.0)
55:         || !(20..=120).contains(&design.hanger_width.0)
56:         || !(30..=180).contains(&design.hanger_height.0)
