1: //! Bounded memoization of successful pure physical evaluations.
2: use crate::DerivedProperties;
3: use std::{collections::VecDeque, sync::Mutex};
4: 
5: // Each recipe is already bounded by the canonical transport/structure limits.
6: // Keep a fixed number of full design keys, never caller-supplied hash keys.
7: const RETAINED_EVALUATIONS: usize = 64;
8: 
9: pub(super) struct PhysicalMemo<D>(Mutex<VecDeque<(D, DerivedProperties)>>);
10: impl<D: Clone + PartialEq> PhysicalMemo<D> {
11:     pub(super) const fn new() -> Self {
12:         Self(Mutex::new(VecDeque::new()))
13:     }
14:     pub(super) fn evaluate<E>(
15:         &self,
16:         design: &D,
17:         construct: impl FnOnce() -> Result<DerivedProperties, E>,
18:     ) -> Result<DerivedProperties, E> {
19:         {
20:             let entries = self.0.lock().expect("physical memo poisoned");
21:             if let Some((_, physical)) = entries.iter().find(|(key, _)| key == design) {
22:                 return Ok(*physical);
23:             }
24:         }
25:         // Do not hold the memo lock during construction. Failure leaves no entry.
26:         let physical = construct()?;
27:         let mut entries = self.0.lock().expect("physical memo poisoned");
28:         if !entries.iter().any(|(key, _)| key == design) {
29:             if entries.len() == RETAINED_EVALUATIONS {
30:                 entries.pop_front();
31:             }
32:             entries.push_back((design.clone(), physical));
33:         }
34:         Ok(physical)
35:     }
36: }
