177:     /// Order derived nodes by dependency, independently of their names.
178:     pub(crate) fn binding_order(&self) -> Result<Vec<String>, String> {
179:         let Some(bindings) = &self.node_bindings else {
180:             return Ok(Vec::new());
181:         };
182:         let mut pending: std::collections::BTreeSet<_> = bindings.keys().cloned().collect();
183:         let mut order = Vec::new();
184:         while !pending.is_empty() {
185:             let next = pending
186:                 .iter()
187:                 .find(|name| match &bindings[*name] {
188:                     NodeBinding::Frame { .. } => true,
189:                     NodeBinding::Between { between, .. } => between
190:                         .iter()
191:                         .all(|dependency| !pending.contains(dependency)),
192:                 })
193:                 .cloned()
194:                 .ok_or("guard node bindings contain a cycle")?;
195:             pending.remove(&next);
196:             order.push(next);
197:         }
198:         Ok(order)
199:     }
200: }
