2: use super::*;
3: pub(super) fn attached(
4:     component: &mut Component,
5:     frames: &BTreeMap<String, Point>,
6:     rotations: &BTreeMap<String, Point>,
7:     rotation: Point,
8:     local: Point,
9:     range: [f64; 2],
10:     mut offset: Point,
11: ) -> Result<Point, String> {
12:     let id = component.id.as_deref().unwrap();
13:     if let Some(stretch) = &component.stretch_between {
14:         if magnitude(local) > 1e-8 {
15:             return Err("stretched start and end must meet their declared frames".into());
16:         }
17:         let from = *frames
18:             .get(&stretch[0])
19:             .ok_or("missing stretch source frame")?;
20:         let to = *frames
21:             .get(&stretch[1])
22:             .ok_or("missing stretch target frame")?;
23:         if to[1] <= from[1] {
24:             return Err("stretch target must lie above source".into());
25:         }
26:         let Shape::KnuckleBow(p) = &mut component.shape else {
27:             return Err("stretchBetween requires knuckle bow".into());
28:         };
29:         p.length = Metres::new(to[1] - from[1])?;
30:         offset = add(from, local);
31:     } else if let Some(attachment) = &component.attach {
32:         let target = *frames
33:             .get(&attachment.to)
34:             .ok_or_else(|| format!("{id}: missing frame {}", attachment.to))?;
35:         let anchor = component
36:             .shape
37:             .attachment_anchor(attachment.at.unwrap_or_default(), range)?;
38:         let (owner, name) = attachment
39:             .to
40:             .rsplit_once('.')
41:             .ok_or("frame needs owner and name")?;
42:         let inward = rotate(
43:             [
44:                 0.0,
45:                 if matches!(name, "root" | "base" | "bottom") {
46:                     1.0
47:                 } else {
48:                     -1.0
49:                 },
50:                 0.0,
51:             ],
52:             *rotations.get(owner).unwrap_or(&[0.0; 3]),
53:         );
54:         let overlap = attachment.overlap.map_or(0.0, Metres::get);
55:         if overlap < 0.0 {
56:             return Err("attachment overlap cannot be negative".into());
57:         }
58:         let expected = add(
59:             add(
60:                 target,
61:                 attachment.offset.map_or([0.0; 3], |p| p.map(Metres::get)),
62:             ),
63:             mul(inward, overlap),
64:         );
65:         offset = sub(expected, rotate(anchor, rotation));
66:     }
67: 
68:     Ok(offset)
69: }
