246: pub(crate) fn validate_simple_path(input: &[Point]) -> Result<(), String> {
247:     if input.len() < 2 {
248:         return Err("member needs at least two stations".into());
249:     }
250:     let closed = magnitude(sub(input[0], *input.last().unwrap())) < 1e-8;
251:     for i in 0..input.len() - 1 {
252:         for j in i + 2..input.len() - 1 {
253:             if closed && i == 0 && j == input.len() - 2 {
254:                 continue;
255:             }
256:             if segment_distance(input[i], input[i + 1], input[j], input[j + 1]) < 1e-10 {
257:                 return Err("member centerline intersects itself".into());
258:             }
259:         }
260:     }
261:     Ok(())
262: }
