4: pub(super) fn check(p: &SpearParameters) -> Checked {
5:     if let Some(roundness) = p.shoulder_roundness {
6:         proportion((0.0..=1.0).contains(&roundness.get()))?;
7:     }
8:     let Some(socket) = &p.socket else {
9:         return Ok(());
10:     };
11:     proportion(p.section != Some(SpearSection::Flat))?;
12:     for dimension in [
13:         socket.length,
14:         socket.neck_length,
15:         socket.base_radius,
16:         socket.wall,
17:         socket.cavity_depth,
18:         socket.insertion_depth,
19:         socket.bore_tip_radius,
20:     ] {
21:         positive(dimension.get())?;
22:     }
23:     let root = p.root_width.map_or(p.width.get() * 0.4, Metres::get) / 2.0;
24:     let barrel = socket.length.get() - socket.neck_length.get();
25:     let depth = p.thickness.get() / 2.0;
26:     proportion(socket.minimum_neck_axis(root, root, 0.0) > 0.0)?;
27:     proportion(socket.minimum_neck_axis(root, depth, -depth * 0.9 / p.length.get()) > 0.0)?;
28:     proportion(barrel > socket.cavity_depth.get() + socket.wall.get())?;
29:     clearance(socket.insertion_depth.get() + socket.wall.get() <= socket.cavity_depth.get())?;
30:     clearance(socket.base_radius.get() > socket.wall.get())?;
31:     let exterior_cap = socket.base_radius.get()
32:         + (root - socket.base_radius.get()) * socket.cavity_depth.get() / barrel;
33:     clearance(socket.bore_tip_radius.get() + socket.wall.get() <= exterior_cap)?;
34:     if let Some(stops) = &socket.stops {
35:         if let Some(blend) = stops.root_blend {
36:             nonnegative(blend.get())?;
37:             proportion(blend.get() <= stops.thickness.get().min(stops.end_height.get()))?;
38:             let lower = stops.center_height.get() - stops.root_height.get();
39:             let upper = stops.center_height.get() + stops.end_height.get() / 2.0;
40:             let socket_radius = socket
41:                 .outer_barrel_radius(root, lower)
42:                 .max(socket.outer_barrel_radius(root, upper));
43:             proportion(blend.get() <= stops.span.get() / 2.0 - socket_radius)?;
44:         }
45:         for dimension in [
46:             stops.span,
47:             stops.center_height,
48:             stops.end_height,
49:             stops.root_height,
50:             stops.thickness,
51:         ] {
52:             positive(dimension.get())?;
53:         }
54:         proportion(stops.orientation.get().abs() <= 360.0)?;
55:         proportion(stops.root_height.get() > stops.end_height.get() / 2.0)?;
56:         proportion(stops.center_height.get() > stops.root_height.get())?;
57:         proportion(stops.center_height.get() + stops.end_height.get() / 2.0 < barrel)?;
58:         proportion(stops.span.get() / 2.0 > socket.base_radius.get().max(root))?;
59:         proportion(stops.thickness.get() / 2.0 < socket.base_radius.get().min(root))?;
60:     }
61:     Ok(())
62: }
