140: impl ModelPart {
141:     pub(crate) fn from_source(source: PartSource) -> Self {
142:         #[derive(Eq, PartialEq, Ord, PartialOrd)]
143:         enum Surface {
144:             Smooth(u32),
145:             Flat([i64; 3]),
146:         }
147:         let mut lookup: BTreeMap<(Surface, [i64; 3]), Vec<usize>> = BTreeMap::new();
148:         let mut positions: Vec<Point> = Vec::new();
149:         let mut sums: Vec<Point> = Vec::new();
150:         let mut neighbors: Vec<Vec<(Point, f64)>> = Vec::new();
151:         let mut indices = Vec::new();
152:         for (triangle, &[a, b, c]) in source.solid.faces.iter().enumerate() {
153:             let points = [
154:                 source.solid.positions[a],
155:                 source.solid.positions[b],
156:                 source.solid.positions[c],
157:             ];
158:             let face = normalize(cross(sub(points[1], points[0]), sub(points[2], points[0])));
159:             let group = source.solid.surfaces[triangle];
160:             let policy = source.surface_smoothing.get(&group);
161:             let cosine = policy.map_or(source.smoothing_cosine, |p| p.cosine);
162:             for corner in 0..3 {
163:                 let point = points[corner];
164:                 let surface = if source.solid.surfaces[triangle] == 0 {
165:                     Surface::Flat(face.map(|v| (v * 1e8).round() as i64))
166:                 } else {
167:                     Surface::Smooth(policy.map_or(group, |p| p.group))
168:                 };
169:                 let candidates = lookup
170:                     .entry((surface, point.map(|v| (v * 1e9).round() as i64)))
171:                     .or_default();
172:                 let index = candidates
173:                     .iter()
174:                     .copied()
175:                     .find(|&i| {
176:                         neighbors[i]
177:                             .iter()
178:                             .all(|&(neighbor, limit)| dot(neighbor, face) > cosine.max(limit))
179:                     })
180:                     .unwrap_or_else(|| {
181:                         let index = positions.len();
182:                         candidates.push(index);
183:                         positions.push(point);
184:                         sums.push([0.0; 3]);
185:                         neighbors.push(Vec::new());
186:                         index
187:                     });
188:                 neighbors[index].push((face, cosine));
189:                 let a = normalize(sub(points[(corner + 1) % 3], point));
190:                 let b = normalize(sub(points[(corner + 2) % 3], point));
191:                 let angle = dot(a, b).clamp(-1.0, 1.0).acos();
192:                 sums[index] = add(sums[index], mul(face, angle));
193:                 indices.push(index as u32);
194:             }
195:         }
196:         let colors = positions
197:             .iter()
198:             .flat_map(|_| source.material.color())
199:             .collect();
200:         Self {
201:             positions: positions.into_iter().flatten().collect(),
202:             normals: sums.into_iter().flat_map(normalize).collect(),
203:             colors,
204:             indices,
205:             material: MaterialAppearance {
206:                 color: source.material.color(),
207:                 density: source.material.density(),
208:             },
209:             material_id: source.material,
210:             label: source.label,
211:             component_id: source.component_id,
212:             animation_pivot: source.animation_pivot,
213:             animation_channel: source.animation_channel,
214:             bore: source.bore,
215:             shield_role: source.shield_role,
216:         }
217:     }
218: }
