71:             if let Some(WrappingSection::Rounded { crest_fraction }) = &wrapping.section {
72:                 proportion(crest_fraction.get() > 0.0 && crest_fraction.get() < 1.0)?;
73:             }
74:             if let Some(support) = wrapping.on_wrapping {
75:                 require((support.0 as usize) < index, RecipeError::Attachment)?;
76:                 let parent = &wrappings[support.0 as usize];
77:                 proportion(
78:                     parent.pattern != WrappingPattern::Crossed
79:                         && wrapping.pattern != WrappingPattern::Crossed,
80:                 )?;
81:                 proportion(wrapping.underlay.is_none())?;
82:                 proportion(
83:                     wrapping.start.get() >= parent.start.get()
84:                         && wrapping.start.get() + wrapping.length.get()
85:                             <= parent.start.get() + parent.length.get(),
86:                 )?;
87:                 let Some(WrappingSection::Rounded { crest_fraction }) = parent.section else {
88:                     return Err(RecipeError::Attachment);
89:                 };
90:                 proportion(wrapping_contact(parent, wrapping, crest_fraction.get()))?;
91:             }
92:             if let Some(underlay) = &wrapping.underlay {
93:                 positive(underlay.thickness.get())?;
94:                 proportion(underlay.thickness.get() < p.radius.get() / 2.0)?;
95:             }
96:             nonnegative(wrapping.start.get())?;
97:             for dimension in [
98:                 wrapping.length,
99:                 wrapping.pitch,
100:                 wrapping.width,
101:                 wrapping.thickness,
102:             ] {
103:                 positive(dimension.get())?;
104:             }
105:             proportion(wrapping.width.get() < wrapping.length.get())?;
106:             let spacing = if wrapping.pattern == WrappingPattern::Crossed {
107:                 4.0
108:             } else {
109:                 1.0
110:             };
111:             proportion(wrapping.width.get() * spacing < wrapping.pitch.get())?;
112:             proportion(wrapping.phase.get().abs() <= 360.0)?;
113:             proportion(wrapping.thickness.get() < p.radius.get() / 2.0)?;
114:             proportion(
115:                 wrapping.start.get() + wrapping.length.get()
116:                     <= p.length.get() - p.tenon.as_ref().map_or(0.0, |t| t.length.get()),
117:             )?;
118:             require(
119:                 wrapping.length.get() / wrapping.pitch.get() <= 128.0,
120:                 RecipeError::Budget,
121:             )?;
122:         }
123:         for (index, a) in wrappings.iter().enumerate() {
124:             for b in &wrappings[index + 1..] {
125:                 let mut support = b.on_wrapping;
126:                 let mut rests_on_a = false;
127:                 while let Some(parent) = support {
128:                     if parent.0 as usize == index {
129:                         rests_on_a = true;
130:                         break;
131:                     }
132:                     support = wrappings[parent.0 as usize].on_wrapping;
133:                 }
134:                 proportion(
135:                     rests_on_a
136:                         || a.start.get() + a.length.get() <= b.start.get()
137:                         || b.start.get() + b.length.get() <= a.start.get(),
138:                 )?;
139:             }
140:         }
141:     }
142:     if let Some(tenon) = &p.tenon {
143:         positive(tenon.length.get())?;
144:         positive(tenon.tip_radius.get())?;
145:         proportion(tenon.length.get() < p.length.get())?;
146:         proportion(
147:             tenon.tip_radius.get() <= p.radius.get() * p.top_scale.map_or(0.92, Ratio::get),
148:         )?;
149:     }
150:     Ok(())
151: }
