153: /// The two helical footprints must overlap a finite portion of the lower crest.
154: fn wrapping_contact(parent: &ShaftWrapping, child: &ShaftWrapping, crest: f64) -> bool {
155:     let direction = |p: WrappingPattern| {
156:         if p == WrappingPattern::LeftHanded {
157:             -1.0
158:         } else {
159:             1.0
160:         }
161:     };
162:     let start = child.start.get() + child.width.get() / 2.0;
163:     let end = child.start.get() + child.length.get() - child.width.get() / 2.0;
164:     let parent_start = parent.start.get() + parent.width.get() / 2.0;
165:     let phase = |y: f64| {
166:         child.phase.get() / 360.0 + direction(child.pattern) * (y - start) / child.pitch.get()
167:             - parent.phase.get() / 360.0
168:             - direction(parent.pattern) * (y - parent_start) / parent.pitch.get()
169:     };
170:     let a = phase(start);
171:     let b = phase(end);
172:     let contact = (parent.width.get() * crest + child.width.get()) / (2.0 * parent.pitch.get());
173:     (a.min(b) - contact).floor() + 1.0 < a.max(b) + contact
174: }

