225:     pub(crate) fn from_sources(
226:         sources: Vec<PartSource>,
227:         resolved_definition: ResolvedRecipe,
228:         physical: PhysicalProperties,
229:     ) -> Self {
230:         let volume = sources.iter().map(|p| p.solid.volume()).sum();
231:         let parts: Vec<_> = sources.into_iter().map(ModelPart::from_source).collect();
232:         let mut positions = Vec::new();
233:         let mut normals = Vec::new();
234:         let mut colors = Vec::new();
235:         let mut indices = Vec::new();
236:         for part in &parts {
237:             let base = positions.len() / 3;
238:             indices.extend(part.indices.iter().map(|&i| i + base as u32));
239:             positions.extend(&part.positions);
240:             normals.extend(&part.normals);
241:             colors.extend(&part.colors);
242:         }
243:         let mut min = [f64::INFINITY; 3];
244:         let mut max = [f64::NEG_INFINITY; 3];
245:         for point in positions.as_chunks::<3>().0 {
246:             for axis in 0..3 {
247:                 min[axis] = min[axis].min(point[axis]);
248:                 max[axis] = max[axis].max(point[axis]);
249:             }
250:         }
251:         let dimensions = sub(max, min);
252:         let stats = ModelStats {
253:             bounds: ModelBounds { min, max },
254:             dimensions,
255:             radius: magnitude(dimensions) / 2.0,
256:             triangles: indices.len() / 3,
257:             vertices: positions.len() / 3,
258:             volume,
259:             part_count: parts.len(),
260:         };
261:         Self {
262:             positions,
263:             normals,
264:             colors,
265:             indices,
266:             parts,
267:             stats,
268:             physical,
269:             resolved_definition,
270:         }
271:     }
272: }
