296: impl PhysicalProperties {
297:     pub(crate) fn from_sources(parts: &[PartSource], control: Point) -> Self {
298:         let mut mass_kg = 0.0;
299:         let mut first = [0.0; 3];
300:         let mut inertia = 0.0;
301:         let mut tip = control[1];
302:         let mut components = Vec::new();
303:         for part in parts {
304:             let mut mass = 0.0;
305:             let mut moment = [0.0; 3];
306:             let mut transverse = 0.0;
307:             for &[a, b, c] in &part.solid.faces {
308:                 let [a, b, c] = [
309:                     part.solid.positions[a],
310:                     part.solid.positions[b],
311:                     part.solid.positions[c],
312:                 ];
313:                 let tetra_mass = dot(a, cross(b, c)) / 6.0 * part.material.density();
314:                 mass += tetra_mass;
315:                 for axis in 0..3 {
316:                     let first = tetra_mass * (a[axis] + b[axis] + c[axis]) / 4.0;
317:                     moment[axis] += first;
318:                     let second = tetra_mass
319:                         * (a[axis] * a[axis]
320:                             + b[axis] * b[axis]
321:                             + c[axis] * c[axis]
322:                             + a[axis] * b[axis]
323:                             + a[axis] * c[axis]
324:                             + b[axis] * c[axis])
325:                         / 10.0;
326:                     let shifted = second - 2.0 * control[axis] * first
327:                         + control[axis] * control[axis] * tetra_mass;
328:                     transverse += shifted * if axis == 1 { 1.0 } else { 0.5 };
329:                 }
330:             }
331:             mass_kg += mass;
332:             first = add(first, moment);
333:             inertia += transverse;
334:             tip = part
335:                 .solid
336:                 .positions
337:                 .iter()
338:                 .map(|p| p[1])
339:                 .fold(tip, f64::max);
340:             components.push(PartMass {
341:                 id: part.component_id.clone(),
342:                 label: part.label.clone(),
343:                 material: part.material,
344:                 mass_kg: mass,
345:                 center_of_mass: mul(moment, 1.0 / mass),
346:             });
347:         }
348:         let center_of_mass = mul(first, 1.0 / mass_kg);
349:         let grip_to_tip_m = (tip - control[1]).max(0.0);
350:         Self {
351:             mass_kg,
352:             control_point: control,
353:             center_of_mass,
354:             center_of_mass_from_grip_m: center_of_mass[1] - control[1],
355:             moment_of_inertia_kg_m2: inertia,
356:             balance: if grip_to_tip_m > 0.0 {
357:                 (inertia / mass_kg).sqrt() / grip_to_tip_m
358:             } else {
359:                 1.0
360:             },
361:             grip_to_tip_m,
362:             components,
363:         }
364:     }
365: }

