109:         let id = component.resolved_id(index);
110:         component.id = Some(id.clone());
111:         let rotation = component.rotation.map_or([0.0; 3], |r| r.map(Degrees::get));
112:         let local = component.offset.map_or([0.0; 3], |p| p.map(Metres::get));
