5:     shaft: Option<&Shaft>,
6:     frames: &BTreeMap<String, Point>,
7:     rotation: Point,
8:     local: Point,
9:     range: [f64; 2],
10: ) -> Result<(Point, Option<f64>), String> {
11:     let mut offset = local;
12:     let mut shaft_contact = None;
13:     if let Some(mount) = component.mount {
14:         match mount {
15:             Mount::ComponentEnd => {
16:                 let anchor = component
17:                     .anchor
18:                     .as_ref()
19:                     .ok_or("component-end needs anchor")?;
20:                 component.attach = Some(Attachment {
21:                     to: format!("{anchor}.top"),
22:                     at: Some(AttachmentAnchor::Center),
23:                     offset: None,
24:                     overlap: None,
25:                 });
26:             }
27:             _ => {
28:                 mounts::check(component, shaft.ok_or("shaft-top mount requires shaft")?)?;
29:                 let top = *frames
30:                     .get(SHAFT_TOP_FRAME)
31:                     .ok_or("shaft-top mount requires shaft")?;
32:                 offset = add(top, local);
33:                 if let Shape::Spear(p) = &component.shape
34:                     && let Some(socket) = &p.socket
35:                 {
36:                     if mount != Mount::ShaftTop {
37:                         return Err("socketed spear uses shaft-top receiving mount".into());
38:                     }
39:                     offset[1] += socket.length.get() - socket.insertion_depth.get();
40:                 }
41:                 match mount {
42:                     Mount::ShaftTopCentered | Mount::ShaftTopSleeve => {
43:                         let contact = if mount == Mount::ShaftTopCentered {
44:                             range[0]
45:                         } else {
46:                             range[1]
47:                         };
48:                         offset = sub(offset, rotate([0.0, contact, 0.0], rotation));
49:                         offset[1] -= component.insertion.map_or(0.012, Metres::get);
50:                     }
51:                     _ => {}
52:                 }
53:                 let shaft = shaft.ok_or("shaft-top mount requires shaft")?;
54:                 let radius = shaft.radius.get() * shaft.top_scale.map_or(0.92, Ratio::get);
55:                 match &mut component.shape {
56:                     Shape::Socket(p) if p.fit_shaft != Some(false) => {
57:                         let wall = p.wall.map_or(0.003, Metres::get);
58:                         for point in &mut p.profile {
59:                             point[1] = Metres::new(radius + wall)?;
60:                         }
61:                         shaft_contact = Some(radius);
62:                     }
63:                     Shape::Sleeve(p) if p.fit_shaft != Some(false) => {
64:                         let wall = p.wall.map_or(0.003, Metres::get);
65:                         p.radius = Metres::new(radius + wall)?;
66:                         p.top_radius = Some(p.radius);
67:                         shaft_contact = Some(radius);
68:                     }
69:                     _ => {}
70:                 }
71:             }
72:         }
73:     }
74: 
75:     Ok((offset, shaft_contact))
76: }
77: pub(super) fn seating(
78:     component: &Component,
79:     components: &[ResolvedComponent],
80:     offset: Point,
81:     rotation: Point,
82: ) -> Option<f64> {
83:     if let Shape::OvalGrip(p) = &component.shape {
84:         let base = p.width.get() * p.bottom_scale.map_or(1.0, Ratio::get) / 2.0;
85:         let parent = components.iter().find(|parent| {
86:             component
87:                 .attach
88:                 .as_ref()
89:                 .is_some_and(|a| a.to == format!("{}.top", parent.id))
90:         });
91:         parent.and_then(|parent| {
92:             if let Shape::Pommel(pommel) = &parent.component.shape {
93:                 if parent.rotation != [0.0; 3] || rotation != [0.0; 3] {
94:                     return None;
95:                 }
96:                 if pommel.construction == PommelConstruction::Lathed {
97:                     let profile = pommel.profile.as_ref()?;
98:                     let y = offset[1] - parent.offset[1];
99:                     let upper = profile
100:                         .iter()
101:                         .position(|point| point[0].get() >= y)
102:                         .unwrap_or(0);
103:                     let a = profile[upper.saturating_sub(1)];
104:                     let b = profile[upper];
105:                     let t = if a[0] == b[0] {
106:                         0.0
107:                     } else {
108:                         ((y - a[0].get()) / (b[0].get() - a[0].get())).clamp(0.0, 1.0)
109:                     };
110:                     Some(base.min(a[1].get() + (b[1].get() - a[1].get()) * t))
111:                 } else {
112:                     let plate = pommel.construction == PommelConstruction::Plate
113:                         || pommel.base_construction == Some(PommelBaseConstruction::Plate);
114:                     let neck = if pommel.outline_style == Some(PommelOutlineStyle::Fan) {
115:                         0.36
116:                     } else {
117:                         pommel.shoulder_width.map_or(0.42, Ratio::get)
118:                     };
119:                     Some(
120:                         base.min(if plate {
121:                             0.009
122:                         } else {
123:                             pommel.diameter.map_or(0.055, Metres::get)
124:                                 * neck
125:                                 * pommel.width_scale.map_or(1.0, Ratio::get)
126:                                 / 2.0
127:                         })
128:                         .min(
129:                             pommel.thickness.map_or(0.018, Metres::get) * 0.48 * p.width.get()
130:                                 / p.thickness.get(),
131:                         ),
132:                     )
133:                 }
134:             } else {
135:                 None
136:             }
137:         })
138:     } else {
139:         None
140:     }
141: }

