89:     pub(crate) fn radius_at(&self, height: f64) -> f64 {
90:         let profile = self.profile();
91:         let span = profile
92:             .windows(2)
93:             .find(|p| height <= p[1][0])
94:             .unwrap_or(&profile[profile.len() - 2..]);
95:         let progress = ((height - span[0][0]) / (span[1][0] - span[0][0])).clamp(0.0, 1.0);
96:         span[0][1] + (span[1][1] - span[0][1]) * progress
97:     }
