1: //! Canonical controlling hand frame selection.
2: use super::*;
3: use std::collections::BTreeMap;
4: pub(super) fn grip_point(recipe: &Recipe, frames: &BTreeMap<String, Point>) -> Point {
5:     if let Some(&grip) = frames.get(SHIELD_GRIP_FRAME) {
6:         return grip;
7:     }
8:     if let (Some(clearance), Some(&base), Some(&top)) = (
9:         recipe.grip_clearance,
10:         frames.get(GRIP_BASE_FRAME),
11:         frames.get(GRIP_TOP_FRAME),
12:     ) {
13:         return add(top, mul(normalize(sub(base, top)), clearance.get()));
14:     }
15:     if let Some(grip) = recipe
16:         .components
17:         .iter()
18:         .rev()
19:         .find(|c| c.role == Some(crate::ComponentRole::Grip))
20:         .and_then(|c| c.id.as_ref())
21:         .and_then(|id| frames.get(&format!("{id}.center")))
22:     {
23:         return *grip;
24:     }
25:     if let Some(&grip) = frames.get(GRIP_CENTER_FRAME) {
26:         return grip;
27:     }
28:     if let (Some(&bottom), Some(&top)) =
29:         (frames.get(SHAFT_BOTTOM_FRAME), frames.get(SHAFT_TOP_FRAME))
30:     {
31:         let length = magnitude(sub(top, bottom));
32:         return lerp(bottom, top, (length * 0.2).clamp(0.18, 0.45) / length);
33:     }
34:     [0.0; 3]
35: }

