1: //! Explicit directional dependencies between independently parameterized heads.
2: use super::*;
3: use std::collections::BTreeSet;
4: 
5: fn direction(shape: &Shape) -> Option<Direction> {
6:     match shape {
7:         Shape::Axe(p) => Some(p.side.unwrap_or(Direction::Positive)),
8:         Shape::Beak(p) => Some(p.direction.unwrap_or(Direction::Negative)),
9:         Shape::FacetedBeak(p) => Some(p.direction.unwrap_or(Direction::Negative)),
10:         Shape::Hammer(p) => Some(p.direction.unwrap_or(Direction::Positive)),
11:         _ => None,
12:     }
13: }
14: 
15: pub(crate) fn directions(recipe: &Recipe) -> Result<Vec<(usize, Direction)>, String> {
16:     fn resolve(
17:         index: usize,
18:         recipe: &Recipe,
19:         visiting: &mut BTreeSet<usize>,
20:     ) -> Result<Direction, String> {
21:         if !visiting.insert(index) {
22:             return Err("working-end facing dependencies contain a cycle".into());
23:         }
24:         let component = &recipe.components[index];
25:         let own = direction(&component.shape).ok_or("component has no directional working end")?;
26:         let result = if let Some(target) = &component.opposed_to {
27:             let parent = recipe
28:                 .components
29:                 .iter()
30:                 .enumerate()
31:                 .position(|(i, c)| c.resolved_id(i) == *target)
32:                 .ok_or("opposed working end names a missing component")?;
33:             match resolve(parent, recipe, visiting)? {
34:                 Direction::Positive => Direction::Negative,
35:                 Direction::Negative => Direction::Positive,
36:             }
37:         } else {
38:             own
39:         };
40:         visiting.remove(&index);
41:         Ok(result)
42:     }
43:     recipe
44:         .components
45:         .iter()
46:         .enumerate()
47:         .filter(|(_, c)| c.opposed_to.is_some())
48:         .map(|(i, _)| resolve(i, recipe, &mut BTreeSet::new()).map(|d| (i, d)))
49:         .collect::<Result<Vec<_>, _>>()
50: }
51: 
52: pub(crate) fn apply(recipe: &mut Recipe) -> Result<(), String> {
53:     for (index, direction) in directions(recipe)? {
54:         let c = &mut recipe.components[index];
55:         match &mut c.shape {
56:             Shape::Axe(p) => p.side = Some(direction),
57:             Shape::Beak(p) => p.direction = Some(direction),
58:             Shape::FacetedBeak(p) => p.direction = Some(direction),
59:             Shape::Hammer(p) => p.direction = Some(direction),
60:             _ => return Err("component has no directional working end".into()),
61:         }
62:         if let Some(offset) = &mut c.offset {
63:             offset[0] = Metres::new(offset[0].get().abs() * direction.sign())?;
64:         }
65:         if let Some(offset) = c.attach.as_mut().and_then(|a| a.offset.as_mut()) {
66:             offset[0] = Metres::new(offset[0].get().abs() * direction.sign())?;
67:         }
68:     }
69:     Ok(())
70: }
