475: fn desirability(candidate: &CultivationCandidate) -> i64 {
476:     let settlement = 900_000_i64.saturating_sub(i64::from(candidate.settlement_distance_m) * 90);
477:     // Roads help only in a short settlement catchment; this cannot create a
478:     // high-scoring ribbon between distant towns.
479:     let road = if candidate.settlement_distance_m <= 8_000 {
480:         180_000_i64.saturating_sub(i64::from(candidate.road_distance_m) * 90)
481:     } else {
482:         0
483:     };
484:     // Water access peaks around 500 m. Banks and wet ground are excluded by
485:     // usable_land before scoring.
486:     let water = 120_000_i64
487:         .saturating_sub((i64::from(candidate.water_distance_m).saturating_sub(500)).abs() * 120);
488:     settlement + road + water
489:         - i64::from(candidate.slope_permille) * 2_500
490:         - i64::from(candidate.relief_m) * 600
491:         - i64::from(candidate.canopy_percent) * 250
492: }
