564:         return Err("strategic map requires Viabundus v2".into());
565:     }
566:     if manifest.files.is_empty() || manifest.files.len() > MAX_SOURCE_FILES {
567:         return Err("Viabundus sidecar file inventory is outside its bound".into());
568:     }
569:     let mut names = BTreeSet::new();
570:     for entry in &manifest.files {
571:         let safe = !entry.name.is_empty()
572:             && entry.name.len() <= 128
573:             && entry
574:                 .name
575:                 .bytes()
576:                 .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'-' | b'_'))
577:             && entry.name.ends_with(".csv");
