591:             .files
592:             .iter()
593:             .find(|entry| entry.name == name)
594:             .ok_or("source manifest is incomplete")?;
595:         let bytes = fs::read(root.join(name))?;
596:         if entry.size != bytes.len() as u64 {
597:             return Err(format!("{name} does not match its initialized size").into());
598:         }
599:         let actual = format!("{:x}", Sha256::digest(&bytes));
600:         if actual != entry.sha256 {
601:             return Err(format!("{name} does not match its initialized SHA-256").into());
602:         }
603:     }
604: 
605:     let mut routing_roads = Vec::new();
606:     let mut reader = csv::Reader::from_path(root.join("edges.csv"))?;
607:     for row in reader.deserialize::<BTreeMap<String, String>>() {
608:         let row = row?;
609:         if !active(&row, WORLD_START_YEAR) {
