611:         }
612:         let kind = row
613:             .get("type")
614:             .ok_or("regional connection has no classification")?
615:             .parse::<RegionalConnectionKind>()?;
616:         let Some(wkt) = row.get("wkt") else { continue };
617:         for points in clip_polyline(&coordinates(wkt), bounds.longitude_latitude_degrees()) {
618:             if points.len() >= 2 {
619:                 routing_roads.push(SourceRoad { kind, points });
620:             }
621:         }
622:     }
623:     routing_roads.sort_by(|a, b| point_order(&a.points, &b.points));
624: 
625:     let mut water = Vec::new();
626:     let mut reader = csv::Reader::from_path(root.join("water-1500.csv"))?;
627:     for row in reader.records() {
628:         let row = row?;
629:         let Some(wkt) = row.get(0) else { continue };
