668: fn wkt_polygons(wkt: &str) -> Vec<Vec<Vec<Point>>> {
669:     let polygon_depth = if wkt.trim_start().starts_with("MULTIPOLYGON") {
670:         2
671:     } else if wkt.trim_start().starts_with("POLYGON") {
672:         1
673:     } else {
674:         return Vec::new();
675:     };
676:     let ring_depth = polygon_depth + 1;
677:     let mut depth = 0_usize;
678:     let mut polygons = Vec::new();
679:     let mut polygon = Vec::new();
680:     let mut ring = String::new();
681:     for character in wkt.chars() {
682:         match character {
683:             '(' => {
684:                 depth += 1;
685:                 if depth == polygon_depth {
686:                     polygon.clear();
687:                 } else if depth == ring_depth {
688:                     ring.clear();
689:                 }
690:             }
691:             ')' => {
692:                 if depth == ring_depth {
693:                     let points = coordinates(&ring);
694:                     if points.len() >= 4 {
695:                         polygon.push(points);
696:                     }
697:                 } else if depth == polygon_depth && !polygon.is_empty() {
698:                     polygons.push(std::mem::take(&mut polygon));
699:                 }
700:                 depth = depth.saturating_sub(1);
701:             }
702:             _ if depth == ring_depth => ring.push(character),
703:             _ => {}
704:         }
705:     }
706:     polygons
707: }
