717:                 }
718:                 current.push(start);
719:             }
720:             current.push(end);
721:         } else if current.len() >= 2 {
722:             output.push(std::mem::take(&mut current));
723:         }
724:     }
725:     if current.len() >= 2 {
726:         output.push(current);
727:     }
728:     output
729: }
