773: fn clip_polygon(points: &[Point], bounds: [f64; 4]) -> Vec<Point> {
774:     let mut output = points.to_vec();
775:     for edge in 0..4 {
776:         let input = std::mem::take(&mut output);
777:         if input.is_empty() {
778:             break;
779:         }
780:         let mut previous = input.last().expect("nonempty").clone();
781:         for current in input {
782:             let previous_inside = polygon_inside(&previous, edge, bounds);
783:             let current_inside = polygon_inside(&current, edge, bounds);
784:             if current_inside {
785:                 if !previous_inside {
786:                     output.push(polygon_intersection(&previous, &current, edge, bounds));
787:                 }
788:                 output.push(current.clone());
789:             } else if previous_inside {
790:                 output.push(polygon_intersection(&previous, &current, edge, bounds));
791:             }
792:             previous = current;
793:         }
794:     }
795:     if output.len() >= 3 && output.first() != output.last() {
796:         output.push(output[0].clone());
797:     }
798:     output
799: }
800: 
801: fn polygon_inside(point: &Point, edge: usize, [west, south, east, north]: [f64; 4]) -> bool {
802:     point.0.into_iter().all(f64::is_finite)
803:         && match edge {
804:             0 => point.0[0] >= west,
805:             1 => point.0[0] <= east,
806:             2 => point.0[1] >= south,
807:             _ => point.0[1] <= north,
808:         }
809: }
810: 
811: fn polygon_intersection(start: &Point, end: &Point, edge: usize, bounds: [f64; 4]) -> Point {
812:     let [x0, y0] = start.0;
813:     let [x1, y1] = end.0;
814:     if edge < 2 {
815:         let x = if edge == 0 { bounds[0] } else { bounds[2] };
816:         let t = if x1 == x0 { 0.0 } else { (x - x0) / (x1 - x0) };
817:         Point([x, y0 + t * (y1 - y0)])
818:     } else {
819:         let y = if edge == 2 { bounds[1] } else { bounds[3] };
820:         let t = if y1 == y0 { 0.0 } else { (y - y0) / (y1 - y0) };
821:         Point([x0 + t * (x1 - x0), y])
822:     }
823: }
824: 
825: fn validate_geometry(package: &Package) -> Result<(), Box<dyn std::error::Error>> {
826:     let bounds = package.bounds.longitude_latitude_degrees();
827:     let valid = |point: &Point| {
828:         point.0[0].is_finite()
829:             && point.0[1].is_finite()
830:             && point.0[0] >= bounds[0]
831:             && point.0[0] <= bounds[2]
832:             && point.0[1] >= bounds[1]
833:             && point.0[1] <= bounds[3]
834:     };
835:     if package
836:         .routing_roads
837:         .iter()
838:         .any(|line| line.points.len() < 2 || line.points.iter().any(|point| !valid(point)))
839:         || package.water.iter().any(|polygon| {
840:             polygon.rings.is_empty()
841:                 || polygon
842:                     .rings
843:                     .iter()
844:                     .any(|ring| ring.len() < 4 || ring.iter().any(|point| !valid(point)))
845:         })
846:     {
847:         return Err("strategic map geometry is non-finite or outside package bounds".into());
848:     }
849:     Ok(())
850: }

