49:     pub fn coordinate_units(self) -> f64 {
50:         f64::from(self.0) / f64::from(Self::UNITS_PER_COORDINATE_UNIT)
51:     }
52: 
53:     pub const fn millionths_of_coordinate_unit(self) -> i32 {
54:         self.0 / (Self::UNITS_PER_COORDINATE_UNIT / MILLIONTHS_PER_COORDINATE_UNIT)
55:     }
56: }
