63: impl LatitudeE7 {
64:     pub const UNITS_PER_DEGREE: i32 = E7_UNITS_PER_COORDINATE_UNIT;
65:     pub const MIN: Self = Self(-90 * Self::UNITS_PER_DEGREE);
66:     pub const MAX: Self = Self(90 * Self::UNITS_PER_DEGREE);
67:     pub const ZERO: Self = Self(0);
68: 
69:     pub const fn new(value: i32) -> Option<Self> {
70:         if value >= Self::MIN.0 && value <= Self::MAX.0 {
71:             Some(Self(value))
72:         } else {
73:             None
74:         }
75:     }
