77:     pub fn from_degrees(degrees: f64) -> Option<Self> {
78:         if !degrees.is_finite() || !(-90.0..=90.0).contains(&degrees) {
79:             return None;
80:         }
81:         Self::new((degrees * f64::from(Self::UNITS_PER_DEGREE)).round() as i32)
82:     }
