113:         } else {
114:             None
115:         }
116:     }
117: 
118:     pub fn from_degrees(degrees: f64) -> Option<Self> {
119:         if !degrees.is_finite() || !(-180.0..=180.0).contains(&degrees) {
120:             return None;
121:         }
122:         Self::new((degrees * f64::from(Self::UNITS_PER_DEGREE)).round() as i32)
123:     }
124: 
125:     pub const fn get(self) -> i32 {
126:         self.0
127:     }
128: 
129:     pub fn degrees(self) -> f64 {
130:         f64::from(self.0) / f64::from(Self::UNITS_PER_DEGREE)
131:     }
132: 
133:     pub const fn to_microdegrees(self) -> LongitudeMicrodegrees {
134:         LongitudeMicrodegrees(
135:             self.0 / (Self::UNITS_PER_DEGREE / LongitudeMicrodegrees::UNITS_PER_DEGREE),
136:         )
137:     }
138: }
139: 
