1: //! Terrain-aware rules-v9 repair of sparse Viabundus topology.
2: 
3: use std::{
4:     cmp::Reverse,
5:     collections::{BTreeMap, BinaryHeap, HashMap, HashSet},
6: };
7: 
8: use adventuresim_terrain::{TerrainPack, TerrainPurpose};
9: use adventuresim_world_schema::{
10:     CompiledWorld, LandRoute, MAX_EDGE_GEOMETRY_POINTS, TravelEdgeImport, TravelEdgeProvenance,
11:     TravelGeometryPoint, TravelRoute,
12: };
13: use sha2::{Digest, Sha256};
14: 
15: use crate::{Error, Result};
16: 
17: const MAX_ROUTE_METRES: u64 = 12_000;
18: const MAX_ROUTE_MINUTES: u64 = 360;
19: const MAX_EVALUATIONS_PER_SETTLEMENT: u8 = 8;
20: const MAX_INFERRED_DEGREE: u8 = 2;
21: const BUCKET_DEGREES: f64 = 0.20;
22: const MAX_BUCKET_SETTLEMENTS: usize = 256;
23: 
24: #[derive(Clone, Copy, Debug)]
25: struct Candidate {
26:     from: u64,
27:     to: u64,
28:     direct_m: u32,
29: }
30: 
31: pub(crate) fn enrich(mut world: CompiledWorld, terrain: &TerrainPack) -> Result<CompiledWorld> {
32:     if terrain.purpose() != TerrainPurpose::DocumentedBase {
33:         return Err(Error::Validation(
34:             "road inference requires a documented-base terrain pack".into(),
35:         ));
36:     }
37:     let nodes = world
38:         .nodes
39:         .iter()
40:         .map(|n| (n.id, (n.latitude, n.longitude)))
41:         .collect::<HashMap<_, _>>();
42:     let settlement_ids = world
43:         .settlements
44:         .iter()
45:         .map(|s| s.source_node_id)
46:         .collect::<HashSet<_>>();
47:     let mut buckets = BTreeMap::<(i32, i32), Vec<u64>>::new();
48:     for id in settlement_ids.iter().copied() {
49:         let &(lat, lon) = nodes
50:             .get(&id)
51:             .ok_or_else(|| Error::Validation("settlement node missing".into()))?;
52:         let key = (
53:             (lat / BUCKET_DEGREES).floor() as i32,
54:             (lon / BUCKET_DEGREES).floor() as i32,
55:         );
56:         let bucket = buckets.entry(key).or_default();
57:         if bucket.len() >= MAX_BUCKET_SETTLEMENTS {
58:             return Err(Error::Validation(
59:                 "road inference bucket exceeds bound".into(),
60:             ));
61:         }
62:         bucket.push(id);
63:     }
64:     for ids in buckets.values_mut() {
65:         ids.sort_unstable();
66:     }
67:     let mut candidates = Vec::new();
68:     let mut seen = HashSet::new();
69:     let mut ids = settlement_ids.into_iter().collect::<Vec<_>>();
70:     ids.sort_unstable();
71:     for from in ids {
72:         let (lat, lon) = nodes[&from];
73:         let key = (
74:             (lat / BUCKET_DEGREES).floor() as i32,
75:             (lon / BUCKET_DEGREES).floor() as i32,
76:         );
77:         let mut nearest = Vec::new();
78:         for dy in -1..=1 {
79:             for dx in -1..=1 {
80:                 if let Some(bucket) = buckets.get(&(key.0 + dy, key.1 + dx)) {
81:                     for &to in bucket {
82:                         if to == from {
83:                             continue;
84:                         }
85:                         let distance = haversine_m((lat, lon), nodes[&to]);
86:                         if distance <= MAX_ROUTE_METRES as u32 {
87:                             nearest.push((distance, to));
88:                         }
89:                     }
90:                 }
91:             }
92:         }
93:         nearest.sort_unstable();
94:         nearest.truncate(MAX_EVALUATIONS_PER_SETTLEMENT as usize);
95:         for (direct_m, to) in nearest {
96:             let pair = (from.min(to), from.max(to));
97:             if seen.insert(pair) {
98:                 candidates.push(Candidate {
99:                     from: pair.0,
100:                     to: pair.1,
101:                     direct_m,
102:                 });
103:             }
104:         }
105:     }
106:     candidates.sort_by_key(|c| (c.direct_m, c.from, c.to));
107:     let mut adjacency = graph(&world.edges);
108:     let mut evaluations = HashMap::<u64, u8>::new();
109:     let mut degree = HashMap::<u64, u8>::new();
110:     let existing_ids = world.edges.iter().map(|e| e.id).collect::<HashSet<_>>();
111:     let mut accepted = Vec::new();
112:     for candidate in candidates {
113:         if degree.get(&candidate.from).copied().unwrap_or(0) >= MAX_INFERRED_DEGREE
114:             || degree.get(&candidate.to).copied().unwrap_or(0) >= MAX_INFERRED_DEGREE
115:         {
116:             continue;
117:         }
118:         if evaluations.get(&candidate.from).copied().unwrap_or(0) >= MAX_EVALUATIONS_PER_SETTLEMENT
119:             || evaluations.get(&candidate.to).copied().unwrap_or(0)
120:                 >= MAX_EVALUATIONS_PER_SETTLEMENT
121:         {
122:             continue;
123:         }
124:         if shortest_within(
125:             &adjacency,
126:             candidate.from,
127:             candidate.to,
128:             u64::from(candidate.direct_m) * 18 / 10,
129:         ) {
130:             continue;
131:         }
132:         *evaluations.entry(candidate.from).or_default() += 1;
133:         *evaluations.entry(candidate.to).or_default() += 1;
134:         let a = nodes[&candidate.from];
135:         let b = nodes[&candidate.to];
136:         let Ok(plan) = terrain.plan(a, b) else {
137:             continue;
138:         };
139:         if plan.distance_m == 0
140:             || plan.distance_m > MAX_ROUTE_METRES
141:             || plan.minutes > MAX_ROUTE_MINUTES
142:         {
143:             continue;
144:         }
145:         let mut geometry = plan
146:             .points
147:             .iter()
148:             .map(|p| TravelGeometryPoint::new(p.longitude, p.latitude).map_err(Error::Validation))
149:             .collect::<Result<Vec<_>>>()?;
150:         if geometry.len() < 2 || geometry.len() > MAX_EDGE_GEOMETRY_POINTS {
151:             continue;
152:         }
153:         geometry[0] = TravelGeometryPoint::new(a.1, a.0).map_err(Error::Validation)?;
154:         let last = geometry.len() - 1;
155:         geometry[last] = TravelGeometryPoint::new(b.1, b.0).map_err(Error::Validation)?;
156:         let id = stable_id(candidate.from, candidate.to, &existing_ids, &accepted);
157:         let length_m = geometry
158:             .windows(2)
159:             .map(|pair| {
160:                 haversine_m(
161:                     (pair[0].latitude(), pair[0].longitude()),
162:                     (pair[1].latitude(), pair[1].longitude()),
163:                 ) as u64
164:             })
165:             .sum::<u64>();
166:         if length_m == 0 || length_m > MAX_ROUTE_METRES {
167:             continue;
168:         }
169:         let length_m = u32::try_from(length_m)
170:             .map_err(|_| Error::Validation("inferred road length overflow".into()))?;
171:         accepted.push(TravelEdgeImport {
172:             id, from_node_id: candidate.from, to_node_id: candidate.to,
173:             route: TravelRoute::Land(LandRoute { bridge: None, water_crossings: Vec::new() }),
174:             provenance: TravelEdgeProvenance::InferredWalkingLink, geometry,
175:             toll: None, length_m, slope_multiplier: 1.0,
176:             terrain: adventuresim_world_schema::RouteTerrain::stage_placeholder(), certainty: 1,
177:             section: "inferred-terrain-link-v9".into(),
178:             sources: format!("- **Terrain-aware road inference rules v9:** A* over documented-base terrain {} found a bounded {} m / {} minute passable alignment between nodes `{}` and `{}`. This is plausible gap-fill, not a Viabundus-documented road.", terrain.package_sha256(), plan.distance_m, plan.minutes, candidate.from, candidate.to),
179:         });
180:         adjacency
181:             .entry(candidate.from)
182:             .or_default()
183:             .push((candidate.to, u64::from(length_m)));
184:         adjacency
185:             .entry(candidate.to)
186:             .or_default()
187:             .push((candidate.from, u64::from(length_m)));
188:         *degree.entry(candidate.from).or_default() += 1;
189:         *degree.entry(candidate.to).or_default() += 1;
190:     }
191:     accepted.sort_by_key(|e| e.id);
192:     let geometry_bytes = serde_json::to_vec(
193:         &accepted
194:             .iter()
195:             .map(|e| (&e.id, &e.geometry))
196:             .collect::<Vec<_>>(),
197:     )?;
198:     world.report.base_terrain_package_sha256 = terrain.package_sha256().into();
199:     world.report.inferred_road_edges = accepted.len();
200:     world.report.inferred_road_geometry_sha256 = format!("{:x}", Sha256::digest(geometry_bytes));
201:     world.edges.extend(accepted);
202:     world.edges.sort_by_key(|edge| edge.id);
203:     world.report.edges = world.edges.len();
204:     world.report.settlements_connected_to_road_network = connected_settlement_count(&world);
205:     Ok(world)
206: }
207: 
208: fn graph(edges: &[TravelEdgeImport]) -> HashMap<u64, Vec<(u64, u64)>> {
209:     let mut g = HashMap::new();
210:     for e in edges {
211:         g.entry(e.from_node_id)
212:             .or_insert_with(Vec::new)
213:             .push((e.to_node_id, u64::from(e.length_m)));
214:         g.entry(e.to_node_id)
215:             .or_insert_with(Vec::new)

