120:         let draft = forest_cover::enrich(draft, forest_cover)?;
121:         let draft = potential_vegetation::enrich(draft, potential_vegetation)?;
122:         let draft = tree_species::enrich(draft, tree_species)?;
123:         let draft = soil::predict(draft, soilgrids)?;
124:         let draft = geology::enrich(draft, geology)?;
125:         let draft = religion::enrich(draft, religion_regions)?;
126:         let draft = drought::enrich(draft, drought)?;
127:         let draft = hydrology::enrich(draft, hydrology)?;
128:         let draft = soil::finalize(draft)?;
129:         let world = environment_synthesis::finalize(draft)?;
130:         let world = faults::enrich(
131:             world,
132:             fault_geopackage,
