628: 
629:     fn plan_with_deadline(
630:         &self,
631:         start: (f64, f64),
632:         goal: (f64, f64),
633:         profile: TerrainSkillProfile,
634:         weather: RoutingWeather,
635:         deadline: Option<Instant>,
636:     ) -> Result<RoutePlan> {
637:         if !profile.is_valid() {
638:             return Err(Error::Validation(
639:                 "terrain skill profile exceeds rank five".into(),
640:             ));
641:         }
642:         if !weather.is_valid() {
643:             return Err(Error::Validation(
644:                 "routing weather exceeds bounded values".into(),
645:             ));
646:         }
647:         if ![start.0, start.1, goal.0, goal.1]
648:             .into_iter()
649:             .all(f64::is_finite)
650:         {
651:             return Err(Error::NoRoute);
652:         }
653:         let [west, south, east, north] = self.bounds();
654:         let inside = |(latitude, longitude): (f64, f64)| {
655:             longitude >= west && longitude <= east && latitude >= south && latitude <= north
656:         };
657:         if !inside(start) || !inside(goal) {
658:             return Err(Error::NoRoute);
659:         }
660:         for window in expanding_windows(start, goal, self.bounds()) {
661:             check_deadline(deadline)?;
662:             match self.plan_window(start, goal, window, profile, weather, deadline) {
663:                 Ok(plan) => return Ok(plan),
664:                 Err(Error::NoRoute) => continue,
665:                 Err(error) => return Err(error),
666:             }
667:         }
668:         Err(Error::NoRoute)
669:     }
670: 
671:     fn plan_window(
672:         &self,
673:         start: (f64, f64),
674:         goal: (f64, f64),
675:         [west, south, east, north]: [f64; 4],
676:         profile: TerrainSkillProfile,
677:         weather: RoutingWeather,
678:         deadline: Option<Instant>,
679:     ) -> Result<RoutePlan> {
680:         if west >= east || south >= north {
681:             return Err(Error::NoRoute);
682:         }
683:         let latitude = (south + north) * 0.5;
684:         let mut step_lat = 30.0 / 111_320.0;
685:         let mut step_lon = 30.0 / (111_320.0 * latitude.to_radians().cos().abs().max(0.2));
686:         loop {
687:             let width = ((east - west) / step_lon).ceil() as usize + 1;
688:             let height = ((north - south) / step_lat).ceil() as usize + 1;
689:             if width
690:                 .checked_mul(height)
691:                 .is_some_and(|count| count <= MAX_ROUTE_NODES)
692:             {
693:                 break;
694:             }
695:             step_lat *= 1.25;
696:             step_lon *= 1.25;
697:         }
698:         let width = ((east - west) / step_lon).ceil() as u32 + 1;
699:         let height = ((north - south) / step_lat).ceil() as u32 + 1;
700:         let mut cells = Vec::with_capacity(width as usize * height as usize);
701:         for y in 0..height {
702:             if y % 16 == 0 {
703:                 check_deadline(deadline)?;
704:             }
705:             let lat = north - f64::from(y) * step_lat;
706:             for x in 0..width {
