16:     b: adventuresim_world_schema::TravelGeometryPoint,
17: ) -> u32 {
18:     let dlat = (b.latitude() - a.latitude()).to_radians();
19:     let dlon = (b.longitude() - a.longitude()).to_radians();
20:     let h = (dlat / 2.0).sin().powi(2)
21:         + a.latitude().to_radians().cos()
22:             * b.latitude().to_radians().cos()
23:             * (dlon / 2.0).sin().powi(2);
24:     (6_371_000.0 * 2.0 * h.sqrt().asin()).round() as u32
25: }
