66:         .collect::<fabelgeist_rig::RigJointTable<_>>();
67:     let vertex_count = input.positions.len();
68:     let unused_texcoords = vec![[0.0f32; 2]; vertex_count];
69:     let body = GpuBody::new(
70:         gpu,
71:         BodySurface {
72:             positions: input.positions,
73:             normals: input.normals,
74:             faces: input.faces,
75:             texcoords: &unused_texcoords,
76:             joint_indices: input.joint_indices,
77:             joint_weights: input.joint_weights,
78:             joints: input.global_joint_states,
79:         },
80:     )?;
81:     let seams = DeviceSeams::new(gpu, &SeamTopology::new(input.faces, input.texcoord_faces)?)?;
82:     let atlas = gpu.upload(BufferUpload::from_elements(input.texcoords))?;
83:     let status = gpu.scratch(4, "bracer status")?;
84: 
85:     let mut batch = gpu.batch("bracer");
86:     let support = gpu.scratch(vertex_count as u64 * 4, "forearm support")?;
87:     let axial = gpu.scratch(vertex_count as u64 * 4, "forearm axial")?;
88:     record_support(
