90:         &mut batch,
91:         &body,
92:         [lowarm, wrist],
93:         &gpu.upload(BufferUpload::from_elements(
94:             &supports.into_iter().map(u32::from).collect::<Vec<_>>(),
95:         ))?,
96:         &support,
97:         &axial,
98:         &status,
99:     )?;
100:     let surface = DeviceSurface::record(gpu, &mut batch, &seams, &body.faces, &support, &status)?;
101:     let mut bracer = DeviceBracer::record(
102:         gpu,
103:         &mut batch,
104:         design,
105:         ForearmSkin {
106:             surface: &surface,
107:             axial: &axial,
108:             atlas: &atlas,
109:             body: &body,
110:         },
111:         &status,
112:     )?;
113:     batch.submit();
114:     for morph in input.morphs {
115:         let positions = gpu.upload(BufferUpload::from_elements(&morph.positions))?;
116:         let normals = gpu.upload(BufferUpload::from_elements(&morph.normals))?;
117:         let mut batch = gpu.batch("bracer morph");
118:         bracer.record_morph(
119:             gpu,
120:             &mut batch,
121:             BracerBody {
122:                 positions: &positions,
123:                 normals: &normals,
124:             },
125:         )?;
126:         batch.submit();
127:     }
128: 
129:     let bits = gpu.read_async::<u32>(&status).await?[0];
130:     if bits & STATUS_COINCIDENT_LANDMARKS != 0 {
131:         bail!("MHR forearm landmarks coincide");
132:     }
133:     if bits & STATUS_EMPTY_SELECTION != 0 {
134:         bail!("MHR forearm skin selected no faces");
135:     }
136:     let names = input
137:         .morphs
138:         .iter()
139:         .map(|morph| morph.name.clone())
