1: //! Results of many stages brought back in one readback.
2: //!
3: //! Every read of a device buffer waits for the queue, and the queue is shared
4: //! by every thread fitting armor: a piece that read its positions, normals,
5: //! indices and statuses one by one waited for everyone else's work a dozen
6: //! times over. Instead each result stages the buffers it needs, one
7: //! [`Readback`] brings them all back, and each result parses its own slice.
8: 
9: use fabelgeist_compute::Readback;
10: use fabelgeist_gpu::prelude::Buffer;
11: 
12: use super::ArmorGpu;
13: use crate::GenerateError;
14: 
15: /// Buffers waiting to be read back together.
16: #[derive(Default)]
17: pub struct Staging<'a> {
18:     buffers: Vec<&'a Buffer>,
19: }
20: 
21: /// Where one staged buffer's bytes will be.
22: #[derive(Clone, Copy, Debug)]
23: pub struct Staged(usize);
24: 
25: /// The bytes of every staged buffer.
26: pub struct StagedResults {
27:     bytes: Vec<Vec<u8>>,
28: }
29: 
30: impl<'a> Staging<'a> {
31:     pub fn new() -> Self {
32:         Self::default()
33:     }
34: 
35:     pub fn stage(&mut self, buffer: &'a Buffer) -> Staged {
36:         self.buffers.push(buffer);
37:         Staged(self.buffers.len() - 1)
38:     }
39: }
40: 
41: impl StagedResults {
42:     /// A staged buffer's contents as plain values.
43:     pub fn get<T: bytemuck::Pod>(&self, staged: Staged) -> Vec<T> {
44:         bytemuck::pod_collect_to_vec(&self.bytes[staged.0])
45:     }
46: 
47:     /// Typed prefix, excluding storage allocation padding.
48:     pub fn prefix<T: bytemuck::Pod>(&self, staged: Staged, count: usize) -> Vec<T> {
49:         let mut values = self.get(staged);
50:         values.truncate(count);
51:         values
52:     }
53: 
54:     /// The first word of a staged status buffer.
55:     pub fn status(&self, staged: Staged) -> u32 {
56:         self.get::<u32>(staged)[0]
57:     }
58: }
59: 
60: impl ArmorGpu {
61:     /// Read every staged buffer back with one mapping, after everything
62:     /// submitted so far.
63:     pub fn read_staged(&self, staging: Staging) -> Result<StagedResults, GenerateError> {
64:         pollster::block_on(self.read_staged_async(staging))
65:     }
66: 
67:     pub async fn read_staged_async(
68:         &self,
69:         staging: Staging<'_>,
70:     ) -> Result<StagedResults, GenerateError> {
71:         let mut batch = self.batch("armor readback");
72:         let readback = Readback::record(self.context(), &mut batch, &staging.buffers)?;
73:         batch.submit();
74:         let bytes = readback.read(self.context()).await?;
75:         Ok(StagedResults { bytes })
76:     }
77: }

