20: /// Room between overlapping rows of unlaced plates, metres.
21: const UNLACED_ROOM: f32 = 0.0006;
22: /// Room around the cord between overlapping rows, beyond its diameter,
23: /// metres.
24: const LACING_ROOM_MARGIN: f32 = 0.0004;
25: /// The closest rows are squeezed, as a share of the pitch the overlap asks.
26: const LEAST_PITCH: f32 = 0.5;
27: /// How far a plate may reach past its grid's border, as a share of its own
28: /// size, before it is left out.
29: const OVERHANG: f32 = 0.25;
30: /// Even units a plate's corner may pass its reach by, so that a plate
31: /// overhanging exactly as far as it may is kept.
32: const REACH_TOLERANCE: f32 = 1e-3;
