57: /// Every plate of a piece.
58: #[derive(Clone, Debug, Default)]
59: pub(super) struct Layout {
60:     pub tiles: Vec<Tile>,
61:     /// Each grid's rows, from its top down.
62:     pub rows: Vec<Vec<TileRow>>,
63:     /// How far each plate's surface rises per metre down it.
64:     pub slopes: Vec<f32>,
65:     /// The room between overlapping rows, metres.
66:     pub room: f32,
67: }
