69: impl Layout {
70:     pub(super) fn new(
71:         surfaces: &[GridSurface],
72:         plate: &Plate,
73:         lacing_radius: Option<f32>,
74:         max_tiles: usize,
75:     ) -> Result<Self, ConstructionError> {
76:         let room = lacing_radius.map_or(UNLACED_ROOM, |radius| 2.0 * radius + LACING_ROOM_MARGIN);
77:         let mut layout = Self {
78:             room,
79:             ..Self::default()
80:         };
81:         for (grid, surface) in surfaces.iter().enumerate() {
82:             let pitch = layout.lay_grid(grid, surface, plate)?;
83:             layout.slopes.push((plate.thickness + room) / pitch);
84:             if layout.tiles.len() > max_tiles {
85:                 return Err(ConstructionError::TooManyPlates);
86:             }
87:         }
88:         if layout.tiles.is_empty() {
89:             return Err(ConstructionError::NoPlateFits);
90:         }
91:         Ok(layout)
92:     }
93: 
94:     /// The plate's height above the surface at `y` metres up it: its top
95:     /// sits a gauge under the surface, its foot lifted by the slope.
96:     pub(super) fn rise(&self, grid: usize, plate: &Plate, y: f32) -> f32 {
97:         -plate.thickness * 0.5 + (plate.height * 0.5 - y) * self.slopes[grid]
98:     }
99: 
100:     /// Lay one grid's rows; returns the pitch between them.
101:     fn lay_grid(
102:         &mut self,
103:         grid: usize,
104:         surface: &GridSurface,
105:         plate: &Plate,
106:     ) -> Result<f32, ConstructionError> {
107:         let length = surface.length();
108:         if !(length > 0.0 && length.is_finite()) {
109:             return Err(ConstructionError::DegenerateSurface);
110:         }
111:         let height = plate.height;
112:         let most_pitch = height * (1.0 - plate.overlap);
113:         let mut rows = if length > height {
114:             ((length - height) / most_pitch).ceil() as usize + 1
115:         } else {
116:             1
117:         };
118:         // Rows squeezed much closer than the overlap asks would have to tilt
119:         // steeply to clear each other; a row fewer leaves a sliver uncovered
120:         // at the ends instead.
121:         if rows > 1 && (length - height) / ((rows - 1) as f32) < most_pitch * LEAST_PITCH {
122:             rows -= 1;
123:         }
124:         let pitch = if rows > 1 {
125:             (length - height) / (rows - 1) as f32
126:         } else {
127:             most_pitch
128:         };
129:         let mut grid_rows = Vec::with_capacity(rows);
130:         for row in 0..rows {
131:             let from_top = if rows > 1 {
132:                 height * 0.5 + row as f32 * pitch
133:             } else {
134:                 length * 0.5
135:             };
136:             let along = if surface.orientation().downward {
137:                 from_top
138:             } else {
139:                 length - from_top
140:             };
141:             let fraction = surface.row_at(along);
142:             let stagger = if row % 2 == 1 { plate.stagger } else { 0.0 };
143:             let (columns, width) = columns(surface, fraction, plate, stagger);
144:             let bounds = Bounds::new(surface, plate, width);
145:             let mut runs = Vec::new();
146:             let mut run = self.tiles.len()..self.tiles.len();
147:             let mut dropped = false;
148:             for column in columns {
149:                 let center = GridPoint {
150:                     row: fraction,
151:                     column,
152:                 };
153:                 let map = TileMap::walk(surface, center, plate.width, plate.height);
154:                 if let Some(map) = map.filter(|map| bounds.holds(map, plate)) {
155:                     self.tiles.push(Tile { grid, map });
156:                     run.end += 1;
157:                     continue;
158:                 }
159:                 dropped = true;
160:                 if !run.is_empty() {
161:                     runs.push(run);
162:                     run = self.tiles.len()..self.tiles.len();
163:                 }
164:             }
165:             if !run.is_empty() {
166:                 runs.push(run);
167:             }
168:             grid_rows.push(TileRow {
169:                 closed: surface.grid().cyclic && !dropped,
170:                 runs,
171:             });
172:         }
173:         self.rows.push(grid_rows);
174:         Ok(pitch)
175:     }
176: }
