178: /// How far past a grid's borders a plate of one row may reach, in even
179: /// units.
180: struct Bounds {
181:     rows: f32,
182:     columns: Option<f32>,
183:     row_overhang: f32,
184:     column_overhang: f32,
185: }
186: 
187: impl Bounds {
188:     /// Around a row `width` metres across. A grid shorter or narrower than
189:     /// the plate lets it overhang by the difference.
190:     fn new(surface: &GridSurface, plate: &Plate, width: f32) -> Self {
191:         let grid = surface.grid();
192:         let overhang = |size: f32, extent: f32| (OVERHANG * size).max((size - extent) * 0.5);
193:         let spans = (grid.columns - 1) as f32;
194:         Self {
195:             rows: (grid.rows - 1) as f32,
196:             columns: (!grid.cyclic).then_some(spans),
197:             row_overhang: surface.row_at(overhang(plate.height, surface.length()))
198:                 + REACH_TOLERANCE,
199:             column_overhang: overhang(plate.width, width) * spans / width + REACH_TOLERANCE,
200:         }
201:     }
202: 
203:     /// Whether every corner of a plate stays within reach of the grid.
204:     fn holds(&self, map: &TileMap, plate: &Plate) -> bool {
205:         let [x, y] = [plate.width * 0.5, plate.height * 0.5];
206:         [[-x, -y], [x, -y], [x, y], [-x, y]]
207:             .into_iter()
208:             .all(|[across, up]| {
209:                 let GridPoint { row, column } = map.at(across, up);
210:                 (-self.row_overhang..=self.rows + self.row_overhang).contains(&row)
211:                     && self.columns.is_none_or(|columns| {
212:                         (-self.column_overhang..=columns + self.column_overhang).contains(&column)
213:                     })
214:             })
215:     }
216: }
