65: /// Small plates laid in overlapping rows over a piece's surface.
66: #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
67: #[serde(deny_unknown_fields)]
68: pub struct Tiling {
69:     pub plate: Plate,
70:     /// Cord through the plates' holes; `None` leaves them unlaced.
71:     pub lacing: Option<Lacing>,
72: }
73: 
74: impl Tiling {
75:     /// Narrow, tall lames with three pairs of holes, laced in red silk.
76:     pub fn lamellar() -> Self {
77:         Self {
78:             plate: Plate {
79:                 width: 0.028,
80:                 height: 0.085,
81:                 thickness: 0.0015,
82:                 roundness: 0.25,
83:                 bevel: 0.0004,
84:                 gap: 0.001,
85:                 overlap: 0.2,
86:                 stagger: 0.0,
87:                 hole_radius: 0.0022,
88:                 hole_pairs: 3,
89:             },
90:             lacing: Some(Lacing {
91:                 radius: 0.0014,
92:                 color: [0.55, 0.09, 0.07],
93:                 roughness: 0.6,
94:             }),
95:         }
96:     }
97: 
98:     /// Round-bottomed scales in staggered rows, laced in leather through one
99:     /// pair of holes at the top.
100:     pub fn scale() -> Self {
101:         Self {
102:             plate: Plate {
103:                 width: 0.045,
104:                 height: 0.065,
105:                 thickness: 0.0015,
106:                 roundness: 1.0,
107:                 bevel: 0.0004,
108:                 gap: 0.0015,
109:                 overlap: 0.3,
110:                 stagger: 0.5,
111:                 hole_radius: 0.0025,
112:                 hole_pairs: 1,
113:             },
114:             lacing: Some(Lacing::default()),
115:         }
116:     }
117: 
118:     pub fn validate(&self) -> Result<(), ConstructionError> {
119:         self.plate.validate()?;
120:         let Some(lacing) = &self.lacing else {
121:             return Ok(());
122:         };
123:         lacing.validate()?;
124:         if self.plate.hole_pairs == 0 || lacing.radius > Lacing::max_radius(&self.plate) {
125:             return Err(ConstructionError::LacingHoles);
126:         }
127:         Ok(())
128:     }
129: }
