131: /// One small plate: its outline, gauge, spacing and lacing holes. Lengths
132: /// are metres.
133: #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
134: #[serde(deny_unknown_fields)]
135: pub struct Plate {
136:     /// Across the row.
137:     pub width: f32,
138:     /// Along the piece, from the row above to the row below.
139:     pub height: f32,
140:     pub thickness: f32,
141:     /// Rounding of the lower corners, as a fraction of the largest radius
142:     /// the plate takes.
143:     pub roundness: f32,
144:     /// Rounding of the front edge.
145:     pub bevel: f32,
146:     /// Space between neighbouring plates of a row.
147:     pub gap: f32,
148:     /// Fraction of a plate's height the row above covers.
149:     pub overlap: f32,
150:     /// Shift of every other row, as a fraction of the plate pitch.
151:     pub stagger: f32,
152:     pub hole_radius: f32,
153:     /// Pairs of lacing holes, one pair per row of holes from the top.
154:     pub hole_pairs: u32,
155: }
156: 
157: impl Plate {
158:     pub const WIDTH: RangeInclusive<f32> = 0.012..=0.15;
159:     pub const HEIGHT: RangeInclusive<f32> = 0.02..=0.2;
160:     pub const THICKNESS: RangeInclusive<f32> = 0.0005..=0.012;
161:     pub const GAP: RangeInclusive<f32> = 0.0..=0.005;
162:     pub const OVERLAP: RangeInclusive<f32> = 0.0..=0.6;
163:     pub const HOLE_RADIUS: RangeInclusive<f32> = 0.0..=0.006;
164:     pub const MAX_HOLE_PAIRS: u32 = 3;
165:     /// The deepest a bevel cuts, as a fraction of the plate's thickness.
166:     pub const MAX_BEVEL: f32 = 0.45;
167:     /// The share of a plate's narrower side a trim band may cover.
168:     const TRIM_SHARE: f32 = 0.15;
169:     /// Holes stay this many radii clear of each other and the plate's edge.
170:     const HOLE_CLEARANCE_RADII: f32 = 5.0;
171:     /// Each hole's distance from the plate's centre line, as a fraction of
172:     /// its width.
173:     const HOLE_INSET: f32 = 0.27;
174:     /// Radii from the top edge to the first row of holes' centres.
175:     const FIRST_HOLE_RADII: f32 = 2.2;
176:     /// The height the rows of holes are spread over, as a fraction of the
177:     /// plate's; one row for each of the most pairs a plate has.
178:     const HOLE_ROW_SPAN: f32 = 0.55;
179: 
180:     pub fn validate(&self) -> Result<(), ConstructionError> {
181:         let within =
182:             |value: f32, range: RangeInclusive<f32>| value.is_finite() && range.contains(&value);
183:         if !within(self.width, Self::WIDTH)
184:             || !within(self.height, Self::HEIGHT)
185:             || !within(self.thickness, Self::THICKNESS)
186:             || !within(self.roundness, 0.0..=1.0)
187:             || !within(self.bevel, 0.0..=self.thickness * Self::MAX_BEVEL)
188:             || !within(self.gap, Self::GAP)
189:             || !within(self.overlap, Self::OVERLAP)
190:             || !within(self.stagger, 0.0..=1.0)
191:         {
192:             return Err(ConstructionError::PlateDimensions);
193:         }
194:         if !within(self.hole_radius, Self::HOLE_RADIUS)
195:             || self.hole_pairs > Self::MAX_HOLE_PAIRS
196:             || self.hole_radius > self.max_hole_radius()
197:         {
198:             return Err(ConstructionError::HoleSpacing);
199:         }
200:         Ok(())
201:     }
202: 
203:     /// The widest trim band along the plate's rim.
204:     pub fn widest_trim(&self) -> f32 {
205:         (self.width.min(self.height) * Self::TRIM_SHARE).max(Trim::MIN_WIDTH)
206:     }
