1: //! The outer face of a plate as rows along it and columns across it.
2: 
3: /// The outer face of one plate, as the grid its carrier was laid out on:
4: /// `rows` rows along the plate, each `columns` vertices across it, closed
5: /// around when `cyclic`. A construction laid over the plate, such as scales,
6: /// is placed in the grid's own coordinates, so it follows the plate through
7: /// every body morph.
8: #[derive(Clone, Debug, PartialEq)]
9: pub struct SurfaceGrid {
10:     pub rows: u32,
11:     pub columns: u32,
12:     pub cyclic: bool,
13:     /// The piece's vertex at each row and column, row by row.
14:     pub vertices: Vec<u32>,
15:     /// Every exported outer vertex, including cuts and shading aliases.
16:     pub samples: Vec<SurfaceSample>,
17: }
18: 
19: #[derive(Clone, Copy, Debug, PartialEq)]
20: pub struct SurfaceSample {
21:     pub vertex: u32,
22:     pub column: SurfaceColumn,
23:     /// Unclamped correspondence in the original carrier's columns. Physical
24:     /// cut endpoints can extend beyond the retained construction rails.
25:     pub carrier_column: SurfaceColumn,
26:     /// Signed inward distance from the first and last construction edges.
27:     pub edge_distances: [SurfaceEdgeDistance; 2],
28: }
29: 
30: /// A regular rail or an authored physical course cut defines the seam.
31: #[derive(Clone, Copy, Debug, PartialEq)]
32: pub enum SurfaceEdgeDistance {
33:     Rail,
34:     /// Perpendicular distance from the inner carrier's cut plane, in metres.
35:     /// Both physical walls retain the same material coordinate.
36:     Cut {
37:         metres: f32,
38:     },
39: }
40: 
41: impl SurfaceSample {
42:     pub fn edge_distance(&self, end: crate::PlateGridEnd) -> SurfaceEdgeDistance {
43:         self.edge_distances[match end {
44:             crate::PlateGridEnd::First => 0,
45:             crate::PlateGridEnd::Last => 1,
46:         }]
47:     }
48: }
49: 
50: /// A continuous column coordinate in the plate's construction grid.
51: #[derive(Clone, Copy, Debug, PartialEq)]
52: pub struct SurfaceColumn(f32);
53: 
54: impl SurfaceColumn {
55:     pub fn at(column: u32) -> Self {
56:         Self(column as f32)
57:     }
58:     pub fn between(a: Self, b: Self, blend: f32) -> Self {
59:         Self(a.0 + blend * (b.0 - a.0))
60:     }
61:     pub fn distance(self, other: Self) -> f32 {
62:         (self.0 - other.0).abs()
63:     }
64:     pub fn total_cmp(self, other: Self) -> std::cmp::Ordering {
65:         self.0.total_cmp(&other.0)
66:     }
67:     pub fn bracket(self, columns: u32) -> Option<(u32, u32, f32)> {
68:         if columns == 0 || !self.0.is_finite() || self.0 < 0.0 || self.0 > (columns - 1) as f32 {
69:             return None;
70:         }
71:         let first = self.0.floor() as u32;
72:         Some((first, (first + 1).min(columns - 1), self.0 - first as f32))
73:     }
74: }
75: 
76: impl SurfaceGrid {
77:     pub fn regular(rows: u32, columns: u32, cyclic: bool, vertices: Vec<u32>) -> Self {
78:         let samples = vertices
79:             .iter()
80:             .enumerate()
81:             .map(|(i, &vertex)| SurfaceSample {
82:                 vertex,
83:                 column: SurfaceColumn::at(i as u32 % columns),
84:                 carrier_column: SurfaceColumn::at(i as u32 % columns),
85:                 edge_distances: [SurfaceEdgeDistance::Rail; 2],
86:             })
87:             .collect();
88:         Self {
89:             rows,
90:             columns,
91:             cyclic,
92:             vertices,
93:             samples,
94:         }
95:     }
96:     pub fn remap_vertices(&mut self, mut remap: impl FnMut(u32) -> u32) {
97:         for vertex in &mut self.vertices {
98:             *vertex = remap(*vertex);
99:         }
100:         for sample in &mut self.samples {
101:             sample.vertex = remap(sample.vertex);
102:         }
103:     }
104:     /// The piece's vertex at `row` and `column`.
105:     pub fn vertex(&self, row: u32, column: u32) -> u32 {
106:         self.vertices[(row * self.columns + column) as usize]
107:     }
108: }

