2: use super::topology::{MidTopology, SolidTopology};
3: use crate::{PlateFace, SurfaceEdgeDistance, SurfaceGrid, SurfaceSample};
4: 
5: impl SolidTopology {
6:     pub(super) fn install_grid(
7:         &mut self,
8:         mid: &MidTopology,
9:         outer: &MidTopology,
10:         boundaries: &[[u32; 2]],
11:     ) {
12:         let count = mid.vertex_count() as u32;
13:         let course = mid
14:             .course_coordinates
15:             .as_ref()
16:             .map(|course| course.on_boundaries(boundaries));
17:         let active = self
18:             .indices
19:             .as_chunks::<3>()
20:             .0
21:             .iter()
22:             .zip(&self.faces)
23:             .filter(|(_, face)| **face == PlateFace::Outer)
24:             .flat_map(|(face, _)| face.iter().copied())
25:             .collect::<std::collections::BTreeSet<_>>();
26:         self.grids.push(SurfaceGrid {
27:             rows: mid.rows as u32,
28:             columns: outer.construction_columns.width() as u32,
29:             cyclic: false,
30:             vertices: outer
31:                 .grid_vertices
32:                 .clone()
33:                 .unwrap_or_else(|| mid.rows_downward().collect())
34:                 .into_iter()
35:                 .map(|vertex| vertex + count)
36:                 .collect(),
37:             samples: active
38:                 .into_iter()
39:                 .map(|vertex| SurfaceSample {
40:                     vertex,
41:                     carrier_column: mid.surface_column(self.mid_of(vertex)),
42:                     column: outer
43:                         .construction_columns
44:                         .column(mid.surface_column(self.mid_of(vertex)), mid.width()),
45:                     edge_distances: course
46:                         .as_ref()
47:                         .map_or([SurfaceEdgeDistance::Rail; 2], |course| {
48:                             course.edge_distances(self.mid_of(vertex))
49:                         }),
50:                 })
51:                 .collect(),
52:         });
53:     }
54: }

