1: //! A band finished apart from the rest of the plate along its edges.
2: //!
3: //! The band has its own [`Metal`], so an edge can be gilded, blued or left
4: //! bright on a darker plate, and the metal's engraving is the ornament that
5: //! runs along it. The ornament repeats once per engraving cell along the edge,
6: //! starting at the edge itself.
7: use crate::engraving::Engraving;
8: use crate::material::Metal;
9: use serde::{Deserialize, Serialize};
10: 
11: #[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
12: pub struct Trim {
13:     /// How far the band reaches in from the edge, metres.
14:     pub width: f32,
15:     pub metal: Metal,
16: }
17: 
18: impl Default for Trim {
19:     /// A gilt band two centimetres wide.
20:     fn default() -> Self {
21:         Self {
22:             width: 0.02,
23:             metal: Metal {
24:                 color: [1.0, 0.77, 0.34],
25:                 roughness: 0.25,
26:                 scratch_density: 0,
27:                 ..Metal::default()
28:             },
29:         }
30:     }
31: }
32: 
33: impl Trim {
34:     pub const MIN_WIDTH: f32 = 0.003;
35:     pub const MAX_WIDTH: f32 = 0.06;
36: 
37:     /// The length along the edge its ornament repeats over, metres: one
38:     /// engraving cell, or one metal tile without an engraving.
39:     pub fn period(&self) -> f32 {
40:         1.0 / (Metal::TILES_PER_METRE * self.tiles())
41:     }
42: 
43:     /// Where an engraving cell begins, in metal tiles: the engraving repeats
44:     /// about the tile's centre, so the band's coordinates start here to put
45:     /// the top of the image on the edge.
46:     pub fn cell_origin(&self) -> f32 {
47:         0.5 - 0.5 / self.tiles()
48:     }
49: 
50:     /// Engraving repeats per metal tile that make one cell as long as the
51:     /// band is wide, within the engraving's range.
52:     pub fn cell_tiles(&self) -> f32 {
53:         (1.0 / (Metal::TILES_PER_METRE * self.width))
54:             .clamp(Engraving::MIN_TILES, Engraving::MAX_TILES)
55:     }
56: 
57:     /// The same finish on a band `width` wide, its ornament shrunk in
58:     /// proportion so that it still spans the band.
59:     pub fn narrowed(&self, width: f32) -> Self {
60:         let mut narrowed = self.clone();
61:         if width < self.width {
62:             let scale = self.width / width;
63:             if let Some(engraving) = &mut narrowed.metal.engraving {
64:                 engraving.tiles =
65:                     (engraving.tiles * scale).clamp(Engraving::MIN_TILES, Engraving::MAX_TILES);
66:             }
67:             narrowed.width = width;
68:         }
69:         narrowed
70:     }
71: 
72:     fn tiles(&self) -> f32 {
73:         self.metal.engraving.as_ref().map_or(1.0, |e| e.tiles)
74:     }
75: 
76:     pub fn validate(&self) -> Result<(), String> {
77:         if !self.width.is_finite() || !(Self::MIN_WIDTH..=Self::MAX_WIDTH).contains(&self.width) {
78:             return Err("Invalid trim width".into());
79:         }
80:         self.metal.validate()
81:     }
82: }
