1: //! The template every lamellar or scale plate is placed from: its outline
2: //! extruded to its gauge, its front edge bevelled and its lacing holes
3: //! pierced through it.
4: //!
5: //! The front and back faces are triangulated with their outline and holes
6: //! as constraints, and the walls are built along the same boundary points,
7: //! so the plate is closed without any cut splitting its faces. Each wall
8: //! facet keeps its own flat normal.
9: //!
10: //! The template lies in the plate's own frame: `x` across the row, `y` up
11: //! towards the row above, `z` out of the piece, centred on its middle.
12: 
13: use spade::{ConstrainedDelaunayTriangulation, Point2, Triangulation};
14: 
15: use crate::{Plate, PlateFace};
16: 
17: /// Sides of the polygon a lacing hole is cut as.
18: const HOLE_SIDES: usize = 12;
19: /// Spacing of the points seeded inside each face, as a share of the plate's
20: /// narrower side. The faces bend with the surface between them, and a trim
21: /// band finds its inner border across them.
22: const INTERIOR_SPACING: f32 = 0.125;
23: /// Seeded points keep this share of their spacing clear of every boundary,
24: /// so no sliver forms against it.
25: const INTERIOR_CLEARANCE: f32 = 0.4;
26: 
27: /// One corner of the template.
28: #[derive(Clone, Copy, Debug, PartialEq)]
29: pub(super) struct TemplateVertex {
30:     pub position: [f32; 3],
31:     /// In the plate's frame; flat across each wall facet.
32:     pub normal: [f32; 3],
33:     /// Metres across the face it lies on.
34:     pub texcoord: [f32; 2],
35: }
36: 
37: /// The plate as an indexed mesh.
38: #[derive(Clone, Debug, Default)]
39: pub(super) struct TileTemplate {
40:     pub vertices: Vec<TemplateVertex>,
41:     pub triangles: Vec<[u32; 3]>,
42:     /// The plate face of each triangle.
43:     pub faces: Vec<PlateFace>,
44: }
45: 
46: impl TileTemplate {
47:     /// `None` when a hole reaches the plate's outline.
48:     pub(super) fn new(plate: &Plate) -> Option<Self> {
49:         let outline = crate::pattern::plate_outline(plate);
50:         let holes = plate
51:             .holes()
52:             .into_iter()
53:             .map(|center| circle(center, plate.hole_radius))
54:             .collect::<Vec<_>>();
55:         let [front, back] = [0.5, -0.5].map(|side| plate.thickness * side);
56:         let rim = front - plate.bevel;
57:         let cap = if plate.bevel > 0.0 {
58:             let scale = 1.0 - plate.bevel * 2.0 / plate.width.min(plate.height);
59:             outline.iter().map(|p| p.map(|x| x * scale)).collect()
60:         } else {
61:             outline.clone()
62:         };
63:         let mut template = Self::default();
64:         let spacing = plate.width.min(plate.height) * INTERIOR_SPACING;
65:         template.face(&cap, &holes, front, PlateFace::Outer, spacing)?;
66:         template.face(&outline, &holes, back, PlateFace::Inner, spacing)?;
67:         for (a, b) in edges(&outline) {
68:             template.quad([(a, back), (b, back), (b, rim), (a, rim)]);
69:         }
70:         if plate.bevel > 0.0 {
71:             for ((a, b), (c, d)) in edges(&outline).zip(edges(&cap)) {
72:                 template.quad([(a, rim), (b, rim), (d, front), (c, front)]);
73:             }
74:         }
75:         for hole in &holes {
76:             // The material lies outside the hole, so its wall faces inward.
77:             for (a, b) in edges(hole) {
78:                 template.quad([(b, back), (a, back), (a, front), (b, front)]);
79:             }
80:         }
81:         Some(template)
82:     }
