84:     fn push(&mut self, position: [f32; 3], normal: [f32; 3]) -> u32 {
85:         let texcoord = if normal[2].abs() > normal[0].abs().max(normal[1].abs()) {
86:             [position[0], position[1]]
87:         } else if normal[0].abs() > normal[1].abs() {
88:             [position[1], position[2]]
89:         } else {
90:             [position[0], position[2]]
91:         };
92:         self.vertices.push(TemplateVertex {
93:             position,
94:             normal,
95:             texcoord,
96:         });
97:         self.vertices.len() as u32 - 1
98:     }
99: 
100:     /// A flat face at height `z` inside `outline` and outside `holes`, facing
101:     /// out of the plate, with points seeded `spacing` apart inside it. `None`
102:     /// when the holes cross the outline.
103:     fn face(
104:         &mut self,
105:         outline: &[[f32; 2]],
106:         holes: &[Vec<[f32; 2]>],
107:         z: f32,
108:         face: PlateFace,
109:         spacing: f32,
110:     ) -> Option<()> {
111:         let mut points = Vec::new();
112:         let mut constraints = Vec::new();
113:         for ring in std::iter::once(outline).chain(holes.iter().map(Vec::as_slice)) {
114:             let first = points.len();
115:             points.extend(
116:                 ring.iter()
117:                     .map(|p| Point2::new(f64::from(p[0]), f64::from(p[1]))),
118:             );
119:             constraints.extend((0..ring.len()).map(|i| [first + i, first + (i + 1) % ring.len()]));
120:         }
121:         points.extend(
122:             interior(outline, holes, spacing).map(|[x, y]| Point2::new(f64::from(x), f64::from(y))),
123:         );
124:         let cdt =
125:             ConstrainedDelaunayTriangulation::<Point2<f64>>::bulk_load_cdt(points, constraints)
126:                 .ok()?;
127:         let up = face == PlateFace::Outer;
128:         let normal = [0.0, 0.0, if up { 1.0 } else { -1.0 }];
129:         let first = self.vertices.len() as u32;
130:         for vertex in cdt.vertices() {
131:             let p = vertex.position();
132:             self.push([p.x as f32, p.y as f32, z], normal);
133:         }
134:         for triangle in cdt.inner_faces() {
135:             let corners = triangle.vertices();
136:             let [a, b, c] = corners.map(|v| v.position());
137:             let centroid = [(a.x + b.x + c.x) / 3.0, (a.y + b.y + c.y) / 3.0].map(|x| x as f32);
138:             if !inside(outline, centroid) || holes.iter().any(|hole| inside(hole, centroid)) {
139:                 continue;
140:             }
141:             // Faces come counterclockwise, seen from the front.
142:             let [a, b, c] = corners.map(|v| first + v.fix().index() as u32);
143:             self.triangles.push(if up { [a, b, c] } else { [a, c, b] });
144:             self.faces.push(face);
145:         }
146:         Some(())
147:     }
148: 
149:     /// A flat wall facet through boundary points at heights, counterclockwise
150:     /// seen from outside the plate.
151:     fn quad(&mut self, corners: [([f32; 2], f32); 4]) {
152:         let points = corners.map(|([x, y], z)| [x, y, z]);
153:         let [a, b, c] = [points[0], points[1], points[3]];
154:         let u = std::array::from_fn::<f32, 3, _>(|k| b[k] - a[k]);
155:         let v = std::array::from_fn::<f32, 3, _>(|k| c[k] - a[k]);
156:         let n = [
157:             u[1] * v[2] - u[2] * v[1],
158:             u[2] * v[0] - u[0] * v[2],
159:             u[0] * v[1] - u[1] * v[0],
160:         ];
161:         let length = n.iter().map(|x| x * x).sum::<f32>().sqrt();
162:         if length.is_nan() || length <= 0.0 {
