198: fn distance_to_segment(p: [f32; 2], a: [f32; 2], b: [f32; 2]) -> f32 {
199:     let ab = [b[0] - a[0], b[1] - a[1]];
200:     let length = ab[0] * ab[0] + ab[1] * ab[1];
201:     let t = if length > 0.0 {
202:         (((p[0] - a[0]) * ab[0] + (p[1] - a[1]) * ab[1]) / length).clamp(0.0, 1.0)
203:     } else {
204:         0.0
205:     };
206:     let d = [p[0] - a[0] - ab[0] * t, p[1] - a[1] - ab[1] * t];
207:     (d[0] * d[0] + d[1] * d[1]).sqrt()
