107:     async fn query_response(&self, sql: &str) -> Result<QueryResponse> {
108:         self.metrics.requests.fetch_add(1, Ordering::Relaxed);
109:         let url = format!("{}/v1/database/{}/sql", self.base_url, self.database);
110:         let mut request = self.http.post(&url).body(sql.to_owned());
111:         if let Some(token) = &self.token {
112:             request = request.header("Authorization", format!("Bearer {token}"));
113:         }
114: 
115:         let started = Instant::now();
116:         let response = request.send().await;
117:         let elapsed = started.elapsed();
118:         self.metrics
119:             .elapsed_micros
120:             .fetch_add(elapsed.as_micros() as u64, Ordering::Relaxed);
121:         if elapsed >= Duration::from_millis(250) {
122:             tracing::warn!(?elapsed, query = %sql, "slow SpacetimeDB query");
123:         }
124:         let response = response?;
125:         if !response.status().is_success() {
126:             let error_text = response.text().await.unwrap_or_default();
127:             return Err(SpacetimeError::Spacetime(error_text));
128:         }
129: 
130:         let text = response.text().await?;
131:         serde_json::from_str(&text).map_err(Into::into)
132:     }
