154: struct ParsedDialogueSessionId<'a> {
155:     owner_character_id: u64,
156:     nonce: &'a str,
157: }
158: 
159: impl<'a> ParsedDialogueSessionId<'a> {
160:     fn parse(value: &'a str) -> Result<Self, String> {
161:         if value.len() > 160 || value.chars().any(char::is_control) {
162:             return Err("Invalid dialogue session ID".into());
163:         }
164:         let mut parts = value.splitn(3, ':');
165:         let domain = parts.next();
166:         let owner_character_id = parts.next().and_then(|part| part.parse::<u64>().ok());
167:         let nonce = parts.next().filter(|part| !part.is_empty());
168:         match (domain, owner_character_id, nonce) {
169:             (Some("dialogue"), Some(owner_character_id), Some(nonce)) => Ok(Self {
170:                 owner_character_id,
171:                 nonce,
172:             }),
173:             _ => Err("Invalid dialogue session ID".into()),
174:         }
175:     }
176: }
