1764: fn transfer_personal_currency_to_party(
1765:     ctx: &ReducerContext,
1766:     character_id: u64,
1767:     party_id: &str,
1768:     amount: u64,
1769: ) -> Result<(), String> {
1770:     let mut stacks: Vec<_> = ctx
1771:         .db
1772:         .inventory_item()
1773:         .character_id()
1774:         .filter(character_id)
1775:         .filter(|stack| crate::item::is_currency(ctx, &stack.item_id))
1776:         .collect();
1777:     if stacks.iter().map(|s| u64::from(s.quantity)).sum::<u64>() < amount {
1778:         return Err("Not enough personal coin".into());
1779:     }
1780:     stacks.sort_by(|a, b| (&a.item_id, a.id).cmp(&(&b.item_id, b.id)));
1781:     let mut remaining = amount;
1782:     for mut stack in stacks {
1783:         let taken = remaining.min(u64::from(stack.quantity)) as u32;
1784:         add_to_party_inventory(ctx, party_id, &stack.item_id, taken);
1785:         stack.quantity -= taken;
1786:         remaining -= u64::from(taken);
1787:         if stack.quantity == 0 {
1788:             ctx.db.inventory_item().id().delete(stack.id);
1789:         } else {
1790:             ctx.db.inventory_item().id().update(stack);
1791:         }
1792:         if remaining == 0 {
1793:             break;
1794:         }
1795:     }
1796:     Ok(())
1797: }
