1033:     stored_effective_hours: &mut f32,
1034:     real_hours: f32,
1035:     aptitude: f32,
1036: ) -> TrainingGain {
1037:     if !real_hours.is_finite() || real_hours <= 0.0 {
1038:         return TrainingGain::default();
1039:     }
1040:     let aptitude = if aptitude.is_finite() {
1041:         aptitude.clamp(0.0, MAX_CHECK)
1042:     } else {
1043:         0.0
1044:     };
1045:     let gain = real_hours * aptitude_training_multiplier(aptitude);
1046:     let current = if stored_effective_hours.is_finite() {
1047:         (*stored_effective_hours).max(0.0)
1048:     } else {
1049:         0.0
1050:     };
1051:     let accepted = gain.min((aptitude * 1_000.0 - current).max(0.0));
1052:     *stored_effective_hours = current + accepted;
1053:     TrainingGain {
1054:         accepted_effective_hours: accepted,
1055:         excess_effective_hours: gain - accepted,
1056:     }
1057: }
