470:     }
471:     let father = father_of_at(ctx, partner_id, minute)
472:         .map_err(|detail| {
473:             CourtshipPairError::rejected(CourtshipRejectionCode::FatherApproval, detail)
474:                 .into_reducer_error()
475:         })?
476:         .ok_or_else(|| {
477:             CourtshipPairError::rejected(
478:                 CourtshipRejectionCode::FatherApproval,
479:                 "Formal courtship requires a known living father",
