1: //! Door approaches stop inside the owned plot or its near half of the street.
2: use super::*;
3: mod surface;
4: use super::super::access::{access_regions, available_run};
5: 
6: pub(super) fn prepare(
7:     request: &SingleBuildingSupportRequest<'_>,
8:     door: DoorwaySupportBinding,
9:     surface: &PropertySupportSurface,
10: ) -> Result<PreparedApron, SupportDiagnostic> {
11:     let reject = |constraint, point, measured, permitted| {
12:         surface.rejection(
13:             constraint,
14:             SupportBoundary::StreetLanding,
15:             point,
16:             measured,
17:             permitted,
18:         )
19:     };
20:     if !door.outward.vector().is_finite()
21:         || (door.outward.vector().length_squared() - 1.0).abs()
22:             > surface.limits.contact_tolerance_metres.metres()
23:     {
24:         return Err(reject(
25:             SupportConstraint::ThresholdBinding,
26:             door.threshold_metres.metres(),
27:             1.0,
28:             0.0,
29:         ));
30:     }
31:     let direction = door.outward.vector();
32:     let tangent = Vec2::new(direction.y, -direction.x);
33:     let outside = planar::distance_outside(
34:         door.threshold_metres.metres().as_dvec2(),
35:         &surface.clipping_outlines[0],
36:     ) as f32;
37:     if outside > surface.limits.contact_tolerance_metres.metres() {
38:         return Err(reject(
39:             SupportConstraint::ThresholdBearing,
40:             door.threshold_metres.metres(),
41:             outside,
42:             surface.limits.contact_tolerance_metres.metres(),
43:         ));
44:     }
45:     let edge = door.threshold_metres.metres();
46:     let width = request.policy.doorway_apron.dimensions_metres().x;
47:     let offset = tangent * width * 0.5;
48:     let private = vec![
49:         request.property.plot.corners().map(Vec2::as_dvec2).to_vec(),
50:         surface.clipping_outlines[0].clone(),
51:     ];
52:     let mut regions =
53:         access_regions(request.property.plot, request.streets, edge).map_err(|cause| {
54:             let mut error = surface.rejection(
55:                 SupportConstraint::Reservation,
56:                 SupportBoundary::FrontBearing,
57:                 edge,
58:                 1.0,
59:                 0.0,
60:             );
61:             error.construction_failure =
62:                 Some(Box::new(SupportConstructionError::FramedGeometry(cause)));
63:             error
64:         })?;
65:     regions.push(surface.clipping_outlines[0].clone());
66:     let internal_run = available_run(
67:         edge,
68:         direction,
69:         offset,
70:         &private,
71:         f32::INFINITY,
72:         request.policy.limits.contact_tolerance_metres(),
73:     );
74:     let run = available_run(
75:         edge,
76:         direction,
77:         offset,
78:         &regions,
79:         internal_run + request.policy.doorway_apron.dimensions_metres().y,
80:         request.policy.limits.contact_tolerance_metres(),
81:     );
82:     // Keep a contact-sized natural strip at the approach boundary. Opposing
83:     // approaches must not acquire the same street support through f32 rounding.
84:     let run = (run - request.policy.limits.contact_tolerance_metres()).max(0.0);
85:     let landing = request
86:         .policy
87:         .stairs
88:         .minimum_floor_landing_run_metres
89:         .metres();
90:     if run <= landing {
91:         let mut error = reject(SupportConstraint::StairClearance, edge, run, landing);
92:         error.violation = error.violation.with_bound(SupportBound::Minimum);
93:         return Err(error);
94:     }
95:     let outer = edge + direction * run;
96:     let points = [outer - offset, outer + offset, edge + offset, edge - offset];
97:     let source = source_pair(request, surface, [points[0], points[1]])?;
98:     Ok(PreparedApron {
99:         outer,
100:         direction,
101:         offset,
102:         run,
103:         landing,
104:         source,
105:         edge,
106:     })
107: }
