120: /// Independent lower and upper floor constraints. A crossed pair represents
121: /// infeasibility and is diagnosed by floor selection, never silently reordered.
122: pub(super) struct FloorConstraints {
123:     pub minimum: SupportElevation,
124:     pub maximum: SupportElevation,
125: }
126: 
127: impl PreparedApron {
128:     pub fn floor_interval(&self, policy: SinglePropertyGradingPolicy) -> FloorConstraints {
129:         let available = self.run - self.landing;
130:         let width = self.offset.length() * 2.0;
131:         let across = (self.source[0] - self.source[1]).abs() / width;
132:         let ramp = available
133:             * (policy.limits.maximum_grade.ratio().powi(2) - across.powi(2))
134:                 .max(0.0)
135:                 .sqrt();
136:         let steps = (available / policy.stairs.minimum_going_metres.metres()).floor()
137:             * policy.stairs.maximum_riser_metres.metres();
138:         let rise = if across <= policy.limits.maximum_grade.ratio() {
139:             ramp.max(steps)
140:         } else {
141:             0.0
142:         };
143:         FloorConstraints {
144:             minimum: SupportElevation(
145:                 self.source.into_iter().fold(f32::NEG_INFINITY, f32::max) - rise,
146:             ),
147:             maximum: SupportElevation(self.source.into_iter().fold(f32::INFINITY, f32::min) + rise),
148:         }
149:     }
