12:     doors: &[&DoorwaySupportBinding],
13:     aprons: &[apron::PreparedApron],
14:     owner: &PropertySupportSurface,
15: ) -> Result<SelectedFloor, SupportDiagnostic> {
16:     if doors.is_empty() {
17:         return Err(owner.rejection(
18:             SupportConstraint::ThresholdBinding,
19:             SupportBoundary::FrontBearing,
20:             request.bearing.centre_metres(),
21:             1.0,
22:             0.0,
23:         ));
24:     }
25:     let controls = request
26:         .geographic
27:         .height_range_in_outline(request.bearing_region.outline())
28:         .ok_or_else(|| {
29:             owner.rejection(
30:                 SupportConstraint::SourceSample,
31:                 SupportBoundary::GeographicSurface,
32:                 request.bearing.centre_metres(),
33:                 1.0,
34:                 0.0,
35:             )
36:         })?;
37:     let permitted = request.policy.limits.maximum_displacement_metres.metres();
38:     let mut lower = controls.maximum.elevation.metres() - permitted;
39:     let mut upper = controls.minimum.elevation.metres() + permitted;
40:     if lower > upper {
41:         return Err(owner.rejection(
42:             SupportConstraint::CutFill,
43:             SupportBoundary::GeographicSurface,
44:             controls.maximum.point.metres(),
45:             (controls.maximum.elevation.metres() - controls.minimum.elevation.metres()) * 0.5,
46:             permitted,
47:         ));
48:     }
49:     for (door, apron) in doors.iter().zip(aprons) {
50:         let constraints = apron.floor_interval(request.policy);
51:         let constrained_lower = lower.max(constraints.minimum.metres());
52:         let constrained_upper = upper.min(constraints.maximum.metres());
53:         if constrained_lower > constrained_upper {
54:             return Err(owner.rejection(
55:                 SupportConstraint::AccessGrade,
56:                 SupportBoundary::StreetLanding,
57:                 door.threshold_metres.metres(),
58:                 constrained_lower - constrained_upper,
59:                 0.0,
60:             ));
61:         }
62:         lower = constrained_lower;
63:         upper = constrained_upper;
64:     }
65:     let observations = doors
66:         .iter()
67:         .map(|entry| {
68:             request
69:                 .geographic
70:                 .elevation_at(entry.threshold_metres)
71:                 .ok_or_else(|| {
72:                     owner.rejection(
73:                         SupportConstraint::SourceSample,
74:                         SupportBoundary::GeographicSurface,
75:                         entry.threshold_metres.metres(),
76:                         1.0,
77:                         0.0,
78:                     )
79:                 })
80:         })
81:         .collect::<Result<Vec<_>, _>>()?;
82:     let preferred = observations
83:         .iter()
84:         .map(|h| f64::from(h.metres()))
85:         .sum::<f64>()
86:         / observations.len() as f64;
87:     let tolerance = request.policy.limits.contact_tolerance_metres.metres();
88:     let elevation = if lower + tolerance <= upper - tolerance {
89:         (preferred as f32).clamp(lower + tolerance, upper - tolerance)
90:     } else {
91:         (lower + upper) * 0.5
92:     };
