1: //! Engineering policy carries checked units independently of terrain samples.
2: use adventuresim_building_generator::spatial_geometry::PositiveLength;
3: use bevy::reflect::Reflect;
4: use serde::{Deserialize, Serialize};
5: 
6: /// Finite positive rise/run bound, independent of metre elevations.
7: /// ```compile_fail
8: /// use adventuresim_tactical_core::city_layout::grounding::SupportGrade;
9: /// use adventuresim_building_generator::spatial_geometry::PositiveLength;
10: /// fn wrong_unit(length: PositiveLength) -> SupportGrade { length }
11: /// ```
12: #[derive(Clone, Copy, Debug, PartialEq, Serialize, Reflect)]
13: #[serde(transparent)]
14: #[reflect(opaque)]
15: pub struct SupportGrade(f32);
16: impl SupportGrade {
17:     pub const fn from_ratio(ratio: f32) -> Option<Self> {
18:         if ratio.is_finite() && ratio > 0.0 {
19:             Some(Self(ratio))
20:         } else {
21:             None
22:         }
23:     }
24:     pub fn ratio(self) -> f32 {
25:         self.0
26:     }
27: }
28: impl<'de> Deserialize<'de> for SupportGrade {
29:     fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
30:         Self::from_ratio(f32::deserialize(d)?)
31:             .ok_or_else(|| serde::de::Error::custom("support grade must be finite and positive"))
32:     }
33: }
34: 
35: /// Construction bounds supplied by generation/capture, not actor movement.
36: #[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize, Reflect)]
37: #[reflect(opaque)]
38: pub struct SupportLimits {
39:     pub(super) maximum_grade: SupportGrade,
40:     pub(super) maximum_displacement_metres: PositiveLength,
41:     pub(super) contact_tolerance_metres: PositiveLength,
42: }
43: impl SupportLimits {
44:     pub const fn new(
45:         maximum_grade: SupportGrade,
46:         maximum_displacement: PositiveLength,
47:         contact_tolerance: PositiveLength,
48:     ) -> Self {
49:         Self {
50:             maximum_grade,
51:             maximum_displacement_metres: maximum_displacement,
52:             contact_tolerance_metres: contact_tolerance,
53:         }
54:     }
55:     pub fn contact_tolerance_metres(self) -> f32 {
56:         self.contact_tolerance_metres.metres()
57:     }
58: }
59: 
60: impl core::fmt::Display for SupportGrade {
61:     fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
62:         self.ratio().fmt(f)
63:     }
64: }

