1: //! Retained single-building reservations supply exact bounded support ownership.
2: use super::*;
3: use crate::city_layout::grounding::*;
4: use bevy::math::Vec3Swizzles;
5: use serde::{Deserialize, Serialize};
6: use std::collections::BTreeMap;
7: mod bearing;
8: 
9: /// A generated home or service property without a separate rear-range member.
10: /// Its complete court and passage reservation survives recipe compilation.
11: #[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
12: pub struct CitySingleProperty {
13:     pub id: CityPropertyId,
14:     pub building_id: crate::scene_input::SceneBuildingId,
15:     pub plot: CityPlotBounds,
16: }
17: 
18: #[derive(Clone, Copy, Debug)]
19: pub struct SinglePropertyGradingPolicy {
20:     pub limits: SupportLimits,
21:     pub stairs: CourtStairLimits,
22:     pub embedment: FoundationEmbedment,
23:     /// Validated clear width and maximum perpendicular doorway approach.
24:     pub doorway_apron: StreetApronDimensions,
25: }
26: 
27: impl CitySceneLayout {
28:     pub fn plan_single_property_support(
29:         &self,
30:         geographic: &GeographicSurface,
31:         policy: SinglePropertyGradingPolicy,
32:     ) -> Result<Vec<SingleBuildingSupportPlan>, CitySupportError> {
33:         self.validate_physical_support_members()?;
34:         let mut recipes = self.support_recipes.clone();
35:         let mut properties: Vec<_> = self.single_properties.iter().collect();
36:         properties.sort_by_key(|property| property.id);
37:         let buildings: BTreeMap<_, _> = self
38:             .playable
39:             .iter()
40:             .cloned()
41:             .chain(
42:                 self.distant
43:                     .iter()
44:                     .copied()
45:                     .map(TacticalBuildingPlacement::from),
46:             )
47:             .map(|b| (b.id, b))
48:             .collect();
49:         properties
50:             .into_iter()
51:             .map(|property| {
52:                 let placement = buildings.get(&property.building_id).ok_or(
53:                     CitySupportError::MissingBuilding {
54:                         property: property.id,
55:                         building: property.building_id,
56:                     },
57:                 )?;
58:                 let recipe = recipes.for_program(&placement.program)?;
59:                 let bearing =
60:                     bearing::SingleBearingProjection::from_recipe(property, placement, &recipe)?;
61:                 let origin = recipe.collision.bounds.centre()?.metres().xz();
62:                 let thresholds: Vec<_> = recipe
63:                     .ground_entrances
64:                     .iter()
65:                     .map(|door| {
66:                         let local = door.threshold_metres.metres() - origin;
67:                         Ok(DoorwaySupportBinding {
68:                             entrance: door.id,
69:                             support: door.support,
70:                             threshold_metres: crate::scene_coordinates::ScenePlanPoint::try_from(placement.centre_metres.metres() + placement.orientation.local_to_world(local))?,
71:                             outward: adventuresim_building_generator::spatial_geometry::PlanDirection::from_normalized(placement.orientation.local_to_world(door.outward.vector()))?,
72:                         })
73:                     })
74:                     .collect::<Result<_, adventuresim_building_generator::spatial_geometry::GeometryError>>()?;
75:                 SingleBuildingSupportRequest {
76:                     property: *property,
77:                     bearing: bearing.bounds,
78:                     bearing_region: bearing.region,
79:                     thresholds: &thresholds,
80:                     geographic,
81:                     streets: &self.streets,
82:                     policy,
83:                 }
84:                 .select()
85:                 .map_err(CitySupportError::Support)
86:             })
87:             .collect()
88:     }
89: }

