1: //! Engineering bounds for production settlement grading, independent of history.
2: use super::*;
3: use crate::city_layout::grounding::SupportGrade;
4: use adventuresim_building_generator::spatial_geometry::PositiveLength;
5: 
6: // Admit authored constants at compile time. An invalid engineering literal is
7: // a build failure, never a runtime fallback or a newly selected terrain policy.
8: const fn positive_metres(value: f32) -> PositiveLength {
9:     match PositiveLength::from_metres(value) {
10:         Ok(length) => length,
11:         Err(_) => panic!("production engineering lengths must be positive"),
12:     }
13: }
14: const SETTLEMENT_LIMITS: SupportLimits = SupportLimits::new(
15:     match SupportGrade::from_ratio(crate::scene::TerrainGradeLimit::PLAYABLE.ratio()) {
16:         Some(grade) => grade,
17:         None => panic!("production support grade must be positive"),
18:     },
19:     positive_metres(6.0),
20:     positive_metres(CityPlotBounds::COORDINATE_TOLERANCE_METRES as f32),
21: );
22: const SETTLEMENT_STAIRS: CourtStairLimits = CourtStairLimits::new(
23:     positive_metres(0.19),
24:     positive_metres(0.25),
25:     positive_metres(1.0),
26:     positive_metres(1.05),
27:     positive_metres(0.5),
28: );
29: const SETTLEMENT_EMBEDMENT: FoundationEmbedment = FoundationEmbedment::new(positive_metres(0.2));
30: const STREET_APPROACH: StreetApronDimensions =
31:     StreetApronDimensions::new(positive_metres(1.0), positive_metres(4.0));
32: 
33: impl CompoundGradingPolicy {
34:     /// Fixed engineering constraints used by generated settlements. Source
35:     /// relief outside each private reservation and bound approach is untouched.
36:     /// These bounds do not certify actor clearance or historical construction.
37:     pub const fn bounded_settlement() -> Self {
38:         Self {
39:             limits: SETTLEMENT_LIMITS,
40:             stairs: SETTLEMENT_STAIRS,
41:             embedment: SETTLEMENT_EMBEDMENT,
42:             street_apron: STREET_APPROACH,
43:         }
44:     }
45: }

