193:     pub async fn call(&self, reducer: &str, args: &[Value]) -> Result<()> {
194:         let url = format!(
195:             "{}/v1/database/{}/call/{}",
196:             self.base_url, self.database, reducer
197:         );
198: 
199:         let mut request = self.http.post(&url).json(args);
200: 
201:         if let Some(token) = &self.token {
202:             request = request.header("Authorization", format!("Bearer {}", token));
203:         }
204: 
205:         let started = Instant::now();
206:         let response = request.send().await;
207:         let elapsed = started.elapsed();
208:         if elapsed >= Duration::from_millis(250) {
209:             tracing::warn!(?elapsed, reducer, "slow SpacetimeDB reducer call");
210:         }
211:         let response = response?;
212: 
213:         if !response.status().is_success() {
214:             let error_text = response.text().await.unwrap_or_default();
215:             return Err(SpacetimeError::Spacetime(error_text));
216:         }
217: 
218:         Ok(())
219:     }

564: macro_rules! reducer_call {
565:     ($runner:expr, $operation:expr, $invoke:expr) => {{
566:         let operation = $operation;
567:         let (tx, rx) = mpsc::sync_channel(1);
568:         ($invoke)(
569:             move |_: &ReducerEventContext,
570:                   result: Result<
571:                 Result<(), String>,
572:                 adventuresim_stdb_client::spacetimedb_sdk::__codegen::InternalError,
573:             >| {
574:                 let normalized = match result {
575:                     Ok(Ok(())) => Ok(()),
576:                     Ok(Err(detail)) => Err(CoreLoopError::reducer_rejected(operation, detail)),
577:                     Err(error) => Err(CoreLoopError::reducer_dispatch(
578:                         operation,
579:                         error.to_string(),
580:                     )),
581:                 };
582:                 let _ = tx.send(normalized);
583:             },
584:         )
585:         .map_or_else(
586:             |error| {
587:                 Err(CoreLoopError::reducer_dispatch(
588:                     operation,
589:                     error.to_string(),
590:                 ))
591:             },
592:             |()| match rx.recv_timeout(ACTION_TIMEOUT) {
593:                 Ok(result) => result,
594:                 Err(_) => Err(CoreLoopError::reducer_timed_out(operation)),
595:             },
596:         )
597:     }};
598: }

