106: pub fn autoresolve_mission(
107:     ctx: &ReducerContext,
108:     character_id: u64,
109:     mission_id: String,
110: ) -> StrategicCombatResult<()> {
111:     require_strategic_character_authority(ctx, character_id)?;
112:     adventuresim_core::mission::MissionId::new(mission_id.clone()).map_err(str::to_string)?;
113:     crate::character::require_living_character(ctx, character_id)?;
114:     let Some(character) = ctx.db.character().id().find(character_id) else {
115:         return Err("Character not found".into());
116:     };
117:     let Some(party_id) = character.party_id else {
118:         return Err("Must be in a party".into());
119:     };
120:     let Some(party) = ctx.db.party_authority().id().find(&party_id) else {
121:         return Err("Party not found".into());
122:     };
123:     if party.leader_id != character_id {
124:         return Err("Only the party leader can autoresolve".into());
125:     }
126:     let case_site = party
127:         .current_case_site_id
128:         .as_ref()
129:         .and_then(|id| ctx.db.case_site_authority().id_key().find(id.to_string()))
130:         .ok_or("Party is not at a case site")?;
131:     if crate::investigation::character_case_site_id(ctx, character_id).as_deref()
