176:     if let Some(resolved) = ctx.db.resolved_party_action().id().find(request_id) {
177:         if resolved.approved_by != leader_id {
178:             return Err("Only the party leader can approve requests".into());
179:         }
180:         return Ok(());
181:     }
182:     let request = ctx
183:         .db
184:         .party_action_request_authority()
