193:         .ok_or("Party not found")?;
194:     if party.leader_id != leader_id {
195:         return Err("Only the party leader can approve requests".into());
196:     }
197:     let action: ApprovedPartyAction = serde_json::from_str(&request.payload)
198:         .map_err(|error| format!("Invalid party action payload: {error}"))?;
199:     if action.kind() != request.action_kind {
200:         return Err("Party action kind does not match its typed payload".into());
201:     }
202:     action.execute(ctx, leader_id, request.requester_id)?;
