17: pub(super) fn movement_intent(
18:     combatant: &Combatant,
19:     distance: f32,
20:     parameters: crate::combat::AutoresolveParameters,
21: ) -> MeleeMovementAction {
22:     let reach = melee_effective_reach(combatant);
23:     let preferred = preferred_melee_measure(combatant, parameters);
24:     let head_length = combatant.equipment.weapon_striking_head_length();
25:     let minimum_working_measure = if head_length > 0.0 {
26:         (reach - head_length).max(0.0)
27:     } else {
28:         preferred
29:     };
30:     if distance < minimum_working_measure
31:         || combatant.equipment.weapon_reach() >= parameters.long_weapon_measure_threshold_metres
32:             && distance < preferred
33:     {
34:         MeleeMovementAction::Retreat
35:     } else if distance > reach
36:         || combatant.melee_attack_started_at_seconds.is_some() && distance >= preferred
37:     {
38:         MeleeMovementAction::Close
39:     } else {
40:         MeleeMovementAction::Hold
41:     }
