55: pub(in crate::autoresolve) fn preview_melee_pair_movement(
56:     first: &Combatant,
57:     second: &Combatant,
58:     elapsed: AnimationElapsed,
59:     parameters: crate::combat::AutoresolveParameters,
60: ) -> SpeedResult<(OpposedMovement, MeleeMovementAction, MeleeMovementAction)> {
61:     let surface = first
62:         .melee_engagement_distance_metres
63:         .min(second.melee_engagement_distance_metres)
64:         .max(0.0);
65:     let first_intent = movement_intent(first, surface, parameters);
66:     let second_intent = movement_intent(second, surface, parameters);
67:     let speed = |combatant: &Combatant| -> SpeedResult<NonnegativeSpeed> {
68:         Ok(combatant
69:             .movement_speed_meters_per_second(parameters.minimum_movement_speed_metres_per_second)?
70:             .min(if combatant.melee_attack_started_at_seconds.is_some() {
71:                 parameters.melee_lunge_speed_metres_per_second
72:             } else {
73:                 parameters.guarded_movement_speed_metres_per_second
74:             })
75:             .into())
76:     };
77:     let acceleration = |combatant: &Combatant| {
78:         ground_drive_acceleration(
79:             parameters.reference_ground_drive_force_newtons,
80:             combatant.attributes.limb_attr_by_weight_by_parts(
81:                 LimbAttribute::Strength,
82:                 &combatant.body,
83:                 LimbWeights::both_legs(),
84:             ),
85:             parameters.reference_leg_strength,
86:             combatant.body.weight_kg,
87:             combatant.equipment.inventory_weight,
88:             parameters.gravity_metres_per_second_squared,
89:             parameters.traction_coefficient,
90:         )
91:     };
92:     let maximum_surface_separation =
93:         maximum_melee_pair_surface_separation(first, second, parameters);
94:     let mut movement = integrate_opposed_movement(
95:         surface + HUMANOID_MELEE_MINIMUM_CENTER_SEPARATION_METRES,
96:         first.melee_separation_velocity_metres_per_second,
97:         first_intent,
98:         speed(first)?,
99:         second.melee_separation_velocity_metres_per_second,
100:         second_intent,
101:         speed(second)?,
102:         acceleration(first),
103:         acceleration(second),
104:         elapsed,
105:         HUMANOID_MELEE_MINIMUM_CENTER_SEPARATION_METRES,
106:         maximum_surface_separation + HUMANOID_MELEE_MINIMUM_CENTER_SEPARATION_METRES,
107:     )?;
108:     movement.distance_before_metres = (movement.distance_before_metres
109:         - HUMANOID_MELEE_MINIMUM_CENTER_SEPARATION_METRES)
110:         .max(0.0);
111:     movement.distance_after_metres =
112:         (movement.distance_after_metres - HUMANOID_MELEE_MINIMUM_CENTER_SEPARATION_METRES).max(0.0);
113:     Ok((movement, first_intent, second_intent))
114: }
