135: pub(in crate::autoresolve) fn advance_melee_pair_movement(
136:     first: &mut Combatant,
137:     second: &mut Combatant,
138:     interval_start: BattleTime,
139:     elapsed: AnimationElapsed,
140:     recorder: &mut BattleRecorder,
141:     parameters: crate::combat::AutoresolveParameters,
142: ) -> BattleResolutionResult<()> {
143:     if elapsed.is_zero() || first.is_defeated() || second.is_defeated() {
144:         return Ok(());
145:     }
146:     let time = interval_start.checked_add(elapsed)?;
147:     if first.melee_engagement_target != Some(second.id)
148:         || second.melee_engagement_target != Some(first.id)
149:     {
150:         let initial_separation = maximum_melee_pair_surface_separation(first, second, parameters);
151:         first.melee_engagement_target = Some(second.id);
152:         second.melee_engagement_target = Some(first.id);
153:         first.melee_engagement_distance_metres = initial_separation;
154:         second.melee_engagement_distance_metres = initial_separation;
155:         first.melee_separation_velocity_metres_per_second = SignedSpeed::ZERO;
156:         second.melee_separation_velocity_metres_per_second = SignedSpeed::ZERO;
157:     }
158:     let (movement, first_intent, second_intent) =
159:         preview_melee_pair_movement(first, second, elapsed, parameters)?;
160:     first.melee_engagement_distance_metres = movement.distance_after_metres;
161:     second.melee_engagement_distance_metres = movement.distance_after_metres;
162:     first.melee_separation_velocity_metres_per_second =
163:         movement.first.velocity_after_metres_per_second;
164:     second.melee_separation_velocity_metres_per_second =
165:         movement.second.velocity_after_metres_per_second;
166:     let (a, a_axis, a_intent, b, b_axis, b_intent) = if first.id <= second.id {
167:         (
168:             &*first,
169:             movement.first,
170:             first_intent,
171:             &*second,
172:             movement.second,
173:             second_intent,
174:         )
175:     } else {
176:         (
177:             &*second,
178:             movement.second,
179:             second_intent,
180:             &*first,
181:             movement.first,
182:             first_intent,
183:         )
184:     };
185:     record_movement(recorder, a, b.id, movement, a_axis, a_intent, time);
186:     record_movement(recorder, b, a.id, movement, b_axis, b_intent, time);
187:     Ok(())
188: }
