190: fn movement_phase(combatant: &Combatant, time: BattleTime) -> MeleeTimelinePhase {
191:     if combatant.melee_attack_started_at_seconds.is_some() {
192:         MeleeTimelinePhase::Windup
193:     } else if combatant.melee_recovery_until_seconds > time {
194:         MeleeTimelinePhase::Recovery
195:     } else {
196:         MeleeTimelinePhase::NeutralGuard
197:     }
198: }
