200: fn record_movement(
201:     recorder: &mut BattleRecorder,
202:     combatant: &Combatant,
203:     target_id: u64,
204:     movement: OpposedMovement,
205:     axis: AxisMotion,
206:     intent: MeleeMovementAction,
207:     time: BattleTime,
208: ) {
209:     let phase = movement_phase(combatant, time);
210:     let mut event = MeleeTimelineEvent::at(MeleeTimelineKind::Movement, time);
211:     event.combatant_id = Some(combatant.id);
212:     event.target_id = Some(target_id);
213:     event.engagement_distance_before_metres = Some(movement.distance_before_metres);
214:     event.engagement_distance_after_metres = Some(movement.distance_after_metres);
215:     event.movement_action = Some(intent);
216:     event.movement_elapsed_seconds = Some(movement.elapsed_seconds);
217:     event.movement_displacement_metres = Some(axis.displacement_metres);
218:     event.movement_velocity_before_metres_per_second = Some(axis.velocity_before_metres_per_second);
219:     event.movement_velocity_after_metres_per_second = Some(axis.velocity_after_metres_per_second);
220:     event.movement_speed_limit_metres_per_second = Some(axis.speed_limit_metres_per_second);
221:     event.readiness_before_seconds = Some(combatant.melee_recovery_until_seconds);
222:     event.readiness_after_seconds = event.readiness_before_seconds;
223:     event.phase_before = Some(phase);
224:     event.phase_after = Some(phase);
225:     recorder.record_timeline(event);
226: }

