20: impl MeleeEngagement {
21:     fn observe(
22:         attacker: &Combatant,
23:         defender: &Combatant,
24:         parameters: crate::combat::AutoresolveParameters,
25:     ) -> Self {
26:         let initial_separation =
27:             maximum_melee_pair_surface_separation(attacker, defender, parameters);
28:         let attacker_distance = if attacker.melee_engagement_target == Some(defender.id) {
29:             attacker.melee_engagement_distance_metres
30:         } else {
31:             initial_separation
32:         };
33:         let defender_distance = if defender.melee_engagement_target == Some(attacker.id) {
34:             defender.melee_engagement_distance_metres
35:         } else {
36:             initial_separation
37:         };
38:         Self {
39:             attacker_id: attacker.id,
40:             target_id: defender.id,
41:             initial_separation,
42:             distance: attacker_distance.min(defender_distance).max(0.0),
43:         }
44:     }
45:     fn commit(self, attacker: &mut Combatant, defender: &mut Combatant) {
46:         if attacker.melee_engagement_target != Some(self.target_id) {
47:             attacker.melee_engagement_target = Some(self.target_id);
48:             attacker.melee_engagement_distance_metres = self.initial_separation;
49:         }
50:         if defender.melee_engagement_target != Some(self.attacker_id) {
51:             defender.melee_engagement_target = Some(self.attacker_id);
52:             defender.melee_engagement_distance_metres = self.initial_separation;
53:         }
54:     }
55: }
