72:         event.engagement_distance_before_metres = Some(distance);
73:         event.engagement_distance_after_metres = Some(distance);
74:         event.readiness_before_seconds = Some(readiness);
75:         event.readiness_after_seconds = Some(timing.recovery_until_seconds);
76:         event.attack_id = Some(timing.attack_id(attacker_id));
77:         event.attack_started_tick = Some(MeleeTimelineEvent::tick_at(timing.started_at_seconds));
78:         event.attack_contact_tick = Some(MeleeTimelineEvent::tick_at(timing.contact_at_seconds));
79:         event.attack_recovery_tick =
80:             Some(MeleeTimelineEvent::tick_at(timing.recovery_until_seconds));
81:         event.phase_before = Some(if readiness > window_start {
82:             MeleeTimelinePhase::Recovery
83:         } else {
84:             MeleeTimelinePhase::NeutralGuard
85:         });
86:         event.phase_after = Some(MeleeTimelinePhase::Windup);
87:         event.phase_adaptation_delay_seconds = Some(adaptation);
88:         recorder.record_timeline(event);
89:     }
