92: pub(in crate::autoresolve) fn initialize_melee_phases(
93:     allies: &mut [Combatant],
94:     enemies: &mut [Combatant],
95:     random: &mut DeterministicRng,
96:     parameters: crate::combat::AutoresolveParameters,
97: ) -> ElapsedResult<()> {
98:     let mut order = allies
99:         .iter()
100:         .enumerate()
101:         .map(|(index, combatant)| (combatant.id, ScheduledBattleSide::Allies, index))
102:         .chain(
103:             enemies
104:                 .iter()
105:                 .enumerate()
106:                 .map(|(index, combatant)| (combatant.id, ScheduledBattleSide::Enemies, index)),
107:         )
108:         .collect::<Vec<_>>();
109:     order.sort_by_key(|(id, _, _)| *id);
110:     for (_, side, index) in order {
111:         let combatant = match side {
112:             ScheduledBattleSide::Allies => &mut allies[index],
113:             ScheduledBattleSide::Enemies => &mut enemies[index],
114:         };
115:         let sampled_delay = parameters.melee_initiative_delay_min_seconds.seconds()
116:             + random.unit_f32()
117:                 * (parameters.melee_initiative_delay_max_seconds.seconds()
118:                     - parameters.melee_initiative_delay_min_seconds.seconds());
119:         let delay = sampled_delay * (3.0 / combatant.attributes.instinct.max(0.5)).clamp(0.6, 2.0);
120:         let jitter = parameters
121:             .melee_cadence_jitter_seconds
122:             .checked_scale(random.unit_f32())?;
123:         // Both derived spans are checked before publishing this initial schedule.
124:         let delay = AnimationElapsed::from_seconds(delay)?;
125:         combatant.melee_recovery_until_seconds = BattleTime::from_elapsed_since_start(delay);
126:         combatant.melee_interval_jitter_seconds = jitter;
127:     }
128:     Ok(())
129: }
