137:     parameters: crate::combat::AutoresolveParameters,
138: ) -> BattleResolutionResult<Vec<ScheduledMeleeAttack>> {
139:     let start = BattleTime::from_seconds(
140:         round.saturating_sub(1) as f32 * parameters.combat_round_seconds.seconds(),
141:     )?;
142:     schedule_side_melee_attacks_in_window(
143:         attackers,
144:         defenders,
145:         start,
146:         parameters.combat_round_seconds,
147:         random,
148:         recorder,
149:         parameters,
