153: pub(in crate::autoresolve) fn schedule_side_melee_attacks_in_window(
154:     attackers: &mut [Combatant],
155:     defenders: &mut [Combatant],
156:     window_start: BattleTime,
157:     window_seconds: AnimationElapsed,
158:     random: &mut DeterministicRng,
159:     recorder: &mut BattleRecorder,
160:     parameters: crate::combat::AutoresolveParameters,
161: ) -> BattleResolutionResult<Vec<ScheduledMeleeAttack>> {
162:     let mut scheduled = Vec::new();
163:     for index in 0..attackers.len() {
164:         if let Some(attack) = schedule_attacker(
165:             index,
166:             attackers,
167:             defenders,
168:             window_start,
169:             window_seconds,
170:             random,
171:             recorder,
172:             parameters,
173:         )? {
174:             scheduled.push(attack);
175:         }
176:     }
177:     Ok(scheduled)
178: }
