180: #[expect(
181:     clippy::too_many_arguments,
182:     reason = "one actor scheduling joins both sides and deterministic state"
183: )]
184: fn schedule_attacker(
185:     index: usize,
186:     attackers: &mut [Combatant],
187:     defenders: &mut [Combatant],
188:     window_start: BattleTime,
189:     window_seconds: AnimationElapsed,
190:     random: &mut DeterministicRng,
191:     recorder: &mut BattleRecorder,
192:     parameters: crate::combat::AutoresolveParameters,
193: ) -> BattleResolutionResult<Option<ScheduledMeleeAttack>> {
194:     if attackers[index].is_defeated()
195:         || side_defeated(defenders)
196:         || preferred_attack_mode(&attackers[index]) != BattleAttackKind::Melee
197:     {
198:         return Ok(None);
199:     }
200:     if !attackers[index].can_attack_melee() {

201:         attackers[index].yielded = true;
202:         return Ok(None);
203:     }
204:     let (target_index, flanking) = melee_assignment(index, attackers, defenders, parameters);
205:     let window_end = window_start.checked_add(window_seconds)?;
206:     if let (Some(started_at_seconds), Some(contact_at_seconds)) = (
207:         attackers[index].melee_attack_started_at_seconds,
208:         attackers[index].melee_attack_contact_at_seconds,
209:     ) {
210:         return Ok(
211:             (contact_at_seconds <= window_end).then(|| ScheduledMeleeAttack {
212:                 attacker_index: index,
213:                 target_index,
214:                 flanking,
215:                 attack_timing: ScheduledMeleeTiming {
216:                     started_at_seconds,
217:                     contact_at_seconds,
218:                     recovery_until_seconds: attackers[index].melee_recovery_until_seconds,
219:                 },
220:             }),
221:         );
222:     }
223:     let engagement =
224:         MeleeEngagement::observe(&attackers[index], &defenders[target_index], parameters);
225:     let MeleeEngagement {
226:         attacker_id,
227:         target_id,
228:         distance,
229:         ..
230:     } = engagement;
231:     let reach = melee_effective_reach(&attackers[index]);
232:     if distance > reach + parameters.melee_lunge_maximum_travel_metres {
233:         engagement.commit(&mut attackers[index], &mut defenders[target_index]);
234:         return Ok(None);
235:     }
236:     let readiness = attackers[index]
237:         .melee_recovery_until_seconds
238:         .checked_add(attackers[index].melee_phase_adaptation_delay_seconds)?;
239:     let Some(started) = available_attack_start(window_start, window_end, window_start, readiness)
240:     else {
241:         engagement.commit(&mut attackers[index], &mut defenders[target_index]);
242:         return Ok(None);
243:     };
244:     let Some(interval) = attack_interval(&attackers[index], parameters)?.available() else {
245:         engagement.commit(&mut attackers[index], &mut defenders[target_index]);
246:         return Ok(None);
247:     };
248:     let timing = ScheduledMeleeTiming {
249:         started_at_seconds: started,
250:         contact_at_seconds: started.checked_add(parameters.melee_windup_seconds)?,
251:         recovery_until_seconds: started.checked_add(interval)?,
252:     };
253:     let adaptation = attackers[index].melee_phase_adaptation_delay_seconds;
254:     let jitter = parameters
255:         .melee_cadence_jitter_seconds
256:         .checked_scale(random.unit_f32())?;
257:     engagement.commit(&mut attackers[index], &mut defenders[target_index]);
258:     timing.commit(&mut attackers[index], distance, jitter);
259:     AttackStartTrace {
260:         attacker_id,
261:         target_id,
262:         distance,
263:         readiness,
264:         window_start,
265:         adaptation,
266:         timing,
267:     }
268:     .record(recorder);
269:     Ok(
270:         (timing.contact_at_seconds <= window_end).then_some(ScheduledMeleeAttack {
271:             attacker_index: index,
272:             target_index,
273:             flanking,
274:             attack_timing: timing,
275:         }),
276:     )
277: }
