279: fn attack_interval(
280:     attacker: &Combatant,
281:     parameters: crate::combat::AutoresolveParameters,
282: ) -> BattleResolutionResult<crate::combat::RecoveryTime> {
283:     let base = attacker
284:         .equipment
285:         .melee_weapon
286:         .map_or(parameters.reference_melee_attack_seconds, |weapon| {
287:             weapon.attack_interval_seconds
288:         })
289:         .max(parameters.minimum_attack_interval_seconds)
290:         .checked_add(attacker.melee_interval_jitter_seconds)?;
291:     Ok(crate::combat::incapacitation_adjusted_recovery_seconds(
292:         base,
293:         attacker.incapacitation_performance()?,
294:     )?)
295: }
