297: pub(in crate::autoresolve) fn scheduled_side_contacts_in_window(
298:     attackers: &[Combatant],
299:     defenders: &[Combatant],
300:     start: BattleTime,
301:     end: BattleTime,
302:     parameters: crate::combat::AutoresolveParameters,
303: ) -> Vec<ScheduledMeleeAttack> {
304:     attackers
305:         .iter()
306:         .enumerate()
307:         .filter_map(|(index, attacker)| {
308:             let started = attacker.melee_attack_started_at_seconds?;
309:             let contact = attacker.melee_attack_contact_at_seconds?;
310:             if contact < start || contact > end {
311:                 return None;
312:             }
313:             let (assigned, flanking) = melee_assignment(index, attackers, defenders, parameters);
314:             let target = attacker
315:                 .melee_engagement_target
316:                 .and_then(|id| defenders.iter().position(|candidate| candidate.id == id))
317:                 .unwrap_or(assigned);
318:             Some(ScheduledMeleeAttack {
319:                 attacker_index: index,
320:                 target_index: target,
321:                 flanking,
322:                 attack_timing: ScheduledMeleeTiming {
323:                     started_at_seconds: started,
324:                     contact_at_seconds: contact,
325:                     recovery_until_seconds: attacker.melee_recovery_until_seconds,
326:                 },
327:             })
328:         })
329:         .collect()
330: }
