332: pub(in crate::autoresolve) fn take_side_turns(
333:     attackers: &mut [Combatant],
334:     defenders: &mut [Combatant],
335:     round: usize,
336:     random: &mut DeterministicRng,
337:     recorder: &mut BattleRecorder,
338:     parameters: crate::combat::AutoresolveParameters,
339: ) -> BattleResolutionResult<()> {
340:     for attack in
341:         schedule_side_melee_attacks(attackers, defenders, round, random, recorder, parameters)?
342:     {
343:         if !scheduled_attack_is_current(&attackers[attack.attacker_index], attack.attack_timing) {
344:             continue;
345:         }
346:         let id = attack
347:             .attack_timing
348:             .attack_id(attackers[attack.attacker_index].id);
349:         resolve_melee_turn(
350:             attack.attacker_index,
351:             attack.target_index,
352:             attack.flanking,
353:             attackers,
354:             defenders,
355:             round,
356:             random,
357:             recorder,
358:             parameters,
359:             attack.attack_timing,
360:             MeleeContactBatch {
361:                 id,
362:                 members: vec![id],
363:                 order: 0,
364:             },
365:         )?;
366:     }
367:     Ok(())
368: }
