1: //! Signed coordinates on the pure autoresolve battle clock.
2: 
3: use crate::elapsed::{AnimationElapsed, ElapsedResult};
4: use serde::{Deserialize, Serialize};
5: use std::cmp::Ordering;
6: 
7: pub type BattleTimeResult<T> = Result<T, BattleTimeError>;
8: 
9: /// Finite seconds relative to the battle origin. Negative coordinates are
10: /// valid; this clock is independent of the tactical server's authority clock.
11: #[derive(Clone, Copy, Debug, Default, PartialEq, PartialOrd, Serialize, Deserialize)]
12: #[serde(try_from = "f32", into = "f32")]
13: pub struct BattleTime(f32);
14: 
15: #[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
16: pub enum BattleTimeError {
17:     #[error("battle-time coordinate must be finite")]
18:     NonFinite,
19:     #[error("battle-time coordinate arithmetic overflowed")]
20:     Overflow,
21: }
22: 
23: impl BattleTime {
24:     pub const ZERO: Self = Self(0.0);
25: 
26:     pub fn from_seconds(seconds: f32) -> BattleTimeResult<Self> {
27:         if !seconds.is_finite() {
28:             return Err(BattleTimeError::NonFinite);
29:         }
30:         Ok(Self(seconds))
31:     }
32: 
33:     /// Place a checked span at the battle origin without rounding its seconds.
34:     pub fn from_elapsed_since_start(elapsed: AnimationElapsed) -> Self {
35:         Self(elapsed.seconds())
36:     }
37: 
38:     /// Native seconds at the serialization or final clock/ratio kernel.
39:     pub fn seconds(self) -> f32 {
40:         self.0
41:     }
42: 
43:     pub fn checked_add(self, elapsed: AnimationElapsed) -> BattleTimeResult<Self> {
44:         let seconds = self.0 + elapsed.seconds();
45:         if !seconds.is_finite() {
46:             return Err(BattleTimeError::Overflow);
47:         }
48:         Ok(Self(seconds))
49:     }
50: 
51:     /// Reject a negative or unrepresentable interval between coordinates.
52:     pub fn elapsed_since(self, earlier: Self) -> ElapsedResult<AnimationElapsed> {
53:         AnimationElapsed::from_seconds(self.0 - earlier.0)
54:     }
55: 
56:     /// Return zero if this coordinate precedes `earlier`; otherwise admit the
57:     /// seconds difference, rejecting a positive unrepresentable interval.
58:     pub fn saturating_elapsed_since(self, earlier: Self) -> ElapsedResult<AnimationElapsed> {
59:         AnimationElapsed::from_seconds((self.0 - earlier.0).max(0.0))
60:     }
61: 
62:     pub fn max(self, other: Self) -> Self {
63:         Self(self.0.max(other.0))
64:     }
65: 
66:     pub fn total_cmp(&self, other: &Self) -> Ordering {
67:         self.0.total_cmp(&other.0)
68:     }
69: 
70:     /// Preserve the original subtraction before the simultaneous-contact test.
71:     /// An overflowing transient difference cannot be within a finite tolerance.
72:     pub fn is_within(self, other: Self, tolerance: AnimationElapsed) -> bool {
73:         (self.0 - other.0).abs() <= tolerance.seconds()
74:     }
75: 
76:     /// Preserve addition-before-comparison without retaining the intermediate
77:     /// coordinate. Overflow makes this predicate false, as in the scalar kernel.
78:     pub fn precedes_with_margin(self, other: Self, margin: AnimationElapsed) -> bool {
79:         self.0 + margin.seconds() < other.0
80:     }
81: }
82: 
83: impl TryFrom<f32> for BattleTime {
84:     type Error = BattleTimeError;
85: 
86:     fn try_from(seconds: f32) -> BattleTimeResult<Self> {
87:         Self::from_seconds(seconds)
88:     }
89: }
90: 
91: impl From<BattleTime> for f32 {
92:     fn from(time: BattleTime) -> Self {
93:         time.0
94:     }
95: }

