216:     Ok(AutoresolveMeleeReactionTiming {
217:         input_reflex: (1.0 - reaction_delay / parameters.melee_reflex_window_seconds.seconds())
218:             .clamp(parameters.minimum_melee_input_reflex, 1.0),
219:         displacement_time_seconds: AnimationElapsed::from_seconds(elapsed_after_input)?,
220:     })
