159: pub(in crate::autoresolve) fn commit_defensive_action(
160:     defender: &mut Combatant,
161:     attempted: DefenderResponse,
162:     effective: DefenderResponse,
163:     phase: MeleeDefenderPhase,
164: ) -> BattleResolutionResult<DefenseCommitment> {
165:     let defense_seconds = match attempted {
166:         DefenderResponse::None => return Ok(DefenseCommitment::NONE),
167:         DefenderResponse::Block { .. }
168:         | DefenderResponse::Parry { .. }
169:         | DefenderResponse::Dodge { .. } => AnimationElapsed::from_seconds(0.5)?,
170:     };
171:     if let DefenderResponse::Block { effectiveness } = effective
172:         && defender.equipment.shield_block_bonus > 0.0
173:         && matches!(phase, MeleeDefenderPhase::CommittedAttack(_))
174:     {
175:         defender.melee_attack_power_multiplier *=
176:             (1.0 - 0.4 * effectiveness.clamp(0.0, 1.0)).clamp(0.2, 1.0);
177:         return Ok(DefenseCommitment {
178:             kind: MeleeDefenseCommitmentKind::TransformedOffhand,
179:             retained_power: Some(defender.melee_attack_power_multiplier),
180:             recovery_seconds_after_contact: AnimationElapsed::ZERO,
181:         });
182:     }
183:     if matches!(phase, MeleeDefenderPhase::NeutralGuard) {
184:         return Ok(DefenseCommitment {
185:             kind: MeleeDefenseCommitmentKind::NeutralGuardRecovery,
186:             retained_power: None,
187:             recovery_seconds_after_contact: if matches!(attempted, DefenderResponse::Dodge { .. }) {
188:                 defense_seconds
189:             } else {
190:                 AnimationElapsed::ZERO
191:             },
192:         });
193:     }
194:     let canceled =
195:         attempted.is_weapon_contact() && matches!(phase, MeleeDefenderPhase::CommittedAttack(_));
196:     Ok(DefenseCommitment {
197:         kind: if canceled {
198:             MeleeDefenseCommitmentKind::CanceledSameWeapon
199:         } else {
200:             MeleeDefenseCommitmentKind::DefenseRecovery
201:         },
202:         retained_power: None,
203:         recovery_seconds_after_contact: defense_seconds,
204:     })
205: }
