664: /// Move a deterministic development fixture into another fixture's party
665: /// without going through the player-facing recruitment workflow.
666: pub(crate) fn attach_seeded_party_member(
667:     ctx: &ReducerContext,
668:     leader_id: u64,
669:     member_id: u64,
670:     role: &str,
671: ) -> Result<(), String> {
672:     let leader = ctx
673:         .db
674:         .character()
675:         .id()
676:         .find(leader_id)
677:         .ok_or("Seed party leader not found")?;
678:     let party_id = leader
679:         .party_id
680:         .clone()
681:         .ok_or("Seed party leader has no party")?;
682:     let mut member = ctx
683:         .db
684:         .character()
685:         .id()
686:         .find(member_id)
687:         .ok_or("Seed party member not found")?;
688: 
689:     if member.party_id.as_deref() == Some(&party_id) {
690:         if let Some(mut membership) = ctx
691:             .db
692:             .party_member()
693:             .character_id()
694:             .filter(member_id)
695:             .find(|membership| membership.party_id == party_id)
696:         {
697:             membership.role = Some(role.into());
698:             ctx.db.party_member().id().update(membership);
699:         }
700:         return Ok(());
701:     }
702: 
703:     if let Some(source_party_id) = member.party_id.clone() {
704:         let source_members: Vec<_> = ctx
705:             .db
706:             .party_member()
707:             .party_id()
708:             .filter(&source_party_id)
709:             .collect();
710:         if source_members
711:             .iter()
712:             .any(|membership| membership.character_id != member_id)
713:         {
714:             return Err("Seed party member belongs to a non-solo party".into());
715:         }
716:         for membership in source_members {
717:             ctx.db.party_member().id().delete(membership.id);
718:         }
719:         for vote in ctx
720:             .db
721:             .party_leader_vote()
722:             .party_id()
723:             .filter(&source_party_id)
724:             .collect::<Vec<_>>()
725:         {
726:             ctx.db.party_leader_vote().id().delete(&vote.id);
727:         }
728:         ctx.db.party_authority().id().delete(&source_party_id);
729:     }
730: 
731:     member.party_id = Some(party_id.clone());
732:     member.current_settlement_id = leader.current_settlement_id.clone();
733:     ctx.db.character().id().update(member);
734:     crate::investigation::set_character_case_site(
735:         ctx,
736:         member_id,
737:         crate::investigation::character_case_site_id(ctx, leader_id),
738:     )?;
739:     crate::social::reset_familiarity_after_join(ctx, member_id);
740:     ctx.db.party_member().insert(PartyMember {
741:         id: 0,
742:         party_id: party_id.clone(),
743:         character_id: member_id,
744:         role: Some(role.into()),
745:         recruitment_role_id: None,
746:     });
747:     put_leader_vote(ctx, &party_id, member_id, leader_id);
748:     if let Some(mut party) = ctx.db.party_authority().id().find(&party_id) {
749:         party.is_solo = false;
750:         ctx.db.party_authority().id().update(party);
751:     }
752:     normalize_and_elect_party_leader(ctx, &party_id)?;
753:     Ok(())

