1994: /// Fires whenever `Player` lands on any entity - via the normal
1995: /// SpacetimeDB-driven [`spawn_connected_player`], a loaded world dump
1996: /// (`load_world_dump`), or a dump-to-live-client merge
1997: /// (`bind_dumped_character_on_join`). Adds everything a character always
1998: /// needs that is never part of its actual data: mid-action authority/
1999: /// cooldown state (correctly starts neutral regardless of source), the
2000: /// physics/controller bundle (colliders aren't reflectable - see
2001: /// `avian3d::Collider`), and the replication marker. This is what lets both
2002: /// SpacetimeDB rows and world dumps carry only "core" reflectable character
2003: /// data (`Player`, `CharacterId`, `Skills`, `Limbs`, `TacticalAttributes`, `Stats`,
2004: /// `TacticalCombatState`, `TacticalCombatSide`, `Transform`) instead of a
2005: /// full component-for-component bundle.
2006: pub(crate) fn on_player_added(
2007:     event: On<Add, Player>,
2008:     mut commands: Commands,
2009:     query: Query<(&Player, &CharacterId)>,
2010: ) -> Result {
2011:     let (player, character_id) = query.get(event.entity)?;
2012:     commands.entity(event.entity).insert_if_new((
2013:         Name::new(format!("Character#{} {}", character_id.0, player.name)),
2014:         Replicated,
2015:         BestiaryCategories::default(),
2016:         MeleeAttackAuthority::default(),
2017:         RangedAttackAuthority::default(),
2018:         player_collider(),
2019:         CollisionMargin(0.01),
2020:         tactical_character_controller(),
2021:         CharacterLook::default(),
2022:         AuthoritativeMovementIntent::default(),
2023:         AuthoritativeInputTick::default(),
2024:         CharacterMotionSnapshot::default(),
2025:         QuickstepPush::default(),
2026:         DoorPassageExemptions::default(),
2027:     ));
2028:     Ok(())
2029: }
