637: fn on_equip_slot_removed(mut world: DeferredWorld, ctx: HookContext) {
638:     let Some(root) = world.get::<ItemOf>(ctx.entity).map(|i| i.0) else {
639:         return;
640:     };
641:     let Some(mut items) = world.get_mut::<InventoryItems>(root) else {
642:         return;
643:     };
