78: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
79: pub enum ScheduleParseError {
80:     ExceedsDay,
81:     NotQuarterHour,
82:     OrganizationWithoutMinutes,
83:     MinutesWithoutOrganization,
84:     EmptyOrganization,
85: }
