87: impl std::fmt::Display for ScheduleParseError {
88:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
89:         f.write_str(match self {
90:             Self::ExceedsDay => "The downtime plan must fit within 24 hours",
91:             Self::NotQuarterHour => "Schedule allocations must use 15-minute increments",
92:             Self::OrganizationWithoutMinutes => {
93:                 "An organization cannot be selected without scheduled minutes"
94:             }
95:             Self::MinutesWithoutOrganization => {
96:                 "Scheduled organization activity requires an organization"
97:             }
98:             Self::EmptyOrganization => "Scheduled organization ID cannot be blank",
99:         })
100:     }
101: }
