104: /// Validates the cross-field invariants of a daily allocation at the reducer
105: /// boundary. Organization policy/membership remains an authoritative DB check.
106: #[derive(Clone, Debug, PartialEq, Eq)]
107: pub struct DailySchedulePlan {
108:     pub activities: [ActivityMinutes; 10],
109:     pub apprenticeship: OrganizationAllocation,
110:     pub practice: OrganizationAllocation,
