113: pub fn validate_daily_allocation(
114:     minutes: [u16; 10],
115:     apprenticeship: (u16, Option<String>),
116:     practice: (u16, Option<String>),
117: ) -> Result<DailySchedulePlan, ScheduleParseError> {
118:     if minutes.into_iter().map(u64::from).sum::<u64>() > MINUTES_PER_DAY {
119:         return Err(ScheduleParseError::ExceedsDay);
120:     }
121:     let activities = minutes
122:         .map(ActivityMinutes::try_from)
123:         .into_iter()
124:         .collect::<Result<Vec<_>, _>>()?
125:         .try_into()
126:         .map_err(|_| ScheduleParseError::ExceedsDay)?;
127:     Ok(DailySchedulePlan {
128:         activities,
129:         apprenticeship: OrganizationAllocation::parse(apprenticeship.0, apprenticeship.1)?,
130:         practice: OrganizationAllocation::parse(practice.0, practice.1)?,
131:     })
132: }
