177: /// Allocation validated independently of persistence and organization access.
178: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
179: pub struct ValidatedSchedule(DailySchedule);
180: 
181: impl TryFrom<DailySchedule> for ValidatedSchedule {
182:     type Error = ScheduleParseError;
183: 
184:     fn try_from(schedule: DailySchedule) -> Result<Self, Self::Error> {
185:         if schedule.allocated_minutes() > MINUTES_PER_DAY {
186:             return Err(ScheduleParseError::ExceedsDay);
187:         }
188:         for minutes in schedule
189:             .redistribution_minutes()
190:             .into_iter()
191:             .chain([schedule.reading_minutes])
192:         {
193:             ActivityMinutes::try_from(minutes)?;
194:         }
195:         Ok(Self(schedule))
196:     }
197: }
