199: impl DailySchedule {
200:     // Authored activity order, shared by execution and both preview paths.

201:     // Reading remains unchanged: unavailable time does not add book study.
202:     fn redistribution_minutes(self) -> [u16; 9] {
203:         [
204:             self.combat_training_minutes,
205:             self.carousing_minutes,
206:             self.socializing_minutes,
207:             self.apprenticeship_minutes,
208:             self.profession_practice_minutes,
209:             self.labor,
210:             self.prayer,
211:             self.thievery,
212:             self.raiding,
213:         ]
214:     }
215: }
