217: impl ValidatedSchedule {
218:     /// Calculate against the supplied context without consuming caller RNG or
219:     /// changing the saved allocation. Callers resolve current organization
220:     /// eligibility before constructing this value. The seed is character ID.
221:     pub fn effective_at(self, location: ActivityLocation, seed: Seed) -> DailySchedule {
222:         let available = [
223:             true,
224:             location.allows(LocationActivity::Carousing),
225:             true,
226:             true,
227:             true,
228:             true,
229:             true,
230:             location.allows(LocationActivity::Thievery),
231:             location.allows(LocationActivity::Raiding),
232:         ];
233:         let planned = self.0.redistribution_minutes();
234:         let mut effective = planned;
235:         let mut segments = 0;
236:         for index in 0..planned.len() {
237:             if !available[index] {
238:                 segments += planned[index] / ACTIVITY_SEGMENT_MINUTES;
239:                 effective[index] = 0;
240:             }
241:         }
242:         let weights = std::array::from_fn::<_, 9, _>(|index| {
243:             if available[index] {
244:                 u64::from(planned[index])
245:             } else {
246:                 0
247:             }
248:         });
249:         if weights.iter().any(|weight| *weight != 0) {
250:             let mut random = StreamId::new("schedule.redistribution").rng(seed, &[]);
251:             for _ in 0..segments {
252:                 let selected = random
253:                     .weighted_index(&weights)
254:                     .expect("validated daily minutes have a positive, bounded total");
255:                 effective[selected] += ACTIVITY_SEGMENT_MINUTES;
256:             }
257:         }
258:         let [
259:             combat_training_minutes,
260:             carousing_minutes,
261:             socializing_minutes,
262:             apprenticeship_minutes,
263:             profession_practice_minutes,
264:             labor,
265:             prayer,
266:             thievery,
267:             raiding,
268:         ] = effective;
269:         DailySchedule {
270:             reading_minutes: self.0.reading_minutes,
271:             combat_training_minutes,
272:             carousing_minutes,
273:             socializing_minutes,
274:             apprenticeship_minutes,
275:             profession_practice_minutes,
276:             labor,
277:             prayer,
278:             thievery,
279:             raiding,
280:         }
281:     }
282: }
