126: enum SocialOrganizationInstanceId<'a> {
127:     ProvisionalFamily(&'a str),
128:     Family(&'a str),
129:     Other,
130: }
131: 
132: impl<'a> SocialOrganizationInstanceId<'a> {
133:     fn parse(value: &'a str) -> Self {
134:         let Some(family_coordinate) = value
135:             .strip_prefix("family:")
136:             .filter(|coordinate| !coordinate.is_empty())
137:         else {
138:             return Self::Other;
139:         };
140:         family_coordinate
141:             .strip_prefix("origin:")
142:             .filter(|coordinate| !coordinate.is_empty())
143:             .map_or(Self::Family(family_coordinate), Self::ProvisionalFamily)
144:     }
145: 
146:     const fn is_provisional_family(&self) -> bool {
147:         matches!(self, Self::ProvisionalFamily(_coordinate))
148:     }
149: 
150:     const fn is_family(&self) -> bool {
151:         match self {
152:             Self::ProvisionalFamily(coordinate) | Self::Family(coordinate) => {
153:                 !coordinate.is_empty()
154:             }
155:             Self::Other => false,
156:         }
157:     }
158: }
