176:         .character_organization_role()
177:         .character_id()
178:         .filter(character_id)
179:         .filter(|assignment| {
180:             SocialOrganizationInstanceId::parse(&assignment.organization_instance_id)
181:                 .is_provisional_family()
182:                 && assignment.organization_instance_id != instance_id
183:         })
184:         .collect::<Vec<_>>();
