187:         ctx.db
188:             .character_organization_role()
189:             .id()
190:             .delete(&assignment.id);
191:         delete_organization_instance_if_unreferenced(ctx, &old_instance);
192:     }
193:     let definition_id = if noble {
194:         "local_noble_house"
195:     } else {
196:         "common_family"
197:     };
198:     let expected = SocialOrganizationInstance {
199:         id: instance_id.clone(),
200:         definition_id: definition_id.into(),
201:         settlement_id: None,
202:     };
203:     if let Some(existing) = ctx
204:         .db
205:         .social_organization_instance()
206:         .id()
207:         .find(&instance_id)
