389: fn compile_organizations(root: &Path) {
390:     // Organization roles and kinds are validated here before embedding.
391:     let content = root.join("content/organizations");
392:     let policies_path = root.join("content/settlement-policies.yaml");
393:     let promotions_path = root.join("content/organization-promotion-transitions.yaml");
394:     println!("cargo:rerun-if-changed={}", content.display());
395:     println!("cargo:rerun-if-changed={}", policies_path.display());
396:     println!("cargo:rerun-if-changed={}", promotions_path.display());
397:     let mut files: Vec<_> = fs::read_dir(&content)
398:         .expect("content/organizations must exist")
399:         .map(|entry| entry.unwrap().path())
400:         .filter(|path| {
401:             path.extension()
402:                 .is_some_and(|extension| extension == "yaml")
403:         })
404:         .collect();
405:     files.sort();
406: 
407:     let mut documents = Vec::new();
408:     let mut source_files = Vec::new();
409:     let mut digest = Sha256::new();
410:     for file in files {
411:         let relative = file
412:             .strip_prefix(root)
413:             .unwrap()
414:             .to_string_lossy()
415:             .replace('\\', "/");
416:         let text = fs::read_to_string(&file).unwrap();
417:         digest.update(relative.as_bytes());
418:         digest.update([0]);
419:         digest.update(text.as_bytes());
420:         let value: serde_json::Value =
421:             serde_json::from_str(&text).unwrap_or_else(|error| panic!("{relative}: {error}"));
422:         match value {
423:             serde_json::Value::Array(values) => {
424:                 source_files.extend(std::iter::repeat_n(relative, values.len()));
425:                 documents.extend(values);
426:             }
427:             value => {
428:                 documents.push(value);
429:                 source_files.push(relative);
430:             }
431:         }
432:     }
433:     assert!(
434:         !documents.is_empty(),
435:         "content/organizations contains no YAML"
436:     );
437: 
438:     let policy_relative = policies_path
439:         .strip_prefix(root)
440:         .unwrap()
441:         .to_string_lossy()
442:         .replace('\\', "/");
443:     let policy_text = fs::read_to_string(&policies_path).unwrap();
444:     digest.update(policy_relative.as_bytes());
445:     digest.update([0]);
446:     digest.update(policy_text.as_bytes());
447:     let policies: serde_json::Value = serde_json::from_str(&policy_text)
448:         .unwrap_or_else(|error| panic!("{policy_relative}: {error}"));
449:     organization_catalog_validation::validate_documents(
450:         &documents,
451:         &source_files,
452:         &policies,
453:         &policy_relative,
454:     )
455:     .unwrap_or_else(|error| panic!("{error}"));
456: 
457:     let promotions_text = fs::read_to_string(&promotions_path).unwrap();
458:     digest.update(b"content/organization-promotion-transitions.yaml");
459:     digest.update([0]);
460:     digest.update(promotions_text.as_bytes());
461:     let promotions: serde_json::Value = serde_json::from_str(&promotions_text)
462:         .unwrap_or_else(|error| panic!("organization promotion transitions: {error}"));
463:     let promotions = promotions
464:         .as_array()
465:         .expect("promotion transitions must be an array");
466:     let mut seen = std::collections::BTreeSet::new();
467:     for transition in promotions {
468:         let organization_id = transition["organization_id"]
469:             .as_str()
470:             .expect("promotion organization_id");
471:         let from = transition["from_role_id"]
472:             .as_str()
473:             .expect("promotion from_role_id");
474:         let to = transition["to_role_id"]
475:             .as_str()
476:             .expect("promotion to_role_id");
477:         assert!(
478:             from != to && seen.insert((organization_id, from, to)),
479:             "duplicate or reflexive promotion transition"
480:         );
481:         let organization = documents
482:             .iter()
483:             .find(|document| document["id"] == organization_id)
484:             .expect("promotion references unknown organization");
485:         let roles = organization["roles"].as_array().unwrap();
486:         assert!(
487:             roles.iter().any(|role| role["id"] == from),
488:             "promotion references unknown source role"
489:         );
490:         assert!(
491:             roles.iter().any(|role| role["id"] == to),
492:             "promotion references unknown target role"
493:         );
494:     }
495: 
496:     let catalog = serde_json::json!({
497:         "organizations": documents,
498:         "promotion_transitions": promotions,
499:         "settlement_policies": policies,
500:     });
501:     let json = serde_json::to_string(&catalog).unwrap();
502:     let digest = format!("{:x}", digest.finalize());
503:     fs::write(
504:         Path::new(&env::var("OUT_DIR").unwrap()).join("organization_catalog.rs"),
505:         format!(
506:             "pub const ORGANIZATION_CATALOG_JSON: &str = {json:?};\n\
507:              pub const ORGANIZATION_CATALOG_DIGEST: &str = {digest:?};\n"
508:         ),
509:     )
510:     .unwrap();

