1386: fn valid_book_shape(book: &crate::item_catalog_schema::Book) -> bool {
1387:     use crate::item_catalog_schema::BookTarget;
1388:     let mut settlements = BTreeSet::new();
1389:     if book.settlement_allowlist.len() > 64
1390:         || book.settlement_allowlist.iter().any(|id| {
1391:             id.is_empty()
1392:                 || id.len() > 96
1393:                 || !id.bytes().all(|byte| {
1394:                     byte.is_ascii_lowercase()
1395:                         || byte.is_ascii_digit()
1396:                         || matches!(byte, b'_' | b'-')
1397:                 })
1398:                 || !settlements.insert(id)
1399:         })
1400:     {
1401:         return false;
1402:     }
1403:     let maximum = match &book.target {
1404:         BookTarget::Written { .. } | BookTarget::Religion { .. } | BookTarget::Bestiary { .. } => 5,
1405:         BookTarget::Skill { skill } if matches!(skill.as_str(), "physiology" | "herbalism") => 4,
1406:         BookTarget::Terrain { terrain }
1407:             if matches!(
1408:                 terrain.as_str(),
1409:                 "plains" | "forest" | "hills" | "wetlands" | "urban" | "snow"
1410:             ) =>
1411:         {
1412:             2
1413:         }
1414:         BookTarget::Skill { skill }
1415:             if matches!(
1416:                 skill.as_str(),
1417:                 "surgery" | "cooking" | "tailoring" | "smithing" | "command" | "charm"
1418:             ) =>
1419:         {
1420:             2
1421:         }
1422:         BookTarget::Skill { skill }
1423:             if matches!(
1424:                 skill.as_str(),
1425:                 "polearm"
1426:                     | "axe"
1427:                     | "bludgeon"
1428:                     | "sword"
1429:                     | "knife"
1430:                     | "bow"
1431:                     | "crossbow"
1432:                     | "firearm"
1433:                     | "throw"
1434:                     | "dodge"
1435:                     | "block"
1436:                     | "balance"
1437:                     | "stealth"
1438:             ) =>
1439:         {
1440:             1
1441:         }
1442:         _ => return false,
1443:     };
1444:     (1..=maximum).contains(&book.quality)
1445: }
