641: fn apply_reading_training(
642:     ctx: &ReducerContext,
643:     character_id: u64,
644:     skills: &mut CharacterSkills,
645:     mut real_hours: f32,
646:     attributes: &CharacterAttributes,
647: ) -> Result<f32, String> {
648:     use crate::item::inventory_item;
649:     use adventuresim_core::book::{BookCandidate, select_candidate};
650:     let character = ctx
651:         .db
652:         .character()
653:         .id()
654:         .find(character_id)
655:         .ok_or("Character disappeared while applying reading training")?;
656:     let personal = ctx
657:         .db
658:         .inventory_item()
659:         .character_id()
660:         .filter(character_id)
661:         .filter(|row| row.quantity > 0)
662:         .map(|row| row.item_id)
663:         .collect::<std::collections::BTreeSet<_>>();
664:     let bookstore = character
665:         .current_settlement_id
666:         .as_ref()
667:         .and_then(|id| ctx.db.settlement().id().find(id))
668:         .filter(|settlement| {
669:             settlement
670:                 .economy
671:                 .has_service(adventuresim_world_schema::SettlementService::Bookstore)
672:         });
673:     let mut excess = 0.0;
674:     let mut unusable = std::collections::BTreeSet::new();
675:     // A bounded title can finish mid-interval; immediately continue with the
676:     // next eligible title. The catalog and item IDs give a stable order.
677:     while real_hours > 0.000_01 {
678:         let candidates = adventuresim_core::item_catalog::catalog()
679:             .iter()
680:             .filter_map(|item| {
681:                 if unusable.contains(&item.id) {
682:                     return None;
683:                 }
684:                 let book = item.capabilities.book.as_ref()?;
685:                 let owned = personal.contains(&item.id);
686:                 let on_site = bookstore.as_ref().is_some_and(|settlement| {
687:                     book.settlement_allowlist.is_empty()
688:                         || book
689:                             .settlement_allowlist
690:                             .iter()
691:                             .any(|id| id == &settlement.id)
692:                 });
693:                 (owned || on_site).then_some(BookCandidate {
694:                     item_id: &item.id,
695:                     book,
696:                     personal: owned,
697:                 })
698:             });
699:         let Some(selected) = select_candidate(candidates, |book| {
700:             let medium_rank = adventuresim_core::book::written_rank(
701:                 skills.written_languages.effective(book.medium),
702:                 attributes.intelligence,
703:             );
704:             target_snapshot(skills, &book.target, attributes).is_some_and(|(rank, aptitude)| {
705:                 let (lower, upper) = adventuresim_core::book::rank_band(book);
706:                 medium_rank >= adventuresim_core::book::READABLE_WRITTEN_RANK
707:                     && rank + 0.000_01 >= f32::from(lower)
708:                     && rank < f32::from(upper).min(aptitude)
709:                     && aptitude > f32::from(lower)
710:             })
711:         }) else {
712:             break;
713:         };
714:         let gain = apply_selected_book(skills, selected.book, real_hours, attributes)?;
715:         if gain.accepted_effective_hours <= 0.0 {
716:             unusable.insert(selected.item_id.to_owned());
717:             continue;
718:         }
719:         excess += 0.0;
720:         if gain.unused_real_hours >= real_hours - 0.000_01 {
721:             break;
722:         }
723:         real_hours = gain.unused_real_hours;
724:     }
725:     Ok(excess)
726: }
