222: fn compile_items(root: &Path) {
223:     let content = root.join("content/items");
224:     println!("cargo:rerun-if-changed={}", content.display());
225:     let mut files: Vec<_> = fs::read_dir(&content)
226:         .expect("content/items must exist")
227:         .map(|entry| entry.unwrap().path())
228:         .filter(|path| {
229:             path.extension()
230:                 .is_some_and(|extension| extension == "yaml")
231:         })
232:         .collect();
233:     files.sort();
234:     let mut documents = Vec::new();
235:     let mut source_files = Vec::new();
236:     let mut sources = Vec::new();
237:     let mut item_sources = Vec::new();
238:     let mut digest = Sha256::new();
239:     for file in files {
240:         let relative = file
241:             .strip_prefix(root)
242:             .unwrap()
243:             .to_string_lossy()
244:             .replace('\\', "/");
245:         let text = fs::read_to_string(&file).unwrap();
246:         assert!(
247:             text.len() <= item_catalog_validation::MAX_SOURCE_BYTES,
248:             "{relative}: item catalog source is too large"
249:         );
250:         digest.update(relative.as_bytes());
251:         digest.update([0]);
252:         digest.update(text.as_bytes());
253:         let value = item_catalog_validation::parse_document(&text)
254:             .unwrap_or_else(|error| panic!("{relative}: {error}"));
255:         collect_item_sources(&value, &text, &relative, &mut item_sources);
256:         documents.push(value);
257:         source_files.push(relative);
258:         sources.push(text);
259:     }
260:     assert!(!documents.is_empty(), "content/items contains no YAML");
261:     item_catalog_validation::validate_documents_with_sources(&documents, &source_files, &sources)
262:         .unwrap_or_else(|error| panic!("{error}"));
263:     let icons = root.join("crates/strategic-web/static/icons/game");
264:     for document in &documents {
265:         for item in document["items"].as_array().unwrap() {
266:             let id = item["id"].as_str().unwrap();
267:             let icon = item["presentation"]["icon"].as_str().unwrap();
268:             assert!(
269:                 icons.join(format!("{icon}.svg")).is_file(),
270:                 "item {id}.presentation.icon: missing vendored icon {icon}.svg"
271:             );
272:         }
273:     }
274:     let json = serde_json::to_string(&documents).unwrap();
275:     let source_map = serde_json::to_string(&item_sources).unwrap();
276:     let digest = format!("{:x}", digest.finalize());
277:     fs::write(
278:         Path::new(&env::var("OUT_DIR").unwrap()).join("item_catalog.rs"),
279:         format!(
280:             "pub const ITEM_CATALOG_JSON: &str = {json:?};\n\
281:              pub const ITEM_CATALOG_SOURCE_MAP_JSON: &str = {source_map:?};\n\
282:              pub const ITEM_CATALOG_DIGEST: &str = {digest:?};\n"
283:         ),
284:     )
