61: pub(crate) fn object_for_row(
62:     ctx: &ReducerContext,
63:     scope: CarriedInventoryScope,
64:     row_id: u64,
65: ) -> Result<Option<InventoryObject>, String> {
66:     let mut matches =
67:         ctx.db
68:             .inventory_object()
69:             .iter()
70:             .filter(|object| match (&object.location, scope) {
71:                 (InventoryLocation::Personal(location), CarriedInventoryScope::Personal) => {
72:                     location.row_id == row_id
73:                 }
74:                 (InventoryLocation::Party(location), CarriedInventoryScope::Party) => {
75:                     location.row_id == row_id
76:                 }
77:                 _ => false,
78:             });
79:     let first = matches.next();
80:     if matches.next().is_some() {
81:         return Err("Inventory row has duplicate physical object identities".into());
82:     }
83:     Ok(first)
84: }
