86: fn insert_carried_object(
87:     ctx: &ReducerContext,
88:     item_id: &str,
89:     location: InventoryLocation,
90: ) -> Result<InventoryObject, String> {
91:     let scope = location
92:         .scope()
93:         .ok_or("Stable physical objects require carried custody at insertion")?;
94:     let row_id = location
95:         .row_id()
96:         .ok_or("Stable physical object has no backing inventory row")?;
97:     if object_for_row(ctx, scope, row_id)?.is_some() {
98:         return Err("Inventory row already has a stable physical object identity".into());
99:     }
100:     Ok(ctx.db.inventory_object().insert(InventoryObject {
101:         id: 0,
102:         item_id: item_id.into(),
103:         location,
104:     }))
105: }
