145: pub(crate) fn ancestry_reaches_fireplace(ctx: &ReducerContext, object_id: u64) -> bool {
146:     let mut cursor = Some(object_id);
147:     for _ in 0..=adventuresim_core::inventory_containers::MAX_CONTAINER_DEPTH {
148:         let Some(id) = cursor else { return false };
149:         let Some(object) = ctx.db.inventory_object().id().find(id) else {
150:             return false;
151:         };
152:         if object.location.is_fireplace() {
153:             return true;
154:         }
155:         cursor = ctx
156:             .db
157:             .inventory_containment()
158:             .child_object_id()
159:             .find(id)
160:             .map(|edge| edge.parent_object_id);
161:     }
162:     true
163: }

