166: fn consume_narrative_party_item(
167:     ctx: &ReducerContext,
168:     party_id: &str,
169:     item_id: &str,
170:     quantity: u32,
171: ) -> Result<(), String> {
172:     if crate::inventory_amount::is_measured_item(ctx, item_id) || item_is_durable(ctx, item_id) {
173:         return Err("Narrative costs currently require an ordinary stackable item".into());
174:     }
175:     let mut stacks: Vec<_> = ctx
176:         .db
177:         .party_inventory_item()
178:         .party_id()
179:         .filter(party_id)
180:         .filter(|stack| stack.item_id == item_id)
181:         .collect();
182:     stacks.sort_by_key(|stack| stack.id);
183:     if stacks
184:         .iter()
185:         .map(|stack| u64::from(stack.quantity))
186:         .sum::<u64>()
187:         < u64::from(quantity)
188:     {
189:         return Err("The party lacks the declared encounter cost".into());
190:     }
191:     let mut remaining = quantity;
192:     for mut stack in stacks {
193:         if remaining == 0 {
194:             break;
195:         }
196:         let taken = remaining.min(stack.quantity);
197:         stack.quantity -= taken;
198:         remaining -= taken;
199:         if stack.quantity == 0 {
200:             ctx.db.party_inventory_item().id().delete(stack.id);
201:         } else {
202:             ctx.db.party_inventory_item().id().update(stack);
203:         }
204:     }
205:     Ok(())
206: }
