234:     match storefront {
235:         Storefront::General => {
236:             profile.has_service(Service::Market) || profile.has_service(Service::GeneralStore)
237:         }
238:         Storefront::Weapons => {
239:             profile.has_service(Service::Weaponsmith)
240:                 || profile.has_service(Service::GeneralBlacksmith)
241:         }
242:         Storefront::Armor => {
243:             profile.has_service(Service::Armorer) || profile.has_service(Service::GeneralBlacksmith)
244:         }
245:         Storefront::Clothing => profile.has_service(Service::Tailor),
246:         Storefront::Herbalist => profile.has_service(Service::Herbalist),
247:         Storefront::Inn => profile.has_service(Service::Inn),
248:         Storefront::Books => profile.has_service(Service::Bookstore),
249:     }
250: }
