261:     // A market or inn is always a viable place to outfit a basic journey.
262:     // These two staples deliberately do not depend on a settlement's broader
263:     // commodity profile: the travel planner must never direct a player to an
264:     // exposed storefront that cannot sell the provisions it just recommended.
265:     if matches!(storefront, Storefront::General | Storefront::Inn)
266:         && crate::item_catalog::definition(id)
