131:         let Self::Presenting { outcome, remaining } = self else {
132:             return None;
133:         };
134:         *remaining = remaining.saturating_sub(delta);
135:         if !remaining.is_zero() {
136:             return None;
137:         }
138:         let outcome = *outcome;
139:         *self = Self::Finished { outcome };
140:         Some(outcome)
