470: /// Convert physical damage energy into the strategic 0-1 body-part health
471: /// scale. The calibration follows combat.md: roughly 20 J to an unarmored arm
472: /// is disabling, while larger body regions absorb proportionally more energy.
473: pub fn health_damage_from_attack(result: AttackResult, part: BodyPart) -> f32 {
474:     let AttackResult::ToDefender {
475:         cut_damage,
476:         blunt_damage,
477:         ..
478:     } = result
479:     else {
480:         return 0.0;
481:     };
482:     let capacity_joules = match part {
483:         BodyPart::LeftArm | BodyPart::RightArm => 20.0,
484:         BodyPart::LeftLeg | BodyPart::RightLeg => 35.0,
485:         BodyPart::Head => 20.0,
486:         BodyPart::Chest => 80.0,
487:         BodyPart::Stomach => 55.0,
488:     };
489:     ((cut_damage + blunt_damage * 0.75) / capacity_joules).max(0.0)
490: }
491: 
492: /// Partitions clamped limb-health damage according to each attack channel's
493: /// contribution to the health calculation.
494: #[must_use]
495: pub fn apportion_attack_health_damage(result: AttackResult, applied: f32) -> (f32, f32) {
496:     let AttackResult::ToDefender {
497:         cut_damage,
498:         blunt_damage,
499:         ..
500:     } = result
501:     else {
502:         return (0.0, 0.0);
503:     };
504:     let cut_weight = cut_damage.max(0.0);
505:     let blunt_weight = blunt_damage.max(0.0) * 0.75;
506:     let total_weight = cut_weight + blunt_weight;
507:     if applied <= 0.0 || total_weight <= 0.0 {
508:         return (0.0, 0.0);
509:     }
510:     let applied_cut = applied * cut_weight / total_weight;
511:     (applied_cut, applied - applied_cut)
512: }
