515: fn terrain_training_exposure(
516:     spans: &[JourneyTerrainSpan],
517:     start: u64,
518:     end: u64,
519:     snow_cover_bps: u16,
520: ) -> [f32; 6] {
521:     let mut exposure = [0.0_f32; 6];
522:     for span in spans {
523:         let overlap = end
524:             .min(span.start_minute.saturating_add(span.duration_minutes))
525:             .saturating_sub(start.max(span.start_minute));
526:         if overlap == 0 {
527:             continue;
528:         }
529:         let hours = overlap as f32 / 60.0 * f32::from(span.training_multiplier_permille) / 1_000.0;
530:         let snow_share =
531:             f32::from(snow_cover_bps.min(adventuresim_world_schema::BASIS_POINTS_PER_WHOLE))
532:                 / f32::from(adventuresim_world_schema::BASIS_POINTS_PER_WHOLE);
533:         let underlying_hours = hours * (1.0 - snow_share);
534:         exposure[0] += underlying_hours * f32::from(span.terrain.plains) / 1_000.0;
535:         exposure[1] += underlying_hours * f32::from(span.terrain.forest) / 1_000.0;
536:         exposure[2] += underlying_hours * f32::from(span.terrain.hills) / 1_000.0;
537:         exposure[3] += underlying_hours * f32::from(span.terrain.wetlands) / 1_000.0;
538:         exposure[4] += underlying_hours * f32::from(span.terrain.urban) / 1_000.0;
539:         exposure[5] += hours * snow_share;
540:     }
541:     exposure
