1: //! Deterministic local-problem generation and consequence evaluation.
2: //!
3: //! Hidden causes stay in the strategic authority.  Consumers receive only the
4: //! bounded effects returned by [`aggregate`] and safe public symptoms.
5: use crate::encounter::EncounterArchetype;
6: use adventuresim_world_schema::calendar::{MINUTES_PER_DAY, StrategicMinute};
7: use adventuresim_world_schema::{BASIS_POINTS_PER_WHOLE, UnitBasisPoints};
