11: pub const MAX_ACTIVE_PER_SCOPE: usize = 3;
12: pub const MAX_TRADE_BPS: i32 = 2_500;
13: pub const MAX_ENCOUNTER_BPS: u16 = 2_000;
14: pub const MAX_DISEASE_INTENSITY: u16 = 700;
15: const DISEASE_INTENSITY_UNITS_PER_EXPOSURE: f32 = 1_000.0;
16: 
17: pub fn mitigated_disease_exposure(intensity: u16, mitigation: UnitBasisPoints) -> f32 {
18:     f32::from(intensity) / DISEASE_INTENSITY_UNITS_PER_EXPOSURE
19:         * mitigation.complement().as_unit_f32()
20: }
21: 
22: /// The initial offence plus four follow-up incidents. This bounded ceiling is
23: /// temporary until other adventuring parties can retire neglected cases.
24: pub const MAX_INCIDENTS_PER_PROBLEM: u16 = 5;
25: pub const INCIDENT_INTERVAL_MINUTES: u64 = 2 * MINUTES_PER_DAY;
26: /// Each follow-up incident makes the unresolved consequences 25% more severe.
27: pub const INCIDENT_SEVERITY_STEP_BPS: u32 = 2_500;
28: 
29: pub fn due_incident_count(starts_at: StrategicMinute, minute: StrategicMinute) -> u16 {
30:     due_incident_count_configured(
31:         starts_at,
32:         minute,
33:         INCIDENT_INTERVAL_MINUTES,
34:         MAX_INCIDENTS_PER_PROBLEM,
35:     )
36: }
37: 
38: pub fn due_incident_count_configured(
39:     starts_at: StrategicMinute,
40:     minute: StrategicMinute,
41:     interval_minutes: u64,
42:     maximum_incidents: u16,
43: ) -> u16 {
44:     if minute < starts_at {
45:         return 0;
46:     }
47:     assert!(interval_minutes > 0 && maximum_incidents > 0);
48:     let follow_ups = minute.elapsed_since(starts_at) / interval_minutes;
49:     u16::try_from(follow_ups.saturating_add(1))
50:         .unwrap_or(u16::MAX)
51:         .min(maximum_incidents)
52: }
53: 
54: pub fn incident_severity_bps(incident_count: u16) -> u32 {
55:     if incident_count == 0 {
56:         return 0;
57:     }
58:     u32::from(BASIS_POINTS_PER_WHOLE).saturating_add(
59:         u32::from(incident_count.saturating_sub(1)).saturating_mul(INCIDENT_SEVERITY_STEP_BPS),
60:     )
61: }
62: 
63: fn scale_i32_for_incidents(value: i32, incident_count: u16) -> i32 {
64:     (i64::from(value) * i64::from(incident_severity_bps(incident_count))
65:         / i64::from(BASIS_POINTS_PER_WHOLE))
66:     .clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32
67: }
68: 
69: fn scale_u16_for_incidents(value: u16, incident_count: u16) -> u16 {
70:     (u64::from(value) * u64::from(incident_severity_bps(incident_count))
71:         / u64::from(BASIS_POINTS_PER_WHOLE))
72:     .min(u64::from(u16::MAX)) as u16
73: }
