1205: fn scoped_id(scope: &str, kind: &str, name: &str) -> String {
1206:     let mut digest = Sha256::new();
1207:     digest.update(b"adventuresim.quest.observer-id.v1\0");
1208:     digest.update(scope.as_bytes());
1209:     digest.update([0]);
1210:     digest.update(kind.as_bytes());
1211:     digest.update([0]);
1212:     digest.update(name.as_bytes());
1213:     format!("{kind}:{}", &format!("{:x}", digest.finalize())[..24])
1214: }
