1218:     digest.update(b"adventuresim.quest.observer-scope.v1\0");
1219:     digest.update(context.observer_entropy_hi.to_le_bytes());
1220:     digest.update(context.observer_entropy_lo.to_le_bytes());
1221:     digest.update(context.ordinal.to_le_bytes());
1222:     digest.update(context.settlement_id.as_bytes());
1223:     format!("{:x}", digest.finalize())
1224: }
